def test_announce_show_start_hook_never_touches_the_stream():
    section("announcements: the show-start hook only flips in-memory "
            "state, it never calls into the output stream itself")
    A = _ann()
    work, cfg, _lengths = _ann_workdir()

    class SlowCloseStream:
        def start(self):
            pass

        def stop(self):
            time.sleep(2.0)   # would hang THIS test if ever actually called

        def close(self):
            pass

    class SlowSD:
        def __init__(self):
            self.devices = [{"name": "MOTU M4", "max_output_channels": 2,
                            "default_samplerate": 8000}]

            class _Default:
                device = (None, None)
            self.default = _Default()

        def query_devices(self):
            return self.devices

        def OutputStream(self, **kw):
            return SlowCloseStream()

    svc = A.AnnounceService(cfg, sd=SlowSD(), operators_folder=work,
                            state_provider=lambda: "STANDBY")
    svc.play(A.DELAYED, "Andy", "rack screen")
    # Finished on its own, but unnoticed: nobody has polled status(),
    # Play or Stop since, exactly the case that used to reach
    # _finish() -> stream.stop() from inside the hook.
    svc._player.frames_written = svc._player.total_frames
    svc._player.done = True

    t0 = time.time()
    svc.on_show_started("SHOW")
    elapsed = time.time() - t0
    # Half the hang: a hook that reached stop() takes 2 s or more, a hook
    # that did not takes milliseconds, and a slow runner's hiccup is not 1 s.
    check(elapsed < 1.0,
          f"on_show_started must never call into the output stream "
          f"(stop() here deliberately hangs for 2 s): took {elapsed:.2f} s"
          f" (audit13b_scheduler_stall.py)")
    check(svc._player is not None
          and svc._player.stop_reason == "a show started",
          "it must still record why, for whatever settles it later")
    check(svc.playing == A.DELAYED,
          "the actual teardown is left to announce.py's own path (a "
          "status poll, Play, Stop, the stall watchdog), never the hook "
          "itself")
    print("  ok")


def test_schedule_hook_runs_outside_service_lock():
    section("scheduler: on_show_started is called strictly after "
            "Service.lock is released, never while nested inside it")
    S = _sched()
    if S is None:
        return
    from ltcplay import schedule_service as SV
    work = tempfile.mkdtemp()
    path = os.path.join(work, SV.RULE_FILE)
    # first_start 17:30, not the shared _sched_doc()'s 17:00: the slot this
    # test fires is 17:50, and it has to actually land on a real boundary.
    doc = {"timezone": "America/Denver",
           "season": {"first_date": "2026-11-14", "last_date": "2027-01-02"},
           "weekly": {"sat": {"first_start": "17:30", "interval_min": 20,
                              "last_end": "22:00"}},
           "exceptions": {}, "show_len_s": 440, "guard_s": 120,
           "late_grace_s": 0}
    SV.save_rule(path, doc)
    now = [_den(S, 17, 34, 0)]
    svc = SV.Service(path, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=work)
    svc.tick()
    check(svc.machine.state == S.STANDBY,
          f"setup: expected STANDBY, got {svc.machine.state}")

    HANG_S = 1.0
    calls = []
    release = threading.Event()

    def slow_hook(state, reason=None):
        calls.append(state)
        # A deliberately slow hook, standing in for ANY future hook that
        # is not as careful as announce.py's own about never touching a
        # stream: schedule_service.py must not trust that. It must simply
        # never let a hook run while Service.lock is held, by anyone, at
        # any depth (audit13b_scheduler_stall.py). It stays stuck until
        # this test lets it go, after the checks below, so a tick() or a
        # lock that waited for it waits the whole HANG_S + 5 s, never
        # something a slow runner could also take.
        release.wait(HANG_S + 5)

    svc.on_show_started = slow_hook
    now[0] = _den(S, 17, 50, 0)

    lock_wait = {}

    def other_thread():
        t0 = time.monotonic()
        with svc.lock:
            pass
        lock_wait["s"] = time.monotonic() - t0

    t0 = time.monotonic()
    tick_thread = threading.Thread(target=svc.tick)
    tick_thread.start()
    # The hook is running on its own, well outside svc.lock, by the time
    # it has actually been called -- if it were not, a thread wanting the
    # same lock would simply queue up behind whichever one holds it.
    check(wait_for(lambda: calls, timeout=2.0),
          "setup: the hook must actually run")
    other = threading.Thread(target=other_thread)
    other.start()
    tick_thread.join(timeout=HANG_S + 5)
    tick_elapsed = time.monotonic() - t0
    other.join(timeout=HANG_S + 5)

    check(svc.machine.state == S.SHOW,
          f"setup: expected the slot to fire into SHOW, got "
          f"{svc.machine.state}")
    check(calls == [S.SHOW],
          f"the hook must fire exactly once, with the new state: {calls}")
    check(tick_elapsed < 3.0,
          f"tick() must not wait for the hook it queued: took "
          f"{tick_elapsed:.2f} s (the hook itself is stuck for "
          f"{HANG_S + 5:g} s)")
    check(lock_wait.get("s", 999) < 3.0,
          f"a separate thread wanting Service.lock (Abort, Hold, Start "
          f"now, any status poll) must not wait behind a slow hook: "
          f"waited {lock_wait.get('s')} s")
    release.set()
    print("  ok")


def test_announce_reentrant_claim_does_not_orphan_a_stream():
    section("announcements: a stale, superseded Play attempt can never "
            "overwrite a later one's live stream")
    A = _ann()
    work, cfg, _lengths = _ann_workdir(device="Sound Blaster Play! 3")

    class FakeStream:
        _n = 0

        def __init__(self):
            FakeStream._n += 1
            self.id = FakeStream._n
            self.started = self.stopped = self.closed = False

        def start(self):
            self.started = True

        def stop(self):
            self.stopped = True

        def close(self):
            self.closed = True

    class _SD:
        def __init__(self):
            self.devices = [{"name": "Sound Blaster Play! 3",
                            "max_output_channels": 2,
                            "default_samplerate": 8000}]

            class _Default:
                device = (None, None)
            self.default = _Default()
            self.streams = []

        def query_devices(self):
            return self.devices

        def OutputStream(self, device=None, channels=None,
                         samplerate=None, blocksize=None, dtype=None,
                         callback=None):
            s = FakeStream()
            self.streams.append(s)
            return s

    sd = _SD()
    svc = A.AnnounceService(cfg, sd=sd, operators_folder=work,
                            state_provider=lambda: "STANDBY")
    real_decode = svc._decode
    release_t1 = threading.Event()
    t1_blocked = threading.Event()
    calls = {"n": 0}

    def controlled_decode(ann_id):
        calls["n"] += 1
        if calls["n"] == 1:
            t1_blocked.set()
            release_t1.wait(timeout=5)
        return real_decode(ann_id)

    svc._decode = controlled_decode
    errors = []

    def t1_play():
        try:
            svc.play(A.DELAYED, "Andy", "rack screen")
        except Exception as e:
            errors.append(e)

    t1 = threading.Thread(target=t1_play)
    t1.start()
    check(t1_blocked.wait(timeout=5), "setup: T1 reached its blocked decode")
    check(svc.playing == A.DELAYED and svc._player is None,
          "setup: T1 has claimed it, but built nothing yet")

    # A legitimate Stop while T1's claim is still outstanding, exactly the
    # interleaving the fix's own design is meant to allow.
    svc.stop("Andy", "rack screen")
    check(svc.playing is None, "Stop clears the claim mid-decode")

    # A second, independent press for the SAME id, fully synchronous.
    svc.play(A.DELAYED, "Andy", "rack screen")
    check(svc.playing == A.DELAYED, "a fresh press for the same id plays")
    live_stream = svc._stream

    # Now let T1's stale decode finish and race to reacquire the lock.
    release_t1.set()
    t1.join(timeout=5)
    check(bool(errors),
          "T1's stale attempt must be refused, not silently swallowed")
    check(errors and "stopped and played again" in str(errors[0]),
          f"and must say so, in a sentence: {errors}")
    check(svc._stream is live_stream,
          f"the live stream operators and the page believe is playing "
          f"must be untouched by the stale attempt: now stream #"
          f"{svc._stream.id if svc._stream else None}, expected #"
          f"{live_stream.id}")
    check(live_stream.started and not live_stream.stopped
          and not live_stream.closed,
          "the live stream must still be running")
    check(len(sd.streams) == 1,
          f"T1's stale attempt must never open a device stream at all "
          f"once it is superseded, not open-then-close: "
          f"{len(sd.streams)} opened (audit13b_reentrant_claim.py)")
    print("  ok")


def test_announce_interlock_matrix():
    section("announcements: the interlock, every scheduler state (a show "
            "running or paused is no longer refused HERE, since Play "
            "Holds it first instead, Jeff, 2026-09-26)")
    from ltcplay import schedule as sch_mod
    A = _ann()
    states = (sch_mod.BOOT, sch_mod.IDLE, sch_mod.STANDBY, sch_mod.SHOW,
              sch_mod.PAUSED, sch_mod.CLOSING, sch_mod.OFF, sch_mod.HOLD)
    check(len(set(states)) == 8,
          "the matrix must cover all 8 scheduler states")
    for state in states + (None,):
        refusal = A.interlock_refusal(state)
        if state is None:
            check(refusal is not None and "inert" in refusal,
                  f"no scheduler: announcements must be inert, got "
                  f"{refusal!r}")
        else:
            check(refusal is None,
                  f"{state}: the interlock itself must not refuse a real "
                  f"state any more; a show running or paused is Held "
                  f"first instead. Got {refusal!r}")
        _no_dashes(refusal or "", f"interlock refusal in {state}")
    # Abort is still the only way out of SHOW or PAUSED in the real
    # machine, and it always lands in STANDBY; unrelated to the interlock
    # change above, this is a schedule.py fact that used to matter here too.
    check(sch_mod.ALLOWED[sch_mod.ABORT] ==
          frozenset((sch_mod.SHOW, sch_mod.PAUSED)),
          "Abort must be exactly the exit from SHOW and PAUSED")

    # With state_provider set but no hold_requester -- an announcements
    # config with no scheduler ALSO wired for Hold, which web.serve() never
    # actually does (see test_announce_routes), but which the interlock's
    # own contract above has to hold for regardless -- a real state is
    # allowed straight through: nothing can Hold it, and the interlock no
    # longer refuses a running show on its own.
    work, cfg, _lengths = _ann_workdir()
    for state in states:
        svc = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                                state_provider=(lambda s=state: s))
        check(svc.hold_requester is None, "setup: no scheduler wired")
        for aid in A.IDS:
            svc.play(aid, "Andy", "rack screen")
            check(svc.playing == aid,
                  f"{state}, no hold_requester: {aid} must be allowed to "
                  f"play")
            svc.stop("Andy", "rack screen")
            check(svc.playing is None, "Stop must clear it for the next id")
    print("  ok")


def test_announce_hold_between_shows():
    section("announcements: between shows, Play Holds the schedule first "
            "(the same path the operator's own Hold uses), then plays, "
            "and the next show does not start at its time")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 34)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.STANDBY,
          f"setup: intermission running, waiting for the next slot: "
          f"{svc.machine.state}")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    ann.hold_requester = svc.hold_for_announcement

    r = ann.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"]["id"] == A.DELAYED,
          f"the announcement must actually play: {r}")
    check(svc.machine.state == S.HOLD,
          f"between shows, Hold is what Play must trigger first: "
          f"{svc.machine.state}")
    # The journal line for the Hold itself carries the SAME who/screen the
    # Play press used, exactly as the operator's own Hold would, and reads
    # as held FOR the announcement (review round 2, 2026-09-26:
    # audit15_journal_noise2.py), not as an indistinguishable operator
    # Hold press.
    hold_lines = [r for r in svc.journal
                 if r.get("action") == S.HOLD_ON]
    check(hold_lines and hold_lines[0]["who"] == "Andy"
          and hold_lines[0]["screen"] == "rack screen",
          f"the Hold the announcement triggered must be attributed to the "
          f"SAME operator and screen as the Play press: {hold_lines}")
    check(hold_lines and "played the Delayed announcement" in
          hold_lines[0]["text"],
          f"the Hold's own journal line must name the announcement, not "
          f"just say 'pressed Hold': {hold_lines}")

    # The next show's time passes while held: it must not fire.
    now[0] = _den(S, 17, 55)
    svc.tick()
    check(svc.machine.state == S.HOLD, "still on hold")
    slot2 = svc.machine.slot(2)
    check(slot2.status == S.DELAYED,
          f"the next show's time passed during the Hold, so it waits "
          f"instead of starting: {slot2.status} {slot2.reason}")
    ann.stop("Andy", "rack screen")
    print("  ok")


def test_announce_hold_during_show():
    section("announcements: during a show, Play plays over the show and "
            "Holds, pauses and stops nothing (Jeff, 2026-10-26: Hold is a "
            "schedule pause; the operator ends a show with Stop)")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
    swork = tempfile.mkdtemp()
    spath = os.path.join(swork, SV.RULE_FILE)
    SV.save_rule(spath, _sched_doc(
        weekly={"sat": {"first_start": "17:30", "interval_min": 20,
                        "last_end": "22:00"}},
        exceptions={}))
    now = [_den(S, 17, 30, 0)]
    svc = SV.Service(spath, clock=lambda: now[0], ntp_query=lambda: 0.0,
                     state_dir=swork)
    svc.tick()
    check(svc.machine.state == S.SHOW,
          f"setup: a show is running at its start time: {svc.machine.state}")
    ann = A.AnnounceService(cfg, sd=FakeSD(), operators_folder=work,
                            state_provider=lambda: svc.machine.state
                                if svc.machine else None)
    svc.on_show_started = ann.on_show_started
    asked = []

    def hold(who, screen, detail=None):
        asked.append((who, screen, detail))
        return svc.hold_for_announcement(who, screen, detail=detail)
    ann.hold_requester = hold
    ann.hold_still_claimed = svc.hold_still_claimed
    journal_before = len(svc.journal)

    r = ann.play(A.CANCELLATION, "Andy", "rack screen")
    check(r["playing"]["id"] == A.CANCELLATION
          and r["playing"]["held_schedule"] is False,
          f"the announcement must play over the running show: {r}")
    check(svc.machine.state == S.SHOW,
          f"during a show nothing is paused: {svc.machine.state}")
    check(asked == [], f"no Hold may even be asked for during a show: "
                       f"{asked}")
    check(not [row for row in list(svc.journal)[journal_before:]
               if row.get("action") == S.HOLD_ON],
          "no Hold line in the schedule's journal")
    started = [row for row in r["journal"] if row["outcome"] == "started"]
    check(started and "nothing was paused or stopped" in
          started[0]["text"], f"the journal says it played over the "
                              f"show: {started}")
    _no_dashes(started[0]["text"] if started else "", "play over show")
    ann.stop("Andy", "rack screen")
    check(svc.machine.state == S.SHOW,
          f"Stop on the announcement stops only its audio: "
          f"{svc.machine.state}")

    # Paused by the operator's own Hold: still a show; it plays, and the
    # show stays exactly as paused as the operator left it.
    with svc._locked():
        svc._apply(S.Event(S.HOLD_ON, "operator", who="Andy",
                           screen="Rack"))
    check(svc.machine.state == S.PAUSED, "setup: the operator paused it")
    r = ann.play(A.DELAYED, "Andy", "rack screen")
    check(r["playing"]["id"] == A.DELAYED and asked == []
          and svc.machine.state == S.PAUSED,
          f"over a paused show: plays, asks no Hold: {asked} "
          f"{svc.machine.state}")
    ann.stop("Andy", "rack screen")
    print("  ok")


def test_announce_hold_refused_refuses_the_announcement():
    section("announcements: if Hold is refused (the night is over), the "
            "announcement is refused too, with the same sentence")
    A, S, SV = _ann(), *_sched_and_service_modules()
    work, cfg, _lengths = _ann_workdir()
