def test_the_gpl_path_never_loads_devices():
    section("devices: the real GPL path (web.serve() with nothing "
            "configured) never imports it -- nothing in this codebase "
            "wires it in yet; it exists only for a future conductor to "
            "call")
    import subprocess
    root = os.path.dirname(os.path.abspath(__file__))
    # Made here, not in the child, so this run's temp sweep removes it.
    work = tempfile.mkdtemp()
    code = (
        "import sys, tempfile\n"
        f"sys.path.insert(0, {root!r})\n"
        "from ltcplay import web\n"
        f"h = web.serve({work!r}, port=0)\n"
        "h.server_close()\n"
        "print(sorted(m for m in sys.modules if m.endswith('.devices') "
        "or m == 'devices'))\n")
    rc = subprocess.run([sys.executable, "-c", code], capture_output=True,
                        text=True, timeout=60)
    loaded = (rc.stdout or "").strip().splitlines()[-1:] or ["<no output>"]
    check(loaded == ["[]"], f"the GPL path loaded devices.py: {loaded}; "
                            f"stderr: {rc.stderr[-800:]}")
    print("  ok")


def test_flamesafe_in_its_own_process():
    """The flame safety program's own suite (flamesafe/test_flamesafe.py),
    run in a SUBPROCESS so that the wall holds: that process never has
    ltcplay loaded, and this one never loads flamesafe. Its FAIL lines are
    relayed here with the same prefix so mutate.py can say what caught a
    mutation in flamesafe/."""
    section("flamesafe: the safety program's own suite, in its own process")
    import subprocess
    root = os.path.dirname(os.path.abspath(__file__))
    r = subprocess.run([sys.executable, "-u", "-m", "flamesafe.test_flamesafe"],
                       cwd=root, capture_output=True, text=True, timeout=240)
    out = (r.stdout or "") + (r.stderr or "")
    fails = [l for l in out.splitlines() if l.startswith("  FAIL")]
    for l in fails[:30]:
        print("  FAIL  flamesafe> " + l[len("  FAIL"):].strip())
    if r.returncode != 0 and not fails:
        print(out[-3000:])
    check(r.returncode == 0, f"flamesafe's own suite passed (exit "
                             f"{r.returncode}, {len(fails)} FAIL line(s))")
    lines = [l for l in out.strip().splitlines() if l.strip()]
    last = lines[-1] if lines else ""
    check(last.startswith("flamesafe: all checks passed"),
          f"flamesafe's last line: {last}")
    check("random cases, seed" in out, "the property test ran")
    check("flamesafe" not in {m.split(".")[0] for m in sys.modules},
          "running flamesafe's suite loaded nothing of it into this process")


def test_the_wall_between_ltcplay_and_flamesafe():
    """Two processes, and neither imports the other's code (handoff section
    15). Proved three ways: by the import statements in every file of both
    packages, by loading every ltcplay module in a clean interpreter and
    looking for flamesafe, and by loading every flamesafe module in a clean
    interpreter and looking for ltcplay."""
    section("the wall: ltcplay never imports flamesafe and flamesafe never "
            "imports ltcplay")
    import ast
    import json
    import subprocess
    root = os.path.dirname(os.path.abspath(__file__))
    check("flamesafe" not in {m.split(".")[0] for m in sys.modules},
          "this process, with all of ltcplay loaded, has no flamesafe module")

    def imports_of(path):
        tree = ast.parse(open(path, encoding="utf-8").read())
        out = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                out |= {a.name.split(".")[0] for a in node.names}
            elif isinstance(node, ast.ImportFrom):
                if node.level == 0 and node.module:
                    out.add(node.module.split(".")[0])
        return out

    scanned = 0
    for d, forbidden in (("ltcplay", "flamesafe"), ("flamesafe", "ltcplay")):
        for name in sorted(os.listdir(os.path.join(root, d))):
            if name.endswith(".py"):
                scanned += 1
                imps = imports_of(os.path.join(root, d, name))
                check(forbidden not in imps, f"{d}/{name} imports {forbidden}")
    check(scanned > 30, f"both packages were scanned ({scanned} files)")
    check("flamesafe" not in imports_of(os.path.join(root, "selftest.py")),
          "selftest.py itself never imports flamesafe")

    def loaded_after_importing(pkg, other):
        code = (
            "import sys, json, importlib, pkgutil\n"
            f"sys.path.insert(0, {root!r})\n"
            f"import {pkg}\n"
            "failed = []\n"
            f"for m in pkgutil.iter_modules({pkg}.__path__):\n"
            "    if m.name.startswith('__'):\n"
            "        continue\n"
            "    try:\n"
            f"        importlib.import_module('{pkg}.' + m.name)\n"
            "    except Exception as e:\n"
            "        failed.append(m.name + ': ' + type(e).__name__)\n"
            f"mine = sorted(m for m in sys.modules if m.split('.')[0] == {pkg!r})\n"
            f"theirs = sorted(m for m in sys.modules if m.split('.')[0] == {other!r})\n"
            "print(json.dumps({'mine': mine, 'theirs': theirs, "
            "'failed': failed}))\n")
        r = subprocess.run([sys.executable, "-c", code], capture_output=True,
                           text=True, timeout=120, cwd=root)
        try:
            return json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            return {"mine": [], "theirs": ["(the probe did not run: "
                                           + r.stderr[-500:] + ")"],
                    "failed": []}

    res = loaded_after_importing("ltcplay", "flamesafe")
    check(len(res["mine"]) > 20, f"every ltcplay module loaded: {res['mine']}")
    check(res["theirs"] == [], f"loading all of ltcplay loaded flamesafe: "
                               f"{res['theirs']}")
    res = loaded_after_importing("flamesafe", "ltcplay")
    check(len(res["mine"]) >= 8 and res["failed"] == [],
          f"every flamesafe module loaded: {res['mine']} {res['failed']}")
    check(res["theirs"] == [], f"loading all of flamesafe loaded ltcplay: "
                               f"{res['theirs']}")


# The GPL show log (showlog.py) as the Dollywood show runs it, line endings
# aside. The Fire & Ice journal must never change it; if this has to move,
# that is a change to the GPL show and needs its own PR saying so.
SHOWLOG_SHA256 = "37e04c9d440fbaeeb292fef190c9d182dbeced2371b9fd97a8db85f934ef1eae"

# ------------------------------------------------ the night journal ----
# Handoff section 9: the machine log and the night journal, written
# together; the incident bundle; the nightly summary; a full disk that stops
# the logging and not the show. Fire & Ice only: the GPL path never loads it.


class _FlameBus:
    """Stands in for the flame bus, which does not exist yet."""

    def __init__(self, frames=40, mismatches=()):
        self.frames = [{"at": f"2026-11-14T18:59:{i % 60:02d}.000-07:00",
                        "seq": 1000 + i,
                        "groups": {"1": {"commanded": 255 if i % 2 else 0,
                                         "sent": 0}}}
                       for i in range(frames)]
        self._mismatches = list(mismatches)

    def recent_frames(self, n):
        return [dict(f) for f in self.frames[-n:]]

    def mismatches(self, night):
        return list(self._mismatches)


def _book(J, folder, now, **kw):
    """A logbook on a folder, with a clock the test moves, in Denver."""
    from ltcplay import schedule as S
    kw.setdefault("tz", S.zone("America/Denver"))
    kw.setdefault("state", "STANDBY")
    return J.Logbook(folder, clock=lambda: now[0], **kw)


def _lines(path):
    with open(path, "rb") as fh:
        return fh.read().decode("utf-8").splitlines()


def _jsonl_rows(path):
    import json
    out = []
    for raw in _lines(path):
        try:
            out.append(json.loads(raw))
        except ValueError:
            out.append(None)
    return out


_JOURNAL_FIELDS = ("id", "at", "night", "state", "to_state", "actor",
                   "action", "outcome", "reason", "fault", "text", "line")


def _complete(r, where):
    """Every event carries every field, never blank; an operator event also
    carries who and which screen."""
    for k in _JOURNAL_FIELDS:
        if k == "fault":
            check(isinstance(r.get(k), bool), f"{where}: fault is not "
                                                    f"a flag: {r}")
            continue
        check(isinstance(r.get(k), str) and r[k].strip(),
                    f"{where}: {k} is blank: {r}")
    check(re.match(r"^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}"
                         r"[+-]\d\d:\d\d$", r.get("at") or ""),
                f"{where}: the time has no offset: {r.get('at')!r}")
    from ltcplay import journal as J
    check(r.get("actor") in J.ACTORS, f"{where}: actor {r.get('actor')}")
    if r.get("actor") == "operator":
        check(bool(r.get("who") and r.get("screen")),
                    f"{where}: an operator event without who or screen: {r}")
    check(r.get("line", "").endswith(r.get("text", "")[-20:])
                or r.get("actor") == "operator",
                f"{where}: the line is not the text: {r}")


def test_journal_every_event_is_complete():
    section("journal: every event carries time, state, actor, action, "
            "outcome and reason")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import journal as J
    check(J.ACTORS == S.ACTORS, f"the journal's actors are the scheduler's: "
                                f"{J.ACTORS} {S.ACTORS}")
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 0, 0)]
    b = _book(J, work, now)
    for actor in J.ACTORS:
        kw = {}
        if actor == "operator":
            kw = {"who": "Andy", "screen": "rack screen"}
        r = b.record(actor=actor, action="test", outcome="done",
                     reason=f"a {actor} line", text=f"A line from {actor}.",
                     state="STANDBY", **kw)
        _complete(r, f"a {actor} event")
    path = os.path.join(work, J.machine_name("2026-11-14"))
    rows = _jsonl_rows(path)
    check(len(rows) == len(J.ACTORS) and all(rows),
          f"one machine log line per event: {len(rows)}")
    for r in rows:
        _complete(r or {}, "the machine log")
    check({r["actor"] for r in rows if r} == set(J.ACTORS),
          "every actor reached the machine log")

    # Anything missing is refused where the event is made, with a sentence.
    base = dict(actor="system", action="a", outcome="b", reason="c",
                text="Some words here.", state="STANDBY")
    for bad, why in ((dict(actor=""), "blank actor"),
                     (dict(actor="nobody"), "unknown actor"),
                     (dict(reason=" "), "blank reason"),
                     (dict(action=""), "blank action"),
                     (dict(outcome=""), "blank outcome"),
                     (dict(text=""), "blank text"),
                     (dict(actor="operator"), "operator with no name"),
                     (dict(actor="operator", who="Andy"),
                      "operator with no screen"),
                     (dict(actor="operator", screen="rack screen"),
                      "operator with no name, with a screen")):
        kw = dict(base)
        kw.update(bad)
        try:
            b.record(**kw)
            check(False, f"a {why} was written")
        except ValueError as e:
            check(len(str(e).split()) > 5, f"a {why} is refused with a "
                                           f"sentence: {e}")
    r = b.record(**dict(base, state=""))
    check(r["state"] == "STANDBY", f"a blank state is filled from the "
                                   f"scheduler's own, never written blank: "
                                   f"{r['state']!r}")
    try:
        J.build_event(at=now[0], night="2026-11-14", state=" ",
                      actor="system", action="a", outcome="b", reason="c",
                      text="Some words.")
        check(False, "an event with a blank state was built")
    except ValueError:
        pass
    try:
        J.build_event(at=datetime_naive(), night="2026-11-14",
                      state="IDLE", actor="system", action="a",
                      outcome="b", reason="c", text="Some words.")
        check(False, "a time without its offset was written")
    except ValueError:
        pass
    check(len(_jsonl_rows(path)) == len(J.ACTORS) + 1,
          "nothing refused reached the file")

    # Through the scheduler service: every line it writes is complete,
    # and the page's rows are the file's records.
    svc_dir = tempfile.mkdtemp()
    now[0] = _den(S, 17, 30)
    svc = _svc(S, svc_dir, now).start(thread=False)
    for t, ev in (((18, 0, 0), None), ((18, 2), _op(S, S.HOLD_ON)),
                  ((18, 3), _op(S, S.RESUME, who="Jeff",
                                screen="Stream Deck")),
                  ((18, 4), S.Event(S.FAULT_RAISED, "madmapper",
                                    detail="MadMapper stopped answering on "
                                           "port 8000")),
                  ((18, 5), _op(S, S.START_NOW)),
                  ((18, 5, 30), S.Event(S.FAULT_RAISED, "safety",
                                        detail="The safety process stopped "
                                               "replying for 2 s")),
                  ((18, 6), S.Event(S.CLEAR_FAULT, "operator", who="Andy",
                                    screen="rack screen")),
                  ((18, 7, 20), None), ((18, 30), None)):
        now[0] = _den(S, *t)
        svc.tick() if ev is None else svc._apply(ev)
    # Refused for not naming who (Resume: Hold and Abort are taken from
    # anyone, PR #43 fix round 1).
    svc._apply(_op(S, S.RESUME, who="  ", screen="rack screen"))  # refused
    svc._apply(_op(S, S.RESUME, who="", screen=""))       # refused
    svc_path = os.path.join(svc_dir, "nights",
                            J.machine_name("2026-11-14"))
    rows = _jsonl_rows(svc_path)
    check(rows and all(rows), "the service's machine log parses line by line")
    for r in rows:
        _complete(r or {}, "a scheduler line")
    got = {r["actor"] for r in rows if r}
    check({"scheduler", "operator", "madmapper", "safety", "system"} <= got,
          f"the service logs every actor it has: {sorted(got)}")
    refused = [r for r in rows if r and r["outcome"] == "refused"
               and r["actor"] == "operator"]
    check(refused and refused[-1]["who"] == "unnamed operator"
          and refused[-1]["screen"] == "unnamed screen"
          and refused[-1]["line"].endswith(
              "By unnamed operator on the unnamed screen."),
          f"a refusal for not naming who is still written, and says so: "
          f"{refused[-1:]}")
    check(len(refused) >= 2 and refused[-2]["who"] == "unnamed operator"
          and not any("bug in ltcplay" in r["text"] for r in rows if r),
          f"a name of only spaces is no name, and never a journal bug: "
          f"{refused[-2:-1]}")
    check([r["id"] for r in svc.journal] == [r["id"] for r in rows][
        -len(svc.journal):], "the page's rows are the file's records, in "
                            "order")
    print("  ok")


def datetime_naive():
    from datetime import datetime
    return datetime(2026, 11, 14, 18, 0, 0)


def test_journal_line_format_is_the_spec():
    section("journal: the line format is section 9's, and the screen and "
            "the file agree")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import journal as J
    work = tempfile.mkdtemp()
    now = [_den(S, 19, 42, 7)]
    b = _book(J, work, now, state="SHOW")
    spec = [
        "19:42:07  Show 4 did not start. Start sent to MadMapper 19:42:04, "
        "no timecode for 3.0 s, retried once, still nothing. Slot marked "
        "FAULT. No operator action.",
        "19:44:12  Andy pressed Abort on the rack screen during show 4. "
        "MadMapper stopped, pixels faded, flame cues zeroed in 40 ms.",
        "19:44:31  Andy played the Cannot Continue announcement, 22 s, "
        "finished normally.",
        "20:01:55  Group 3 fired on the wire for 2 frames with no arm. Alarm "
        "latched. Cleared by Andy at 20:02:40.",
    ]
    b.fault("madmapper", spec[0][10:], action="SHOW_FAILED", show=4)
    now[0] = _den(S, 19, 44, 12)
    b.record(actor="operator", action="ABORT", outcome="aborted",
             reason="ABORTED (operator)", text=spec[1][10:], state="SHOW",
             who="Andy", screen="rack screen", show=4)
    now[0] = _den(S, 19, 44, 31)
    b.announcement(who="Andy", screen="rack screen", name="Cannot Continue",
                   length_s=22, ended="finished normally", state="STANDBY")
    now[0] = _den(S, 20, 1, 55)
    b.fault("safety", spec[3][10:], action="flame alarm")
    got = _lines(os.path.join(work, J.journal_name("2026-11-14")))
    check(got == spec, "the journal lines are section 9's, character for "
                       "character:\n    " + "\n    ".join(got))

    # The engine's own Abort sentence comes out in the same shape.
    n = _Night(S, _one_night_rule(S))
    n.do(S.BOOT_DONE, "system", _den(S, 17, 0))
    n.do(S.TICK, "scheduler", _den(S, 18, 0))
    o = n.do(S.ABORT, "operator", _den(S, 18, 1, 5), confirmed=True)
    le = [x for x in o.log if x.action == S.ABORT][0]
    line = J.render_line(le.at, le.text, "operator", le.who, le.screen)
    check(line.startswith("18:01:05  Andy pressed Abort on the rack screen "
                          "during show 1."),
          f"the engine's Abort line reads like the spec: {line!r}")

    # One line per event, whatever the sentence held; no em or en dashes.
    now[0] = _den(S, 20, 5)
    r = b.record(actor="system", action="note", outcome="done",
                 reason="two\nlines", text="First line.\nSecond line\u2014"
                                            "and a dash\u2013too.",
                 state="STANDBY")
    check("\n" not in r["line"] and "\u2014" not in r["line"]
          and "\u2013" not in r["line"],
          f"one line, no dashes: {r['line']!r}")
    # An operator line always says who and which screen.
    r = b.record(actor="operator", action="HOLD", outcome="refused",
                 reason="x", text="The Hold was refused.", state="SHOW",
                 who="Jeff", screen="Stream Deck")
    check(r["line"].endswith("By Jeff on the Stream Deck."),
          f"an operator line that did not name them now does: {r['line']}")
    r = b.record(actor="operator", action="HOLD", outcome="refused",
                 reason="x", text="Jeff's Hold was refused.", state="SHOW",
                 who="Jeff", screen="Stream Deck")
    check(r["line"].endswith("Jeff's Hold was refused.")
          and r["screen"] == "Stream Deck",
          f"a line that names them is left as it is; the screen is in the "
          f"machine log: {r['line']}")

    # The page's lines are the file's lines: same strings, newest first.
    file_lines = _lines(os.path.join(work, J.journal_name("2026-11-14")))
    page = b.recent(20)
    check([p["line"] for p in page] == file_lines[::-1][:20],
          "the log strip shows the file's own lines, newest first")
    check(all(p["age_s"] is not None and p["age_s"] >= 0 for p in page),
          "every line on the page carries its age")
    for l in file_lines:
        _no_dashes(l, "journal line")
    print("  ok")


def test_journal_is_append_only():
    section("journal: append only, and a line cut short is finished, "
            "never truncated")
    S = _sched()
    if S is None:
        return
    import errno
    import tempfile
    from ltcplay import journal as J
    work = tempfile.mkdtemp()
    now = [_den(S, 18, 0)]
    a = _book(J, work, now)
    for i in range(5):
        now[0] = _den(S, 18, i)
        a.record(actor="system", action="note", outcome="done",
                 reason="r", text=f"Line {i} from the first run.",
                 state="IDLE")
    jp = os.path.join(work, J.journal_name("2026-11-14"))
    mp = os.path.join(work, J.machine_name("2026-11-14"))
    before_j, before_m = open(jp, "rb").read(), open(mp, "rb").read()
    # A second run (a restart) only ever adds.
    b = _book(J, work, now)
    now[0] = _den(S, 18, 10)
    b.started(state="STANDBY")
    b.record(actor="scheduler", action="note", outcome="done", reason="r",
             text="A line from the second run.", state="STANDBY")
    after_j, after_m = open(jp, "rb").read(), open(mp, "rb").read()
    check(after_j.startswith(before_j) and len(after_j) > len(before_j),
          "the journal only grows: every byte already written is still "
          "there")
    check(after_m.startswith(before_m) and len(after_m) > len(before_m),
          "the machine log only grows")
    check("started again" in after_j.decode() and "without warning" in
          after_j.decode(), "a restart says so, and that the last run did "
                            "not stop cleanly")

    # A full disk cuts a line in half: the half stays, gets its newline,
    # and the next line starts clean. Nothing is truncated.
    class Half:
        def __init__(self, path):
            self.fh = open(path, "ab", buffering=0)

        def write(self, data):
            self.fh.write(data[:len(data) // 2])
            raise OSError(errno.ENOSPC, "No space left on device")

        def fileno(self):
            return self.fh.fileno()

        def close(self):
            self.fh.close()

    b._opener = Half
    now[0] = _den(S, 18, 11)
    b.record(actor="system", action="note", outcome="done", reason="r",
             text="This line is cut in half by a full disk.", state="STANDBY")
    cut_m = open(mp, "rb").read()
    check(cut_m.startswith(after_m) and not cut_m.endswith(b"\n"),
          "the half line is on disk as the disk left it")
    b._opener = J._open_append
    now[0] = _den(S, 18, 11, 10)
    b.record(actor="system", action="note", outcome="done", reason="r",
             text="The disk has room again.", state="STANDBY")
    check(b.pending() == 3 and not b.health()["ok"]
          and open(mp, "rb").read() == cut_m,
          f"before the retry time nothing more is tried: {b.pending()}")
    now[0] = _den(S, 18, 11, 31)
    b.drain()
    final_m = open(mp, "rb").read()
    check(final_m.startswith(cut_m) and final_m.endswith(b"\n"),
          "the cut line is kept, byte for byte, and finished with a newline")
    rows = _jsonl_rows(mp)
    check(rows.count(None) == 1 and rows[-1] is not None
          and any(r and "cut in half" in r["text"] for r in rows),
          "one unreadable half line; the whole line and everything after "
          "it follow, each on its own line")
    check(b.health()["ok"] and b.pending() == 0, "and logging is back")
    # One stream taken, the other refused: the retry finishes the other and
    # never writes the first one twice.
    def only_machine_log(path):
        if path.endswith(".journal.txt"):
            raise OSError(errno.ENOSPC, "No space left on device")
        return J._open_append(path)

    b._opener = only_machine_log
    now[0] = _den(S, 18, 20)
    r = b.record(actor="system", action="note", outcome="done", reason="r",
                 text="Written to one stream first.", state="STANDBY")
    b._opener = J._open_append
    now[0] = _den(S, 18, 21)
    b.drain()
    ids = [x["id"] for x in _jsonl_rows(mp) if x]
    check(r["id"] in ids and len(ids) == len(set(ids)),
          "a record the machine log already has is not written to it twice")
    check(sum(1 for l in _lines(jp) if "Written to one stream first." in l)
          == 1, "and the journal gets it once, on the retry")
    # The source only ever opens a night file to append.
    src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "ltcplay", "journal.py"), encoding="utf-8").read()
    import ast
    modes = set()
    for node in ast.walk(ast.parse(src)):
        if isinstance(node, ast.Call) and getattr(node.func, "id", "") == \
                "open" and len(node.args) > 1 and \
                isinstance(node.args[1], ast.Constant):
            modes.add(node.args[1].value)
    check(modes == {"ab", "a+b", "rb", "xb", "wb"},
          f"journal.py opens files only to append, read, create or write a "
          f"temp file: {sorted(modes)}")
    check(src.count('"wb"') == 1 and 'open(tmp, "wb")' in src,
          "the one whole-file write is the summary's temp file")
    print("  ok")


def test_journal_rotation_and_pruning_across_dst():
    section("journal: one file per night, kept 90 days, across both clock "
            "changes")
    S = _sched()
    if S is None:
        return
    import tempfile
    import time as _t
    from datetime import date, datetime, timedelta, timezone
    from ltcplay import journal as J
    work = tempfile.mkdtemp()
    tz = S.zone("America/Denver")
    utc = timezone.utc
    now = [datetime(2026, 11, 1, 5, 59, 59, tzinfo=utc)]   # 23:59:59 MDT
    b = _book(J, work, now)

    def line(text):
        return b.record(actor="system", action="note", outcome="done",
                        reason="r", text=text, state="IDLE")

    line("Last second of the 31st.")
    now[0] = datetime(2026, 11, 1, 6, 0, 1, tzinfo=utc)      # 00:00:01 MDT
    line("First second of the 1st.")
    now[0] = datetime(2026, 11, 1, 7, 30, tzinfo=utc)        # 01:30 MDT
    line("Half past one, the first time.")
    now[0] = datetime(2026, 11, 1, 8, 30, tzinfo=utc)        # 01:30 MST
    line("Half past one, the second time.")
    oct31 = _jsonl_rows(os.path.join(work, J.machine_name("2026-10-31")))
    nov1 = _jsonl_rows(os.path.join(work, J.machine_name("2026-11-01")))
    check(len(oct31) == 1 and len(nov1) == 3,
          f"a new night file at local midnight: {len(oct31)} {len(nov1)}")
    check([r["at"][-6:] for r in nov1] == ["-06:00", "-06:00", "-07:00"],
          f"the repeated hour is told apart by its offset: "
          f"{[r['at'] for r in nov1]}")
    j = _lines(os.path.join(work, J.journal_name("2026-11-01")))
    check([l[:10] for l in j] == ["00:00:01  ", "01:30:00  ", "01:30:00  "],
          f"the journal reads the wall clock: {j}")

    # Pruning, by the name's date: kept 120 days (Jeff, 2026-09-26). A
    # night for every day from 1 Jun to 1 Nov, two with misleading
    # timestamps, incident folders, and things this module did not write.
    check(J.KEEP_DAYS == 120, f"night files are kept 120 days: {J.KEEP_DAYS}")

    def nights_from(first, n, folder, kinds=(J.machine_name, J.journal_name)):
        made = []
        for i in range(n):
            d = first + timedelta(days=i)
            for kind in kinds:
                name = kind(d.isoformat())
                open(os.path.join(folder, name), "w").write("x\n")
                made.append((d, name))
        return made

    old = os.path.join(tempfile.mkdtemp(), "nights")
    os.makedirs(old)
    made = nights_from(date(2026, 6, 1), 154, old)
    # A kept night with an ancient timestamp, a pruned one stamped today.
    os.utime(os.path.join(old, J.machine_name("2026-07-05")), (1, 1))
    os.utime(os.path.join(old, J.machine_name("2026-07-01")),
             (_t.time(), _t.time()))
    strangers = ["notes.txt", "night_2026-07-01.jsonl.bak",
                 "night_2020-01-01.jsonl.txt", "ltcplay.log"]
    for n in strangers:
        open(os.path.join(old, n), "w").write("x")
    os.makedirs(os.path.join(old, "night_2020-01-01.jsonl"))
    inc = os.path.join(old, "incidents")
    for n in ("incident_2026-07-01_120000", "incident_2026-07-02_120000_2",
              "incident_2026-07-03_120000.partial",
              "incident_2026-07-10_120000", "notes"):
        os.makedirs(os.path.join(inc, n))
        open(os.path.join(inc, n, "journal.txt"), "w").write("x\n")
    open(os.path.join(inc, "incident_2020-01-01_120000"), "w").write("x")
    # The .partial is a crash leftover, not work in progress: old enough
    # (over a day, by its mtime) that the stale rule removes it. Its NAME's
    # date (2026-07-03, also older than 120 days) must play no part: that
    # would be pruning a `.partial` by the date rule, which round 1 of the
    # review said never to do again.
    stale_partial = os.path.join(inc, "incident_2026-07-03_120000.partial")
    stale_ts = datetime(2026, 7, 3, tzinfo=utc).timestamp()
    os.utime(stale_partial, (stale_ts, stale_ts))
    now[0] = datetime(2026, 11, 1, 18, 0, tzinfo=utc)   # the fall-back day
    p = _book(J, old, now)
    gone = p.prune(date(2026, 11, 1))
    left = set(os.listdir(old))
    # Kept: 120 days back from 1 Nov is 4 Jul.
    want = sorted([n for d, n in made if d < date(2026, 7, 4)] +
                  ["incident_2026-07-01_120000",
                   "incident_2026-07-02_120000_2",
                   "incident_2026-07-03_120000.partial"])
    check(sorted(gone) == want,
          f"night files and incident folders older than 120 days are "
          f"removed, by the date in their name: {len(gone)} "
          f"{sorted(set(gone) ^ set(want))[:4]}")
    check(all(n in left for d, n in made if d >= date(2026, 7, 4)),
          "the 120th night back and newer are kept, whatever their "
          "timestamps say")
    check(sorted(os.listdir(inc)) == ["incident_2020-01-01_120000",
                                      "incident_2026-07-10_120000", "notes"],
          f"a newer incident, and anything that is not an incident folder, "
          f"stay: {sorted(os.listdir(inc))}")
    check(all(n in left for n in strangers)
          and os.path.isdir(os.path.join(old, "night_2020-01-01.jsonl")),
          "nothing this module did not write is touched")
    check(any("Removed 66 night log file(s) and 2 incident folder(s)" in
              r["text"] for r in p.memory),
          "the journal says what was removed by the date rule (the "
          "stale .partial is reported separately, below)")
    check(any("Removed 1 incident folder(s) left unfinished (.partial)" in
              r["text"] and "incident_2026-07-03_120000.partial" in r["text"]
              for r in p.memory),
          "and a stale .partial is reported for what it is, not folded "
          "into the by-date removal")
    check("incident_2026-07-03_120000.partial" not in
          set(os.listdir(inc)), "the stale .partial is gone")
    # A clock nobody could check yet (floor=True): the newest 120 nights
    # that exist stay, whatever the date says, and NOTHING is removed by
    # age at all -- so a year-ahead date with only 4 nights on disk (a
    # seasonal show early in its life) removes nothing. A clock the time
    # server DOES agree with (floor=False) is the opposite: purely by
    # age, with no floor to protect anything -- so the same year-ahead
    # date, if this machine's clock can actually be trusted to say so,
    # removes every one of those 4, having nothing left to protect them
    # with (round 2 review of PR 25: floor is conditional again, but on
    # trust Service keeps genuinely current, not a boot-time snapshot).
    ahead = os.path.join(tempfile.mkdtemp(), "nights")
    os.makedirs(ahead)
    made_ahead = nights_from(date(2026, 11, 14), 4, ahead)
    now[0] = datetime(2027, 11, 20, 18, 0, tzinfo=utc)
    check(_book(J, ahead, now).prune(date(2027, 11, 20), floor=True) == []
          and len(os.listdir(ahead)) == 8,
          f"an untrusted clock a year ahead removes nothing at all, by "
          f"count alone: {os.listdir(ahead)}")
    gone_ahead = _book(J, ahead, now).prune(date(2027, 11, 20), floor=False)
    check(sorted(gone_ahead) == sorted(n for _d, n in made_ahead)
          and not any(os.path.exists(os.path.join(ahead, n))
                      for _d, n in made_ahead),
          f"a TRUSTED clock a year ahead removes everything by age alone, "
          f"with no floor to protect the last few nights that exist: "
          f"{gone_ahead}")
    many = os.path.join(tempfile.mkdtemp(), "nights")
    os.makedirs(many)
    made = nights_from(date(2026, 11, 1), 150, many, (J.machine_name,))
    gone = _book(J, many, now).prune(date(2028, 1, 1), floor=True)
    check(sorted(gone) == [n for _d, n in made[:30]]
          and sum(os.path.exists(os.path.join(many, n))
                  for _d, n in made) == 120,
          f"however far ahead, an untrusted clock keeps the newest 120 "
          f"nights, by count alone: {len(gone)}")
    many2 = os.path.join(tempfile.mkdtemp(), "nights")
    os.makedirs(many2)
    made2 = nights_from(date(2026, 11, 1), 150, many2, (J.machine_name,))
    gone2 = _book(J, many2, now).prune(date(2028, 1, 1))       # floor=False
    check(sorted(gone2) == sorted(n for _d, n in made2)
          and not any(os.path.exists(os.path.join(many2, n))
                      for _d, n in made2),
          f"and a TRUSTED clock removes every one of them by age alone: "
          f"every seeded night is more than 120 days before 2028-01-01, "
          f"and there is no floor to keep any of them: {len(gone2)}")
    # The spring change: 120 days back from 14 Mar 2027 is 14 Nov 2026.
    spring = os.path.join(tempfile.mkdtemp(), "nights")
    os.makedirs(spring)
    made = nights_from(date(2026, 11, 1), 134, spring, (J.machine_name,))
    now[0] = datetime(2027, 3, 14, 9, 30, tzinfo=utc)     # 02:30 MST skipped
    sp = _book(J, spring, now)
    check(sorted(sp.prune(date(2027, 3, 14))) ==
          [n for d, n in made if d < date(2026, 11, 14)],
          f"across the spring change too: {sorted(os.listdir(spring))[:3]}")
    check(sp.night_of() == date(2027, 3, 14), "the night is the local date")

    # The service prunes once the time server has agreed with the clock,
    # at start and again when each night begins. A night held past its
    # last show never closes, so its summary is written at midnight.
    work = tempfile.mkdtemp()
    nights = os.path.join(work, "nights")
    os.makedirs(nights)
    # More than 120 nights, and running right up to yesterday, so the age
    # rule (not the newest-120 floor, always applied now regardless -- see
    # journal.Logbook.prune()) is what is actually under test here.
    nights_from(date(2026, 6, 1), 165, nights, (J.machine_name,))
    now[0] = _den(S, 21, 30)
    svc = _svc(S, work, now).start(thread=False)

    def there(d):
        return os.path.exists(os.path.join(nights, J.machine_name(d)))

    check(not there("2026-07-16") and there("2026-07-17"),
          "the service prunes by age when a night begins")
    now[0] = _den(S, 21, 35)
    svc._apply(_op(S, S.HOLD_ON))
    now[0] = _den(S, 23, 59, 50)
    svc.tick()
    check(not os.path.exists(os.path.join(nights,
                                          J.summary_name("2026-11-14"))),
          "a night on hold has not closed")
    now[0] = _den(S, 0, 0, 5, d=(2026, 11, 15))
    svc.tick()
    # By now the night's last show, 21:40, has gone by during the Hold and
    # is DELAYED. A delayed show keeps last night open across midnight
    # (Jeff, 2026-10-01): it is not swept away just because the date
    # changed, so neither pruning nor the new night's file happen yet.
    check(svc.machine.delayed() is not None and
          str(svc.machine.date) == "2026-11-14" and
          svc.machine.state == S.HOLD,
          f"a delayed show keeps last night open past midnight, got "
          f"{svc.machine.date} {svc.machine.state} "
          f"{svc.machine.delayed()}")
    check(there("2026-07-17") and not there("2026-11-15"),
          "so pruning's floor does not move another day and the new "
          "night's file does not appear while a delayed show still waits")
    # Once the operator actually closes the delayed night, the new night
    # begins at the 2 AM nightly reset (Jeff, 2026-10-03), and pruning and
    # the rollover happen then.
    svc._apply(_op(S, S.END_NIGHT, confirmed=True))
    check(svc.machine.state == S.OFF, "Close for the night finally closes "
                                      "the delayed night")
    now[0] = _den(S, 0, 0, 6, d=(2026, 11, 15))
    svc.tick()
    check(str(svc.machine.date) == "2026-11-14" and
          not there("2026-11-15"),
          "a closed night still runs until the 2 AM reset")
    now[0] = _den(S, 2, 0, 6, d=(2026, 11, 15))
    svc.tick()
    check(str(svc.machine.date) == "2026-11-15",
          "and now the new night starts")
    check(not there("2026-07-17") and there("2026-07-18"),
          "and prunes again once the delayed night actually closes")
    check(there("2026-11-15"),
          "and the lines go to the new night's file")
    # A clock the time server disagrees with: nothing is pruned until it
    # has run for 10 minutes, and then with the floor.
    work2 = tempfile.mkdtemp()
    nights2 = os.path.join(work2, "nights")
    os.makedirs(nights2)
    nights_from(date(2026, 6, 1), 130, nights2, (J.machine_name,))
    now[0] = _den(S, 21, 30)
    svc2 = _svc(S, work2, now, ntp_query=lambda: 90000.0).start(thread=False)
    first = os.path.join(nights2, J.machine_name("2026-06-01"))
    check(svc2.clock_check["level"] == "warn" and os.path.exists(first),
          "an unchecked clock prunes nothing at first")
    now[0] = _den(S, 21, 40, 1)
    svc2.tick()

    def there2(d):
        return os.path.exists(os.path.join(nights2, J.machine_name(d)))

    check(not there2("2026-06-11") and there2("2026-06-12"),
          "and after 10 minutes prunes, keeping the newest 120 nights even "
          "where the age rule would remove them")
    sp14 = os.path.join(nights, J.summary_name("2026-11-14"))
    check(os.path.exists(sp14) and "Close for the night" in
          open(sp14, encoding="utf-8").read(),
          "and the delayed night's summary, once it is actually closed, "
          "says who closed it")
    print("  ok")


def test_journal_prune_never_removes_a_partial_by_its_name_date():
    section("journal: a .partial incident is never removed by the date in "
            "its name; only a stale one, by how long it has sat "
            "unfinished, ever goes")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date, datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    # A .partial dated long ago (a wrong clock, or simply an old crash,
    # could leave one so named), but written moments ago by this run's own
    # clock: save_incident() could still be filling it. prune() must leave
    # it alone even with `today` set far enough ahead that the date-based
    # rule would remove a FINISHED incident with the same name's date
    # (round 1 review of PR 25, should-fix).
    folder = tempfile.mkdtemp()
    inc = os.path.join(folder, J.INCIDENTS)
    os.makedirs(inc)
    partial = os.path.join(inc, "incident_2020-01-01_000000.partial")
    os.makedirs(partial)
    open(os.path.join(partial, "journal.txt"), "w").write("still open\n")
    now = [datetime(2026, 11, 1, 12, 0, tzinfo=utc)]
    # Its mtime is real wall-clock time (whenever this test happens to
    # run), which has nothing to do with the mocked clock above: set it to
    # match `now[0]`, so "freshly written" is judged against the same
    # clock prune() itself uses.
    fresh_ts = now[0].timestamp()
    os.utime(partial, (fresh_ts, fresh_ts))
    b = _book(J, folder, now)
    gone = b.prune(date(2026, 11, 1))       # far more than 120 days past 2020
    check(gone == [] and os.path.isdir(partial),
          f"a freshly-written .partial survives, whatever its name's date "
          f"says: {gone}")

    # The same folder, now old enough (mtime over a day) that whatever was
    # writing it is gone: a separate, simple rule removes it, and only
    # that rule.
    old_ts = (now[0] - timedelta(days=2)).timestamp()
    os.utime(partial, (old_ts, old_ts))
    gone2 = b.prune(date(2026, 11, 1))
    check(gone2 == ["incident_2020-01-01_000000.partial"]
          and not os.path.exists(partial),
          f"a .partial unfinished for more than a day is removed, as a "
          f"stale crash leftover: {gone2}")
    check(any("left unfinished (.partial)" in r["text"] for r in b.memory),
          "and the journal says so, distinctly from a by-date removal")
    print("  ok")


def test_journal_prune_takes_the_incident_lock():
    section("journal: prune() takes the same lock save_incident() uses, "
            "so the two can never interleave")
    S = _sched()
    if S is None:
        return
    import tempfile
    import threading
    from datetime import date, datetime, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    folder = tempfile.mkdtemp()
    now = [datetime(2026, 11, 1, 12, 0, tzinfo=utc)]
    b = _book(J, folder, now)
    # prune() defaults to floor=False (a trustworthy clock, the ordinary
    # case): purely by age, no newest-N floor at all, so a single old
    # night file is removed on its own, whatever else does or does not
    # exist alongside it.
    old_name = J.machine_name("2020-01-01")
    open(os.path.join(b.folder, old_name), "w").write("x\n")

    order = []
    holding = threading.Event()
    released = threading.Event()

    def hold_and_release():
        with b._io:
            order.append("held")
            holding.set()
            released.wait(2)
        order.append("released")

    holder = threading.Thread(target=hold_and_release, daemon=True)
    holder.start()
    check(holding.wait(2), "the other holder took the lock")

    result = {}

    def run_prune():
        result["gone"] = b.prune(date(2026, 11, 1))
        order.append("pruned")

    pruner = threading.Thread(target=run_prune, daemon=True)
    pruner.start()
    pruner.join(timeout=0.3)
    check(pruner.is_alive()
          and os.path.exists(os.path.join(b.folder, old_name)),
          "prune() waits for the lock, rather than running through it "
          "while save_incident() (or anything else) holds it")
    released.set()
    pruner.join(timeout=2)
    holder.join(timeout=2)
    check(not pruner.is_alive() and result.get("gone") == [old_name],
          "and runs, and removes the old file, once the lock is free")
    check(order == ["held", "released", "pruned"],
          f"the two never interleave: {order}")
    print("  ok")


def test_schedule_clock_jump_midrun_keeps_the_floor_and_is_journaled():
    section("scheduler: a clock that jumps mid-run, after passing its own "
            "one-shot check at start, never breaks the 120-night floor, "
            "and is itself noticed and journaled")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import date, datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    work = tempfile.mkdtemp()
    nights = os.path.join(work, J.FOLDER)
    os.makedirs(nights)
    boot = datetime(2026, 9, 27, 12, 0, tzinfo=utc)
    base = boot.date() - timedelta(days=1)
    made = []
    for i in range(130):
        d = base - timedelta(days=i)
        open(os.path.join(nights, J.machine_name(d.isoformat())), "w") \
            .write("x\n")
        made.append(d)

    def unique_dates():
        # Every distinct night date still on disk, this test's own 130
        # seeded ones and any the service itself wrote for "tonight"
        # alike: the floor protects whatever the newest 120 actually are,
        # not just the ones this test happened to seed.
        out = set()
        for name in os.listdir(nights):
            m = J._NAME.match(name)
            if m:
                out.add(date(int(m.group(1)), int(m.group(2)),
                             int(m.group(3))))
        return out

    now = [boot]
    perf = [0.0]

    def real_ntp_query():
        # A real time server measures against the true elapsed time,
        # which perf_counter tracks (it cannot be stepped by whatever
        # stepped `now`): this is the offset an actual server would
        # report, so a recheck after the jump below genuinely still
        # catches the wrong clock, rather than a fixed "it's fine"
        # answer that could never have noticed anything either way.
        true_now = boot + timedelta(seconds=perf[0])
        return (now[0] - true_now).total_seconds()

    svc = _svc(S, work, now, ntp_query=real_ntp_query,
              perf_counter=lambda: perf[0])
    svc.start(thread=False)                     # a good clock at boot
    check(svc.clock_check["level"] == "ok", "the boot-time check passed")
    check(len(unique_dates()) >= 120,
          f"the boot-time prune never keeps fewer than the newest 120: "
          f"{len(unique_dates())}")

    # The clock steps forward 200 days between two ticks that, by
    # perf_counter, were a quarter of a second apart: an NTP step, an RTC
    # glitch, or someone setting it by hand -- none of which this process
    # would otherwise ever notice again after its one boot-time check.
    now[0] = boot + timedelta(days=200)
    perf[0] = 0.25
    svc.tick()

    check(any(r.get("outcome") == "jumped" for r in svc.journal),
          "the jump itself is noticed and journaled")
    check(svc.clock_check["level"] != "ok",
          "the recheck the jump triggers genuinely still catches the "
          "wrong clock (a real time server would), so trust is not "
          "wrongly restored")
    check(len(unique_dates()) >= 120,
          f"and nothing beyond the newest 120 nights is ever removed, "
          f"however this tick's own housekeeping used the wrong date: "
          f"{len(unique_dates())}")
    print("  ok")


def test_journal_prune_trusted_clock_deletes_purely_by_age():
    section("journal: prune() with a trusted clock (floor=False) deletes "
            "purely by age, even a handful of nights spread over years "
            "(a seasonal show), with no newest-N floor to protect any of "
            "them (round 2 review of PR 25: an unconditional floor had "
            "overcorrected the round 1 fix, and a seasonal show could "
            "then never age files out at all)")
    import tempfile
    from datetime import date, datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    tmp = tempfile.mkdtemp()
    today = date(2026, 9, 27)
    # The reviewer's own case: 10 nights over the last two years, none of
    # them recent, all genuinely more than 120 days old.
    old_nights = [today - timedelta(days=n)
                 for n in (800, 700, 600, 500, 400, 300, 250, 200, 150, 130)]
    names = [J.journal_name(d) for d in old_nights]
    for d in old_nights:
        open(os.path.join(tmp, J.journal_name(d)), "wb").write(b"x\n")
    lb = J.Logbook(folder=tmp, clock=lambda: datetime.now(utc))
    removed = lb.prune(today, state="BOOT", floor=False)
    check(sorted(removed) == sorted(names),
          f"a trusted clock removes every one of these 10 nights: "
          f"{removed}")
    check(not any(os.path.exists(os.path.join(tmp, n)) for n in names),
          "and none of them are left on disk")
    print("  ok")


def test_journal_prune_untrusted_clock_keeps_them_all():
    section("journal: prune() with an untrusted clock (floor=True) "
            "removes nothing by age at all; with only a handful of "
            "nights on disk, every one of them IS 'the newest 120'")
    import tempfile
    from datetime import date, datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    tmp = tempfile.mkdtemp()
    today = date(2026, 9, 27)
    old_nights = [today - timedelta(days=n)
                 for n in (800, 700, 600, 500, 400, 300, 250, 200, 150, 130)]
    names = [J.journal_name(d) for d in old_nights]
    for d in old_nights:
        open(os.path.join(tmp, J.journal_name(d)), "wb").write(b"x\n")
    now = [datetime(2026, 9, 27, 12, 0, tzinfo=utc)]
    lb = J.Logbook(folder=tmp, clock=lambda: now[0])
    removed = lb.prune(today, state="BOOT", floor=True)
    check(removed == [],
          f"an untrusted clock removes nothing: {removed}")
    check(all(os.path.exists(os.path.join(tmp, n)) for n in names),
          "every one of the 10 nights is still there")
    print("  ok")


def test_schedule_sleep_and_wake_restores_trust_and_resumes_pruning():
    section("scheduler: sleeping for days and waking again looks like a "
            "jump too (the wall clock moves, perf_counter barely does), "
            "but a genuinely correct clock is re-confirmed at once, not "
            "left distrusted, and pruning resumes normally")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    work = tempfile.mkdtemp()
    nights = os.path.join(work, J.FOLDER)
    os.makedirs(nights)
    boot = datetime(2026, 9, 27, 20, 0, tzinfo=utc)
    now = [boot]
    perf = [0.0]
    # A genuinely correct clock throughout: unlike a bad jump, a real time
    # server agrees with it before AND after the sleep.
    svc = _svc(S, work, now, ntp_query=lambda: 0.0,
              perf_counter=lambda: perf[0])
    svc.start(thread=False)
    check(svc.clock_check["level"] == "ok", "the boot-time check passed")

    # The machine sleeps for three days over a long weekend; perf_counter
    # (suspend time is not counted) barely advances, but the wall clock
    # genuinely did move three real days.
    now[0] = boot + timedelta(days=3)
    perf[0] = 0.3
    svc.tick()

    check(any(r.get("outcome") == "jumped" for r in svc.journal),
          "sleep and wake is itself noticed and journaled, the same as "
          "any other jump")
    check(svc.clock_check["level"] == "ok",
          "but the recheck it triggers finds a genuinely correct clock, "
          "so trust is restored, not left lost")
    check(svc._clock_trusted(), "and the service agrees it is trusted")

    # An old night added after waking is removed by age, proving pruning
    # is not stuck refusing to trust the clock just because a jump was
    # noticed once.
    old = now[0].date() - timedelta(days=200)
    old_name = J.machine_name(old.isoformat())
    open(os.path.join(nights, old_name), "w").write("x\n")
    gone = svc.logbook.prune(now[0].date(), state="BOOT",
                             floor=not svc._clock_trusted())
    check(gone == [old_name],
          f"and age-based pruning resumes normally after waking: {gone}")
    print("  ok")


def test_schedule_trusted_clock_prunes_by_age_through_normal_housekeeping():
    section("scheduler: Service's own housekeeping, not just Logbook.prune() "
            "called directly, computes floor from LIVE trust: a trusted "
            "clock deletes an old night by age even with only one night "
            "on disk, far fewer than the newest-120 floor would ever let "
            "age alone touch")
    S = _sched()
    if S is None:
        return
    import tempfile
    from datetime import datetime, timedelta, timezone
    from ltcplay import journal as J
    utc = timezone.utc

    work = tempfile.mkdtemp()
    nights = os.path.join(work, J.FOLDER)
    os.makedirs(nights)
    boot = datetime(2026, 9, 27, 20, 0, tzinfo=utc)
    old = boot.date() - timedelta(days=200)
    old_name = J.machine_name(old.isoformat())
    open(os.path.join(nights, old_name), "w").write("x\n")

    now = [boot]
    # A trusted clock from the start: no jump, no ambiguity.
    svc = _svc(S, work, now, ntp_query=lambda: 0.0)
