def test_journal_housekeeping_runs_once():
    section("journal: two callers at once never prune or look back twice")
    S = _sched()
    if S is None:
        return
    import tempfile
    import threading
    import time as _t
    from datetime import date, timedelta
    from ltcplay import journal as J
    from ltcplay import schedule_service as SV
    twice = []
    for trial in range(5):
        work = tempfile.mkdtemp()
        nights = os.path.join(work, "nights")
        os.makedirs(nights)
        for i in range(100):
            open(os.path.join(nights, J.machine_name(
                str(date(2026, 5, 1) + timedelta(days=i)))), "w").write("x\n")
        _book(J, nights, [_den(S, 20, 0, d=(2026, 11, 13))]).record(
            actor="system", action="note", outcome="done", reason="r",
            text="Yesterday, never summarised.")
        base = _den(S, 17, 30)
        slow = {"on": False}

        def clock():
            if slow["on"]:
                _t.sleep(0.005)          # a busy machine
            return base

        rule = os.path.join(work, SV.RULE_FILE)
        SV.save_rule(rule, _sched_doc(
            weekly={"sat": {"first_start": "18:00", "interval_min": 20,
                            "last_end": "22:00"}}, exceptions={}))
        svc = SV.Service(rule, clock=clock, state_dir=work,
                         ntp_query=lambda: 0.0)
        with svc.lock:
            svc._ensure_night(base)
        svc.clock_check = {"level": "ok"}
        calls = {"prune": 0, "summary": {}}
        real_prune, real_sum = svc.logbook.prune, svc.logbook.write_summary

        def prune(*a, **k):
            calls["prune"] += 1
            return real_prune(*a, **k)

        def summary(night, *a, **k):
            calls["summary"][night] = calls["summary"].get(night, 0) + 1
            return real_sum(night, *a, **k)

        svc.logbook.prune, svc.logbook.write_summary = prune, summary
        slow["on"] = True
        go = threading.Barrier(2)
        ts = [threading.Thread(target=lambda: (go.wait(),
                                               svc._housekeeping()))
              for _ in range(2)]
        for t in ts:
            t.start()
        for t in ts:
            t.join(10)
        slow["on"] = False
        if calls["prune"] > 1 or any(n > 1 for n in
                                     calls["summary"].values()):
            twice.append(dict(calls))
    check(not twice, f"housekeeping is decided under the lock, so it runs "
                     f"once: {twice}")
    print("  ok")


# ------------------------------------------------------------ audio_master
# ltcplay plays the show's multi-track audio and the timecode is read off
# the audio device (handoff section 4a). Everything below runs without a
# sound card: showaudio.FakeSoundDevice stands in for sounddevice, and all
# but the last two tests run the audio process's own loop in THIS process
# on a clock the test moves, so every timing is exact and repeatable.


class _AmClock:
    """A perf_counter the test moves by hand."""

    def __init__(self, t=1000.0):
        self.t = t

    def __call__(self):
        return self.t


def _am_write_wav(path, x, rate=48000, fmt="pcm16"):
    """A WAV file of `x` (frames, channels), -1.0 to 1.0, written by hand so
    every format the show audio accepts can be made: pcm16, pcm24, pcm32,
    float32, and float32 wrapped as WAVE_FORMAT_EXTENSIBLE."""
    import numpy as np
    import struct
    x = np.asarray(x, dtype=np.float64)
    if x.ndim == 1:
        x = x[:, None]
    ch = x.shape[1]
    if fmt in ("float32", "ext_float32"):
        data, tag, bits = x.astype("<f4").tobytes(), 3, 32
    elif fmt == "pcm16":
        data = np.clip(np.round(x * 32767), -32768, 32767).astype(
            "<i2").tobytes()
        tag, bits = 1, 16
    elif fmt == "pcm24":
        v = np.clip(np.round(x * 8388607), -8388608, 8388607).astype("<i4")
        data = v.view(np.uint8).reshape(-1, 4)[:, :3].tobytes()
        tag, bits = 1, 24
    elif fmt == "pcm32":
        data = np.clip(np.round(x * 2147483647), -2147483648,
                       2147483647).astype("<i4").tobytes()
        tag, bits = 1, 32
    else:
        raise ValueError(fmt)
    align = ch * bits // 8
    if fmt == "ext_float32":
        fmt_chunk = struct.pack("<HHIIHHHHI", 0xFFFE, ch, rate, rate * align,
                                align, bits, 22, bits, 0) + \
            struct.pack("<I", 3) + bytes.fromhex("00001000800000aa00389b71")
    else:
        fmt_chunk = struct.pack("<HHIIHH", tag, ch, rate, rate * align,
                                align, bits)
    body = (b"WAVE" + b"LIST" + struct.pack("<I", 4) + b"INFO"
            + b"fmt " + struct.pack("<I", len(fmt_chunk)) + fmt_chunk
            + b"data" + struct.pack("<I", len(data)) + data
            + (b"\x00" if len(data) & 1 else b""))
    with open(path, "wb") as fh:
        fh.write(b"RIFF" + struct.pack("<I", len(body)) + body)


def _am_tone(seconds, channels=1, amp=0.5, freq=375.0, rate=48000):
    import numpy as np
    t = np.arange(int(round(seconds * rate))) / float(rate)
    x = amp * np.sin(2 * np.pi * freq * t)
    return np.repeat(x[:, None], channels, axis=1)


def _am_clock_doc(show_stems, intermission_stems=None, **audio):
    cues = {"show": {"cue": "Show", "stems": show_stems}}
    if intermission_stems:
        cues["intermission"] = {"cue": "Intermission",
                                "stems": intermission_stems}
    a = {"device": "Show DSP", "rate": 48000, "channels": 8, "cues": cues}
    a.update(audio)
    return {"source": "audio_master",
            "artnet": {"nodes": {"MadMapper": "127.0.0.1",
                                 "BEYOND": "127.0.0.2"}},
            "audio": a}


def _am_show(work, seconds=6.0, clock_doc=None, silences=(), **audio):
    """A show folder with a show and an intermission, each with its audio,
    and the timeline loaded from it. `silences` are (start, end) seconds of
    digital silence (exact zeros) in every show stem."""
    music, sub = _am_tone(seconds, 2), _am_tone(seconds, 1, 0.3)
    for a, b in silences:
        music[int(a * 48000):int(b * 48000)] = 0.0
        sub[int(a * 48000):int(b * 48000)] = 0.0
    _am_write_wav(os.path.join(work, "music.wav"), music)
    _am_write_wav(os.path.join(work, "sub.wav"), sub)
    _am_write_wav(os.path.join(work, "loop.wav"), _am_tone(2.0, 2, 0.2))
    doc = clock_doc or _am_clock_doc(
        [{"file": "music.wav", "gain_db": 0, "channels": [1, 2]},
         {"file": "sub.wav", "gain_db": -6, "channels": [3]}],
        [{"file": "loop.wav", "channels": [1, 2]}], **audio)
    tlp, net = _clock_show(work, doc,
                           [("01:00:00:00", "Show.fseq", "Show"),
                            ("02:00:00:00", "Intermission.fseq",
                             "Intermission")])
    return timeline.Timeline.load(tlp), tlp, net


class _AmOut(_TcOut):
    """Every Art-Net timecode packet, stamped on the test's clock."""

    def __init__(self, clock):
        super().__init__()
        self._vc = clock

    def send(self, pkt):
        self.sent.append((self._vc(), bytes(pkt)))
        self.packets_sent += 1
        return True

    def frames(self, since=None):
        out = []
        for t, p in self.sent:
            if since is not None and t < since:
                continue
            h, m, s, f, _ = _tc_of(p)
            out.append((t, ((h * 60 + m) * 60 + s) * 30 + f))
        return out


class _AmJournal:
    def __init__(self):
        self.faults, self.records = [], []

    def fault(self, actor, sentence, action=None, **kw):
        self.faults.append((actor, sentence, action))

    def record(self, **kw):
        self.records.append(kw)


class _AmLog:
    def __init__(self):
        self.lines = []

    def event(self, kind, msg, throttle_s=0.0):
        self.lines.append((kind, msg))

    def info(self, msg):
        self.lines.append(("info", msg))


class _AmLocalEngine:
    """showaudio.AudioProcess, the audio process's real loop, run in this
    process against a FakeSoundDevice on the test's clock. The same
    interface as showaudio.AudioEngine, with no process in it."""

    def __init__(self, spec, vc, block=480, latency=0.02, drift_ppm=0.0,
                 devices=None, hostapis=None, reported_latency=None):
        from ltcplay import showaudio as sa
        self.sa, self.spec, self.vc = sa, spec, vc
        self.block, self.latency, self.drift_ppm = block, latency, drift_ppm
        self.devices, self.hostapis = devices, hostapis
        self.reported_latency = reported_latency
        self.log = []                 # (t, Position, block) per callback
        self.respawns = 0
        self.crashed = False
        self._msgs = []
        self._new()

    def _new(self):
        sa = self.sa
        self.arr = [0.0] * sa.SLOTS
        fake = {"threaded": False, "block": self.block,
                "latency": self.latency, "drift_ppm": self.drift_ppm,
                "devices": self.devices or [{"name": "Show DSP", "hostapi": 0,
                                             "max_output_channels": 8}],
                "reported_latency": self.reported_latency}
        if self.hostapis:
            fake["hostapis"] = self.hostapis
        self.sd = sa.FakeSoundDevice(**fake)
        self.proc = sa.AudioProcess(self.spec, self.sd,
                                    sa.Publisher(self.arr),
                                    self._msgs.append, clock=self.vc,
                                    sync_load=True)
        self.period = self.block / 48000.0 / (1.0 + self.drift_ppm * 1e-6)
        self._stream = None
        self._next = None
        self._next_step = self.vc()

    def start(self, wait_s=0):
        self.proc.step(self.vc())
        same = self.spec.get("same_length", {})
        for role, stems in self.spec["cues"].items():
            self.proc.command(("load", role, stems, same.get(role, True)))
        self.proc.step(self.vc())
        for m in self._msgs:
            if m[0] in ("opened", "refused", "unavailable"):
                return m
        return None

    def send(self, msg):
        if self.crashed:
            return False
        self.proc.command(msg)
        return True

    def read(self):
        return self.sa.read_position(self.arr)

    def events(self):
        out = list(self._msgs)
        del self._msgs[:]
        return out

    def close(self):
        self.proc.close(wait_s=0)

    def crash(self):
        """The audio process dies: the engine says so, as the real one
        does, and a new one is started later by respawn()."""
        self.crashed = True
        self._stream = None
        self._msgs.append(("crashed", "The show audio process stopped: it "
                                      "exited (code 3). It is being started "
                                      "again."))

    def respawn(self):
        self.crashed = False
        self.respawns += 1
        self._new()
        self._msgs.append(("respawned", 0))
        self.start()

    def next_time(self):
        if self.crashed:
            return float("inf")
        s = self.proc.stream
        if s is not self._stream:
            self._stream = s
            self._next = None if s is None else self.vc() + self.period
        t = self._next_step
        if self._next is not None:
            t = min(t, self._next)
        return t

    def run_at(self, t):
        if self.crashed:
            return
        if self._next is not None and t >= self._next - 1e-12 \
                and self.proc.stream is self._stream:
            blk = self._stream.pump(t)
            if blk is not None:
                self.log.append((t, self.read(), blk))
            self._next += self.period
        if t >= self._next_step - 1e-12:
            self.proc.step(t)
            self._next_step = t + 0.02


class _AmSim:
    """Runs a clock and its local engine together on the test's clock,
    waking the clock exactly when it asked to be woken, the way its own
    thread would with no scheduling delay at all."""

    def __init__(self, am, eng, vc):
        self.am, self.eng, self.vc = am, eng, vc
        self.next_am = vc()
        self.trace = []               # (t, epoch, mode) after each step

    def run(self, until):
        vc = self.vc
        if self.am.kicked:
            self.am.kicked = False
            self.next_am = vc()
        while True:
            t = min(self.next_am, self.eng.next_time())
            if t > until:
                vc.t = until
                return
            vc.t = t
            self.eng.run_at(t)
            if t >= self.next_am - 1e-12:
                due = self.am.step(t)
                self.trace.append((t, self.am._epoch, self.am._mode))
                self.next_am = max(due, t + 1e-6)

    def until(self, pred, limit):
        end = self.vc() + limit
        while self.vc() < end:
            self.run(min(self.vc() + 0.005, end))
            if pred():
                return True
        return pred()


def _am_rig(work=None, seconds=6.0, block=480, latency=0.02, drift_ppm=0.0,
            devices=None, reported_latency=None, silences=(), **audio):
    """A deterministic audio_master: the show, the clock, a local audio
    engine, and a recorder for everything the clock tells the world."""
    import tempfile
    from ltcplay import clock as clock_mod, showaudio as sa
    work = work or tempfile.mkdtemp()
    tl, _tlp, _net = _am_show(work, seconds, silences=silences, **audio)
    checked = sa.check_show(tl.clock.audio, tl)
    # The fake interface is a CoreAudio one, so this is a Mac's rule for
    # picking the output, on every OS the suite runs on.
    spec = sa.engine_spec(tl.clock.audio, checked, platform="darwin")
    vc = _AmClock()
    eng = _AmLocalEngine(spec, vc, block=block, latency=latency,
                         drift_ppm=drift_ppm, devices=devices,
                         reported_latency=reported_latency)
    out = _AmOut(vc)
    calls = {"stop": [], "pause": [], "resume": []}
    fed = []
    jr, lg = _AmJournal(), _AmLog()
    am = clock_mod.AudioMaster(
        tl.clock, sink=lambda pos, at, drop, text: fed.append(
            (vc(), pos, at, text)),
        out=out, engine=eng,
        cues={c["label"]: (role, c["frames"]) for role, c in checked.items()},
        clock=vc, mono=vc, log=lg, journal=jr, threaded=False,
        on_stop=lambda: calls["stop"].append(vc()),
        on_pause=lambda: calls["pause"].append(vc()),
        on_resume=lambda: calls["resume"].append(vc()))
    am.start()
    sim = _AmSim(am, eng, vc)
    sim.run(vc() + 0.05)
    return {"am": am, "eng": eng, "vc": vc, "out": out, "calls": calls,
            "fed": fed, "journal": jr, "log": lg, "sim": sim, "tl": tl,
            "work": work, "checked": checked}


def _am_true_pos(rig, t):
    """Where the audio really is at `t`: from the callbacks the fake device
    made (each block's first frame is heard `latency` after its callback)."""
    best = None
    for tc, pos, _blk in rig["eng"].log:
        if pos is None or not pos.playing or tc + pos.latency > t:
            continue
        best = (tc + pos.latency, pos.frame)
    if best is None:
        return None
    rate = 48000.0 * (1.0 + rig["eng"].drift_ppm * 1e-6)
    return best[1] / 48000.0 + (t - best[0]) * rate / 48000.0


def _am_consecutive(frames):
    """The places a frame number did not follow the one before by 1."""
    return [(a, b) for (_, a), (_, b) in zip(frames, frames[1:])
            if b != a + 1]


# The show's 19 channels (Jeff, 2026-10-20), the default map: Music L, C, R
# on 1 to 3, Music Atmo L, R on 4 and 5, Lily, Jack and Narrator L, C, R on
# 6 to 14, Sound Effects L, C, R on 15 to 17, Sound Effects Atmo L, R on 18
# and 19, and a timecode track that would be a 20th output of its own.
_AM_19 = ("Music L", "Music C", "Music R", "Music Atmo L", "Music Atmo R",
          "Lily L", "Lily C", "Lily R", "Jack L", "Jack C", "Jack R",
          "Narrator L", "Narrator C", "Narrator R", "Sound Effects L",
          "Sound Effects C", "Sound Effects R", "Sound Effects Atmo L",
          "Sound Effects Atmo R")


def _am_19_files(work, seconds):
    """show19.wav: 19 channels, 24-bit, channel k a tone of 110 x k Hz
    (each a whole number of cycles a second, so each is told apart by its
    frequency); ltc.wav: mono LTC from 01:00:00:00, 30 fps. Returns the two
    as decoded (frames, channels) arrays."""
    import numpy as np
    from ltcplay import ltc as ltc_mod, showaudio as sa
    n = int(seconds * 48000)
    t = np.arange(n) / 48000.0
    x = np.stack([0.04 * np.sin(2 * np.pi * 110 * k * t)
                  for k in range(1, len(_AM_19) + 1)], axis=1)
    _am_write_wav(os.path.join(work, "show19.wav"), x, fmt="pcm24")
    lt = np.asarray(ltc_mod.synthesize(1, 0, 0, 0, 30, 48000,
                                       frames=int(seconds * 30)))[:n]
    _am_write_wav(os.path.join(work, "ltc.wav"), lt)
    return (sa.read_wav(os.path.join(work, "show19.wav")),
            sa.read_wav(os.path.join(work, "ltc.wav")))


def test_audio_master_nineteen_channels_and_timecode():
    section("audio_master: 19 show channels mapped to any outputs, timecode "
            "on a 20th of its own, and an interface without 20 outputs "
            "refused out loud")
    import tempfile
    import numpy as np
    from ltcplay import clock as clock_mod, showaudio as sa, ltc as ltc_mod
    N = len(_AM_19)              # 19 program channels: odd, on purpose
    L = N + 1                    # the timecode output
    work = tempfile.mkdtemp()
    secs = 2.0
    pcm, ltc_pcm = _am_19_files(work, secs)
    check(pcm.shape == (96000, N) and ltc_pcm.shape == (96000, 1),
          f"the synthetic {N} channel show did not decode whole: "
          f"{pcm.shape} {ltc_pcm.shape}")
    ident = list(range(1, N + 1))
    # A map that is neither the identity nor a plain reversal.
    perm = [ident[(i * 7) % N] for i in range(N)]
    check(sorted(perm) == ident and perm != ident
          and perm != ident[::-1], f"the test map is not a shuffle: {perm}")

    def doc(show_stems, **kw):
        a = dict(channels=L, ltc_output=L)
        a.update(kw)
        return _am_clock_doc(show_stems,
                             [{"file": "loop.wav", "channels": [1, 2]}], **a)

    def stems(m=None, ltc_out=L):
        s = [{"file": "show19.wav", "channels": m or ident}]
        if ltc_out:
            s.append({"file": "ltc.wav", "channels": [ltc_out]})
        return s

    def parse(d):
        return clock_mod.ClockConfig.parse(d, "show.json")

    def refused(d, *want, files=False, memory=None):
        try:
            cfg = parse(d)
            if files:
                tl, _p, _n = _am_show(work, secs, clock_doc=d)
                sa.check_show(cfg.audio, tl, total_memory=memory)
        except (clock_mod.ClockConfigError, sa.AudioConfigError) as e:
            msg = str(e)
            check(all(w in msg for w in want),
                  f"the refusal does not say {want}: {msg}")
            check(not any(c in msg for c in ("—", "–"))
                  and msg.rstrip().endswith("."),
                  f"a refusal is not a plain sentence: {msg}")
            return msg
        check(False, f"a show that cannot run was accepted ({want})")

    def mixed(d):
        """Parse, check the files, load them the way the audio process
        does, and mix the first second."""
        cfg = parse(d)
        tl, _p, _n = _am_show(work, secs, clock_doc=d)
        checked = sa.check_show(cfg.audio, tl, total_memory=64 << 30)
        mix = sa.Mixer(cfg.audio.channels)
        dec = [(sa.read_wav(p), g, o) for p, g, o, _n in
               checked["show"]["stems"]]
        mix.add_cue("show", dec)
        mix.play("show")
        return cfg, mix.render(48000)

    # 1. Every channel on the output its map names, untouched; the
    # timecode output carries the timecode and nothing else, and it decodes.
    for m in (ident, perm):
        cfg, out = mixed(doc(stems(m)))
        check(out.shape == (48000, L), f"the mix is {out.shape}, not {L} "
                                       f"outputs")
        for k, o in enumerate(m):
            check(np.array_equal(out[:, o - 1], pcm[:48000, k]),
                  f"{_AM_19[k]} (channel {k + 1}) is not exactly what plays "
                  f"on output {o} with the map {m}")
            spec = np.abs(np.fft.rfft(out[:, o - 1]))
            check(int(np.argmax(spec)) == 110 * (k + 1),
                  f"output {o} does not carry {_AM_19[k]}'s "
                  f"{110 * (k + 1)} Hz tone")
        check(np.array_equal(out[:, L - 1], ltc_pcm[:48000, 0]),
              f"output {L} is not the timecode track alone")
        got = [str(f) for f in ltc_mod.LTCDecoder(48000).feed(
            out[:, L - 1].tolist())]
        check(len(got) >= 25 and got[0].startswith("01:00:00:0"),
              f"the timecode on output {L} does not decode: {got[:3]}")
    check(cfg.audio.ltc_output == L and f"timecode on output {L}"
          in cfg.summary(), f"the summary does not name the timecode "
                            f"output: {cfg.summary()}")

    # 2. 19 is odd: nothing pairs outputs. 19 outputs and no timecode
    # parse and mix as they are.
    cfg, out = mixed(doc(stems(ltc_out=None), channels=N, ltc_output=None))
    check(out.shape == (48000, N) and np.array_equal(out, pcm[:48000])
          and cfg.audio.ltc_output is None,
          f"{N} channels on {N} outputs, no timecode, did not play as is")
    check("timecode on output" not in cfg.summary(),
          f"a show with no timecode output names one: {cfg.summary()}")

    # 3. A show file written before ltc_output existed reads exactly as it
    # did: nothing set aside, two stems may share an output.
    c = parse(_am_clock_doc([{"file": "music.wav", "channels": [1, 2]},
                             {"file": "sub.wav", "channels": [2]}]))
    check(c.audio.ltc_output is None and c.audio.channels == 8,
          "a show file without ltc_output changed meaning")

    # 4. The timecode output may not collide with program audio.
    refused(doc(stems() + [{"file": "sub.wav", "channels": [L]}]),
            f"output {L} is the timecode output", "'ltc.wav', 'sub.wav'",
            "garbles")
    refused(doc(stems(ltc_out=None)), "no stem of the show audio",
            "would be silent")
    refused(doc(stems(), ltc_output=L + 1), "'clock.audio.ltc_output'",
            f"1 to 'clock.audio.channels' ({L})")
    refused(doc(stems(), ltc_output=0), "'clock.audio.ltc_output'")
    refused(doc(stems(), ltc_output=True), "'clock.audio.ltc_output'")
    # A mono timecode file spread onto a program output too: only the
    # files can tell a mono stem from a stereo one.
    refused(doc(stems(ltc_out=None) + [{"file": "ltc.wav",
                                        "channels": [L, 1]}]),
            "ltc.wav is one channel", f"{L}, 1",
            f"output {L} is the timecode output", files=True)
    # The intermission may have no timecode, but may not mix into it.
    d3 = doc(stems())
    d3["audio"]["cues"]["intermission"]["stems"] = [
        {"file": "loop.wav", "channels": [N, L]},
        {"file": "sub.wav", "channels": [L]}]
    refused(d3, "the intermission audio plays", "'loop.wav'", "'sub.wav'")

    # 5. A file whose channel count is not the number of outputs it lists
    # is refused with the files, never played on fewer or more.
    refused(doc([{"file": "show19.wav", "channels": ident[:-1]},
                 {"file": "ltc.wav", "channels": [N]}], ltc_output=N),
            f"show19.wav has {N} channels", f"lists {N - 1}", files=True)
    refused(doc([{"file": "show19.wav", "channels": ident + [L]}],
                ltc_output=None),
            f"show19.wav has {N} channels", f"lists {L}", files=True)

    # 6. Too big for this computer's memory: refused when the show file
    # loads, with the sizes, never found out at Run or mid-show.
    refused(doc(stems()), "GB of memory", "more than half",
            files=True, memory=10 * 1000 * 1000)
    tl, _p, _n = _am_show(work, secs, clock_doc=doc(stems()))
    ok = sa.check_show(parse(doc(stems())).audio, tl,
                       total_memory=100 * 1000 * 1000)
    check(set(ok) == {"show", "intermission"},
          "a show that fits in memory was refused")
    tm = sa.total_memory_bytes()
    check(tm is None or (isinstance(tm, int) and tm > 1 << 26),
          f"this computer's memory reads as {tm!r}")

    # 7. The limits: 32 outputs and 32 stems, not 8; 33 refused.
    many = doc([{"file": f"m{i}.wav", "channels": [i]}
                for i in range(1, N + 1)] + [{"file": "ltc.wav",
                                               "channels": [L]}])
    check(len(parse(many).audio.cues["show"].stems) == L,
          f"{N} mono stems and a timecode stem were refused")
    check(parse(doc(stems(), channels=32)).audio.channels == 32,
          "32 outputs were refused")
    refused(doc(stems(), channels=33), "1 to 32")
    refused(doc([{"file": f"m{i}.wav", "channels": [i]}
                 for i in range(1, 34)], channels=32, ltc_output=None),
            "lists 33 stems", "at most 32")

    # 8. The interface: 20 outputs open; fewer (18, what PreSonus lists for
    # the 16R's USB playback, or 2, a stereo endpoint) is refused naming how
    # many it has on every way it was tried, and Run is refused with that
    # sentence: never a quiet play on fewer outputs.
    def fake(devs, apis=("Core Audio",)):
        return sa.FakeSoundDevice(devices=devs, hostapis=apis,
                                  threaded=False)

    def cb(*_a):
        pass
    s, desc, shared = sa.open_output_stream(
        fake([{"name": "StudioLive 16R", "hostapi": 0,
               "max_output_channels": L}], ("ASIO",)),
        "StudioLive 16R", L, 48000, cb, platform="win32")
    check(s.channels == L and f"ASIO, mixer-free, {L} outputs" in desc
          and not shared, f"{L} outputs over ASIO did not open: {desc}")
    for devs, apis, want in (
            ([{"name": "StudioLive 16R", "hostapi": 0,
               "max_output_channels": 18}], ("ASIO",),
             (f"ASIO: it has 18 output(s), and the show uses {L}",)),
            ([{"name": "StudioLive 16R", "hostapi": 0,
               "max_output_channels": N}], ("ASIO",),
             (f"ASIO: it has {N} output(s), and the show uses {L}",)),
            ([{"name": "StudioLive 16R", "hostapi": 0,
               "max_output_channels": 18},
              {"name": "StudioLive 16R", "hostapi": 1,
               "max_output_channels": 2}], ("ASIO", "Windows WASAPI"),
             ("ASIO: it has 18 output(s)",
              f"WASAPI exclusive: it has 2 output(s), and the show uses {L}",
              "Use an interface with enough outputs"))):
        try:
            sa.open_output_stream(fake(devs, apis), "StudioLive 16R", L,
                                  48000, cb, platform="win32")
            check(False, f"an interface without {L} outputs opened: {devs}")
        except sa.Refusal as e:
            check(all(w in str(e) for w in want),
                  f"the refusal does not say {want}: {e}")
    try:
        _am_rig(work=work, seconds=secs, clock_doc=doc(stems()),
                devices=[{"name": "Show DSP", "hostapi": 0,
                          "max_output_channels": 18}])
        check(False, f"Run was allowed on an interface with 18 outputs for "
                     f"a show that uses {L}")
    except clock_mod.ClockConfigError as e:
        check(f"has 18 output(s), and the show uses {L}" in str(e),
              f"Run's refusal does not say why: {e}")

    # 9. End to end on a 20 output interface: the audio process's own
    # loop, its callback blocks, the shuffled map and the timecode.
    r = _am_rig(work=work, seconds=secs, clock_doc=doc(stems(perm)),
                devices=[{"name": "Show DSP", "hostapi": 0,
                          "max_output_channels": L}])
    am, sim = r["am"], r["sim"]
    am.play(3600.0, None, "Show")
    sim.run(r["vc"]() + 1.0)
    blocks = [(p, b) for _t, p, b in r["eng"].log
              if p is not None and p.playing and b is not None]
    check(len(blocks) > 50 and all(b.shape[1] == L for _p, b in blocks),
          f"the interface did not get {L} outputs a block")
    p0, b0 = blocks[5]
    a = p0.frame
    for k, o in enumerate(perm):
        check(np.array_equal(b0[:, o - 1], pcm[a:a + b0.shape[0], k]),
              f"{_AM_19[k]} is not on output {o} in the interface's block")
    check(np.array_equal(b0[:, L - 1], ltc_pcm[a:a + b0.shape[0], 0]),
          f"the interface's output {L} is not the timecode alone")
    am.stop()
    print("  ok")


def test_soak_bench_track_nineteen_channels():
    section("stress kit: the soak's 19 channel bench track, each tone on "
            "the output its map names, LTC on output 20, through the "
            "engine's own checks and mix")
    import shutil
    import tempfile
    import numpy as np
    from ltcplay import showaudio as sa, ltc as ltc_mod
    sp = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                      "packaging", "windows")
    sys.path.insert(0, sp)
    was = sys.dont_write_bytecode
    sys.dont_write_bytecode = True      # no __pycache__ in packaging/
    names = ("soak", "ltcwin", "soak_apps", "soak_exercise", "supervisor")
    work = tempfile.mkdtemp()
    try:
        for m in names:
            sys.modules.pop(m, None)
        import soak
        check(list(soak.SHOW_TRACKS) == list(_AM_19),
              f"the soak's track names are not the show's 19: "
              f"{soak.SHOW_TRACKS}")
        for line in soak._bench_audio_check():
            check(bool(line), "the soak's own bench track check said nothing")
        perm = [3, 1, 2, 5, 4, 8, 6, 7, 11, 9, 10, 14, 12, 13, 17, 15, 16,
                19, 18]
        audio = soak.write_bench_audio(work, 1.0, 19, perm, 20)
        check(audio["channels"] == 20 and audio["ltc_output"] == 20,
              f"the bench track does not use 20 outputs: {audio}")
        _am_write_wav(os.path.join(work, "loop.wav"), _am_tone(1.0, 2, 0.2))
        doc = {"source": "audio_master",
               "artnet": {"nodes": {"MadMapper": "127.0.0.1"}},
               "audio": dict(audio, device="Show DSP")}
        tlp, _net = _clock_show(work, doc, [("00:00:00:00", "Show.fseq",
                                             "Show")])
        tl = timeline.Timeline.load(tlp)
        cfg = tl.clock.audio
        checked = sa.check_show(cfg, tl, total_memory=64 << 30)
        mix = sa.Mixer(cfg.channels)
        mix.add_cue("show", [(sa.read_wav(p), g, o)
                             for p, g, o, _n in checked["show"]["stems"]])
        mix.play("show")
        out = mix.render(48000)
        for k, o in enumerate(perm, 1):
            spec = np.abs(np.fft.rfft(out[:, o - 1]))
            check(int(np.argmax(spec)) == 110 * k,
                  f"{soak.track_name(k, 19)} ({110 * k} Hz) is not on "
                  f"output {o}")
        got = [str(f) for f in ltc_mod.LTCDecoder(48000).feed(
            out[:, 19].tolist())]
        check(len(got) >= 25 and got[0].startswith("00:00:00:0"),
              f"the bench LTC on output 20 does not decode: {got[:3]}")
        try:
            soak.audio_plan(19, perm[:-1] + [3], 20)
            check(False, "a bench map with an output twice was accepted")
        except ValueError as e:
            check("twice" in str(e), f"the bench map refusal: {e}")
    finally:
        shutil.rmtree(work, ignore_errors=True)
        if sp in sys.path:
            sys.path.remove(sp)
        for m in names:
            sys.modules.pop(m, None)
        sys.dont_write_bytecode = was
    print("  ok")


def test_audio_master_settings_and_files_refuse_in_sentences():
    section("audio_master: settings, stems and devices refused in sentences")
    import tempfile
    from ltcplay import clock as clock_mod, showaudio as sa
    work = tempfile.mkdtemp()

    def refusal(doc, *want):
        try:
            clock_mod.ClockConfig.parse(doc, "show.json")
        except clock_mod.ClockConfigError as e:
            msg = str(e)
            check(all(w in msg for w in want),
                  f"the refusal does not say {want}: {msg}")
            check(not any(d in msg for d in ("—", "–"))
                  and msg.rstrip().endswith("."),
                  f"a refusal is not a plain sentence: {msg}")
            return msg
        check(False, f"a clock block that cannot run was accepted: {doc}")

    good = _am_clock_doc([{"file": "music.wav", "channels": [1, 2]}])
    cfg = clock_mod.ClockConfig.parse(good, "show.json")
    check(cfg.source == "audio_master" and cfg.audio.channels == 8
          and cfg.audio.hold_fade_ms == 250 and cfg.audio.abort_fade_ms
          == 1000 and cfg.audio.return_fade_ms == 1000
          and not cfg.audio.allow_shared_mode,
          "an audio_master block did not parse with its defaults")
    check("audio_master" in cfg.summary() and "Show DSP" in cfg.summary(),
          f"the summary does not name the audio: {cfg.summary()}")
    import copy

    def with_audio(**kw):
        d = copy.deepcopy(good)
        d["audio"].update(kw)
        return d

    refusal(with_audio(rate=44100), "48000")
    refusal(with_audio(rate=96000), "48000")
    refusal(with_audio(device=""), "names the show's audio interface")
    refusal(with_audio(channels=0), "'clock.audio.channels'")
    refusal(with_audio(channels=33), "1 to 32")
    refusal(with_audio(cues={"show": {"cue": "Show", "stems": [
        {"file": f"s{i}.wav", "channels": [1]} for i in range(33)]}}),
        "lists 33 stems", "at most 32")
    refusal(with_audio(cues={"show": {"cue": "Show", "stems": [
        {"file": "music.wav", "channels": [9]}]}}), "output 9",
        "'clock.audio.channels' is 8")
    refusal(with_audio(cues={"show": {"cue": "Show", "stems": [
        {"file": "music.wav", "channels": [1, 1]}]}}), "same output twice")
    refusal(with_audio(cues={"show": {"cue": "Show", "stems": [
        {"file": "music.wav", "gain_db": 40, "channels": [1]}]}}),
        "gain_db")
    refusal(with_audio(cues={"encore": {"cue": "Show", "stems": []}}),
            "\"show\" and \"intermission\"")
    refusal(with_audio(volume=3), "'volume'")
    d = copy.deepcopy(good)
    d["show_audio"] = "madmapper"
    refusal(d, "must be \"ltcplay\"")
    d = copy.deepcopy(good)
    del d["audio"]
    refusal(d, "no 'clock.audio' block")
    d = copy.deepcopy(good)
    del d["artnet"]
    refusal(d, "no 'clock.artnet' block")
    d = copy.deepcopy(good)
    d["artnet"] = {"broadcast": "10.0.0.255"}
    refusal(d, "never by broadcast")
    # "audio" is audio_master's alone: any other source still reads it as
    # the typo it is, in the same words as before.
    d = {"source": "artnet_master", "artnet": {"nodes": {"M": "127.0.0.1"}},
         "audio": {}}
    msg = refusal(d, "has no setting 'audio'")
    taken = {k.strip(" .") for k in msg.split("it takes:")[1].split(",")}
    check(taken == {"artnet", "notes", "show_audio", "source", "zones"},
          f"artnet_master's list of settings changed: {msg}")

    # The files, against the show folder.
    tl, _t, _n = _am_show(work, 2.0)

    def file_refusal(doc_cues, *want, **kw):
        a = sa.AudioConfig.parse(dict(good["audio"], cues=doc_cues, **kw),
                                 "show.json")
        try:
            sa.check_show(a, tl)
        except sa.AudioConfigError as e:
            msg = str(e)
            check(all(w in msg for w in want),
                  f"the file refusal does not say {want}: {msg}")
            check(not any(x in msg for x in ("—", "–"))
                  and msg.rstrip().endswith("."),
                  f"a file refusal is not a plain sentence: {msg}")
            return msg
        check(False, f"stems that cannot play were accepted: {doc_cues}")

    file_refusal({"show": {"cue": "Show", "stems": [
        {"file": "gone.wav", "channels": [1]}]}},
        "The show audio file gone.wav is missing", "cannot play without it")
    _am_write_wav(os.path.join(work, "cd.wav"), _am_tone(2.0, 2, rate=44100),
                  rate=44100)
    file_refusal({"show": {"cue": "Show", "stems": [
        {"file": "cd.wav", "channels": [1, 2]}]}}, "cd.wav is 44100 Hz",
        "48 kHz")
    _am_write_wav(os.path.join(work, "short.wav"), _am_tone(1.5, 1))
    msg = file_refusal({"show": {"cue": "Show", "stems": [
        {"file": "music.wav", "channels": [1, 2]},
        {"file": "short.wav", "channels": [3]}]}},
        "not all the same length", "music.wav is 0:02.000",
        "short.wav is 0:01.500", "allow_different_lengths")
    ok = sa.AudioConfig.parse(dict(good["audio"], cues={"show": {
        "cue": "Show", "allow_different_lengths": True, "stems": [
            {"file": "music.wav", "channels": [1, 2]},
            {"file": "short.wav", "channels": [3]}]}}), "show.json")
    got = sa.check_show(ok, tl)
    check(got["show"]["frames"] == 96000,
          "stems allowed to differ do not run to the longest one")
    file_refusal({"show": {"cue": "Show", "stems": [
        {"file": "music.wav", "channels": [1, 2, 3]}]}}, "has 2 channels",
        "3 output(s)")
    file_refusal({"show": {"cue": "Finale", "stems": [
        {"file": "music.wav", "channels": [1, 2]}]}},
        "'Finale', which is not a cue in this show")
    open(os.path.join(work, "notes.wav"), "w").write("not a wav")
    file_refusal({"show": {"cue": "Show", "stems": [
        {"file": "notes.wav", "channels": [1]}]}}, "not a WAV file")

    # Every format the show audio takes decodes to the same samples.
    import numpy as np
    x = _am_tone(0.1, 2, 0.7)
    for fmt, tol in (("pcm16", 1e-4), ("pcm24", 1e-6), ("pcm32", 1e-7),
                     ("float32", 1e-7), ("ext_float32", 1e-7)):
        p = os.path.join(work, f"{fmt}.wav")
        _am_write_wav(p, x, fmt=fmt)
        got = sa.read_wav(p)
        check(got.shape == x.shape and got.dtype == np.float32
              and float(np.max(np.abs(got - x))) <= tol,
              f"a {fmt} WAV decoded wrong: max error "
              f"{float(np.max(np.abs(got - x))) if got.shape == x.shape else got.shape}")
    neg = os.path.join(work, "neg24.wav")
    _am_write_wav(neg, np.array([[-1.0], [-0.5], [0.5]]), fmt="pcm24")
    check(np.allclose(sa.read_wav(neg)[:, 0], [-1.0, -0.5, 0.5], atol=1e-6),
          "a negative 24-bit sample lost its sign")

    # The device: found by exact name, never through Windows' shared mixer.
    def sd(apis, devs, **kw):
        return sa.FakeSoundDevice(devices=devs, hostapis=apis,
                                  threaded=False, **kw)

    def dev(name, api, outs=8):
        return {"name": name, "hostapi": api, "max_output_channels": outs}

    cb = lambda *a: None
    win = ("MME", "Windows DirectSound", "Windows WASAPI", "ASIO",
           "Windows WDM-KS")
    all4 = [dev("Show DSP", i) for i in range(4)]
    s, desc, shared = sa.open_output_stream(sd(win, all4), "show dsp", 8,
                                            48000, cb, platform="win32")
    check("ASIO" in desc and not shared and s.dev["hostapi"] == 3,
          f"Windows did not pick ASIO when the device offers it: {desc}")
    s, desc, shared = sa.open_output_stream(sd(win, all4[:3]), "Show DSP", 8,
                                            48000, cb, platform="win32")
    check("WASAPI exclusive" in desc and not shared
          and s.extra is not None and s.extra.exclusive is True,
          f"without ASIO, Windows did not use WASAPI exclusive: {desc}")
    for apis_have in (all4[:2], all4[:1]):
        try:
            sa.open_output_stream(sd(win, apis_have), "Show DSP", 8, 48000,
                                  cb, platform="win32")
            check(False, "the show audio fell back to Windows' shared mixer "
                         "without being allowed to")
        except sa.Refusal as e:
            check("shared audio engine" in str(e)
                  and "allow_shared_mode" in str(e),
                  f"the shared-mixer refusal is not a sentence: {e}")
    s, desc, shared = sa.open_output_stream(sd(win, all4[:2]), "Show DSP", 8,
                                            48000, cb, allow_shared=True,
                                            platform="win32")
    check(shared and "DirectSound" in desc,
          f"allow_shared_mode did not open shared, or did not say so: "
          f"{desc}")
    # Every allowed API is tried in order until one takes 48 kHz (bench
    # B23, the Scarlett: WASAPI refused 48 kHz; WDM-KS, DirectSound and MME
    # took it). Order: ASIO, WASAPI exclusive, WDM-KS, then only with
    # allow_shared_mode WASAPI shared, DirectSound, MME.
    def scarlett(**over):
        d = [dict(dev("Scarlett Solo USB", i, 2), rates=[48000])
             for i in range(5) if i != 3]           # no ASIO driver
        for x in d:
            if x["hostapi"] == 2:                   # WASAPI: 44.1 kHz only
                x["rates"] = [44100]
            if x["hostapi"] == 4 and over.get("ks_busy"):
                x["busy"] = True
        return sd(win, d)

    def opened(*a, **k):
        try:
            return sa.open_output_stream(*a, **k)
        except Exception as e:
            return None, f"{type(e).__name__}: {e}", None

    s, desc, shared = opened(scarlett(), "Scarlett Solo USB", 2, 48000, cb,
                             platform="win32")
    check(s is not None and s.dev["hostapi"] == 4
          and "WDM-KS, mixer-free" in desc and not shared,
          f"WASAPI refusing 48 kHz did not move on to WDM-KS: {desc}")
    try:
        sa.open_output_stream(scarlett(ks_busy=True), "Scarlett Solo USB",
                              2, 48000, cb, platform="win32")
        check(False, "the Scarlett opened through the shared engine unasked")
    except (sa.Refusal, sa.Unavailable) as e:
        msg = str(e)
        check(isinstance(e, sa.Refusal)
              and "WASAPI exclusive: it will not play 2 output(s) at 48000"
              in msg and "WDM-KS: it would not open" in msg
              and "allow_shared_mode" in msg and msg.endswith(".")
              and "\u2014" not in msg,
              f"the refusal does not say what was tried and why: {msg}")
    s, desc, shared = opened(scarlett(ks_busy=True), "Scarlett Solo USB",
                             2, 48000, cb, allow_shared=True,
                             platform="win32")
    check(s is not None and s.dev["hostapi"] == 1 and shared
          and "DirectSound" in desc
          and "shared audio engine" in desc,
          f"with allow_shared_mode the next that works was not used: {desc}")
    s, desc, shared = sa.open_output_stream(
        sd(("Core Audio",), [dev("Show DSP", 0)]), "Show DSP", 8, 48000, cb,
        platform="darwin")
    check("CoreAudio" in desc and not shared,
          f"macOS did not open CoreAudio: {desc}")
    for devs, want, kind in (
            ([dev("Show DSP", 0, 2)], "has 2 output(s), and the show uses 8",
             sa.Refusal),
            ([dev("Show DSP 2", 0)], "is not attached", sa.Unavailable),
            ([dev("Show DSP", 0), dev("show dsp", 0)], "not specific enough",
             sa.Refusal)):
        try:
            sa.open_output_stream(sd(("Core Audio",), devs), "Show DSP", 8,
                                  48000, cb, platform="darwin")
            check(False, f"a device that cannot run the show opened: {want}")
        except kind as e:
            check(want in str(e), f"the device refusal does not say "
                                  f"{want!r}: {e}")
    try:
        sa.open_output_stream(sd(("Core Audio",), [dev("Show DSP", 0)],
                                 rates=(44100,)), "Show DSP", 8, 48000, cb,
                              platform="darwin")
        check(False, "a device that cannot run at 48 kHz opened")
    except sa.Refusal as e:
        check("will not play 8 output(s) at 48000 Hz" in str(e)
              and "set the interface to 48 kHz" in str(e),
              f"the rate refusal: {e}")
    # SD_ENABLE_ASIO has to be in the environment BEFORE sounddevice is
    # imported, and only on Windows.
    import inspect
    src = inspect.getsource(sa.import_sounddevice)
    check(src.index('os.environ["SD_ENABLE_ASIO"] = "1"')
          < src.index("import sounddevice"),
          "SD_ENABLE_ASIO is set after sounddevice is imported")
    # Proven with a stand-in module, so this needs no sounddevice (CI does
    # not install it).
    import types
    old = os.environ.pop("SD_ENABLE_ASIO", None)
    had = sys.modules.get("sounddevice")
    sys.modules["sounddevice"] = types.ModuleType("sounddevice")
    try:
        sa.import_sounddevice("darwin")
        check("SD_ENABLE_ASIO" not in os.environ,
              "SD_ENABLE_ASIO was set on a Mac")
        sa.import_sounddevice("win32")
        check(os.environ.get("SD_ENABLE_ASIO") == "1",
              "SD_ENABLE_ASIO was not set on Windows")
    except Exception as e:
        check(False, f"importing sounddevice for the show audio failed: {e}")
    finally:
        os.environ.pop("SD_ENABLE_ASIO", None)
        if old is not None:
            os.environ["SD_ENABLE_ASIO"] = old
        if had is None:
            sys.modules.pop("sounddevice", None)
        else:
            sys.modules["sounddevice"] = had
    print("  ok")


def test_audio_master_mixing():
    section("audio_master: gain, routing, summing, clipping, fades")
    import numpy as np
    from ltcplay import showaudio as sa
    m = sa.Mixer(8)
    n = 4800
    a = np.full((n, 1), 0.25, np.float32)             # mono
    b = np.tile(np.array([[0.1, 0.2]], np.float32), (n, 1))   # stereo
    c = np.full((n, 1), 0.9, np.float32)
    ramp = (np.arange(n, dtype=np.float32) / n)[:, None]
    m.add_cue("show", [(a, sa.db_to_gain(-6.0206), [0, 1]),
                       (b, 1.0, [1, 2]),
                       (c, sa.db_to_gain(6.0206), [3]),
                       (ramp, 1.0, [5])])
    m.play("show", 1000, 0, 7)
    blk = m.render(256)
    check(blk.dtype == np.float32 and blk.shape == (256, 8),
          f"the mix is {blk.dtype} {blk.shape}, not float32 (256, 8)")
    check(np.allclose(blk[:, 0], 0.125, atol=1e-5),
          f"-6 dB did not halve a stem: {blk[0, 0]}")
    check(np.allclose(blk[:, 1], 0.225, atol=1e-5),
          f"two stems on one output did not sum: {blk[0, 1]}")
    check(np.allclose(blk[:, 2], 0.2, atol=1e-6),
          f"a stereo stem's right channel is not on output 3: {blk[0, 2]}")
    check(np.all(blk[:, 3] == 1.0) and m.clipped == 256,
          f"a mix over full scale was not held at 1.0 and counted: "
          f"{blk[0, 3]} {m.clipped}")
    check(np.all(blk[:, 4] == 0.0) and np.all(blk[:, 6:] == 0.0),
          "an output nothing is routed to is not silent")
    check(np.allclose(blk[:, 5], ramp[1000:1256, 0], atol=1e-7),
          "play from a position did not start at that frame")
    check(m.frame == 1256, f"the frame count is {m.frame}, not 1256")
    m.clipped = 0
    # Pause: the fade ends the playback on an exact frame, announced as it
    # starts, and nothing after it: no run-on.
    m.pause(480, 7)
    check(m.stop_frame == 1256 + 480,
          f"the pause did not say where it stops: {m.stop_frame}")
    pieces = [m.render(200) for _ in range(5)]
    whole = np.concatenate(pieces)[:, 5]
    src = ramp[1256:1256 + 1000, 0]
    env = whole[:480] / np.maximum(src[:480], 1e-9)
    check(np.all(np.diff(env[1:]) <= 1e-6) and abs(env[-1]) < 1e-6
          and env[0] > 0.99,
          "the pause is not a clean fade to zero")
    check(np.all(whole[480:] == 0.0),
          "sound kept coming after the pause's fade ended (run-on)")
    check(m.state == sa.PAUSED and m.frame == 1736,
          f"after the fade: {sa.STATE_NAMES[m.state]} at {m.frame}")
    check(np.all(m.render(300) == 0.0) and m.frame == 1736,
          "a paused mix moved or made sound")
    # Resume: from the exact frame, fading in.
    m.resume(240, 7)
    blk = m.render(480)
    check(m.frame == 2216 and blk[0, 5] < 0.01 and
          abs(blk[300, 5] - ramp[1736 + 300, 0]) < 1e-6,
          "resume did not carry on from the frame the pause stopped on")
    # Resume inside a pause's fade cancels it.
    m.pause(4800, 7)
    m.render(100)
    m.resume(0, 7)
    check(m.state == sa.PLAYING and m.stop_frame == -1,
          "resume during the pause's fade did not cancel it")
    m.render(100)
    # A command for another play is ignored.
    check(m.pause(100, 99) is False and m.state == sa.PLAYING,
          "a pause meant for an older cue paused this one")
    # The level fade (Abort) scales everything, linearly.
    m.clipped = 0
    m.set_level(0.0, 1000)
    blk = m.render(1000)
    lv = blk[:, 2] / 0.2
    check(abs(lv[499] - 0.5) < 0.01 and abs(lv[-1]) < 1e-6
          and np.all(np.diff(lv) <= 1e-6),
          "the level fade is not a straight line to zero")
    check(np.all(m.render(100) == 0.0), "the level stayed up after its fade")
    m.set_level(1.0, 0)
    # Stop fades to nothing and forgets the cue.
    m.stop(480, 7)
    m.render(600)
    check(m.state == sa.IDLE and m.cue is None,
          "stop did not end the playback")
    # The end of the audio.
    m.play("show", n - 100, 0, 8)
    blk = m.render(256)
    check(m.state == sa.ENDED and m.frame == n
          and np.all(blk[100:] == 0.0) and blk[99, 2] != 0.0,
          "the end of the audio is not where the mix stops")
    # Stems of different lengths: the short one just stops contributing.
    m2 = sa.Mixer(2)
    m2.add_cue("x", [(np.full((100, 1), 0.5, np.float32), 1.0, [0]),
                     (np.full((50, 1), 0.5, np.float32), 1.0, [1])])
    m2.play("x", 0, 0, 1)
    blk = m2.render(100)
    check(np.all(blk[:, 0] == 0.5) and np.all(blk[:50, 1] == 0.5)
          and np.all(blk[50:, 1] == 0.0),
          "a shorter stem did not simply end")
    # A stem routed past the last output is refused, not wrapped.
    try:
        m2.add_cue("y", [(np.zeros((10, 1), np.float32), 1.0, [2])])
        check(False, "a stem routed past the last output was accepted")
    except ValueError:
        pass
    print("  ok")


def test_audio_master_timecode_follows_the_audio():
    section("audio_master: the timecode follows the audio device")
    for block, drift in ((480, 0.0), (2400, 0.0), (480, 1500.0)):
        r = _am_rig(block=block, drift_ppm=drift, seconds=4.0)
        am, sim, out, fed = r["am"], r["sim"], r["out"], r["fed"]
        t_play = r["vc"]()
        am.play(3600.0, None, "Show")
        sim.run(t_play + 3.0)
        frames = out.frames()
        check(len(frames) >= 85, f"block {block}: only {len(frames)} "
                                 f"packets in 3 s")
        first = [(t, p) for t, p, _b in r["eng"].log if p.playing]
        check(first and frames and frames[0][1] == 0
              and abs(frames[0][0] - (first[0][0] + first[0][1].latency))
              < 1e-6,
              f"block {block}: 00:00:00:00 did not go out the moment the "
              f"first sample was heard")
        check(not _am_consecutive(frames),
              f"block {block}, drift {drift}: frames skipped or repeated: "
              f"{_am_consecutive(frames)[:5]}")
        # Each frame goes out when the audio reaches it, including between
        # callbacks (block 2400 is a callback every 50 ms, under the frame
        # rate): interpolated, not stepped.
        worst = max(abs(_am_true_pos(r, t) - n / 30.0)
                    for t, n in frames[3:])
        check(worst < 0.002, f"block {block}, drift {drift}: a frame went "
                             f"out {worst * 1000:.2f} ms off the audio")
        gaps = [b[0] - a[0] for a, b in zip(frames, frames[1:])]
        check(max(abs(g - 1 / 30.0) for g in gaps[3:]) < 0.002,
              f"block {block}: the packets are not evenly spaced between "
              f"callbacks")
        # The pixels get the same position, the same way ArtNetMaster
        # gives it: cue position plus frame, stamped when the frame began.
        check(fed and all(abs(p - (3600.0 + n / 30.0)) < 1e-9
                          for (_, p, _, _), (_, n) in zip(fed, frames)),
              f"block {block}: the pixels were not fed the timecode's "
              f"position")
        check(r["am"].snapshot()["audio"]["following"],
              "the page does not say the clock follows the audio")
        am.stop()
    # With the device's crystal 1500 ppm fast, the timecode runs fast with
    # it: it follows the audio, not this computer's clock.
    print("  ok")


def test_audio_master_hold_resume_and_abort():
    section("audio_master: Hold freezes on the audio's last frame, Resume "
            "carries on, Abort fades then stops")
    import numpy as np
    from ltcplay import showaudio as sa
    r = _am_rig(seconds=6.0)
    am, sim, out, eng, vc = r["am"], r["sim"], r["out"], r["eng"], r["vc"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    t_hold = vc()
    am.pause()
    check(am.paused and r["calls"]["pause"] == [],
          "the clock froze before the audio had faded")
    sim.run(vc() + 1.5)
    stop = am._frozen_sec * 48000
    check(abs(stop - (eng.proc.mixer.stop_frame)) < 1e-6
          and eng.proc.mixer.state == sa.PAUSED,
          "the clock's freeze point is not where the audio stopped")
    frozen = int(np.floor((stop - 1) * 30 / 48000.0))
    held = out.frames(since=t_hold + 0.4)
    check(held and all(n == frozen for _, n in held),
          f"the timecode did not freeze on frame {frozen} (the audio's "
          f"last): {sorted({n for _, n in held})}")
    check(28 <= len([1 for t, _ in held if t < t_hold + 1.4]) <= 31,
          "the frozen frame is not repeated 30 times a second")
    check(len(r["calls"]["pause"]) == 1 and
          t_hold + 0.25 <= r["calls"]["pause"][0] <= t_hold + 0.25 + 0.06,
          f"on_pause was not called once, as the audio stopped: "
          f"{r['calls']['pause']}")
    # No run-on: nothing but silence was played from the stop point on.
    after = [(t, p, b) for t, p, b in eng.log if t > t_hold]
    loud = [p.frame for t, p, b in after if np.any(b != 0.0)]
    check(loud and max(loud) < stop,
          "sound was played after the Hold stopped the audio")
    last_played = max(p.frame + len(b) for t, p, b in after
                      if np.any(b != 0.0))
    check(last_played <= stop + 480, "the audio ran on past its stop point")
    fed = [p for t, p, _a, _x in r["fed"] if t > t_hold + 0.3]
    check(fed and all(abs(p - (3600.0 + frozen / 30.0)) < 1e-9
                      for p in fed),
          "the pixels were not held on the frozen frame")
    # Resume: the audio carries on from the exact sample it stopped on.
    t_res = vc()
    sent = []
    real_send = eng.send
    eng.send = lambda msg: (sent.append(msg), real_send(msg))[1]
    am.resume()
    eng.send = real_send
    check([m[0] for m in sent] == ["resume"],
          f"Resume did not ask the audio process to resume: {sent}")
    sim.run(vc() + 1.0)
    first = [(t, p, b) for t, p, b in eng.log if t > t_res and p.playing]
    check(first and first[0][1].frame == int(stop),
          f"the audio resumed at {first[0][1].frame if first else None}, "
          f"not at {int(stop)} where it stopped")
    check(first and abs(float(first[0][2][0, 0])) < 0.01,
          "the audio did not fade back in")
    moving = [n for t, n in out.frames(since=t_res) if n != frozen]
    check(moving and moving[0] == frozen + 1 and not _am_consecutive(
        [(0, n) for n in moving]),
          f"the timecode did not carry on from frame {frozen + 1}: "
          f"{moving[:3]}")
    check(len(r["calls"]["resume"]) == 1, "on_resume was not called once")
    worst = max(abs(_am_true_pos(r, t) - n / 30.0)
                for t, n in out.frames(since=t_res + 0.2))
    check(worst < 0.002, f"after Resume the timecode is {worst * 1000:.1f} "
                         f"ms off the audio")
    # Resume pressed inside the Hold's own fade: the Hold finishes, then
    # the Resume runs from the same sample.
    am.pause()
    sim.run(vc() + 0.1)
    am.resume()
    sim.run(vc() + 1.0)
    check(not am.paused and len(r["calls"]["pause"]) == 2
          and len(r["calls"]["resume"]) == 2,
          "Resume during the Hold's fade was lost")
    # Abort: the level fades to zero over a second, then everything stops.
    t_abort = vc()
    am.halt()
    check(am.playing and r["calls"]["stop"] == [],
          "Abort stopped at once instead of fading")
    sim.run(vc() + 1.5)
    check(len(r["calls"]["stop"]) == 1 and
          t_abort + 1.0 <= r["calls"]["stop"][0] <= t_abort + 1.2,
          f"Abort did not stop after its 1 s fade: {r['calls']['stop']}")
    lv = [(t, float(np.max(np.abs(b)))) for t, p, b in eng.log
          if t_abort < t < t_abort + 1.2]
    mid = [v for t, v in lv if t_abort + 0.45 < t < t_abort + 0.55]
    check(mid and 0.2 < max(mid) < 0.3 and max(v for t, v in lv
                                                if t < t_abort + 0.05) > 0.45,
          "the Abort fade is not a fade")
    check(all(v == 0.0 for t, v in lv if t > t_abort + 1.05),
          "sound kept coming after Abort's fade")
    check(not out.frames(since=r["calls"]["stop"][0] + 1e-9),
          "timecode kept going after Abort stopped the cue")
    check(not am.playing and "stopped" in am.last_ended,
          f"after Abort: playing={am.playing} {am.last_ended!r}")
    check(eng.proc.mixer.level == 1.0,
          "the level was left at zero for the next cue")
    # The next cue plays at full level.
    am.play(7200.0, None, "Intermission")
    sim.run(vc() + 0.5)
    check(out.frames(since=vc() - 0.3) and eng.proc.mixer.level == 1.0,
          "the cue after an Abort did not play")
    am.stop()
    print("  ok")


def test_audio_master_device_loss_freeruns_and_returns():
    section("audio_master: the interface lost mid-show, the show carries on, "
            "the audio comes back and the clock follows it again")
    import numpy as np
    # Big buffers (50 ms), and a driver that says its latency is 0 while
    # its buffers are really heard 20 ms later: the audio comes back a
    # little away from where the clock is, and that has to be slewed out.
    r = _am_rig(seconds=30.0, block=2400, reported_latency=0.0)
    am, sim, out, eng, vc = r["am"], r["sim"], r["out"], r["eng"], r["vc"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    # A monitor's HDMI audio appearing and going away must not disturb a
    # stream that is working.
    opens, inits = eng.proc.opens, eng.sd.inits
    eng.sd.control("add", "LG TV (NVIDIA High Definition Audio)")
    sim.run(vc() + 0.5)
    eng.sd.control("remove", "LG TV (NVIDIA High Definition Audio)")
    sim.run(vc() + 0.5)
    check(eng.proc.opens == opens and eng.sd.inits == inits
          and am.snapshot()["audio"]["following"] and not am._fault,
          "a device appearing and disappearing disturbed a healthy stream")
    # Pull the interface.
    tries = []
    real_try = eng.proc._try_open
    eng.proc._try_open = lambda now: (tries.append(now), real_try(now))[1]
    t_pull = vc()
    eng.sd.control("unplug")
    sim.run(vc() + 1.0)
    check(am._mode == "freerun" and am.losses == 1,
          f"losing the interface did not put the show on its own clock: "
          f"{am._mode}")
    warn = " ".join(am.health_warnings())
    check("dropped out" in warn and "carries on" in warn,
          f"health does not say the audio dropped out: {warn}")
    check(len(r["journal"].faults) == 1 and
          "dropped out" in r["journal"].faults[0][1],
          f"no journal line for the dropout: {r['journal'].faults}")
    check(any("dropped out" in m for k, m in r["log"].lines),
          "the show log does not say the audio dropped out")
    snap = am.snapshot()
    check(snap["audio"]["connected"] is False and snap["audio"]["fault"],
          "the page does not show the interface lost")
    from ltcplay import display as disp_mod
    check(any("dropped out" in w for w in disp_mod.clock_warnings(am)),
          "the page's red list does not carry the dropout")
    sim.run(t_pull + 8.0)
    lost_at = [t for t, _p, _b in eng.log][-1]
    rel = [round(t - tries[0], 2) for t in tries]
    check(len(tries) >= 4 and all(abs(a - b) < 0.1 for a, b in
                                  zip(rel, [0.0, 1.0, 3.0, 6.0]))
          and 1.4 < tries[0] - lost_at < 1.6,
          f"the reopen attempts are not every 1 s backing off to 3 s: "
          f"{rel}, first {tries[0] - lost_at:.2f} s after the loss")
    # Back.
    t_plug = vc()
    eng.sd.control("plug")
    ok = sim.until(lambda: am._mode == "follow", 12.0)
    check(ok, f"the audio came back but the clock never followed it again "
              f"(mode {am._mode})")
    t_back = vc()
    check(am.returns == 1 and not am._fault
          and not am.health_warnings(),
          f"health did not clear when the audio came back: "
          f"{am.health_warnings()}")
    check(r["journal"].records and "is back" in
          r["journal"].records[-1]["text"],
          "no journal line for the audio coming back")
    sim.run(vc() + 1.0)
    frames = out.frames()
    check(not _am_consecutive(frames),
          f"the timecode jumped somewhere through the loss and the return: "
          f"{_am_consecutive(frames)[:5]}")
    gaps = [b[0] - a[0] for a, b in zip(frames[3:], frames[4:])]
    check(max(gaps) < 1 / 30.0 * 1.05 + 0.001
          and min(gaps) > 1 / 30.0 * 0.95 - 0.001,
          f"the timecode stepped (a packet gap of {max(gaps) * 1000:.1f} or "
          f"{min(gaps) * 1000:.1f} ms): never slewed faster than 5%")
    # The audio restarted at the show's current position, faded in.
    back = [(t, p, b) for t, p, b in eng.log if t > t_plug and p.playing]
    heard = back[0][0] + back[0][1].latency
    clock_pos = heard - [e for t, e, m in sim.trace if t <= heard][-1]
    offset = back[0][1].frame / 48000.0 - clock_pos
    check(abs(offset) < 0.06,
          f"the audio came back at {back[0][1].frame / 48000.0:.3f} s, the "
          f"show was at {clock_pos:.3f} s")
    t_in = back[0][0]
    lv = [(t - t_in, float(np.max(np.abs(b)))) for t, p, b in back]
    early = [v for t, v in lv if t < 0.1]
    mid = [v for t, v in lv if 0.45 < t < 0.55]
    late = [v for t, v in lv if 1.1 < t < 1.5]
    check(early and max(early) < 0.08 and mid and 0.15 < max(mid) < 0.32
          and late and min(late) > 0.45,
          f"the returning audio did not fade in over a second: "
          f"{early[:2]} {mid[:2]} {late[:2]}")
    # The handover slewed: the epoch never moved faster than 5% of the
    # time that passed.
    tr = [(t, e) for t, e, m in sim.trace if t_plug <= t <= t_back
          and e is not None]
    fast = [(b[1] - a[1]) / (b[0] - a[0]) for a, b in zip(tr, tr[1:])
            if b[0] - a[0] > 1e-4]
    check(fast and max(abs(x) for x in fast) <= 0.0501,
          "the handover moved the clock faster than a 5% slew")
    t_follow = [t for t, e, m in sim.trace if t > t_plug and m == "return"]
    took = t_follow[-1] - t_follow[0] if t_follow else 0.0
    check(abs(offset) > 0.005 and
          abs(offset) / 0.05 - 0.1 < took < abs(offset) / 0.05 + 0.2,
          f"a {offset * 1000:.1f} ms handover offset took {took:.2f} s to "
          f"slew out, not about {abs(offset) / 0.05:.2f} s")
    worst = max(abs(_am_true_pos(r, t) - n / 30.0)
                for t, n in out.frames(since=t_back + 0.3))
    check(worst < 0.002, f"after the return the timecode is "
                         f"{worst * 1000:.1f} ms off the audio")
    # The audio process dying counts the same way, and a new one takes
    # over.
    eng.crash()
    sim.run(vc() + 0.5)
    check(am._mode == "freerun" and am.losses == 2,
          "the audio process dying was not treated as losing the audio")
    eng.respawn()
    ok = sim.until(lambda: am._mode == "follow", 8.0)
    check(ok and am.returns == 2, "the new audio process did not take over")
    check(not _am_consecutive(out.frames()),
          "the timecode jumped when the audio process died")
    # Audio that comes back far from where the show is (here a quarter of
    # a second and more) is not slewed for minutes: the handover is tried
    # again.
    eng.sd.control("unplug")
    sim.run(vc() + 1.0)
    am.LEAD_S = 0.6
    eng.sd.control("plug")
    ok = sim.until(lambda: any("did not come back" in m and "away from the "
                               "show" in m for k, m in r["log"].lines), 12.0)
    check(ok and am._mode != "follow",
          "audio that came back far from the show was slewed, not re-tried")
    type(am).LEAD_S and delattr(am, "LEAD_S")
    ok = sim.until(lambda: am._mode == "follow", 12.0)
    check(ok and not _am_consecutive(out.frames()),
          "the retried handover did not take, or the timecode jumped")
    am.stop()
    print("  ok")


def test_audio_master_the_audio_ending_ends_the_cue():
    section("audio_master: the end of the audio is the end of the cue")
    r = _am_rig(seconds=1.0)
    am, sim, out, vc = r["am"], r["sim"], r["out"], r["vc"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    frames = [n for _, n in out.frames()]
    check(frames == list(range(30)),
          f"a 1 s cue sent frames {frames[:3]}..{frames[-3:]}, not 0 to 29")
    check(len(r["calls"]["stop"]) == 1 and not am.playing
          and am.last_ended == "Show finished",
          f"the audio ending did not stop the cue the normal way: "
          f"{r['calls']['stop']} {am.last_ended!r}")
    end = r["calls"]["stop"][0]
    heard_end = _am_true_pos(r, end)
    check(heard_end is not None and 1.0 - 1e-6 <= heard_end < 1.0 + 1 / 30.0,
          f"the cue ended at {heard_end}, not when its audio did")
    # With no interface a show does not start at all (Jeff, 2026-09-27):
    # a sentence on the page, in the log, and nothing sent.
    from ltcplay import clock as clock_mod
    r2 = _am_rig(seconds=1.0)
    r2["eng"].sd.control("unplug")
    r2["sim"].run(r2["vc"]() + 1.0)
    try:
        r2["am"].play(3600.0, None, "Show")
        check(False, "a show started with its audio interface missing")
    except clock_mod.ClockConfigError as e:
        check("will not start" in str(e) and "Show DSP" in str(e)
              and str(e).endswith("."), f"the refusal: {e}")
        check(any("will not start" in m for k, m in r2["log"].lines),
              "the refusal is not in the show log")
    r2["sim"].run(r2["vc"]() + 1.0)
    check(not r2["out"].sent and not r2["am"].playing
          and not r2["calls"]["stop"],
          "something was sent for a show that did not start")
    check(r2["am"].health_warnings(), "no interface, and health is clear")
    # A cue with no audio cannot play under audio_master.
    try:
        r["am"].play(0.0, 10.0, "Preshow")
        check(False, "a cue with no audio played under audio_master")
    except clock_mod.ClockConfigError as e:
        check("has no show audio" in str(e), f"the refusal: {e}")
    r["am"].stop()
    r2["am"].stop()
    print("  ok")


def test_audio_master_session_hold_resume_abort():
    section("audio_master through the session: Run, play, Hold, Resume, "
            "Abort")
    import tempfile
    from ltcplay.session import Session, SessionError
    from ltcplay import settings as st_mod, showaudio as sa
    import ltcplay.player as plmod
    work = tempfile.mkdtemp()
    real_path, real_prefs = st_mod.path, st_mod.prefs_path
    st_mod.path = lambda: os.path.join(work, st_mod.FILENAME)
    st_mod.prefs_path = lambda: os.path.join(work, st_mod.PREFS_FILE)
    real_prepare = plmod.Player._prepare

    def fake_prepare(self, cue):
        cue.fseq = FakeFSEQ(frames=4000)
        cue.duration = cue.fseq.duration_ms / 1000.0
        cue._spans = [(0, 0, cue.fseq.channel_count)]
        cue._gaps = None
        return 0

    plmod.Player._prepare = fake_prepare
    _tl, tlp, net = _am_show(work, 8.0)
    sess = None
    stop_proc = threading.Event()
    try:
        sess = Session(tlp, no_output=True, networks=net, no_log=True,
                       sd=FakeSD())
        sess.open()
        clk = sess.clock
        check(clk is not None and clk.source == "audio_master"
              and isinstance(clk.engine, sa.AudioEngine),
              "the show file asked for audio_master and did not get it")
        check("the show audio" in sess.input_summary,
              f"the input line: {sess.input_summary}")
        # The real engine would start a process; this one runs the audio
        # process's loop on a thread here, with a fake interface in real
        # time.
        spec = dict(clk.engine.spec, platform="darwin")
        arr = [0.0] * sa.SLOTS
        msgs = []
        fsd = sa.FakeSoundDevice(threaded=True, keep=False,
                                 devices=[{"name": "Show DSP", "hostapi": 0,
                                           "max_output_channels": 8}])
        proc = sa.AudioProcess(spec, fsd, sa.Publisher(arr), msgs.append,
                               sync_load=True)

        class Eng:
            respawns = 0

            def start(self, wait_s=0):
                proc.step(time.perf_counter())
                same = spec.get("same_length", {})
                for role, stems in spec["cues"].items():
                    proc.command(("load", role, stems,
                                  same.get(role, True)))

                def loop():
                    while not stop_proc.is_set():
                        proc.step(time.perf_counter())
                        time.sleep(0.01)
                threading.Thread(target=loop, daemon=True).start()
                return msgs[0] if msgs else None

            def send(self, msg):
                proc.command(msg)
                return True

            def read(self):
                return sa.read_position(arr)

            def events(self):
                out = list(msgs)
                del msgs[:]
                return out

            def close(self):
                stop_proc.set()
                proc.close(wait_s=0)

        clk.engine = Eng()
        out = _TcOut()
        clk.out = out
        sess.start()
        sess.clock_play("Show")
        check(wait_for(lambda: len(out.sent) >= 10
                       and sess.player.current_cue is not None, 3.0),
              "the show audio clock started but nothing followed it")
        check(_tc_of(out.sent[0][1])[:4] == (0, 0, 0, 0),
              "the cue's timecode did not start at 00:00:00:00")
        check(3600.0 <= sess.player.tc_seconds < 3602.0,
              f"the pixels are at {sess.player.tc_seconds}, not the show")
        sess.clock_pause()
        check(wait_for(lambda: clk._paused, 2.0),
              "Hold through the session did not freeze the clock")
        n0 = len(out.sent)
        check(wait_for(lambda: len(out.sent) - n0 >= 6, 3.0),
              "the frozen frame is not being repeated")
        held = {_tc_of(p)[:4] for _, p in out.sent[n0:]}
        check(len(held) == 1, f"the timecode moved while held: {held}")
        check(sess.snapshot()["clock"]["paused"] is True,
              "the page does not say the clock is paused")
        try:
            sess.clock_pause()
            check(False, "a second Hold was accepted")
        except SessionError:
            pass
        sess.clock_resume()
        check(wait_for(lambda: not clk._paused, 3.0),
              "Resume through the session did not unfreeze the clock")
        n1 = len(out.sent)
        check(wait_for(lambda: len({_tc_of(p)[:4]
                                    for _, p in out.sent[n1:]}) >= 4, 3.0),
              f"the timecode did not move after Resume: "
              f"{[_tc_of(p)[:4] for _, p in out.sent[n1:n1 + 5]]}")
        sess.clock_halt()
        check(clk.playing, "Abort through the session did not fade first")
        check(wait_for(lambda: not clk.playing, 2.5),
              "Abort through the session never stopped the cue")
        check(wait_for(lambda: sess.player.current_cue is None, 2.0),
              "after Abort the pixels did not go back to the idle look")
        snap = sess.snapshot()
        check(snap["clock"]["source"] == "audio_master"
              and snap["clock"]["audio"]["device"] == "Show DSP",
              f"the page does not show the audio clock: {snap['clock']}")
        sess.stop()
        sess = None
        # An interface that is there but cannot run the show refuses Run
        # with its sentence, and leaves nothing running.
        s2 = Session(tlp, no_output=True, networks=net, no_log=True,
                     sd=FakeSD())
        s2.open()

        class Refuses:
            def start(self, wait_s=0):
                return ("refused", "Show DSP has 2 output(s), but the show "
                                   "uses 8.")

            def close(self):
                pass

        s2.clock.engine = Refuses()
        try:
            s2.start()
            check(False, "Run went ahead on an interface that cannot run "
                         "the show")
        except SessionError as e:
            check("has 2 output(s)" in str(e), f"the Run refusal: {e}")
        check(not s2.running and not s2.clock.playing,
              "a refused Run left the session running")
        s2.stop()
    finally:
        stop_proc.set()
        if sess is not None:
            sess.stop()
        plmod.Player._prepare = real_prepare
        st_mod.path, st_mod.prefs_path = real_path, real_prefs
    print("  ok")


def test_audio_master_runs_in_its_own_process():
    section("audio_master: the audio plays in its own process, and a new "
            "one takes over if it dies")
    import tempfile
    from ltcplay import showaudio as sa
    work = tempfile.mkdtemp()
    tl, _t, _n = _am_show(work, 3.0)
    checked = sa.check_show(tl.clock.audio, tl)
    spec = sa.engine_spec(tl.clock.audio, checked, platform="darwin",
                          fake={"devices": [{"name": "Show DSP",
                                             "hostapi": 0,
                                             "max_output_channels": 8}]})
    spec["lock"] = os.path.join(work, "audio.lock")
    eng = sa.AudioEngine(spec)
    eng.RESPAWN_S = (0.2, 0.2, 0.2)
    seen = []

    def got(kind, limit=10.0):
        end = time.time() + limit
        while time.time() < end:
            seen.extend(eng.events())
            if any(e[0] == kind for e in seen):
                return True
            time.sleep(0.02)
        return False

    try:
        first = eng.start()
        check(first is not None and first[0] == "opened",
              f"the audio process did not open the interface: {first}")
        check(eng.pid and eng.pid != os.getpid() and eng.alive
              and eng._ctx.get_start_method() == "spawn",
              "the audio is not in a spawned process of its own")
        check(abs(eng.offset) < 0.01,
              f"the audio process's clock is {eng.offset:.4f} s off this "
              f"one's")
        check(got("loaded"), f"the show audio did not load: {seen}")
        eng.send(("play", "show", 0, 0, 5))
        check(wait_for(lambda: (eng.read() or sa.Position(*[0] * 13))
                       .frame > 24000, 3.0),
              "the audio process's position did not advance")
        p = eng.read()
        check(p.token == 5 and p.playing and p.callbacks > 10
              and abs(time.perf_counter() - p.perf) < 0.5,
              f"the shared position is wrong: {p}")
        eng.send(("pause", 480, 5))
        time.sleep(0.2)
        a = eng.read().frame
        time.sleep(0.2)
        check(eng.read().frame == a and eng.read().stop_frame == a,
              "the audio kept moving after a pause in its own process")
        pid = eng.pid
        del seen[:]
        eng.send(("fake", "crash"))
        check(got("crashed", 5.0), "the audio process died and nobody "
                                   "noticed")
        check(got("respawned", 8.0) and got("opened", 5.0)
              and got("loaded", 5.0) and eng.pid != pid and eng.alive,
              f"no new audio process took over: {seen}")
    finally:
        eng.close()
    check(not eng.alive, "the audio process outlived close()")
    print("  ok")


def test_the_gpl_path_never_loads_the_show_audio():
    section("GPL and artnet_master: the show audio code is never loaded")
    import json, subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    top = []
    for name in sorted(os.listdir(os.path.join(here, "ltcplay"))):
        if not name.endswith(".py") or name == "showaudio.py":
            continue
        for i, line in enumerate(open(os.path.join(here, "ltcplay", name),
                                      encoding="utf-8"), 1):
            if re.match(r"(from \.showaudio |from \. import .*\bshowaudio\b|"
                        r"import ltcplay\.showaudio|from ltcplay import .*"
                        r"\bshowaudio\b)", line):
                top.append(f"{name}:{i}")
    check(not top, f"the show audio is imported at module scope: {top}")
    script = r'''
import json, os, sys, tempfile, time
sys.path.insert(0, sys.argv[1])
import selftest as T
from ltcplay import settings as st_mod
from ltcplay.session import Session
import ltcplay.player as plmod
import ltcplay.web, ltcplay.cli
work = tempfile.mkdtemp()
st_mod.path = lambda: os.path.join(work, st_mod.FILENAME)
st_mod.prefs_path = lambda: os.path.join(work, st_mod.PREFS_FILE)


def fake_prepare(self, cue):
    cue.fseq = T.FakeFSEQ(frames=4000)
    cue.duration = cue.fseq.duration_ms / 1000.0
    cue._spans = [(0, 0, cue.fseq.channel_count)]
    cue._gaps = None
    return 0
plmod.Player._prepare = fake_prepare
res = {}
for label, clock_doc in (("gpl", None),
                         ("artnet", {"source": "artnet_master",
                                     "artnet": {"nodes": {"M": "127.0.0.1"}}})):
    d = tempfile.mkdtemp(dir=work)
    tlp, net = T._clock_show(d, clock_doc, [("01:00:00:00", "S.fseq", "S")])
    s = Session(tlp, no_output=True, networks=net, no_log=True,
                sd=T.FakeSD(), device="MOTU M4", channel=2)
    s.open(); s.start()
    if label == "artnet":
        s.clock.out = T._TcOut()
        s.clock_play()
        s.clock_pause(); s.clock_resume(); s.clock_halt()
    time.sleep(0.3)
    s.snapshot()
    s.stop()
    res[label] = sorted(m for m in sys.modules
                        if m == "ltcplay.showaudio"
                        or m.startswith("multiprocessing"))
print(json.dumps(res))
import shutil; shutil.rmtree(work, ignore_errors=True)
'''
    r = _sp.run([sys.executable, "-c", script, here], capture_output=True,
                text=True, timeout=120)
    try:
        res = json.loads(r.stdout.strip().splitlines()[-1])
    except Exception:
        check(False, f"the GPL/artnet check did not run: {r.stdout[-400:]} "
                     f"{r.stderr[-800:]}")
        return
    check("ltcplay.showaudio" not in res["gpl"],
          "a GPL run imported the show audio")
    check("ltcplay.showaudio" not in res["artnet"],
          "an artnet_master run imported the show audio")
    check(not res["gpl"] and not res["artnet"],
          f"a run without audio_master loaded multiprocessing: {res}")
    print("  ok")


class _AmJitterEngine(_AmLocalEngine):
    """A driver that enters its callback a few ms late at random, and can
    report a latency spike on chosen callbacks, while the sound is really
    heard a steady `latency` after each callback (review of PR 26)."""

    jitter = (0.0, 0.003)
    spikes = {}

    def __init__(self, *a, **k):
        import random
        self.rng = random.Random(7)
        self.n = 0
        super().__init__(*a, **k)

    def run_at(self, t):
        if self.crashed:
            return
        if self._next is not None and t >= self._next - 1e-12 \
                and self.proc.stream is self._stream:
            from ltcplay import showaudio as sa
            import numpy as np
            j = self.rng.uniform(*self.jitter)
            extra = self.spikes.get(self.n, 0.0)
            self.n += 1
            real = self.proc._clock
            self.proc._clock = lambda: t + j
            s = self._stream
            out = np.zeros((s.sd.block, s.channels), dtype=np.float32)
            if s.running and not s.closed and s.dev["present"]:
                s.callback(out, s.sd.block,
                           sa._TimeInfo(t + j + s.sd.latency + extra, t + j),
                           sa._Flags(False))
                p = self.read()
                self.log.append((t + j, p._replace(latency=s.sd.latency),
                                 out))
            self.proc._clock = real
            self._next += self.period
        if t >= self._next_step - 1e-12:
            self.proc.step(t)
            self._next_step = t + 0.02


def _am_jitter_rig(drift=0.0, seconds=20.0, spikes=None):
    """_am_rig with the jittery driver, and the clock thread itself woken
    0 to 4 ms late, and now and then 25 ms late."""
    import random
    global _AmLocalEngine
    real = _AmLocalEngine
    _AmJitterEngine.spikes = spikes or {}
    _AmLocalEngine = _AmJitterEngine
    try:
        r = _am_rig(seconds=seconds, drift_ppm=drift)
    finally:
        _AmLocalEngine = real
    rng = random.Random(11)
    sim = r["sim"]

    def run(until):
        vc = sim.vc
        if sim.am.kicked:
            sim.am.kicked = False
            sim.next_am = vc()
        while True:
            t = min(sim.next_am, sim.eng.next_time())
            if t > until:
                vc.t = until
                return
            vc.t = t
            sim.eng.run_at(t)
            if t >= sim.next_am - 1e-12:
                due = sim.am.step(t)
                sim.trace.append((t, sim.am._epoch, sim.am._mode))
                late = rng.uniform(0.0, 0.004)
                if rng.random() < 0.002:
                    late += 0.025
                sim.next_am = max(due, t + 1e-6) + late
    sim.run = run
    return r


def _am_errors(r, since):
    fr = r["out"].frames(since=since)
    n = [x for _, x in fr]
    back = [(a, b) for a, b in zip(n, n[1:]) if b <= a]
    skip = [(a, b) for a, b in zip(n, n[1:]) if b > a + 1]
    errs = [(_am_true_pos(r, t) - x / 30.0, t) for t, x in fr
            if _am_true_pos(r, t) is not None]
    return fr, back, skip, errs


def test_audio_master_review_rules():
    section("audio_master: the review's rules (late start, stale readings, "
            "frozen frame floor, spikes, stalls, Hold in odd places)")
    import numpy as np
    from ltcplay import showaudio as sa

    # A clock thread 250 ms late to a new cue still starts it at
    # 00:00:00:00, then goes straight to where the audio is.
    r = _am_rig(seconds=6.0)
    am, sim, vc = r["am"], r["sim"], r["vc"]
    t0 = vc()
    am.play(3600.0, None, "Show")
    am.kicked = False
    sim.next_am = t0 + 0.25
    sim.run(t0 + 1.0)
    n = [x for _, x in r["out"].frames(since=t0)]
    check(n[:1] == [0] and 6 <= n[1] <= 8 and not _am_consecutive(
        [(0, x) for x in n[1:]]),
          f"a cue reached 250 ms late did not start at 00:00:00:00 and "
          f"then follow the audio: {n[:5]}")
    # A reading from an older play or another cue moves nothing.
    ep, mode = am._epoch, am._mode
    pos = sa.read_position(r["eng"].arr)
    am._on_reading(pos._replace(seq=pos.seq + 1001, token=am._token - 1,
                                frame=pos.frame - 960), vc())
    check(am._epoch == ep and am._mode == mode,
          "a reading from an older play moved the clock")
    # The frozen frame is never below the last frame sent.
    with am._lock:
        am._stop_frame = 24000              # frame 14
        last = am._last_frame
        am._pause_req = True
        am._freeze(vc())
    check(am._frozen_frame == last and last > 14,
          f"the clock froze on frame {am._frozen_frame}, below the "
          f"{last} it had already sent")
    am.stop()

    # The seqlock: a read that sees a write in progress, or a write
    # between its two looks, reads again.
    class Torn(list):
        def __init__(self, passes):
            super().__init__([0.0] * sa.SLOTS)
            self.passes, self.looks = passes, 0

        def __getitem__(self, k):
            if k == sa.SEQ:
                v = self.passes[min(self.looks, len(self.passes) - 1)]
                self.looks += 1
                return v
            if isinstance(k, slice):
                body = [7.0 if self.looks < 4 else 8.0] * (
                    sa.ERRORS - sa.TOKEN + 1)
                return body
            return super().__getitem__(k)

    got = sa.read_position(Torn([3.0, 4.0, 6.0, 6.0, 6.0, 6.0]))
    check(got is not None and got.seq == 6 and got.token == 8,
          f"a torn read was returned instead of read again: {got}")

    # A driver whose latency report spikes (0.88 s, then 0.48 s) moves
    # nothing; nor does a PC clock 100 ppm either way, with the callbacks
    # and the clock thread both jittering.
    for drift, spikes in ((100.0, {}), (-100.0, {}),
                          (0.0, {500: 0.88, 900: 0.48})):
        r = _am_jitter_rig(drift, 20.0, spikes)
        t0 = r["vc"]()
        r["am"].play(3600.0, None, "Show")
        r["sim"].run(t0 + 16.0)
        fr, back, skip, errs = _am_errors(r, t0)
        late = max(abs(e) for e, t in errs if t > t0 + 1.0)
        tail = max(abs(e) for e, t in errs if t > t0 + 10.0)
        check(len(fr) > 450 and not back and not skip,
              f"drift {drift}, spikes {spikes}: frames backwards {back[:3]} "
              f"or skipped {skip[:3]}")
        check(tail < 0.008 and late < 0.035,
              f"drift {drift}, spikes {spikes}: the timecode strayed "
              f"{late * 1000:.1f} ms (last 6 s {tail * 1000:.1f} ms) from "
              f"the audio")
        if spikes:
            check(r["am"].outliers >= 2,
                  "the latency spikes were not recognised as spikes")
        r["am"].stop()

    # A 350 ms hiccup in the driver (callbacks pause, the stream stays
    # open) is not a loss: the music is not stopped and reopened, the
    # clock just waits for the audio.
    r = _am_rig(seconds=10.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    dev = eng.proc.stream.dev
    th = vc()
    dev["present"] = False
    sim.run(vc() + 0.35)
    dev["present"] = True
    sim.run(vc() + 3.0)
    silent = [t for t, p, b in eng.log if t > th and not np.any(b != 0)]
    fr, back, skip, _e = _am_errors(r, 0)
    check(am.losses == 0 and eng.proc.opens == 1 and not silent
          and not r["journal"].faults and not back,
          f"a 0.35 s hiccup became a loss: losses {am.losses}, opens "
          f"{eng.proc.opens}, silent callbacks {len(silent)}")
    worst = max(abs(_am_true_pos(r, t) - x / 30.0)
                for t, x in fr if t > th + 1.0)
    check(worst < 0.002, f"after a hiccup the timecode is "
                         f"{worst * 1000:.1f} ms off the audio")
    # Longer than the clock's own limit, but the audio process has not
    # given up on the stream (a hung child, say): when the same stream
    # plays on, the clock follows it again, and the music was never
    # stopped.
    eng.proc.STALL_S = 5.0
    sent = []
    real_send = eng.send
    eng.send = lambda msg: (sent.append(msg), real_send(msg))[1]
    th = vc()
    dev["present"] = False
    sim.run(vc() + 0.8)
    check(am.losses == 1 and am._mode == "freerun",
          "0.8 s with no audio was not treated as a loss")
    dev["present"] = True
    sim.run(vc() + 2.0)
    eng.send = real_send
    check(am._mode == "follow" and not am._fault and am.returns == 1
          and not [m for m in sent if m[0] in ("stop", "play")]
          and eng.proc.opens == 1,
          f"the same stream playing on was not followed again: mode "
          f"{am._mode}, sent {sent}")
    check(not _am_errors(r, 0)[1], "the timecode went backwards")
    # The audio process stopping the sound with nothing asking it to is a
    # loss, not something to follow quietly.
    eng.send(("stop", 0, None))
    sim.run(vc() + 0.3)
    check(am.losses == 2 and am._fault and "stopped playing" in am._fault,
          f"sound that stopped by itself was not a loss: {am._fault}")
    ok = sim.until(lambda: am._mode == "follow", 8.0)
    check(ok and not am._fault, "the audio did not come back after that")
    # Errors making the sound reach the page.
    real_render = eng.proc.mixer.render
    boom = [1]

    def render(n):
        if boom:
            boom.pop()
            raise RuntimeError("test")
        return real_render(n)

    eng.proc.mixer.render = render
    sim.run(vc() + 0.2)
    check(any("error(s) making the sound" in w
              for w in am.health_warnings()),
          f"an error in the audio process did not reach the page: "
          f"{am.health_warnings()}")
    am.stop()

    # Hold during a loss: freezes at once, repeats the frame; Resume
    # carries on on this computer's clock; the audio comes back after.
    r = _am_rig(seconds=30.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    eng.sd.control("unplug")
    sim.run(vc() + 1.0)
    th = vc()
    am.pause()
    check(am._paused and len(r["calls"]["pause"]) == 1,
          "Hold during a loss did not freeze at once")
    sim.run(vc() + 1.0)
    held = r["out"].frames(since=th + 0.05)
    check(len(held) >= 28 and len({x for _, x in held}) == 1,
          "Hold during a loss did not keep repeating the frozen frame")
    frozen = held[0][1]
    tr = vc()
    am.resume()
    sim.run(vc() + 0.5)
    moving = [x for _, x in r["out"].frames(since=tr)]
    check(moving and moving[0] in (frozen, frozen + 1) and moving[-1] > frozen
          + 10 and am._fault,
          "Resume during a loss did not carry on from the frozen frame")
    eng.sd.control("plug")
    ok = sim.until(lambda: am._mode == "follow", 12.0)
    check(ok and not am._fault and not _am_consecutive(
        [(0, x) for x in moving[1:]]), "the audio did not come back")
    am.stop()

    # Hold during the handover slew, then Resume: the red clears.
    r = _am_rig(seconds=30.0, block=2400, reported_latency=0.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    eng.sd.control("unplug")
    sim.run(vc() + 3.0)
    eng.sd.control("plug")
    sim.until(lambda: am._mode == "return" and am._target is not None, 10.0)
    am.pause()
    sim.run(vc() + 1.0)
    am.resume()
    sim.run(vc() + 2.0)
    check(am._mode == "follow" and not am._fault and not
          am.health_warnings() and r["journal"].records,
          f"Hold during the handover left health red: {am._fault}")
    am.stop()

    # Hold inside the last fade, then Resume: the cue simply ends.
    r = _am_rig(seconds=3.0)
    am, sim, vc = r["am"], r["sim"], r["vc"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.93)
    am.pause()
    sim.run(vc() + 1.0)
    am.resume()
    sim.run(vc() + 2.0)
    check(not r["journal"].faults and am.losses == 0
          and am.last_ended == "Show finished"
          and len(r["calls"]["stop"]) == 1,
          f"Resume at the very end gave {r['journal'].faults} "
          f"{am.last_ended!r}")
    am.stop()

    # Abort waits until its fade has been HEARD, not just sent.
    r = _am_rig(seconds=6.0, latency=0.1)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    am.play(3600.0, None, "Show")
    sim.run(vc() + 2.0)
    ta = vc()
    am.halt()
    sim.run(vc() + 2.0)
    stop = r["calls"]["stop"][0]
    heard = [t + p.latency for t, p, b in eng.log
             if t > ta and np.any(b != 0)]
    check(stop - ta >= 1.1 and heard and max(heard) <= stop,
          f"Abort stopped the cue {stop - ta:.2f} s in, before the last of "
          f"its fade was heard at {max(heard) - ta:.2f} s")
    am.stop()

    # The show's music has silences longer than half a second. Losing the
    # audio means the stream stopped moving, never that it went quiet: a
    # cue with 5 s of exact zeros at its start, in its middle and at its
    # end plays through with no loss, no stall, no fault, health clear.
    r = _am_rig(seconds=20.0, silences=((0.0, 5.0), (7.0, 12.0),
                                        (15.0, 20.0)))
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    t0 = vc()
    am.play(3600.0, None, "Show")
    warned = []
    while vc() < t0 + 21.0:
        sim.run(vc() + 0.5)
        warned += am.health_warnings()
    quiet = [t for t, p, b in eng.log if p.playing and not np.any(b != 0)]
    check(len(quiet) > 1400, "the silent stretches were not silent")
    check(am.losses == 0 and eng.proc.opens == 1 and not warned
          and not r["journal"].faults and am.last_ended == "Show finished"
          and not _am_consecutive(r["out"].frames(since=t0)),
          f"digital silence was taken for a lost interface: losses "
          f"{am.losses}, opens {eng.proc.opens}, faults "
          f"{r['journal'].faults}, health {warned[:1]}")
    am.stop()

    # WAV files whose data size cannot be true are refused, not played.
    import struct, tempfile
    work = tempfile.mkdtemp()
    good = os.path.join(work, "good.wav")
    _am_write_wav(good, _am_tone(0.2, 1))
    raw = open(good, "rb").read()
    at = raw.index(b"data") + 4
    for size, want in ((0, "placeholder"), (0xFFFFFFFF, "placeholder"),
                       (len(raw), "cut off")):
        p = os.path.join(work, f"bad{size}.wav")
        open(p, "wb").write(raw[:at] + struct.pack("<I", size) +
                            raw[at + 4:])
        try:
            sa.wav_info(p)
            check(False, f"a WAV claiming {size} bytes of audio was taken")
        except sa.AudioConfigError as e:
            check(want in str(e) and str(e).endswith("."),
                  f"the size refusal is not a plain sentence: {e}")
    # Decoded a chunk at a time, the samples are the same.
    x = _am_tone(0.05, 3, 0.6)
    for fmt in ("pcm16", "pcm24", "float32"):
        p = os.path.join(work, f"c_{fmt}.wav")
        _am_write_wav(p, x, fmt=fmt)
        whole = sa.read_wav(p)
        real = sa.READ_CHUNK_FRAMES
        sa.READ_CHUNK_FRAMES = 7
        try:
            parts = sa.read_wav(p)
        finally:
            sa.READ_CHUNK_FRAMES = real
        check(parts.shape == whole.shape and np.array_equal(parts, whole)
              and np.max(np.abs(whole - x)) < 1e-4,
              f"decoding {fmt} in chunks changed the samples")
    print("  ok")


def test_audio_master_stop_during_a_respawn():
    section("audio_master: Stop while the audio process is being replaced, "
            "then Run, leaves one process and one watch thread; a second "
            "audio process is refused")
    import multiprocessing
    import signal
    from ltcplay import showaudio as sa
    import tempfile
    spec = {"device": "Fake Interface", "channels": 2, "rate": 48000,
            "allow_shared": False, "cues": {}, "platform": "darwin",
            "fake": {"threaded": True},
            "lock": os.path.join(tempfile.mkdtemp(), "audio.lock")}

    def ours():
        return [p for p in multiprocessing.active_children()
                if p.name == "ltcplay-show-audio"]

    def watches():
        return sum(t.name == "ltcplay-audio-watch" and t.is_alive()
                   for t in threading.enumerate())

    eng = sa.AudioEngine(spec)
    eng.RESPAWN_S = (0.1, 0.1, 0.1)
    try:
        first = eng.start()
        check(first is not None and first[0] == "opened",
              f"the audio process did not start: {first}")
        real = eng._hello

        def slow(p, conn, stop):
            time.sleep(2.0)            # numpy's import on a slow PC
            return real(p, conn, stop)

        eng._hello = slow
        os.kill(eng.pid, signal.SIGKILL) if hasattr(signal, "SIGKILL") \
            else eng._proc.kill()
        time.sleep(0.5)                # noticed; the new one is starting
        t = time.perf_counter()
        eng.close()
        took = time.perf_counter() - t
        check(took < 1.0, f"Stop waited {took:.1f} s for the audio process")
        eng._hello = real
        first = eng.start()
        check(first is not None and first[0] == "opened",
              f"Run after that did not start the audio: {first}")
        time.sleep(1.0)
        check(len(ours()) == 1 and watches() == 1,
              f"after Stop then Run: {len(ours())} audio processes, "
              f"{watches()} watch threads")
        check(eng.alive and eng.pid == ours()[0].pid if ours() else False,
              "the engine is not talking to the process that is running")
    finally:
        eng.close()
    check(wait_for(lambda: not ours(), 3.0),
          f"{len(ours())} audio process(es) outlived the last close")

    # One audio process per user, by an operating-system lock: a second
    # one refuses with a sentence and exits, and the engine says so.
    from ltcplay import onlyone
    check(os.path.dirname(sa.lock_path()) == os.path.dirname(onlyone.path())
          and sa.lock_path().endswith(sa.LOCK_FILE),
          f"the audio lock is not beside ltcplay's own: {sa.lock_path()}")
    a = sa.AudioEngine(dict(spec))
    b = sa.AudioEngine(dict(spec, lock_wait_s=0.3))
    try:
        check((a.start() or ("",))[0] == "opened",
              "the first audio process did not open")
        got = b.start()
        check(got is not None and got[0] == "refused"
              and "Another show audio process is already running" in got[1]
              and got[1].endswith("."),
              f"a second audio process was not refused: {got}")
        check(wait_for(lambda: len(ours()) == 1, 3.0) and not b.alive,
              f"{len(ours())} audio processes are running at once")
        a.close()
        check(wait_for(lambda: not ours(), 3.0),
              "the first audio process did not go")
        got = b.start()
        check(got is not None and got[0] == "opened",
              f"the lock was not released when its process went: {got}")
    finally:
        a.close()
        b.close()
    check(wait_for(lambda: not ours(), 3.0),
          "an audio process outlived the lock test")
    print("  ok")


def test_audio_master_never_reruns_an_unguarded_main():
    section("audio_master: the audio process never re-runs a main script "
            "that has no __main__ guard")
    import subprocess as _sp, tempfile
    here = os.path.dirname(os.path.abspath(__file__))
    work = tempfile.mkdtemp()
    log = os.path.join(work, "ran.log")
    script = os.path.join(work, "boot.py")
    # The shape the Mac app's boot.py had: everything at the top level.
    open(script, "w").write(
        "import os, sys\n"
        f"sys.path.insert(0, {here!r})\n"
        f"open({log!r}, 'a').write(str(os.getpid()) + '\\n')\n"
        "from ltcplay import showaudio as sa\n"
        "eng = sa.AudioEngine({'device': 'Fake Interface', 'channels': 2,\n"
        "    'rate': 48000, 'allow_shared': False, 'cues': {},\n"
        f"    'lock': {os.path.join(work, 'audio.lock')!r},\n"
        "    'platform': 'darwin', 'fake': {'threaded': True}})\n"
        "eng.HELLO_S = 10.0\n"
        "first = eng.start(wait_s=5)\n"
        "print('FIRST', first and first[0])\n"
        "eng.close()\n")
    r = _sp.run([sys.executable, script], capture_output=True, text=True,
                timeout=60, cwd=work)
    ran = open(log).read().split() if os.path.exists(log) else []
    check("FIRST opened" in r.stdout,
          f"the audio did not start under an unguarded main: "
          f"{r.stdout[-300:]} {r.stderr[-500:]}")
    check(len(ran) == 1, f"the main script ran {len(ran)} times; the audio "
                         f"process ran it again")
    b = _builder_text()
    if b is not None:
        boot = _between(b, "<<'BOOT'\n", "\nBOOT\n")
        check('\nif __name__ == "__main__":\n' in boot
              and boot.index('if __name__ == "__main__":')
              < boot.index("from ltcplay.cli import main"),
              "the Mac app's boot.py runs the engine without a __main__ "
              "guard")
    print("  ok")


def test_audio_master_loads_all_or_nothing():
    section("audio_master: a cue is loaded whole and checked, or not at all")
    import builtins
    import numpy as np
    from ltcplay import clock as clock_mod, showaudio as sa
    r = _am_rig(seconds=4.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    stems = eng.spec["cues"]["show"]
    music = stems[0][0]
    check(all(len(st) == 4 and st[3] == 192000 for st in stems),
          f"the audio process is not told how long each stem must be: "
          f"{[st[3:] for st in stems]}")
    ready = am.snapshot()["audio"]["ready"]
    check(ready == {"show": "ready", "intermission": "ready"},
          f"the page does not say both cues are ready: {ready}")

    def reload_and_play():
        eng.proc.command(("load", "show", stems, True))
        sim.run(vc() + 0.1)
        try:
            am.play(3600.0, None, "Show")
            return None
        except clock_mod.ClockConfigError as e:
            return str(e)

    # 1. A read that stops halfway (a disk error, a placeholder file).
    real_open = builtins.open

    class Half:
        def __init__(self, fh, limit):
            self.fh, self.left = fh, limit

        def read(self, n=-1):
            if self.left <= 0:
                return b""
            b = self.fh.read(min(n, self.left) if n >= 0 else self.left)
            self.left -= len(b)
            return b

        def __getattr__(self, k):
            return getattr(self.fh, k)

        def __enter__(self):
            return self

        def __exit__(self, *a):
            self.fh.close()

    def half_open(path, mode="r", *a, **k):
        fh = real_open(path, mode, *a, **k)
        if path == music and "b" in mode:
            return Half(fh, os.path.getsize(path) // 2)
        return fh

    sa.open = half_open
    try:
        try:
            sa.read_wav(music)
            check(False, "a read that stopped halfway gave a shorter clip")
        except sa.AudioConfigError as e:
            check("could only be read to" in str(e) and "of 0:04.000" in
                  str(e) and str(e).endswith("."),
                  f"the short read refusal: {e}")
        why = reload_and_play()
    finally:
        del sa.open
    check(why is not None and "could not be loaded" in why
          and "could only be read to" in why
          and "press Stop and Run again" in why and not am.playing,
          f"a cue read only halfway could still be started: {why}")
    check(am.snapshot()["audio"]["ready"]["show"] == "failed",
          "the page shows a half-read cue as ready")
    check(any("could only be read to" in f[1] for f in r["journal"].faults)
          or "could only be read to" in (am._fault or ""),
          "a half-read cue is not reported")

    # 2. The file cut short after the show was checked.
    raw = real_open(music, "rb").read()
    real_open(music, "wb").write(raw[:len(raw) // 2])
    why = reload_and_play()
    check(why is not None and "could not be loaded" in why
          and "press Stop and Run again" in why and not am.playing,
          f"a cue cut short after checking could still be started: {why}")
    # Every stem swapped for a whole, consistent, but shorter file after
    # the show was checked: still refused, on the lengths it was checked at.
    sub = stems[1][0]
    raw_sub = real_open(sub, "rb").read()
    _am_write_wav(music, _am_tone(3.0, 2))
    _am_write_wav(sub, _am_tone(3.0, 1, 0.3))
    why = reload_and_play()
    check(why is not None and "when the show was checked" in why
          and not am.playing,
          f"stems changed since the show was checked could be started: "
          f"{why}")
    real_open(sub, "wb").write(raw_sub)
    real_open(music, "wb").write(raw)
    why = reload_and_play()
    check(why is None and am.playing,
          f"the cue did not load again once the file was whole: {why}")
    am.stop()

    # 3. Stems that decode to different lengths, each still exactly as long
    # as it was checked (so the length-mismatch defense is exercised on its
    # own, not stacked behind the per-stem checked-length refusal).
    r = _am_rig(seconds=4.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    stems = list(eng.spec["cues"]["show"])
    sub = stems[1][0]
    _am_write_wav(sub, _am_tone(3.0, 1, 0.3))
    stems[1] = (stems[1][0], stems[1][1], stems[1][2], int(3.0 * 48000))
    eng.proc.command(("load", "show", stems, True))
    sim.run(vc() + 0.1)
    try:
        am.play(3600.0, None, "Show")
        check(False, "a cue whose stems differ in length was started")
    except clock_mod.ClockConfigError as e:
        check("not all the same length" in str(e) and "sub.wav is 0:03.000"
              in str(e), f"the length refusal: {e}")
    eng.proc.command(("load", "show", stems, False))
    sim.run(vc() + 0.1)
    check(am.snapshot()["audio"]["ready"]["show"] == "ready",
          "stems allowed to differ in length were not loaded")
    am.stop()

    # 4. Stems sent without their checked length (a caller bug, since
    # production always sends it from check_show): a loud refusal, never a
    # silent skip of the length check.
    r = _am_rig(seconds=4.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    short_stems = [tuple(st[:3]) for st in eng.spec["cues"]["show"]]
    eng.proc.command(("load", "show", short_stems, True))
    sim.run(vc() + 0.1)
    try:
        am.play(3600.0, None, "Show")
        check(False, "a cue with no checked length was started")
    except clock_mod.ClockConfigError as e:
        check("has no checked length" in str(e)
              and "not checked before" in str(e), f"the refusal: {e}")
    check(am.snapshot()["audio"]["ready"]["show"] == "failed",
          "the page shows a cue with no checked length as ready")

    # 5. A load command with no same-length flag at all: the same loud
    # refusal, not a silent default.
    r = _am_rig(seconds=4.0)
    am, sim, vc, eng = r["am"], r["sim"], r["vc"], r["eng"]
    eng.proc.command(("load", "show", eng.spec["cues"]["show"]))
    sim.run(vc() + 0.1)
    try:
        am.play(3600.0, None, "Show")
        check(False, "a load command with no same-length flag was accepted")
    except clock_mod.ClockConfigError as e:
        check("no same-length flag" in str(e)
              and "not checked before" in str(e),
              f"the missing same-length refusal: {e}")
    print("  ok")


def test_journal_every_line_reaches_the_disk_within_a_second():
    section("journal: every line is on the disk, flushed and synced, within "
            "a second of happening")
    S = _sched()
    if S is None:
        return
    import tempfile
    import time as _t
    from ltcplay import journal as J
    work = tempfile.mkdtemp()
    syncs = {"n": 0}

    def fsync(fd):
        syncs["n"] += 1
        return os.fsync(fd)

    b = J.Logbook(work, tz=S.zone("America/Denver"), state="SHOW",
                  fsync=fsync).start_writer()
    jp = os.path.join(work, J.journal_name(b.current_night()))

    def on_disk(text):
        try:
            return text in open(jp, encoding="utf-8").read()
        except OSError:
            return False

    check(J.MAX_LINE_WAIT_S <= 1.0, f"the bound is a second at most: "
                                    f"{J.MAX_LINE_WAIT_S}")
    for i in range(3):
        before = syncs["n"]
        b.record(actor="system", action="note", outcome="done", reason="r",
                 text=f"Line {i}, which must be on the disk at once.")
        check(wait_for(lambda: on_disk(f"Line {i},"),
                       timeout=J.MAX_LINE_WAIT_S),
              f"line {i} is on the disk within {J.MAX_LINE_WAIT_S:g} s")
        check(wait_for(lambda: syncs["n"] >= before + 2, timeout=1.0),
              f"and both files were synced to the disk: "
              f"{syncs['n'] - before}")
    # A wake-up that never comes: the line still goes down within the
    # bound, because the writer looks again at least that often.
    wake = b._wake.set
    b._wake.set = lambda: None
    t0 = _t.monotonic()
    b.record(actor="system", action="note", outcome="done", reason="r",
             text="A line whose wake-up was lost.")
    got = wait_for(lambda: on_disk("whose wake-up was lost"), timeout=3.0)
    took = _t.monotonic() - t0
    check(got and took <= J.MAX_LINE_WAIT_S + 0.5,
          f"a line waits at most about {J.MAX_LINE_WAIT_S:g} s even when "
          f"nothing wakes the writer: {took:.2f} s")
    b._wake.set = wake
    # The program dies: the writer stops where it is, nothing is closed or
    # flushed on the way out. Every line older than the bound is there.
    for i in range(10):
        b.record(actor="system", action="note", outcome="done", reason="r",
                 text=f"Burst line {i} before the crash.")
    _t.sleep(J.MAX_LINE_WAIT_S + 0.2)
    b._closing = True                 # killed: no close(), no last drain
    text = open(jp, encoding="utf-8").read()
    missing = [i for i in range(10) if f"Burst line {i} before" not in text]
    check(not missing, f"after a crash every line older than "
                       f"{J.MAX_LINE_WAIT_S:g} s is on the disk: missing "
                       f"{missing}")
    print("  ok")


def test_journal_summary_is_written_however_the_night_closes():
    section("journal: the nightly summary is written by itself, however "
            "the night closes")
    S = _sched()
    if S is None:
        return
    import tempfile
    from ltcplay import journal as J
    # The schedule's own close, after the last show: nobody presses
    # anything.
    work = tempfile.mkdtemp()
    now = [_den(S, 21, 30)]
    svc = _svc(S, work, now).start(thread=False)
    for t in ((21, 40), (21, 47, 20), (21, 47, 21)):
        now[0] = _den(S, *t)
        svc.tick()
    path = os.path.join(work, "nights", J.summary_name("2026-11-14"))
    text = open(path, encoding="utf-8").read() if os.path.exists(path) \
        else ""
    check(svc.machine.state == S.OFF and "closed after the last show" in
          text, f"the schedule's own close writes it: "
                f"{svc.machine.state} {text[:200]!r}")
    # Close for the night: the operator's words, never End night.
    work2 = tempfile.mkdtemp()
    now[0] = _den(S, 17, 30)
    b = _svc(S, work2, now).start(thread=False)
    now[0] = _den(S, 18, 30)
    b._apply(_op(S, S.END_NIGHT, confirmed=True))
    t2 = open(os.path.join(work2, "nights", J.summary_name("2026-11-14")),
              encoding="utf-8").read()
    j2 = open(os.path.join(work2, "nights", J.journal_name("2026-11-14")),
              encoding="utf-8").read()
    check("closed by Andy with Close for the night" in t2
          and "Andy pressed Close for the night on the rack screen" in j2
          and "the night was closed" in j2,
          "Close for the night writes it, in those words")
    check("End night" not in t2 and "End night" not in j2
          and "End the night" not in j2,
          "no operator sentence says End night any more")
    check([a["label"] for a in S.ACTIONS if a["id"] == "end_night"] ==
          ["Close for the night"] and "Close for the night?" in
          [a["confirm"] for a in S.ACTIONS if a["id"] == "end_night"][0],
          "the transport panel's label and question say it too")
    # A crash, and ltcplay not back for three days: every night it missed
    # closing gets its summary when it starts, with no button.
    work3 = tempfile.mkdtemp()
    now[0] = _den(S, 17, 30)
    a = _svc(S, work3, now).start(thread=False)
    now[0] = _den(S, 18, 0)
    a.tick()                                       # show 1; then the crash
    now[0] = _den(S, 17, 0, d=(2026, 11, 17))
    _svc(S, work3, now).start(thread=False)
    p3 = os.path.join(work3, "nights", J.summary_name("2026-11-14"))
    t3 = open(p3, encoding="utf-8").read() if os.path.exists(p3) else ""
    check("written later from the journal" in t3 and "| 1 |" in t3,
          f"the night the crash cut short gets its summary three days "
          f"later: {t3[:200]!r}")
    print("  ok")


# ---------------------------------------------------------------------------
# The show conductor (ltcplay/conductor.py): Hold, Resume, Abort, Reset and
# announcements on the rig. Driven on a fake clock, single threaded, so every
# "arrives mid fade" case lands at an exact, repeatable instant; one test at
# the end does the same on real threads and real time.
# ---------------------------------------------------------------------------


def _cond_mod():
    from ltcplay import conductor
    return conductor


class _CondTime:
    """A fake perf_counter. The conductor's waits advance it, and a test can
    schedule a press at an exact time: it fires inside the wait that spans
    it, which is exactly where a real press would land."""

    def __init__(self, t=100.0):
        self.t = t
        self.events = []

    def now(self):
        return self.t

    def at(self, when, fn):
        self.events.append((when, fn))

    def wait(self, left):
        target = self.t + left
        due = [e for e in self.events if e[0] <= target + 1e-12]
        if due:
            e = min(due, key=lambda x: x[0])
            self.events.remove(e)
            self.t = max(self.t, e[0])
            e[1]()
        else:
            self.t = target


class _CondRig:
    """Both sides at once: DeviceOutputs (lasers, video) and ShowOutputs
    (clock, pixels, flames). Records every call with the fake time. The
    clock freezes `fade` after music_hold and moves `move_s` after
    music_resume, like AudioMaster; either can be told never to."""

    def __init__(self, time_fn):
        self.now = time_fn
        self.calls = []
        self.cue = True
        self.frozen_at = None
        self.moving_at = None
        self.frozen = False
        self.move_s = 0.05
        self.never_freeze = False
        self.never_move = False
        self.fail = set()
        self.raise_on = set()
        self.bad = set()
        self.slow = {}
        self.slow_by = None
        self.on_call = {}      # name -> fn: a press landing mid call

    def _rec(self, name, *args):
        self.calls.append((name, args, self.now()))
        hook = self.on_call.pop(name, None)
        if hook is not None:
            hook()
        if name in self.slow and self.slow_by is not None:
            self.slow_by(self.slow[name])
        if name in self.raise_on:
            raise OSError(f"{name} exploded")
        if name in self.bad:
            return None
        C = _cond_mod()
        if name in self.fail:
            return C.failed(f"{name} could not be sent")
        return C.done()

    def names(self, since=0):
        return [c[0] for c in self.calls[since:]]

    def first(self, name, since=0):
        for c in self.calls[since:]:
            if c[0] == name:
                return c
        return None

    def count(self, name):
        return sum(1 for c in self.calls if c[0] == name)

    # DeviceOutputs
    def lasers_blank(self):
        return self._rec("lasers_blank")

    def lasers_fade_out(self, s):
        return self._rec("lasers_fade_out", s)

    def lasers_restore(self):
        return self._rec("lasers_restore")

    def video_fade_out(self, s):
        return self._rec("video_fade_out", s)

    def video_restore(self, s):
        return self._rec("video_restore", s)

    def video_stop(self):
        return self._rec("video_stop")

    # ShowOutputs
    def playing(self):
        return self.cue

    def music_hold(self, fade):
        r = self._rec("music_hold", fade)
        self.frozen_at = None if self.never_freeze else self.now() + fade
        self.moving_at = None
        return r

    def music_resume(self, fade):
        r = self._rec("music_resume", fade)
        self.moving_at = None if self.never_move else self.now() + self.move_s
        return r

    def music_halt(self, fade):
        return self._rec("music_halt", fade)

    def music_frozen(self):
        t = self.now()
        if self.moving_at is not None and t >= self.moving_at:
            return False
        if self.moving_at is None and self.frozen_at is not None \
                and t >= self.frozen_at:
            return True
        # Held but not yet frozen reads False; resuming but not yet moving
        # still reads True (the timecode is still frozen).
        return self.moving_at is not None

    def pixels_fade_out(self, s):
        return self._rec("pixels_fade_out", s)

    def pixels_restore(self, s):
        return self._rec("pixels_restore", s)

    def flames_zero(self):
        return self._rec("flames_zero")

    def flames_release(self):
        return self._rec("flames_release")

    def flames_disarm_all(self, reason):
        return self._rec("flames_disarm_all", reason)


def _cond(gate=None, hold_gate=None, announcer=None, devices=None, **kw):
    C = _cond_mod()
    T = _CondTime()
    rig = _CondRig(T.now)
    rig.slow_by = lambda s: setattr(T, "t", T.t + s)
    lines = []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    c = C.Conductor(devices or rig, rig,
                    gate if gate is not None else (lambda: None),
                    hold_gate=hold_gate, announcer=announcer,
                    journal=journal, clock=T.now, waiter=T.wait,
                    threaded=False, **kw)
    return c, rig, T, lines


def _cond_live(c, rig):
    """A show running with everything up, and the call log cleared."""
    check(c.show_starting("Andy", "rack screen").ok, "show start accepted")
    c.run_pending()
    rig.frozen_at = rig.moving_at = None
    del rig.calls[:]


def test_conductor_abort_cuts_flames_at_once_and_fades_the_rest():
    section("conductor: Abort zeroes and disarms the flames at once, fades "
            "lasers, video, pixels and music together over 1 s, and latches")
    C = _cond_mod()
    check(C.HOLD_FADE_S == 0.25, "production Hold fades over 0.25 s")
    check(C.ABORT_FADE_S == 1.0, "Abort fades over 1 s")
    check(C.ANNOUNCE_DARK_S == 0.5, "an announcement waits 0.5 s in the dark")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    T.t = 200.0
    r = c.abort("Andy", "rack screen")
    check(r.ok, f"Abort accepted: {r}")
    # Before the executor has run at all: the flames are already cut, and
    # the lasers blanked on the pressing thread (independent review of PR
    # #29, finding D: never queued behind the executor).
    check(rig.names() == ["flames_zero", "flames_disarm_all",
                          "lasers_blank"],
          f"Abort cuts and disarms the flames, then sends the lasers dark, "
          f"before it returns, and nothing else yet: {rig.names()}")
    check(all(t == 200.0 for _n, _a, t in rig.calls),
          "the flame cut and the lasers' dark command have zero delay")
    check(c.latched, "Abort latches at once")
    c.run_pending()
    for name in ("video_fade_out", "pixels_fade_out", "music_halt"):
        got = rig.first(name)
        check(got is not None and got[1] == (1.0,) and got[2] == 200.0,
              f"{name} starts at the press, over 1 s: {got}")
    las = rig.first("lasers_blank")
    check(las is not None and las[1] == () and las[2] == 200.0,
          f"Abort blanks the lasers at once at the press, no ramp (Jeff and "
          f"Andy, 2026-10-04): {las}")
    check(rig.count("lasers_blank") == 2 and
          rig.names().index("lasers_blank") < rig.names().index(
              "video_fade_out"),
          "the executor sends the lasers dark again once the press's "
          "command got out, every time, whatever the record says (review "
          "of PR #43, P0-3)")
    check(any("lasers blanked again" in t for t, _f in lines),
          "the journal says the lasers were blanked again")
    stop = rig.first("video_stop")
    check(stop is not None and abs(stop[2] - 201.0) < 1e-9,
          f"the video stops once the 1 s fade is done: {stop}")
    check(rig.count("lasers_restore") == 0 and rig.count("flames_release")
          == 0, "nothing comes back up after an Abort")
    # Latched: nothing else responds.
    for what, fn in (("Hold", lambda: c.hold("Andy", "rack screen")),
                     ("Resume", lambda: c.resume("Andy", "rack screen")),
                     ("Show start", lambda: c.show_starting()),
                     ("an announcement", lambda: c.announce("delayed")),
                     ("a mode change", lambda: c.set_mode(C.REHEARSAL))):
        r = fn()
        check(not r.ok and "Reset" in r.sentence,
              f"{what} is refused while aborted, saying to Reset: {r}")
    n = len(rig.calls)
    c.run_pending()
    check(len(rig.calls) == n, "a refused press sends nothing")
    r = c.reset("Andy", "rack screen")
    check(r.ok and not c.latched, f"one Reset press clears the latch: {r}")
    c.run_pending()
    check(len(rig.calls) == n, "Reset leaves the rig dark")
    check(not c.reset().ok, "a second Reset has nothing to reset")
    check(any("Reset" in t for t, _f in lines), "Reset is journaled")
    print("  ok")


def test_conductor_failed_start_leaves_groups_as_they_are():
    section("conductor: a failed start goes dark like a cut show and leaves "
            "every flame group AS IT IS: no disarm, no latch, Start now at "
            "once (Jeff's ruling 1, 2026-10-12, reversing 2026-10-03). This "
            "test used to be test_conductor_failed_start_disarms_without_"
            "latch and asserted the disarm.")
    C = _cond_mod()
    c, rig, T, lines = _cond()
    _cond_live(c, rig)                  # flame cues live, so the zero shows
    k = len(rig.calls)
    r = c.failed_start("the scheduler", "")
    check(r.ok and "flames_disarm_all" not in rig.names(k),
          f"NO disarm is sent on the calling thread: {r} {rig.names(k)}")
    check("left as it was" in r.sentence and "failed to start" in r.sentence
          and "disarm" not in r.sentence.lower(),
          f"and its answer says the groups are left as they were: "
          f"{r.sentence}")
    c.run_pending()
    a = c.snapshot()["applied"]
    check(not c.latched and c.snapshot()["look"] == C.STOPPED_DARK and
          a["flames"] == "zero" and a["lasers"] == "black" and
          a["pixels"] == "black" and a["music"] == "stopped" and
          rig.names(k)[:1] == ["flames_zero"] and
          rig.count("flames_disarm_all") == 0 and not a["disarmed"],
          f"the rig is dark (cues zeroed first, like a cut show), nothing "
          f"disarmed, nothing latched: latched={c.latched} {a} "
          f"{rig.names(k)}")
    rig.cue = False
    check(any("Failed start" in t for t, f in lines)
          and not any("disarm" in t.lower() for t, f in lines),
          f"its own line records the failed start and never speaks of a "
          f"disarm: {lines}")
    check(not hasattr(C.Conductor, "FAILED_START"),
          "the failed-start disarm reason is gone with the disarm")
    rig.cue = True
    check(c.show_starting("Andy", "rack screen").ok,
          "no Reset is needed: the next show start is accepted")
    # While aborted it changes nothing (the Abort already disarmed).
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    c.abort("Andy", "rack screen")
    c.run_pending()
    k = len(rig.calls)
    r = c.failed_start("the scheduler", "")
    check(r.ok and rig.names(k) == [] and c.latched,
          f"a failed start while aborted sends nothing and keeps the latch: "
          f"{rig.names(k)}")
    # The Abort still disarms: ruling 1 touched failed_start only.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    c.abort("Andy", "rack screen")
    check(rig.names()[-2:] == ["flames_zero", "flames_disarm_all"]
          or "flames_disarm_all" in rig.names(),
          f"Abort still zeroes the cues and disarms every group at once: "
          f"{rig.names()}")
    print("  ok")


def test_conductor_double_abort_is_idempotent():
    section("conductor: a second Abort does nothing, Reset waits for the "
            "fade, and Abort needs something playing")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    T.t = 300.0
    c.abort("Andy", "rack screen")
    gen = c._gen
    r2 = c.abort("Jeff", "Stream Deck")
    check(r2.ok and "Already aborted" in r2.sentence
          and "blank was sent again" in r2.sentence,
          f"a second Abort starts nothing new but blanks again: {r2}")
    check(c._gen == gen, "a second Abort starts no new effect")
    resets = []
    T.at(300.5, lambda: resets.append(c.reset("Andy", "rack screen")))
    c.run_pending()
    c.abort("Andy", "rack screen")
    c.run_pending()
    for name in ("flames_zero", "flames_disarm_all",
                 "video_fade_out", "pixels_fade_out", "music_halt",
                 "video_stop"):
        check(rig.count(name) == 1, f"{name} sent exactly once for three "
                                    f"Abort presses ({rig.count(name)})")
    # Finding B: each press while latched sends the laser blank again (a
    # blank only makes it darker), so a blank that did not get out the
    # first time is not stuck that way until Reset.
    check(rig.count("lasers_blank") == 4,
          f"the first Abort press blanks the lasers, its executor once more "
          f"(review of PR #43, P0-3), and each later press sends the blank "
          f"again ({rig.count('lasers_blank')})")
    check(resets and not resets[0].ok and "still fading" in
          resets[0].sentence, f"Reset during the fade is refused: {resets}")
    check(c.latched, "a refused Reset leaves it latched")
    check(c.reset().ok, "Reset once the fade is done")
    # Nothing playing: no show to stop, but the flames are still cut and
    # every group disarmed (review of PR #43, P0-1: a group armed before a
    # show or between two must come off at an Abort too).
    c2, rig2, _T2, _l2 = _cond()
    rig2.cue = False
    r = c2.abort("Andy", "rack screen")
    check(not r.ok and "nothing is playing" in r.sentence and
          "disarm was sent to every flame group" in r.sentence,
          f"Abort with nothing playing stops no show, and says the flames "
          f"were cut anyway: {r}")
    check(rig2.names() == ["flames_zero", "flames_disarm_all"] and
          not c2.latched,
          f"an Abort with nothing playing zeroes the flame cues and "
          f"disarms every group, and latches nothing: {rig2.names()}")
    c2.run_pending()
    check(rig2.names() == ["flames_zero", "flames_disarm_all"],
          f"and starts nothing else: {rig2.names()}")
    print("  ok")


def test_conductor_abort_mid_hold_fade_wins():
    section("conductor: Abort during a Hold's fade takes over at once and "
            "the Hold never finishes")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    T.t = 400.0
    seen = {}

    def press():
        seen["r"] = c.abort("Andy", "rack screen")
        seen["cut"] = rig.names()[-3:]
    T.at(400.1, press)
    check(c.hold("Andy", "rack screen").ok, "Hold accepted")
    c.run_pending()
    check(seen.get("r") is not None and seen["r"].ok, "Abort accepted")
    check(seen.get("cut") == ["flames_zero", "flames_disarm_all",
                              "lasers_blank"],
          f"the flames were cut and the lasers sent dark inside the press "
          f"itself: {seen.get('cut')}")
    hold = rig.first("music_hold")
    check(hold is not None and hold[1] == (0.25,) and hold[2] == 400.0,
          f"the Hold had started its 0.25 s fade: {hold}")
    # The Hold's own video and pixels fade (Jeff 2026-09-30) had already
    # gone out at the press, over the Hold's 0.25 s, before Abort landed.
    for name in ("video_fade_out", "pixels_fade_out"):
        got = rig.first(name)
        check(got is not None and abs(got[2] - 400.0) < 1e-9
              and got[1] == (0.25,),
              f"{name} went with the Hold at the press: {got}")
    halt = rig.first("music_halt")
    check(halt is not None and abs(halt[2] - 400.1) < 1e-9
          and halt[1] == (1.0,),
          f"music_halt starts the moment Abort lands, not after the Hold's "
          f"fade: {halt}")
    # The Hold blanked the lasers; Abort sends their dark command again
    # anyway (BEYOND never confirms, so "already dark" is never trusted),
    # on the pressing thread, before the music fade.
    blanks = [i for i, cl in enumerate(rig.calls) if cl[0] == "lasers_blank"]
    check(len(blanks) == 3, "the Hold blanked the lasers, then the Abort at "
                            "its press, then the Abort's executor again")
    las = rig.calls[blanks[1]]
    check(abs(las[2] - 400.1) < 1e-9
          and blanks[1] < rig.names().index("music_halt"),
          f"Abort sends the lasers dark again at its press, before "
          f"anything else it fades: {las} {rig.names()}")
    # Finding C: Abort fades the video again, from wherever the Hold's fade
    # had got to, never trusting a record that says black. Pixels are
    # ltcplay's own and their record is the truth.
    vf = [cl for cl in rig.calls if cl[0] == "video_fade_out"]
    check(len(vf) == 2 and vf[1][1] == (1.0,)
          and abs(vf[1][2] - 400.1) < 1e-9,
          f"Abort fades the video again at its press, over 1 s: {vf}")
    check(rig.count("pixels_fade_out") == 1,
          "Abort does not re-send pixels: the Hold's fade left them black")
    stop = rig.first("video_stop")
    check(stop is not None and abs(stop[2] - 401.1) < 1e-9,
          f"Abort's own 1 s runs from its press: {stop}")
    check(any("Hold stopped part way because Abort" in t for t, _f in lines),
          "the journal says the Hold was cut short by Abort")
    check(c.snapshot()["look"] == "ABORTED", "the look is Abort's")
    print("  ok")


def test_conductor_resume_before_the_hold_fade_finishes():
    section("conductor: Resume during a Hold's fade undoes exactly what the "
            "Hold did, lasers and flames only once the timecode moves")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.move_s = 0.3
    T.t = 500.0
    T.at(500.1, lambda: c.resume("Andy", "rack screen"))
    c.hold("Andy", "rack screen")
    c.run_pending()
    names = rig.names()
    check(names[:5] == ["flames_zero", "lasers_blank", "music_hold",
                        "video_fade_out", "pixels_fade_out"],
          f"Hold: flames, lasers, the music fade, then video and pixels "
          f"fade to black with it (Jeff 2026-09-30): {names}")
    res = rig.first("music_resume")
    check(res is not None and abs(res[2] - 500.1) < 1e-9,
          f"the music resumes at the Resume press: {res}")
    las = rig.first("lasers_restore")
    fl = rig.first("flames_release")
    check(las is not None and las[2] >= 500.4 - 1e-9,
          f"the lasers come back only once the timecode moves: {las}")
    check(fl is not None and fl[2] >= 500.4 - 1e-9,
          f"the flame cues are released only once the timecode moves: {fl}")
    check(names.index("flames_release") > names.index("lasers_restore"),
          "flame cues last")
    snap = c.snapshot()
    check(snap["look"] == "PLAYING" and snap["applied"]["flames"] == "live"
          and snap["applied"]["lasers"] == "lit", f"back to playing: {snap}")
    # Resume when nothing is held is refused.
    r = c.resume("Andy", "rack screen")
    check(not r.ok and "not on hold" in r.sentence, f"{r}")
    # A second Hold press while held changes nothing.
    c.hold("Andy", "rack screen")
    c.run_pending()
    n, gen = len(rig.calls), c._gen
    r = c.hold("Jeff", "Stream Deck")
    check(r.ok and "Already on hold" in r.sentence and c._gen == gen,
          f"a double Hold starts nothing new: {r}")
    c.run_pending()
    check(rig.names(n) == ["lasers_blank"],
          f"a double Hold sends only the laser blank again (finding B): "
          f"{rig.names(n)}")
    print("  ok")


def test_conductor_generation_guard_stops_a_stale_effect():
    section("conductor: a superseded effect never applies its last steps")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.move_s = 0.3
    c.hold("Andy", "rack screen")
    c.run_pending()
    T.t = 600.0
    # Resume is waiting for the timecode to move (it will at 600.3); Abort
    # lands at 600.1. The Resume's last two steps must never happen.
    T.at(600.1, lambda: c.abort("Andy", "rack screen"))
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_restore") == 0,
          "a stale Resume never lights the lasers after an Abort")
    check(rig.count("flames_release") == 0,
          "a stale Resume never releases the flames after an Abort")
    a = c.snapshot()["applied"]
    check(a["flames"] == "zero" and a["lasers"] == "black",
          f"the rig ends as Abort left it: {a}")
    check(any("Resume stopped part way because Abort" in t
              for t, _f in lines), "the journal says so")
    # A press landing DURING a step: the step itself happened (the lasers
    # came up), but the Resume's next step, releasing the flames, must not.
    C = _cond_mod()
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    c.hold("Andy", "rack screen")
    c.run_pending()
    # The record as the Abort's executor re-sends its blank: what the
    # press's blank wrote, or the restore's late "lit" if that got through.
    at_resend = []

    def abort_mid_restore():
        c.abort("Andy", "rack screen")
        # The press's own blank has been made inside abort(); the next
        # lasers_blank is the executor's re-send.
        rig.on_call["lasers_blank"] = lambda: at_resend.append(
            c.snapshot()["applied"]["lasers"])
    rig.on_call["lasers_restore"] = abort_mid_restore
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_restore") == 1 and
          rig.count("flames_release") == 0,
          f"no step of a superseded effect runs after the press: "
          f"{rig.names()}")
    ri = rig.calls.index(rig.first("lasers_restore"))
    check(any(cl[0] == "lasers_blank" for cl in rig.calls[ri + 1:]),
          "and Abort takes the lasers that did come up back down")
    check(c.snapshot()["applied"]["lasers"] == "black",
          f"and the record says dark, not the restore's lit: "
          f"{c.snapshot()['applied']}")
    check(rig.count("lasers_blank") == 3,
          f"the Hold's blank, then the Abort's own, which stands, and the "
          f"Abort's executor's once more (review of PR #43, P0-3): "
          f"{rig.names()}")
    # The restore returned after the Abort's blank: its "lit" must not
    # overwrite the newer record (finding D). The executor's re-send goes
    # out whatever the record says (P0-3), so the proof is the record
    # itself: as that blank is sent it already says dark, and the journal
    # calls it a re-send of a blank that had landed. A late "lit" that got
    # through would read as lit here, and the re-send as a fresh blank.
    check(at_resend == ["black"],
          f"the record still says dark when the executor re-sends the "
          f"blank: the restore's late \"lit\" was dropped (finding D): "
          f"{at_resend}")
    check(any(f"lasers blanked again {C.AGAIN}" in t for t, _f in lines),
          f"and the journal says the re-send found the lasers already "
          f"dark: {[t for t, _f in lines if 'Abort finished' in t]}")
    # Straight at the guard: a step or an announcement for an older
    # generation does nothing at all.
    C = _cond_mod()
    played = []
    c, rig, T, lines = _cond(hold_gate=lambda *a: (None, 1),
                             announcer=lambda *a: played.append(a))
    stale = c._gen
    c._gen += 1
    n = len(rig.calls)
    for what, fn in (
            ("a step", lambda: c._step(stale, "lasers", "lit", "x", [],
                                       rig.lasers_restore)),
            ("an announcement", lambda: c._run_announce(
                stale, {"announce": ("delayed", "Andy", "rack"),
                        "look": "DARK", "changed": False}, []))):
        try:
            fn()
            check(False, f"{what} for an older generation must be refused")
        except C._Superseded:
            pass
    check(len(rig.calls) == n and played == [],
          "and it sent nothing and played nothing")
    # The same for an announcement waiting in the dark.
    plays = []
    gate_calls = []

    def hold_gate(who, screen, detail):
        gate_calls.append((who, screen, detail))
        return None, 1
    c, rig, T, lines = _cond(hold_gate=hold_gate,
                             announcer=lambda *a: plays.append(a))
    _cond_live(c, rig)
    T.t = 700.0
    T.at(700.4, lambda: c.abort("Andy", "rack screen"))
    c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    check(plays == [], "an announcement superseded in the dark never plays")
    halt = rig.first("music_halt")
    check(halt is not None and abs(halt[2] - 700.4) < 1e-9,
          f"the wait in the dark wakes for the Abort at once: {halt}")
    check(any("delayed announcement did not play: Abort" in t
              for t, _f in lines), "and the journal says why")
    # Superseded before its effect even started: the claim is released.
    c, rig, T, lines = _cond(hold_gate=hold_gate,
                             announcer=lambda *a: plays.append(a))
    _cond_live(c, rig)
    c.announce("delayed", "Andy", "rack screen")
    c.resume("Jeff", "Stream Deck")
    c.run_pending()
    check(plays == [], "a Resume before the announcement started cancels it")
    r = c.announce("cancellation", "Andy", "rack screen")
    check(r.ok, f"the cancelled claim does not block the next one: {r}")
    c.run_pending()
    check(plays == [("cancellation", "Andy", "rack screen")],
          f"the next announcement plays: {plays}")
    print("  ok")


def _in_the_dark(played_at, dark_at):
    """Played 0.5 s after the rig went dark, give or take the conductor's
    own polling of the clock (POLL_S)."""
    C = _cond_mod()
    late = played_at - dark_at - C.ANNOUNCE_DARK_S
    return -1e-9 <= late <= C.POLL_S + 1e-9


def test_conductor_announcements_hold_go_dark_then_play():
    section("conductor: an announcement holds the show, fades lasers, video "
            "and pixels to black, waits 0.5 s in the dark, then plays")
    plays, gates = [], []
    refusal = [None]

    def hold_gate(who, screen, detail):
        gates.append((who, screen, detail))
        return refusal[0], len(gates)
    c, rig, T, lines = _cond(
        hold_gate=hold_gate,
        announcer=lambda *a: plays.append(a + (T.now(),)))
    _cond_live(c, rig)
    T.t = 800.0
    r = c.announce("delayed", "Andy", "rack screen")
    check(r.ok, f"accepted: {r}")
    check(len(gates) == 1 and gates[0][:2] == ("Andy", "rack screen"),
          f"the scheduler's hold gate is asked once, with who and where: "
          f"{gates}")
    r2 = c.announce("cancellation", "Jeff", "Stream Deck")
    check(not r2.ok and "still starting" in r2.sentence,
          f"a second announcement while one starts is refused: {r2}")
    c.run_pending()
    for name in ("flames_zero", "lasers_blank", "music_hold",
                 "video_fade_out", "pixels_fade_out"):
        got = rig.first(name)
        check(got is not None and got[2] == 800.0 and
              (name in ("flames_zero", "lasers_blank") or
               got[1] == (0.25,)),
              f"{name} at the press, fading with the music: {got}")
    check(len(plays) == 1 and _in_the_dark(plays[0][3], 800.25),
          f"played 0.5 s after the 0.25 s fade ended: {plays}")
    # Another announcement once that one has started: already dark, so it
    # plays at once with nothing sent but the lasers' blank, which is always
    # re-sent (conductor.ALWAYS_RESENT), and is not a change worth 0.5 s.
    n = len(rig.calls)
    T.t = 810.0
    c.announce("cancellation", "Andy", "rack screen")
    c.run_pending()
    check(rig.names(n) == ["lasers_blank"],
          f"already dark: only the lasers' blank is sent again: "
          f"{rig.names(n)}")
    check(plays[-1][3] == 810.0, "and it plays at once")
    # Resume from the dark: everything comes back.
    T.t = 820.0
    c.resume("Andy", "rack screen")
    c.run_pending()
    for name in ("music_resume", "video_restore", "pixels_restore",
                 "lasers_restore", "flames_release"):
        check(rig.first(name, n) is not None, f"Resume sends {name}")
    # During a production Hold: a production Hold already faded video and
    # pixels to black with the lasers (Jeff 2026-09-30), so there is
    # nothing left for the announcement to send, and it plays at once
    # rather than waiting 0.5 s in a dark that is already there.
    c, rig, T, lines = _cond(
        hold_gate=hold_gate,
        announcer=lambda *a: plays.append(a + (T.now(),)))
    _cond_live(c, rig)
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(rig.first("video_fade_out") is not None and
          rig.first("pixels_fade_out") is not None,
          "the Hold itself already faded video and pixels to black")
    n = len(rig.calls)
    T.t = 900.0
    c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    check(rig.names(n) == ["lasers_blank"],
          f"an announcement during a Hold sends nothing but the lasers' "
          f"blank again (always re-sent): already dark: {rig.names(n)}")
    check(plays[-1][3] == 900.0,
          f"and it plays at once, with nothing left to fade: {plays[-1]}")
    # A Hold pressed during the wait in the dark changes nothing.
    c, rig, T, lines = _cond(
        hold_gate=hold_gate,
        announcer=lambda *a: plays.append(a + (T.now(),)))
    _cond_live(c, rig)
    got = []
    T.t = 1000.0
    T.at(1000.5, lambda: got.append(c.hold("Jeff", "Stream Deck")))
    c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    check(got and got[0].ok and "Already on hold" in got[0].sentence,
          f"Hold during the announcement's wait: {got}")
    check(_in_the_dark(plays[-1][3], 1000.25), "and it still plays on time")
    # The scheduler refuses the Hold: the announcement is refused, nothing
    # is sent.
    c, rig, T, lines = _cond(hold_gate=hold_gate,
                             announcer=lambda *a: plays.append(a))
    _cond_live(c, rig)
    refusal[0] = "the night is closed"
    k = len(plays)
    r = c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    refusal[0] = None
    check(not r.ok and "the night is closed" in r.sentence,
          f"the gate's refusal is the announcement's: {r}")
    check(rig.calls == [] and len(plays) == k, "and nothing happens")
    # Between shows: no fade, no wait, it just plays.
    c, rig, T, lines = _cond(
        hold_gate=hold_gate,
        announcer=lambda *a: plays.append(a + (T.now(),)))
    rig.cue = False
    T.t = 1100.0
    c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    check(rig.calls == [] and plays[-1][3] == 1100.0,
          f"between shows it plays at once and touches nothing: "
          f"{rig.calls}")
    # No scheduler connected: refused, as announce.py is inert without one.
    c, rig, T, lines = _cond()
    r = c.announce("delayed", "Andy", "rack screen")
    check(not r.ok and "no scheduler" in r.sentence, f"{r}")
    # A refusal from the player itself is written down, not raised.
    def refuse(*a):
        raise ValueError("Delayed is not available: the file is missing.")
    c, rig, T, lines = _cond(hold_gate=hold_gate, announcer=refuse)
    _cond_live(c, rig)
    c.announce("delayed", "Andy", "rack screen")
    c.run_pending()
    check(any("file is missing" in t for t, _f in lines),
          "the player's refusal reaches the journal")
    print("  ok")


def test_conductor_no_lasers_during_intermission():
    section("conductor: the lasers are only ever lit through the gate, and "
            "never in intermission")
    C = _cond_mod()
    state = ["SHOW"]

    def boom():
        raise RuntimeError("scheduler gone")
    for st, lit in (("SHOW", True), ("PAUSED", True), ("REHEARSAL", True),
                    ("STANDBY", False), ("HOLD", False), ("IDLE", False),
                    ("CLOSING", False), (None, False), ("", False),
                    (boom, False)):
        gate = C.laser_gate_for(st if callable(st) else (lambda s=st: s))
        c, rig, T, lines = _cond(gate=gate)
        c.show_starting("Andy", "rack screen")
        c.run_pending()
        check((rig.count("lasers_restore") == 1) == lit,
              f"show start in state {st!r}: lasers "
              f"{'lit' if lit else 'dark'} ({rig.names()})")
        if not lit:
            check(any("lasers stay dark" in t for t, _f in lines),
                  f"state {st!r}: the journal says why")
        check(rig.count("flames_release") == 1,
              f"state {st!r}: the gate is for lasers only")
    gate = C.laser_gate_for(lambda: state[0])
    c, rig, T, lines = _cond(gate=gate)
    _cond_live(c, rig)
    c.hold("Andy", "rack screen")
    c.run_pending()
    state[0] = "STANDBY"
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_restore") == 0,
          "a Resume in intermission keeps the lasers dark")
    check(any("no lasers during intermission" in t for t, _f in lines),
          "in those words")
    check(c.snapshot()["applied"]["lasers"] == "black", "still black")
    def broken_gate():
        raise RuntimeError("gate broke")
    c, rig, T, lines = _cond(gate=broken_gate)
    c.show_starting("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_restore") == 0 and
          any("laser gate failed" in t for t, _f in lines),
          "a laser gate that raises keeps the lasers dark")
    for bad in (None, "yes"):
        try:
            C.Conductor(rig, rig, bad)
            check(False, f"a conductor without a laser gate ({bad!r}) must "
                         f"be refused")
        except ValueError:
            pass
    # Enforced, not assumed: lasers already lit are blanked when the gate
    # says no, and leaving the show blanks them whatever the gate says.
    state[0] = "SHOW"
    c, rig, T, lines = _cond(gate=gate)
    _cond_live(c, rig)
    check(c.snapshot()["applied"]["lasers"] == "lit", "lit in the show")
    state[0] = "STANDBY"
    c.show_starting("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_blank") == 1 and
          c.snapshot()["applied"]["lasers"] == "black",
          f"a gate that says no blanks lasers left lit: {rig.names()}")
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    r = c.intermission("scheduler")
    c.run_pending()
    check(r.ok and rig.names() == ["flames_zero", "lasers_blank"],
          f"leaving the show zeroes the flame cues and blanks the lasers, "
          f"nothing else: {rig.names()} {r}")
    a = c.snapshot()["applied"]
    check(a["lasers"] == "black" and a["flames"] == "zero", f"{a}")
    check(not c.resume("Andy", "rack screen").ok,
          "there is nothing to resume in intermission")
    # While an Abort is fading, intermission must not cut the fade short.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    T.t = 1300.0
    got = []
    T.at(1300.3, lambda: got.append(c.intermission("scheduler")))
    c.abort("Andy", "rack screen")
    c.run_pending()
    stop = rig.first("video_stop")
    check(got and got[0].ok and stop is not None and
          abs(stop[2] - 1301.0) < 1e-9 and c.latched,
          f"intermission during Abort's fade leaves it alone: {got} {stop}")
    print("  ok")


def test_conductor_rehearsal_hold_is_instant():
    section("conductor: in rehearsal Hold and Resume are instant; Abort is "
            "still 1 s")
    C = _cond_mod()
    c, rig, T, lines = _cond()
    check(c.mode == C.PRODUCTION, "production by default")
    check(not c.set_mode("practice").ok, "an unknown mode is refused")
    check(c.set_mode(C.REHEARSAL).ok and c.mode == C.REHEARSAL, "rehearsal")
    _cond_live(c, rig)
    T.t = 1200.0
    c.hold("Andy", "rehearsal page")
    c.run_pending()
    check(rig.first("music_hold")[1] == (0.0,), "the music stops at once")
    check(T.t == 1200.0, f"the Hold took no time: {T.t}")
    c.resume("Andy", "rehearsal page")
    c.run_pending()
    check(rig.first("music_resume")[1] == (0.0,), "and comes back at once")
    n = len(rig.calls)
    plays = []
    c.hold_gate = lambda *a: (None, 1)
    c.announcer = lambda *a: plays.append(a)
    c.announce("delayed", "Andy", "rehearsal page")
    c.run_pending()
    check(rig.first("lasers_blank", n) is not None and
          rig.first("video_fade_out", n)[1] == (0.0,),
          f"a rehearsal announcement goes dark at once: {rig.names(n)}")
    c.resume("Andy", "rehearsal page")
    c.run_pending()
    c.abort("Andy", "rehearsal page")
    c.run_pending()
    check(rig.first("music_halt")[1] == (1.0,), "Abort still fades 1 s")
    c.reset()
    check(c.set_mode(C.PRODUCTION).ok, "back to production")
    c.show_starting()
    c.run_pending()
    c.hold()
    c.run_pending()
    holds = [x for x in rig.calls if x[0] == "music_hold"]
    check(holds[-1][1] == (0.25,), f"production fades again: {holds}")
    print("  ok")


def test_conductor_hold_video_pixels_freeze_or_fade():
    section("conductor: rehearsal Hold leaves video and pixels frozen in "
            "place; production Hold fades them to black with the lasers "
            "(Jeff 2026-09-30)")
    C = _cond_mod()
    # Rehearsal: video and pixels are never touched, so they hold on
    # whatever frame they were already showing (frozen, not black).
    c, rig, T, lines = _cond()
    check(c.set_mode(C.REHEARSAL).ok, "rehearsal")
    _cond_live(c, rig)
    c.hold("Andy", "rehearsal page")
    c.run_pending()
    check(rig.first("video_fade_out") is None and
          rig.first("pixels_fade_out") is None,
          f"a rehearsal Hold never calls video or pixel fade: "
          f"{rig.names()}")
    a = c.snapshot()["applied"]
    check(a["video"] == C.LIT and a["pixels"] == C.LIT,
          f"neither was ever sent a command, so they stay exactly as they "
          f"were (lit, showing the frozen frame), not black: {a}")
    # Production: video and pixels fade out over the same 0.25 s as the
    # music and the lasers, and land on black.
    c, rig, T, lines = _cond()
    check(c.mode == C.PRODUCTION, "production by default")
    _cond_live(c, rig)
    c.hold("Andy", "rack screen")
    c.run_pending()
    vcall, pcall = rig.first("video_fade_out"), rig.first("pixels_fade_out")
    check(vcall is not None and vcall[1] == (0.25,),
          f"a production Hold fades the video out over 0.25 s: {vcall}")
    check(pcall is not None and pcall[1] == (0.25,),
          f"and the pixels too: {pcall}")
    a = c.snapshot()["applied"]
    check(a["video"] == C.BLACK and a["pixels"] == C.BLACK,
          f"both land on black, not merely frozen: {a}")
    # Resume brings them back either way.
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(rig.first("video_restore") is not None and
          rig.first("pixels_restore") is not None,
          "Resume brings video and pixels back up")
    a = c.snapshot()["applied"]
    check(a["video"] == C.LIT and a["pixels"] == C.LIT,
          f"and they are lit again: {a}")
    print("  ok")


def test_conductor_output_failures_are_loud_and_never_crash_it():
    section("conductor: a failed, raising, wrong or slow output is a fault "
            "sentence; the rest still runs and the command is sent again")
    C = _cond_mod()
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.fail = {"lasers_blank"}
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(any(f and "lasers_blank could not be sent" in t for t, f in lines),
          "a failed blank is a fault, with the device's sentence")
    check(rig.count("music_hold") == 1, "the Hold carried on past it")
    check(c.snapshot()["applied"]["lasers"] == "unknown",
          "a failed blank is not counted as dark")
    rig.fail = set()
    n0 = rig.count("lasers_blank")
    c.abort("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_blank") == n0 + 2,
          "so the Abort sends the lasers to black again, at the press and "
          "once more after it")
    # A raise, and a return that is not a Result.
    for mode in ("raise_on", "bad"):
        c, rig, T, lines = _cond()
        _cond_live(c, rig)
        setattr(rig, mode, {"lasers_blank", "flames_zero"})
        r = c.hold("Andy", "rack screen")
        c.run_pending()
        check(r.ok, f"{mode}: the press itself is fine")
        check(rig.count("music_hold") == 1, f"{mode}: the Hold carried on")
        a = c.snapshot()["applied"]
        check(a["lasers"] == "unknown" and a["flames"] == "unknown",
              f"{mode}: neither counts as done: {a}")
        check(sum(1 for _t, f in lines if f) >= 2,
              f"{mode}: both are faults: {lines}")
        setattr(rig, mode, set())
        c.abort("Andy", "rack screen")
        c.run_pending()
        check(rig.count("flames_zero") == 2,
              f"{mode}: Abort cuts the flames again")
    # A failed start sends no disarm at all (Jeff's ruling 1, 2026-10-12),
    # failing rig or not, so there is nothing to send again; its dark still
    # goes out past a failing output, which is journaled as a fault.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.fail = {"flames_disarm_all"}
    c.failed_start("the scheduler", "")
    rig.fail = set()
    c.run_pending()
    check(rig.count("flames_disarm_all") == 0,
          f"a failed start never sends a disarm, whatever the rig does: "
          f"{rig.names()}")
    check(rig.count("flames_zero") >= 1 and rig.count("music_halt") == 1
          and rig.count("lasers_blank") >= 1 and not c.latched
          and any("dark after a failed start" in t and "left as it was"
                  in t and not f for t, f in lines),
          f"its dark still goes out, its own line says the groups are left "
          f"as they were, and nothing latches: {rig.names()} {lines[-2:]}")
    # Abort's inline disarm fails: the executor sends it again.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.fail = {"flames_disarm_all"}
    c.abort("Andy", "rack screen")
    rig.fail = set()
    c.run_pending()
    check(rig.count("flames_disarm_all") == 2,
          "a failed disarm is sent again by the Abort's own effect")
    # A slow call.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.slow = {"lasers_blank": 0.2}
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(any(f and "took 200 ms" in t for t, f in lines),
          f"a slow output call is a fault: {lines}")
    # The clock never freezes: the safety half still stands.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    rig.never_freeze = True
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(any(f and "did not say it had frozen" in t for t, f in lines),
          "a Hold the clock never confirms is a fault")
    a = c.snapshot()["applied"]
    check(a["flames"] == "zero" and a["lasers"] == "black",
          f"flames zero and lasers dark anyway: {a}")
    # The clock never moves again: lasers and flames stay down.
    c, rig, T, lines = _cond()
    _cond_live(c, rig)
    c.hold("Andy", "rack screen")
    c.run_pending()
    rig.never_move = True
    c.resume("Andy", "rack screen")
    c.run_pending()
    check(rig.count("lasers_restore") == 0 and
          rig.count("flames_release") == 0,
          "no timecode movement: lasers and flame cues stay down")
    check(any(f and "was moving" in t for t, f in lines),
          "and that is a fault sentence")
    # The stand-in device layer says it is one.
    c, rig, T, lines = _cond(devices=C.NotWiredDevices())
    check(c.snapshot()["devices_wired"] is False,
          "the stand-in shows as not wired")
    check(any(f and "not connected" in t for t, f in lines),
          "and a fault line says so at start")
    # A journal that raises never stops a show.
    def bad_journal(text, **f):
        raise OSError("disk full")
    c = C.Conductor(rig, rig, lambda: None, journal=bad_journal,
                    clock=T.now, waiter=T.wait, threaded=False)
    rig.cue = True
    rig.never_freeze = False
    check(c.show_starting().ok and c.abort().ok,
          "a broken journal does not stop Abort")
    c.run_pending()
    check(c.journal_errors > 0, "its failures are counted")
    print("  ok")


def test_conductor_on_real_threads():
    section("conductor: real threads and real time, Abort pressed twice at "
            "once during a Hold")
    import threading as _th
    C = _cond_mod()
    rig = _CondRig(time.perf_counter)
    c = C.Conductor(rig, rig, lambda: None, clock=time.perf_counter)
    try:
        c.show_starting("Andy", "rack screen")
        check(c.wait_idle(5), "show start done")
        del rig.calls[:]
        c.hold("Andy", "rack screen")
        time.sleep(0.08)
        cut = {}
        go = _th.Event()

        def press(who):
            go.wait()
            t0 = time.perf_counter()
            r = c.abort(who, "rack screen")
            cut[who] = (r, t0, rig.first("flames_disarm_all"))
        ts = [_th.Thread(target=press, args=(w,)) for w in ("Andy", "Jeff")]
        for t in ts:
            t.start()
        go.set()
        for t in ts:
            t.join(5)
        pressed = min(v[1] for v in cut.values())
        check(all(v[0].ok for v in cut.values()), f"both answered: {cut}")
        check(all(v[2] is not None for v in cut.values()),
              "the flames were disarmed before either press returned")
        check(c.wait_idle(5), "the Abort finished")
        for name in ("pixels_fade_out",
                     "music_halt", "video_stop", "flames_disarm_all"):
            check(rig.count(name) == 1, f"{name} once for two presses "
                                        f"({rig.count(name)})")
        # The Hold's blank, then one per Abort press (finding B); the
        # Hold's video fade, then Abort's own from where it got to (C).
        check(rig.count("lasers_blank") == 4,
              f"lasers blanked by the Hold, by the first Abort press, by "
              f"its executor (review of PR #43, P0-3) and again by the "
              f"second ({rig.count('lasers_blank')})")
        vfs = [cl for cl in rig.calls if cl[0] == "video_fade_out"]
        check(len(vfs) == 2, f"the Hold's video fade, then the Abort's "
                             f"({len(vfs)})")
        vf = vfs[-1] if vfs else None
        check(vf is not None and vf[2] - pressed < 0.15,
              f"Abort's fade started at once, not after the Hold's "
              f"({(vf[2] - pressed) if vf else None})")
        vs = rig.first("video_stop")
        check(vs is not None and 0.95 <= vs[2] - vf[2] < 1.5,
              f"then 1 s of fade ({(vs[2] - vf[2]) if vs else None})")
        check(rig.count("flames_release") == 0 and
              rig.count("lasers_restore") == 0, "and nothing came back")
    finally:
        c.close()
    print("  ok")


def test_streamdeck_pure_logic():
    section("Stream Deck (real wiring): the pure logic, no hardware needed")
    from ltcplay import streamdeck as sd

    # The literal hold/refractory durations, Jeff's own decisions (module
    # docstring, 2026-10-01). Every other test reads these SYMBOLICALLY
    # (sd.ARM_HOLD_S, not a literal 0.6) so its own timing always tracks
    # whatever the constant currently says -- which means changing the
    # constant itself would otherwise sail through every test unnoticed
    # (round 3 of the safety review, item 4: a hand-mutation proved this).
    # This is the one place that pins down the actual numbers.
    check(sd.STOP_HOLD_S == 0.5,
          f"Stop's hold is the old Abort key's, from the approved bench "
          f"demo: {sd.STOP_HOLD_S}")
    check(sd.ARM_HOLD_S == 0.6,
          f"arming requires a hold a little longer than Stop's own, "
          f"short enough to still read as 'hold this key': "
          f"{sd.ARM_HOLD_S}")
    check(sd.REARM_REFRACTORY_S == 2.0,
          f"a key refuses to even start a new arm-hold for this long "
          f"after its own disarm or an Abort: {sd.REARM_REFRACTORY_S}")

    check([sd.group_look(None, slot=i) for i in range(4)] ==
          [(w, None, sd.RED, sd.CHAMPAGNE, False) for w in ("NO", "FLAME", "LINK")]
          + [("NO", "LINK", sd.RED, sd.CHAMPAGNE, False)],
          "no status ever received (or stale): NO / FLAME / LINK, one red "
          "word per key, and NO LINK on the fourth, steady, never a guess")
    check(sd.group_look({"armed": "armed"})[0] == "ARMED",
          "a real 'armed' status reads ARMED")
    check(sd.group_look({"armed": "disarmed"})[0] == "OFF",
          "a real 'disarmed' status reads OFF")
    held_dwell = sd.group_look({"armed": "held", "reason": "re-arm dwell",
                                "amber": "steady", "dwell_s": 4})
    check(held_dwell[0] == "4" and held_dwell[4] is False,
          f"a dwell counts down from the REAL dwell_s, steady: {held_dwell}")
    held_cycle = sd.group_look({"armed": "held", "reason": "cycle the arm",
                                "amber": "flashing", "dwell_s": 0})
    check(held_cycle[:2] == ("ARM", "AGAIN") and held_cycle[4] is True,
          f"'cycle the arm' flashes and reads ARM AGAIN: {held_cycle}")
    held_lost = sd.group_look({"armed": "held", "reason":
                               "Show program stopped answering: disarmed. "
                               "Cycle the arm to re-arm once it is back.",
                               "amber": "steady", "dwell_s": 0})
    check((held_lost[0], held_lost[1]) == ("SHOW", "LOST"),
          f"the exact CONTRACT.md sentence for a lost show program maps to "
          f"SHOW LOST: {held_lost}")
    held_unknown = sd.group_look({"armed": "held", "reason": "something new",
                                  "amber": "steady", "dwell_s": 0})
    check(held_unknown[0] == "HELD",
          "a reason not in the table still shows something (HELD), never "
          "a crash or a blank key")

    # Item 4: a non-empty top-level `fault` is red for EVERY group, even
    # one flamesafe itself still reports armed -- the wire is not being
    # written, so "armed" is not "fine" (CONTRACT.md).
    faulted = sd.group_look({"armed": "armed"}, fault="sACN send failed")
    check(faulted[0] == "FAULT" and faulted[2] == sd.RED,
          f"a fault overrides even a reported ARMED: {faulted}")
    # flamesafe's top-level `confirmed` never reaches a key any more (Jeff,
    # 2026-10-19: the amber corner mark item 5 of the safety review's round
    # 2 added for confirmed:false was pointless). group_look does not take
    # it, and every look is the plain 5-tuple whatever the config says; the
    # unconfirmed config is journaled and in the engine's status instead
    # (test_streamdeck_unconfirmed_config_never_marks_a_key).
    import inspect as _insp
    check("confirmed" not in _insp.signature(sd.group_look).parameters,
          "group_look no longer takes `confirmed`: a key's look comes from "
          "the group's real state and flamesafe's fault alone")
    plain = sd.group_look({"armed": "armed"})
    check(len(plain) == 5 and plain[0] == "ARMED",
          f"every look is the plain 5-tuple, no caveat element: {plain}")
    held = sd.group_look({"armed": "held", "reason": "cycle the arm",
                          "amber": "flashing", "dwell_s": 0})
    check(held[:2] == ("ARM", "AGAIN") and len(held) == 5,
          f"a two-line held reason is a plain 5-tuple too: {held}")
    check(sd.group_look({"armed": "armed"})[0] == "ARMED",
          "fault='' (the default) changes nothing: every existing caller "
          "keeps working")

    check(sd.operator_gate("", "arm") and sd.operator_gate("", "start")
          and sd.operator_gate("", "hold"),
          "arm, start and hold are refused with no operator chosen")
    check(sd.operator_gate("", "abort") is None
          and sd.operator_gate("", "disarm") is None,
          "Abort and disarm are NEVER gated on an operator: a risk-reducing "
          "press must never wait on a picker (item 7, Jeff's policy, "
          "blessed explicitly)")
    check(sd.operator_gate("Andy", "arm") is None,
          "a chosen operator unlocks arm")

    check(sd.edges([False, True, False], [True, True, True]) == [0, 2],
          "edges() finds every up-to-down transition, in key order")
    check(sd.releases([True, True], [False, True]) == [0],
          "releases() finds every down-to-up transition")

    h = sd.AbortHold(hold_s=0.5)
    check(h.fraction(0.0) == 0.0, "not pressed: fraction 0")
    h.press(10.0)
    check(h.fraction(10.25) == 0.5, "half way through the 0.5 s hold")
    check(h.fired(10.3) is False, "not yet: fired() is False before the hold")
    check(h.fired(10.5) is True, "fired() is True exactly at the hold time")
    check(h.fired(10.5) is False,
          "fired() consumes the press: it does not fire twice for one hold")
    h.press(20.0)
    h.release()
    check(h.fraction(20.4) == 0.0,
          "letting go before the hold completes resets to nothing, exactly "
          "like the approved demo")

    five = sd.Controller(_FakeArmSocket(5), _FakeStatusSocket(),
                         ["a", "b", "c", "d", "e"])
    check(five._key_group == {1: 0, 2: 1, 3: 2, 4: 3} and
          sd.GROUP_KEYS == (1, 2, 3, 4) and sd.GROUP_KEY_LIMIT == 4 and
          sd.TOP_START == 0 and sd.SPARE_KEY == 5,
          "five groups start (Jeff, 2026-10-26: a layout that does not fit "
          "is said, never refused): keys 1 to 4 are the first four, key 0 "
          "Start/Stop, key 5 spare")
    try:
        sd.Controller(_FakeArmSocket(0), _FakeStatusSocket(), [])
        check(False, "no group names at all were accepted")
    except ValueError as e:
        check("no flamesafe group" in str(e), str(e))


class _FakeArmSocket:
    def __init__(self, n):
        self.n = n
        self.wanted = [False] * n
        self.sends = []
        self.opens = 0
        self.closes = 0
        self.restarts = 0
        self.is_open = False
        self.seq = 0

    def open(self):
        self.opens += 1
        self.is_open = True
        self.wanted = [False] * self.n
        self.seq = 0

    def restart(self):
        # Mirrors sd.ArmSocket.restart (round 4, item A): same socket.
        if not self.is_open:
            self.open()
            return
        self.restarts += 1
        self.wanted = [False] * self.n
        self.seq = 0

    def close(self):
        self.closes += 1
        self.is_open = False

    def set_group(self, i, on):
        self.wanted[i] = bool(on)

    def set_all(self, on):
        self.wanted = [bool(on)] * self.n

    def send(self, names):
        self.seq += 1
        self.sends.append(list(self.wanted))


class _FakeStatusSocket:
    last = None

    def stale(self, clock=None):
        return True

    def poll(self, clock=None):
        pass


class _FakeConductor:
    """Enough of ltcplay.conductor.Conductor's shape to drive Controller,
    without constructing a real one (Conductor needs real DeviceOutputs/
    ShowOutputs, which this test is not about)."""

    def __init__(self):
        self.calls = []
        self._latched = False
        self._look = "PLAYING"

    def hold(self, who, screen):
        self.calls.append(("hold", who, screen))
        self._look = "HELD"
        return _Result(True, "Hold: ok.")

    def resume(self, who, screen):
        self.calls.append(("resume", who, screen))
        self._look = "PLAYING"
        return _Result(True, "Resume: ok.")

    def abort(self, who, screen):
        self.calls.append(("abort", who, screen))
        self._latched = True
        return _Result(True, "Abort: ok.")

    def reset(self, who, screen):
        self.calls.append(("reset", who, screen))
        self._latched = False
        return _Result(True, "Reset.")

    def snapshot(self):
        return {"latched": self._latched, "look": self._look}


class _Result:
    def __init__(self, ok, sentence):
        self.ok, self.sentence = ok, sentence


def test_streamdeck_controller_with_fakes():
    section("Stream Deck (real wiring): the controller, with a fake deck, "
            "fake sockets and a fake conductor")
    from ltcplay import streamdeck as sd

    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    names = ["front row", "cat-walk", "wave flamer"]
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "",
                      show_running_provider=lambda: True,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    down = [False] * 6

    def press(k):
        nonlocal down
        d2 = list(down)
        d2[k] = True
        c.run_once(d2)
        down = d2

    def release(k):
        nonlocal down
        d2 = list(down)
        d2[k] = False
        c.run_once(d2)
        down = d2

    press(sd.GROUP_KEYS[0])
    check(arm.wanted == [False, False, False],
          "arming is refused with no operator chosen: wanted stays false, "
          "and the hold never even starts")
    check("no operator is chosen" in events[-1][0], events[-1])
    check(c._arm_holds[0].fraction(t[0]) == 0.0,
          "the hold itself never started: nothing to let go of")
    release(sd.GROUP_KEYS[0])

    # Item 8 (Jeff, 2026-10-01): arming now needs a HOLD. A plain
    # press-and-release, even with an operator chosen, sends nothing.
    c.operator_provider = lambda: "Andy"
    press(sd.GROUP_KEYS[0])
    check(arm.wanted == [False, False, False],
          "pressing starts the hold, but nothing is sent until it "
          f"completes: {arm.wanted}")
    check(c._arm_holds[0]._down_at is not None, "the hold is now running")
    release(sd.GROUP_KEYS[0])
    check(arm.wanted == [False, False, False],
          "letting go before ARM_HOLD_S cancels the hold: nothing sent, "
          "exactly like letting go of Abort early")

    # Held the full ARM_HOLD_S this time: arms for real.
    press(sd.GROUP_KEYS[0])
    down_held = list(down)
    t[0] += sd.ARM_HOLD_S / 2
    c.run_once(down_held)           # still held, short of ARM_HOLD_S
    c.tick()                        # item 2: hold completion is tick()'s job
    check(arm.wanted == [False, False, False],
          f"held for only half of ARM_HOLD_S: nothing fired yet: "
          f"{arm.wanted}")
    t[0] += sd.ARM_HOLD_S
    c.run_once(down_held)           # held past ARM_HOLD_S
    c.tick()                        # tick() fires the now-completed hold
    check(arm.wanted == [True, False, False],
          f"holding the full ARM_HOLD_S arms front row: {arm.wanted}")
    release(sd.GROUP_KEYS[0])

    # Disarm stays an instant single tap, no hold.
    press(sd.GROUP_KEYS[0])
    check(arm.wanted == [False, False, False],
          "a single press disarms an armed group instantly, no hold "
          f"needed (Jeff, 2026-10-01): {arm.wanted}")
    release(sd.GROUP_KEYS[0])

    # Item 8's refractory window: pressing the SAME key again right after
    # its own disarm must not even start a hold.
    press(sd.GROUP_KEYS[0])
    check(arm.wanted == [False, False, False]
          and c._arm_holds[0].fraction(t[0]) == 0.0,
          "an immediate re-press right after a disarm is refused before "
          "the hold can even start")
    check("refractory" in events[-1][0], events[-1])
    release(sd.GROUP_KEYS[0])
    t[0] += sd.REARM_REFRACTORY_S + 0.1
    press(sd.GROUP_KEYS[0])
    check(c._arm_holds[0]._down_at is not None,
          "once the refractory window has passed, the same key can start "
          "a hold again")
    release(sd.GROUP_KEYS[0])

    # Start/Stop: a show is running here, so the key is Stop, a complete
    # halt (Jeff, 2026-10-26), and so a hold: a tap journals nothing and
    # sends nothing.
    n = len(events)
    press(sd.TOP_START)
    check(c._stop_hold._down_at is not None and len(events) == n,
          f"a press during a show starts a Stop hold: {events[n:]}")
    release(sd.TOP_START)
    check(len(events) == n and c._stop_hold.fraction(t[0]) == 0.0,
          f"a tap during a show sends nothing: {events[n:]}")

    # The deck has no Hold and no Abort key (Jeff, 2026-10-26): keys 1 to
    # 4 are arm keys, key 5 does nothing while the engine runs no announcements.
    check(sd.GROUP_KEYS == (1, 2, 3, 4) and not hasattr(sd, "TOP_HOLD")
          and not hasattr(sd, "TOP_ABORT"),
          "keys 1 to 4 arm groups; no Hold or Abort key on the deck")
    n = len(events)
    press(sd.SPARE_KEY)
    release(sd.SPARE_KEY)
    check(len(events) == n and arm.wanted == [False, False, False],
          "the spare key does nothing")

    # Stop: a STOP_HOLD_S hold while a run is going, every group disarmed
    # on the arm link first, whether or not an engine is connected; never
    # the Abort latch.
    arm2 = _FakeArmSocket(3)
    events2 = []
    run = [True]
    c2 = sd.Controller(arm2, status, names, operator_provider=lambda: "",
                       show_running_provider=lambda: False,
                       run_live_provider=lambda: run[0],
                       journal=lambda t_, **kw: events2.append((t_, kw)),
                       clock=lambda: t[0])
    arm2.set_group(0, True)
    arm2.set_group(2, True)
    stop = [False] * 6
    stop[sd.TOP_START] = True
    c2.run_once(stop)
    t[0] += 0.2
    c2.run_once(stop)
    c2.tick()
    check(arm2.wanted == [True, False, True],
          "held for only 0.2 s of Stop's 0.5 s: nothing yet")
    t[0] += 0.4
    c2.tick()
    check(arm2.wanted == [False, False, False] and
          arm2.sends[-1] == [False, False, False],
          f"Stop disarms every group on the arm link, no operator needed: "
          f"{arm2.wanted}")
    check(c2._latched_now() is False,
          "Stop never sets the Abort latch")
    check(all(c2._in_rearm_refractory(i, t[0]) > 0 for i in range(3)),
          "Stop starts every group's re-arm refractory window, as Abort "
          "did: a panicked re-press cannot quietly re-arm")
    check(any("no engine is connected" in e[0] for e in events2),
          "no engine wired: the /api/stop half is said, as a fault")
    c2.run_once([False] * 6)

    # With a real (fake) conductor latched by an Abort from a screen.
    class _Cond(_FakeConductor):
        def stop_run(self, who, screen):
            self.calls.append(("stop", who, screen))
            return _Result(True, "Stopped.")
    cond = _Cond()
    arm3 = _FakeArmSocket(3)
    c3 = sd.Controller(arm3, status, names, operator_provider=lambda: "Andy",
                       show_running_provider=lambda: False,
                       run_live_provider=lambda: run[0], conductor=cond,
                       journal=lambda t_, **kw: None, clock=lambda: t[0])
    cond._latched = True
    check(c3._latched_now() is True,
          "latched is read from the real conductor's own snapshot")
    arm3.set_group(1, True)
    tap = [False] * 6
    tap[sd.GROUP_KEYS[1]] = True
    c3.run_once(tap)
    c3.run_once([False] * 6)
    check(arm3.wanted == [False, False, False],
          "latched: a tap on an armed group's key disarms it")
    t[0] = 300.0
    tap0 = [False] * 6
    tap0[sd.GROUP_KEYS[0]] = True
    c3.run_once(tap0)
    t[0] += sd.ARM_HOLD_S + 0.1
    c3.run_once(tap0)
    c3.tick()
    c3.run_once([False] * 6)
    check(arm3.wanted == [False, False, False],
          "latched: nothing can be armed from a key")
    arm3.set_group(2, True)
    c3.run_once(stop)
    t[0] += sd.STOP_HOLD_S + 0.01
    c3.tick()
    c3.run_once([False] * 6)
    check(arm3.wanted == [False, False, False] and
          cond.calls[-1] == ("stop", "Andy", "Stream Deck") and
          not any(c[0] in ("abort", "reset", "hold", "resume")
                  for c in cond.calls),
          f"latched, Stop is reachable as on the Rack screen: every group "
          f"disarmed and /api/stop asked; the deck never Aborts, Resets, "
          f"Holds or Resumes: {cond.calls}")
    check(c3._latched_now() is True, "and the latch stands")


class _FakeStatus:
    """A controllable fake StatusSocket for the spoof-alarm and group_look
    wiring tests: unlike _FakeStatusSocket (always stale), this one can
    hold a real status dict and say it is fresh."""

    def __init__(self):
        self.last = None
        self._stale = True

    def set(self, doc):
        self.last = doc
        self._stale = False

    def stale(self, clock=None):
        return self._stale

    def poll(self, clock=None):
        pass


def _deck_draw_stubs(sd):
    """For a test that drives the REAL sd.run_forever(): stub the drawing
    it does on every pass, which is hardware-adjacent rendering, not the
    logic under test. Fonts.text_block is always stubbed (no font file on
    CI). Where Pillow itself is missing, as on the CI runners, which never
    install it, Fonts and Controller.draw are stubbed too: Fonts() calls
    _import_pil(), which raises SystemExit without Pillow. Before this
    (found in round 5) that SystemExit ended the whole suite at the first
    of these tests on every OS since round 3, so none of the Stream Deck
    tests after it ever ran in CI. Returns a function that undoes it all."""
    real_fonts, real_draw = sd.Fonts, sd.Controller.draw
    real_text_block = real_fonts.text_block
    real_fonts.text_block = lambda self, *a, **kw: None
    try:
        import PIL.Image  # noqa: F401
        have_pillow = True
    except Exception:                     # noqa: BLE001
        have_pillow = False
    if not have_pillow:
        class _Img:
            def crop(self, box):
                return self

        class _NoPillowFonts:
            Image = None

        sd.Fonts = _NoPillowFonts
        sd.Controller.draw = lambda self, *a, **kw: _Img()

    def restore():
        sd.Fonts = real_fonts
        sd.Controller.draw = real_draw
        real_fonts.text_block = real_text_block
    return restore


def test_streamdeck_look_a_marquee():
    section("Stream Deck: the approved look A (Jeff, 2026-09-27): a ring of "
            "marquee dots round every key and no solid outline; two snakes "
            "the same way round the deck's outside dots, half a lap apart; "
            "Abort fills every key's own ring red, clockwise, all at once, "
            "and fully while latched; an arm-hold fills that key's ring gold")
    from ltcplay import streamdeck as sd
    check((sd.DOT_INSET, sd.DOT_SPACING, sd.DOT_R) == (6, 11.0, 2.6)
          and sd.RUN_FRACTION == 0.16 and sd.CHASE_STEP_S == 0.06
          and sd.FACE_MARGIN == 12 and sd.STOP_HOLD_S == 0.5,
          "look A's geometry and pace are the demo's own numbers")
    check(sd.face_box(4) == (92, 92, 148, 148),
          f"faces sit 12 px inside each key: {sd.face_box(4)}")
    rings = [sd.key_ring(k) for k in range(6)]
    check(all(len(r) == 24 for r in rings) and len(sd.ALL_DOTS) == 144,
          f"24 dots round each key, 144 in all: "
          f"{[len(r) for r in rings]}, {len(sd.ALL_DOTS)}")
    check(rings[0][0] == (6, 6) and rings[0][6] == (74, 6)
          and rings[0][12] == (74, 74) and rings[0][18] == (6, 74),
          f"each ring runs clockwise from its top-left dot: "
          f"{rings[0][0]}, {rings[0][6]}, {rings[0][12]}, {rings[0][18]}")
    outer = sd.OUTER_DOTS
    n = len(outer)
    check(n == 66 and outer[0] == (6, 6) and outer[1][1] == 6
          and outer[1][0] > 6,
          f"66 outside dots, clockwise along the top first: {n}, "
          f"{outer[:2]}")
    run = round(n * sd.RUN_FRACTION)
    for chase in (0, 7, 59, 123):
        c = sd.marquee_colours(chase, 0.0)
        heads = [i for i, p in enumerate(outer) if c[p] == sd.CHAMPAGNE]
        gold = [p for p in sd.ALL_DOTS if c[p] == sd.GOLD]
        want = sorted({chase % n, (chase + n // 2) % n})
        check(heads == want and len(gold) == 2 * (run - 1)
              and all(p in outer for p in gold)
              and all(c[outer[(h - j) % n]] == sd.GOLD
                      for h in heads for j in range(1, run))
              and all(c[p] == sd.BULB_OFF for p in sd.ALL_DOTS
                      if p not in outer),
              f"chase {chase}: two champagne heads half a lap apart at "
              f"{want}, each trailing {run - 1} gold dots behind it on the "
              f"outside, every other dot unlit: heads {heads}, "
              f"{len(gold)} gold")
    c0, c1 = sd.marquee_colours(10, 0.0), sd.marquee_colours(11, 0.0)
    h0 = [i for i, p in enumerate(outer) if c0[p] == sd.CHAMPAGNE]
    h1 = [i for i, p in enumerate(outer) if c1[p] == sd.CHAMPAGNE]
    check([(b - a) % n for a, b in zip(h0, h1)] == [1, 1],
          f"both snakes step the same way, one dot per step: {h0} -> {h1}")
    half = sd.marquee_colours(5, 0.5)
    check(all([half[p] for p in r] == [sd.RED] * 12 + [sd.BULB_OFF] * 12
              for r in rings),
          "Abort held halfway: every key's own ring is red for its first "
          "half, clockwise, all keys at once, and nothing chases")
    full = sd.marquee_colours(5, 1.0)
    check(set(full.values()) == {sd.RED},
          "Abort complete or latched: every dot on the deck is red")
    arm = sd.marquee_colours(0, 0.0, {4: 0.5})
    check([arm[p] for p in rings[4]] == [sd.GOLD] * 12 + [sd.BULB_OFF] * 12,
          "an arm-hold halfway fills that key's ring gold, clockwise, with "
          "no snake across it")
    check(sd.CHAMPAGNE in {arm[p] for p in rings[0]},
          "the snakes keep running round the other keys meanwhile")
    try:
        import PIL.Image  # noqa: F401
    except Exception:                     # noqa: BLE001
        print("  note: Pillow is not installed here, so look A's pixels are "
              "not checked on this machine.")
        print("  ok")
        return
    fonts = sd.Fonts()
    fonts.text_block = lambda *a, **kw: None
    t = [10.0]
    ctl = sd.Controller(_FakeArmSocket(3), _FakeStatusSocket(),
                        ["front row", "cat-walk", "wave flamer"],
                        operator_provider=lambda: "Andy",
                        show_running_provider=lambda: True,
                        clock=lambda: t[0])
    img = ctl.draw(fonts, blink_on=True, chase=3)
    want = sd.marquee_colours(3, 0.0)
    check(all(img.getpixel((round(x), round(y))) == want[(x, y)]
              for (x, y) in sd.ALL_DOTS),
          "the drawn deck carries every dot in its marquee colour")
    # Between two dots of a ring, on the ring's own line, is the deck's
    # black: a solid outline (the old look B) would be drawn there.
    edge = {img.getpixel((ox + x, oy + y)) for k in range(6)
            for ox, oy in [sd.key_origin(k)]
            for x, y in ((6, 12), (12, 6), (74, 12), (12, 74))}
    check(edge == {sd.BLACK},
          f"no solid outline round any key, only dots: {edge}")
    ctl._latched = True
    img = ctl.draw(fonts, blink_on=True, chase=3)
    check(all(img.getpixel((round(x), round(y))) == sd.RED
              for (x, y) in sd.ALL_DOTS),
          "latched: every dot of every ring is drawn red")
    print("  ok")


def test_streamdeck_idle_deck_draws_rarely():
    section("Stream Deck: what moves on the keys is evidence of life, never "
            "the deck's own clock (Jeff, 2026-10-05; the approved demo's "
            "freeze). The snakes step on flamesafe's status frames, one step "
            "per 0.06 s of its ticks; the bottom row flashes on them too; "
            "the top row flashes on the engine's fresh answers. Frozen "
            "flamesafe and engine: nothing moves. The keys are redrawn only "
            "when something on them changed, a held key every FRAME_S, and "
            "the arm link still goes out every pass")
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    alive = [True]

    class _TickingStatus:
        """flamesafe at 40 Hz: each poll reads the newest status frame,
        whose heartbeat counts its ticks, until it freezes."""
        last = None
        hb = 0

        def poll(self, clock=None):
            if alive[0]:
                self.hb = int(t[0] / 0.025)
            self.last = {"heartbeat": self.hb, "tick_ms": 25.0,
                         "fault": "", "confirmed": True, "groups": []}

        def stale(self, clock=None):
            return False

    class _AnsweringEngine:
        """The engine answering a 4 Hz poll, until it freezes."""
        at = None

        def answered_at(self):
            if alive[0]:
                self.at = int(t[0] / 0.25) * 0.25
            return self.at

        def snapshot(self):
            return {"latched": False, "look": ""}

    c = sd.Controller(arm, _TickingStatus(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True,
                      conductor=_AnsweringEngine(), clock=lambda: t[0])

    class _Stop(BaseException):
        pass
    press = [False] * 6
    press[sd.GROUP_KEYS[0]] = True
    draws = []

    class _Deck:
        def __init__(self):
            self.i = 0

        def keys_down(self):
            i, self.i = self.i, self.i + 1
            if i == 200:
                draws.append("held")
                return [press]
            if i == 220:
                return [[False] * 6]
            if i == 300:
                alive[0] = False
                draws.append("frozen")
            if i >= 340:
                raise _Stop()
            return []

        def set_key(self, image, key, img):
            pass

        def close(self):
            pass
    restore = _deck_draw_stubs(sd)
    real_draw = sd.Controller.draw

    def counting_draw(self, fonts, blink_on, chase, group_blink=None):
        draws.append((t[0], self._prev_keys[sd.GROUP_KEYS[0]], chase,
                      blink_on, group_blink))
        return real_draw(self, fonts, blink_on, chase, group_blink)
    sd.Controller.draw = counting_draw
    try:
        sd.run_forever(c, deck_factory=_Deck,
                       sleep=lambda s_: t.__setitem__(0, t[0] + s_),
                       clock=lambda: t[0])
    except _Stop:
        pass
    finally:
        sd.Controller.draw = real_draw
        restore()
    i, j = draws.index("held"), draws.index("frozen")
    idle = [d for d in draws[1:i]]          # the first draw is the connect
    held = [d for d in draws[i + 1:j] if d[1]]
    frozen = [d for d in draws[j + 1:] if d[0] > t[0] - 1.9]
    span = idle[-1][0] - idle[0][0]
    rate = (idle[-1][2] - idle[0][2]) / span
    check(abs(rate - 1.0 / sd.CHASE_STEP_S) < 0.5,
          f"healthy: the snakes step {rate:.1f} times a second, the "
          f"demo's one step per {sd.CHASE_STEP_S:g} s")
    toggles = sum(1 for a, b in zip(idle, idle[1:]) if a[3] != b[3])
    gtoggles = sum(1 for a, b in zip(idle, idle[1:]) if a[4] != b[4])
    check(abs(toggles - span / 0.5) <= 2 and abs(gtoggles - span / 0.5) <= 2,
          f"healthy: the top row changes phase every 2 engine answers and "
          f"the bottom row every 0.5 s of flamesafe's ticks: {toggles} and "
          f"{gtoggles} changes in {span:.1f} s")
    check(all(a[2:] != b[2:] for a, b in zip(idle, idle[1:])),
          "healthy and idle: the keys are drawn only when the snakes or a "
          "flash moved, never twice the same")
    steps = span / sd.CHASE_STEP_S
    check(steps - 2 <= len(idle) <= steps + toggles + gtoggles + 2,
          f"idle: {len(idle)} draws in {span:.1f} s, one per change "
          f"({steps:.0f} steps, {toggles + gtoggles} flashes)")
    check(len(frozen) >= 3 and len({d[2:] for d in frozen}) == 1,
          f"frozen flamesafe and engine: the snakes and every flash stop "
          f"dead: {sorted({d[2:] for d in frozen})}")
    check(len(frozen) <= 1.9 / sd.DRAW_IDLE_S + 2,
          f"frozen: drawn only every {sd.DRAW_IDLE_S:g} s, for a state "
          f"change: {len(frozen)} draws in 1.9 s")
    frames = 20 * (1.0 / sd.ARM_SEND_HZ) / sd.FRAME_S
    check(len(held) >= frames - 3,
          f"a key held is drawn every {sd.FRAME_S:g} s, its ring on the "
          f"deck's own clock: {len(held)} draws in 20 passes "
          f"({frames:.0f} frames)")
    check(len(arm.sends) >= 335, f"the arm link went out every pass: "
                                 f"{len(arm.sends)}")
    print("  ok")


def _deck_face_recorder(sd):
    """A real Fonts whose show_key and text_block only record what each
    key was told to read (lines, colours, background), with the module's
    arm_key_image recorded the same way. Returns (fonts, faces, restore),
    `faces` a dict of key number -> (lines, text, bg) or, for a bottom-row
    key, (name, look), refilled on every draw. None without Pillow."""
    # Without Pillow the deck tests that read `faces` skip themselves; in
    # CI that is a FAIL (_pillow_missing), since this is exactly how PR
    # #49's "deck states" and "deck look" mutations went NOT CAUGHT in a
    # mutate job that never installed Pillow (shards 0 to 3, 8, 9, 24, 30
    # and 31).
    if _pillow_missing("the deck's key faces"):
        return None, None, lambda: None
    fonts = sd.Fonts()
    fonts.text_block = lambda *a, **kw: None
    faces = {}
    key_of = {sd.face_box(k): k for k in range(6)}

    def show_key(d, box, lines, text, bg=None, kind="serif", max_size=24):
        faces[key_of[tuple(box)]] = (list(lines), text, bg)
    fonts.show_key = show_key
    real_arm_key_image = sd.arm_key_image

    def arm_key_image(fonts_, d, box, name, look, blink_on):
        faces[key_of[tuple(box)]] = (name, tuple(look))
    sd.arm_key_image = arm_key_image

    def restore():
        sd.arm_key_image = real_arm_key_image
    return fonts, faces, restore


def test_streamdeck_stop_hold_face_and_ring_from_the_first_instant():
    section("Stream Deck: a Stop hold on key 0 reads HOLD TO STOP from the "
            "first instant it is held, its ring fills 0 to 1 over "
            "STOP_HOLD_S, and both are gone once it is let go: during a "
            "show, held, with a run going, with the state unknown and "
            "while aborted (the full mutation sweep, 2026-10-27: a Stop "
            "hold that never showed on the key went uncaught)")
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]

    class _Cond(_FakeConductor):
        def stop_run(self, who="", screen=""):
            self.calls.append(("stop", who, screen))
            return _Result(True, "Stopped.")
    fonts, faces, restore = _deck_face_recorder(sd)
    if fonts is None:
        print("  ok")
        return
    rings = []
    real_marquee = sd.draw_marquee

    def draw_marquee(d, chase, abort_frac, arm_fills=None):
        rings.append(dict(arm_fills or {}))
        return real_marquee(d, chase, abort_frac, arm_fills)
    sd.draw_marquee = draw_marquee
    up, down = [False] * 6, [True] + [False] * 5
    hold_face = ["HOLD TO", "STOP"]
    # (what, show running, run live, conductor look, latched, the face the
    # key reads when it is not held)
    cases = [
        ("during a show", True, False, "PLAYING", False, ["NOW", "PLAYING"]),
        ("a show held", True, False, "HELD", False, ["PAUSED"]),
        ("a run going", False, True, "BETWEEN", False, ["STOP", "RUN"]),
        ("the state unknown", None, False, "BETWEEN", False,
         ["STOP", "ALL"]),
        ("aborted during a show", True, False, "PLAYING", True,
         ["STOP", "RUN"]),
    ]
    try:
        for what, running, live, look, latched, calm in cases:
            t = [100.0]
            cond = _Cond()
            cond._look, cond._latched = look, latched
            c = sd.Controller(_FakeArmSocket(3), _FakeStatusSocket(), names,
                              operator_provider=lambda: "Andy",
                              show_running_provider=lambda r=running: r,
                              run_live_provider=lambda v=live: v,
                              conductor=cond, clock=lambda: t[0],
                              journal=lambda *a, **kw: None)

            def frame():
                del rings[:]
                c.draw(fonts, blink_on=True, chase=0)
                check(len(rings) == 1, f"{what}: one ring per frame: "
                                       f"{rings}")
                return faces[0][0], rings[-1].get(sd.TOP_START)
            face, fill = frame()
            check(face == calm and fill is None,
                  f"{what}, not held: the key reads {calm}, no Stop ring: "
                  f"{face} {fill}")
            c.run_once(down)
            check(c._stop_hold.fraction(t[0]) == 0.0 and
                  c._stop_hold._down_at == t[0],
                  f"{what}: the press starts a Stop hold")
            face, fill = frame()
            check(fill is None,
                  f"{what}: pressed this very instant, the ring has not "
                  f"started: {fill}")
            t0, last = t[0], 0.0
            # The first instants, under STOP_FACE_AFTER_S, then on to the
            # very end of the hold: HOLD TO STOP throughout, the fill the
            # time held over STOP_HOLD_S, always growing.
            for dt in (0.01, sd.STOP_FACE_AFTER_S / 2,
                       sd.STOP_FACE_AFTER_S * 0.9, sd.STOP_FACE_AFTER_S,
                       sd.STOP_HOLD_S / 2, sd.STOP_HOLD_S * 0.9,
                       sd.STOP_HOLD_S):
                t[0] = t0 + dt
                face, fill = frame()
                want = min(1.0, dt / sd.STOP_HOLD_S)
                check(face == hold_face,
                      f"{what}, held {dt:.3f} s: the key reads HOLD TO "
                      f"STOP from the first instant: {face}")
                check(fill is not None and abs(fill - want) < 1e-9
                      and fill > last,
                      f"{what}, held {dt:.3f} s: Stop's ring fills to "
                      f"{want:.3f}, more than before ({last:.3f}): {fill}")
                last = fill or last
            check(last == 1.0, f"{what}: held STOP_HOLD_S, full: {last}")
            check(not [x for x in cond.calls if x[0] == "stop"],
                  f"{what}: drawing never stops anything: {cond.calls}")
            # Let go before the hold completes (a fresh hold): the face and
            # the ring go with it, and nothing was sent.
            c.run_once(up)
            face, fill = frame()
            check(face == calm and fill is None,
                  f"{what}, let go: {calm} again, no Stop ring: {face} "
                  f"{fill}")
            c.run_once(down)
            t[0] += sd.STOP_HOLD_S * 0.1
            face, fill = frame()
            check(face == hold_face and fill is not None and
                  abs(fill - 0.1) < 1e-9,
                  f"{what}, a second hold: HOLD TO STOP, the ring from 0 "
                  f"again: {face} {fill}")
            c.run_once(up)
            t[0] += sd.STOP_HOLD_S
            c.tick()
            face, fill = frame()
            check(face == calm and fill is None and
                  not [x for x in cond.calls if x[0] == "stop"],
                  f"{what}, let go early: {calm}, no ring, nothing "
                  f"stopped: {face} {fill} {cond.calls}")
    finally:
        sd.draw_marquee = real_marquee
        restore()
    print("  ok")


def test_streamdeck_start_key_during_a_show():
    section("Stream Deck: during a show the Start key reads NOW PLAYING, "
            "flashing green on the engine's own answers; PAUSED while the "
            "show is held; AUDIO LOST, flashing amber, while the engine "
            "says the show audio is lost, on that one key only, Hold and "
            "Abort never covered (Jeff, 2026-09-27, the approved demo and "
            "\"Lock them in\")")
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatus()
    status.set({"arm_input": {"state": "live", "seq": 1}, "fault": "",
                "confirmed": True, "groups": [
                    {"name": n, "armed": "disarmed", "wanted": False,
                     "reason": "", "amber": "", "dwell_s": 0}
                    for n in names]})
    running = [True]
    lines = []

    class _Engine:
        look = "PLAYING"
        lost = False
        calls = []

        def snapshot(self):
            return {"latched": False, "look": self.look}

        def audio_lost(self):
            return self.lost

        def hold(self, who, screen):
            self.calls.append("hold")
            return sd.EngineResult(True, "Hold: ok.")
    eng = _Engine()
    t = [10.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: running[0],
                      conductor=eng, clock=lambda: t[0],
                      journal=lambda text, **kw: lines.append((text, kw)))
    # Pressing the Start/Stop key during the show: it is Stop, a complete
    # halt (Jeff, 2026-10-26: the show ends), and so a HOLD: a tap sends
    # nothing and asks nothing of the engine. NOW PLAYING is honest.
    c.run_once([True, False, False, False, False, False])
    check(c._stop_hold._down_at is not None,
          "a press during the show starts a Stop hold")
    c.run_once([False] * 6)
    check(not lines and not eng.calls and
          c._stop_hold.fraction(t[0]) == 0.0,
          f"a tap on Start/Stop during a show sends nothing: {lines}")
    fonts, faces, restore = _deck_face_recorder(sd)
    if fonts is None:
        print("  note: Pillow is not installed here, so the Start key's "
              "words are not checked on this machine.")
        print("  ok")
        return
    try:
        for on in (True, False):
            c.draw(fonts, blink_on=on, chase=0)
            bg, text = sd.PLAYING_ON if on else sd.PLAYING_OFF
            check(faces[0] == (["NOW", "PLAYING"], text, bg),
                  f"show playing, flash phase {on}: NOW PLAYING in the "
                  f"demo's green: {faces[0]}")
            check(sd.SPARE_KEY not in faces and
                  all(k == 0 or k in sd.GROUP_KEYS for k in faces),
                  f"no Hold or Abort face on the deck, the spare key blank: "
                  f"{sorted(faces)}")
        check(sd.PLAYING_ON == ((50, 205, 95), (4, 28, 10))
              and sd.PLAYING_OFF == ((8, 40, 16), (60, 200, 100)),
              "the green is the approved demo's")
        # Held during the show: Stop's hold fills, HOLD TO STOP (Jeff,
        # 2026-10-26: Stop is a complete halt, the show ends).
        c.run_once([True, False, False, False, False, False])
        t[0] += sd.STOP_HOLD_S / 2
        c.tick()
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0][0] == ["HOLD TO", "STOP"],
              f"held during a show: HOLD TO STOP: {faces[0]}")
        c.run_once([False] * 6)
        check(not eng.calls, "let go early: nothing")
        eng.look = "HELD"
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["PAUSED"], sd.CHAMPAGNE, sd.PAUSED_BG),
              f"held: PAUSED on the Start key: {faces[0]}")
        eng.lost = True
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["PAUSED"], sd.CHAMPAGNE, sd.PAUSED_BG),
              f"held with the audio lost: still PAUSED, the operator's own "
              f"Hold: {faces[0]}")
        eng.look = "PLAYING"
        eng.lost = False
        c.draw(fonts, blink_on=True, chase=0)
        calm = dict(faces)
        eng.lost = True
        for on in (True, False):
            c.draw(fonts, blink_on=on, chase=0)
            bg, text = sd.AUDIO_LOST_ON if on else sd.AUDIO_LOST_OFF
            check(faces[0] == (["AUDIO", "LOST"], text, bg),
                  f"audio lost mid-show, flash phase {on}: AUDIO LOST, "
                  f"amber: {faces[0]}")
            check({k: v for k, v in faces.items() if k} ==
                  {k: v for k, v in calm.items() if k},
                  f"only the Start key changed: the arm keys read exactly "
                  f"as before: {faces}")
        check(sd.AUDIO_LOST_ON == (sd.AMBER, (40, 20, 0))
              and sd.AUDIO_LOST_OFF == (sd.AMBER_DIM, sd.AMBER),
              "AUDIO LOST flashes amber like CYCLE ARM")
        running[0] = False
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["START", "NOW"], sd.CHAMPAGNE, None),
              f"no show running: START NOW, lost audio or not: {faces[0]}")
        eng.look = "HELD"
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["START", "NOW"], sd.DIM_TEXT, None),
              f"held with no show: START NOW dims, as the demo has it: "
              f"{faces[0]}")
        eng.look = "PLAYING"
        eng.lost = False
        running[0] = True
        # The flash is the engine's liveness, never the deck's own clock:
        # the same phase whatever the clock says, a new phase on answers.
        c.conductor = type("_AnsweringEngine", (), {
            "at": [None],
            "answered_at": lambda s: s.at[0],
            "snapshot": lambda s: {"latched": False, "look": "PLAYING"},
            "audio_lost": lambda s: False})()
        seen = set()
        for step in range(8):
            t[0] = 10.0 + step * 0.26
            c.conductor.at[0] = 1.0      # frozen engine: no new answer
            c.draw(fonts, c.engine_blink(), chase=0)
            seen.add(faces[0][2])
        check(len(seen) == 1, f"a frozen engine freezes NOW PLAYING's "
                              f"flash whatever the deck's clock says: "
                              f"{seen}")
        for n in range(2 * sd.ENGINE_ANSWERS_PER_BLINK):
            c.conductor.at[0] = 2.0 + n
            c.draw(fonts, c.engine_blink(), chase=0)
            seen.add(faces[0][2])
        check(seen == {sd.PLAYING_ON[0], sd.PLAYING_OFF[0]},
              f"fresh answers change its phase: {seen}")
    finally:
        restore()
    print("  ok")


def test_streamdeck_no_flame_link_words():
    section("Stream Deck: with no link to flamesafe the arm keys read "
            "NO / FLAME / LINK, one red word per key, steady, in place of "
            "the old dim flashing NO LINK (Jeff, 2026-09-27, locked "
            "wording); the arm link is held OFF exactly as before")
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [10.0]
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      clock=lambda: t[0])
    fonts, faces, restore = _deck_face_recorder(sd)
    if fonts is None:
        print("  note: Pillow is not installed here, so the arm keys' "
              "words are not checked on this machine.")
        print("  ok")
        return
    words = [(w, None, sd.RED, sd.CHAMPAGNE, False)
             for w in ("NO", "FLAME", "LINK")] + [
                 ("NO", "LINK", sd.RED, sd.CHAMPAGNE, False)]
    want = list(zip(names + [""], words))
    try:
        for blink in (True, False):
            c.draw(fonts, blink_on=blink, chase=0, group_blink=blink)
            check([faces[k] for k in sd.GROUP_KEYS] == want,
                  f"no link, flash phase {blink}: the arm keys read NO / "
                  f"FLAME / LINK in red, steady, each over its own group's "
                  f"name, and the fourth (no group) NO LINK: "
                  f"{[faces[k] for k in sd.GROUP_KEYS]}")
        c._latched = True
        c.draw(fonts, blink_on=True, chase=0)
        check([faces[k] for k in sd.GROUP_KEYS] == want,
              f"latched: the missing link still shows, never greyed over: "
              f"{[faces[k] for k in sd.GROUP_KEYS]}")
        c._latched = False
        check(arm.wanted == [False] * 3 and not arm.sends,
              "drawing changed nothing on the arm link: every group still "
              "wanted off")
        one = sd.Controller(_FakeArmSocket(1), _FakeStatusSocket(),
                            ["front row"], operator_provider=lambda: "Andy",
                            show_running_provider=lambda: False,
                            clock=lambda: t[0])
        one.draw(fonts, blink_on=True, chase=0)
        check([faces[k] for k in sd.GROUP_KEYS] ==
              [("front row", words[0]), ("", words[1]), ("", words[2]),
               ("", words[3])],
              f"one group: the message still reads whole across the four "
              f"keys: {[faces[k] for k in sd.GROUP_KEYS]}")
        faces.clear()
        st = _FakeStatus()
        st.set({"arm_input": {"state": "live", "seq": 1}, "fault": "",
                "confirmed": True, "groups": [
                    {"name": "front row", "armed": "disarmed",
                     "wanted": False, "reason": "", "amber": "",
                     "dwell_s": 0}]})
        one.status = st
        one.draw(fonts, blink_on=True, chase=0)
        check(faces[sd.GROUP_KEYS[0]][1][0] == "OFF"
              and sd.GROUP_KEYS[1] not in faces,
              f"the link back: OFF, and the spare keys go blank: {faces}")
    finally:
        restore()
    print("  ok")


def test_streamdeck_tick_drives_holds_without_new_key_snapshots():
    section("Stream Deck: tick() advances the Stop hold and every group's "
            "arm-hold on EVERY main-loop pass, even when keys_down() "
            "reports a key's state only on CHANGE and hands back nothing "
            "while it is held (item 2, round 2 of the safety review). "
            "Round 3 of the safety review found the regression test added "
            "for this mirrored run_forever()'s OWN loop body instead of "
            "calling it -- so a regression that removed the tick() call "
            "from run_forever entirely would NOT have been caught. This "
            "version calls the REAL sd.run_forever() with a fake deck and "
            "a fake clock/sleep (no hardware, no PIL fonts needed): only "
            "Fonts.text_block is stubbed out, since drawing needs a real "
            "font file this CI box does not have, and that is hardware-"
            "adjacent rendering, not the logic under test.")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      run_live_provider=lambda: True,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    # 2 s holds for this test, independent of the real ARM_HOLD_S /
    # STOP_HOLD_S constants: what is under test is the tick() mechanism
    # itself (does a hold complete without a new snapshot), not any
    # particular duration.
    c._stop_hold = sd.AbortHold(hold_s=2.0)
    c._arm_holds = [sd.AbortHold(hold_s=2.0) for _ in names]

    class _StopTest(BaseException):
        """Not an Exception at all, like KeyboardInterrupt: run_forever()
        treats every Exception as an unplug (round 5, item 2) and lets only
        a deliberate stop through, so raising this from keys_down() is how
        this test ends a loop that is otherwise infinite by design."""

    down_all_false = [False] * 6
    press_group0 = list(down_all_false)
    press_group0[sd.GROUP_KEYS[0]] = True
    press_abort = list(down_all_false)
    press_abort[sd.TOP_START] = True        # Stop, held
    results = {}

    class _ChangeOnlyDeck:
        """Deck.keys_down(): hands back a new 6-key snapshot exactly once,
        on the pass it actually changes, and an EMPTY list on every other
        pass -- what the safety review believed the real Stream Deck Mini
        hardware does, and the more demanding of the two possibilities
        (module docstring, "What NOT to do": this test covers it without
        settling the hardware question either way). A caller that only
        checks hold completion inside run_once() -- which this fake would
        never call again between the press and the release -- could never
        see the hold complete. The checks themselves run INSIDE
        keys_down(), at the pass index where the right number of tick()
        calls (driven by the real run_forever(), not this test) have
        already happened: that is the only place this test can read state
        mid-run, since run_forever() does not return until it raises."""

        def __init__(self):
            self.i = 0

        def keys_down(self):
            i, self.i = self.i, self.i + 1
            if i == 0:
                return [press_group0]            # start the arm-hold
            if i == 50:                          # 50 passes @ 0.05 s = 2.5 s
                results["armed_from_tick_alone"] = list(arm.wanted)
                return [list(down_all_false)]    # release
            if i == 51:
                return [press_abort]             # start the Stop hold
            if i == 101:                         # another 50 passes
                results["disarmed_from_tick_alone"] = list(arm.wanted)
                return [list(down_all_false)]    # release
            if i >= 102:
                raise _StopTest()
            return []

        def set_key(self, image, key, img):
            pass

        def close(self):
            pass

    deck = _ChangeOnlyDeck()
    restore_drawing = _deck_draw_stubs(sd)
    try:
        sd.run_forever(c, deck_factory=lambda: deck,
                       journal=lambda t_, **kw: events.append((t_, kw)),
                       sleep=lambda s: t.__setitem__(0, t[0] + s),
                       clock=lambda: t[0])
    except _StopTest:
        pass
    finally:
        restore_drawing()

    check(results.get("armed_from_tick_alone") == [True, False, False],
          f"a 2 s arm-hold completes from tick() alone, inside the REAL "
          f"run_forever() loop, even though keys_down() never reported "
          f"anything after the initial press: "
          f"{results.get('armed_from_tick_alone')}")
    check(results.get("disarmed_from_tick_alone") == [False, False, False],
          f"a 2 s Stop hold ALSO completes from tick() alone, inside the "
          f"REAL run_forever() loop, under the same condition: "
          f"{results.get('disarmed_from_tick_alone')}")


def test_streamdeck_reconnect_resets_hold_state_and_key_snapshot():
    section("Stream Deck: a reconnect clears every hold-start timestamp "
            "and the last-seen key snapshot, not only ArmSocket's own "
            "`wanted`/seq (item 2, round 3 of the safety review -- a "
            "PROVEN bug: a group key mid-hold when the deck unplugs, "
            "released while it is unplugged, used to fire the arm on the "
            "very FIRST pass after reconnecting, purely because real time "
            "kept passing during the outage -- tick() runs unconditionally "
            "every pass and checked the hold's elapsed time against a "
            "press timestamp from before the gap that nothing had ever "
            "cleared). This calls the REAL sd.run_forever() across a real "
            "DeckDisconnected/reconnect cycle, with two fake decks.")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    # A short hold for this test: run_forever's own reconnect path sleeps a
    # full second on a DeckDisconnected before trying again, which alone
    # is already many times a short hold's own duration -- exactly the gap
    # this fix has to survive, with no dependency on the real ARM_HOLD_S.
    c._arm_holds = [sd.AbortHold(hold_s=0.1) for _ in names]

    class _StopTest(BaseException):
        """A deliberate stop, like KeyboardInterrupt: run_forever() does
        not catch this (it handles every Exception as an unplug)."""

    down_all_false = [False] * 6
    press_group0 = list(down_all_false)
    press_group0[sd.GROUP_KEYS[0]] = True

    class _Deck1:
        """The real deck: reports front row's key going down once, then
        unplugs (DeckDisconnected) on its very next read -- disconnected
        with the key held down mid-hold."""

        def __init__(self):
            self.i = 0

        def keys_down(self):
            self.i += 1
            if self.i == 1:
                return [press_group0]
            raise sd.DeckDisconnected("unplugged mid-hold")

        def set_key(self, image, key, img):
            pass

        def close(self):
            pass

    class _Deck2:
        """The reconnect. The operator physically released the key WHILE
        the deck was unplugged (module docstring, failure mode 2's own
        scenario) -- real hardware reports a key's state only on change,
        and from ITS point of view nothing has changed since before the
        gap (it never reported anything then either), so keys_down() hands
        back nothing at all, pass after pass: the worst, most demanding
        case, matching this file's own established choice for the other
        tick() test above."""

        def __init__(self):
            self.i = 0

        def keys_down(self):
            self.i += 1
            if self.i > 5:
                raise _StopTest()
            return []

        def set_key(self, image, key, img):
            pass

        def close(self):
            pass

    decks = [_Deck1(), _Deck2()]

    def deck_factory():
        return decks.pop(0)

    restore_drawing = _deck_draw_stubs(sd)
    try:
        sd.run_forever(c, deck_factory=deck_factory,
                       journal=lambda t_, **kw: events.append((t_, kw)),
                       sleep=lambda s: t.__setitem__(0, t[0] + s),
                       clock=lambda: t[0])
    except _StopTest:
        pass
    finally:
        restore_drawing()

    check(arm.wanted == [False, False, False],
          f"a hold in progress when the deck unplugged, released WHILE it "
          f"was unplugged, must NOT fire on reconnect just because real "
          f"time kept passing during the outage: {arm.wanted}")
    check(not any(kw.get("action") == "arm" for _text, kw in events),
          f"no arm line was journaled for a press that never really "
          f"happened after the reconnect: {events}")


def test_streamdeck_abort_same_pass_as_arm_hold_completion():
    section("Stream Deck: a Stop firing in the SAME main-loop pass an "
            "arm-hold completes in must never also arm the group Stop just "
            "disarmed (item 3, round 2 of the safety review; the deck's "
            "Abort key had the rule until it went, 2026-10-26)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      run_live_provider=lambda: True,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    # Start an arm-hold on front row, and (independently) a Stop hold,
    # timed so BOTH reach their own fired() threshold in the same tick().
    down = [False] * 6
    down[sd.GROUP_KEYS[0]] = True
    c.run_once(down)                         # front row hold starts at t=0
    t[0] = 0.1
    down2 = list(down)
    down2[sd.TOP_START] = True
    c.run_once(down2)                        # Stop hold starts at t=0.1
    t[0] = 0.1 + sd.STOP_HOLD_S + 0.01
    check(c._stop_hold.fraction(t[0]) >= 1.0
          and c._arm_holds[0].fraction(t[0]) >= 1.0,
          "both holds have reached completion by this instant: a real "
          "race between a Stop and an in-progress arm-hold")
    c.tick()
    check(arm.wanted == [False, False, False],
          f"Stop fired, and front row was NOT also armed in the same "
          f"pass: {arm.wanted}")
    check(not any(e for e in events if e[1].get("action") == "arm"
                  and "front row" in e[0] and "refused" not in e[0]),
          f"no successful arm line was journaled for front row: {events}")

    # The two guards are meant to be INDEPENDENT: prove the ordering fix
    # (the `return` right after _do_stop() in tick()) on its own: in the
    # pass Stop fires, _do_arm_fire must never even be reached.
    arm2 = _FakeArmSocket(3)
    t2 = [0.0]
    c2 = sd.Controller(arm2, _FakeStatusSocket(), names,
                       operator_provider=lambda: "Andy",
                       show_running_provider=lambda: False,
                       run_live_provider=lambda: True,
                       clock=lambda: t2[0])
    reached = []
    c2._do_arm_fire = lambda i, now: reached.append(i)
    c2.run_once(down)
    t2[0] = 0.1
    c2.run_once(down2)
    t2[0] = 0.1 + sd.STOP_HOLD_S + 0.01
    c2.tick()
    check(arm2.wanted == [False, False, False] and not reached,
          f"in the pass Stop fires, tick() returns before ANY arm-hold "
          f"completion is even attempted -- the ordering guard on its own, "
          f"not relying on _do_arm_fire's own refusal: reached={reached}")


def test_streamdeck_arm_fire_refuses_latched_and_refractory():
    section("Stream Deck: _do_arm_fire refuses to arm a latched rig or a "
            "group still inside its own re-arm refractory window, as a "
            "SECOND, independent guard -- not relying solely on ordering "
            "within one pass (item 3, round 2 of the safety review)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True,
                      clock=lambda: t[0])

    c._latched = True
    c._do_arm_fire(0, t[0])
    check(arm.wanted == [False, False, False],
          "a latched rig refuses to arm even when _do_arm_fire is called "
          "directly (the second, independent guard)")
    c._latched = False

    c._disarmed_at[0] = t[0]
    c._do_arm_fire(0, t[0] + 0.1)
    check(arm.wanted == [False, False, False],
          "still inside the re-arm refractory window: refused even though "
          "nothing re-checks ordering here")
    t[0] += sd.REARM_REFRACTORY_S + 0.1
    c._do_arm_fire(0, t[0])
    check(arm.wanted == [True, False, False],
          f"once the refractory window has passed, _do_arm_fire succeeds: "
          f"{arm.wanted}")


def test_streamdeck_refractory_also_starts_at_reset():
    section("Stream Deck: the re-arm refractory window starts when the "
            "deck sees an Abort latch AND when it sees the Reset, both now "
            "from a screen (item 9, round 2 of the safety review: with "
            "Reset delayed past the window, a re-press right after Reset "
            "was NOT refused; the deck's own Abort and Reset keys went "
            "2026-10-26)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    events = []
    t = [0.0]
    cond = _FakeConductor()
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False, conductor=cond,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    c.tick()
    check(all(c._in_rearm_refractory(i, t[0]) == 0 for i in range(3)),
          "nothing latched: no wait")
    cond._latched = True                 # an Abort on the Rack screen
    t[0] += 1.0
    c.tick()
    check(all(c._in_rearm_refractory(i, t[0]) > 0 for i in range(3)),
          "the deck seeing the Abort latch starts every group's wait")
    # Reset is delayed well past REARM_REFRACTORY_S after the Abort.
    t[0] += sd.REARM_REFRACTORY_S + 5.0
    cond._latched = False                # Reset on the Rack screen
    c.tick()
    check(c._latched_now() is False, "Reset cleared the latch")
    # A press right after THIS Reset, long after the Abort's own wait
    # expired, must still be refused.
    down_group = [False] * 6
    down_group[sd.GROUP_KEYS[0]] = True
    c.run_once(down_group)
    check(arm.wanted == [False, False, False]
          and c._arm_holds[0].fraction(t[0]) == 0.0,
          "a re-press right after Reset is refused before the hold can "
          "even start, even though the Abort's own wait is long expired")
    check(any("refractory" in e[0] for e in events[-3:]), events[-3:])


def test_streamdeck_builds_one_http_opener():
    section("Stream Deck: one urllib opener for the whole process, never one "
            "per request (on Python 3.12 each costs about 20 ms and a fresh "
            "TLS context; on Windows the deck's memory climbed with it at "
            "the 4 Hz engine poll, 2026-10-04)")
    import urllib.request as UR
    from ltcplay import streamdeck as sd
    built = []
    real = UR.build_opener
    saved = list(sd._OPENER)
    del sd._OPENER[:]

    def counting(*a, **k):
        built.append(a)
        return real(*a, **k)
    UR.build_opener = counting
    try:
        e = sd.EngineConductor("http://127.0.0.1:9")
        for _ in range(5):
            e._http_get("/api/conductor")
            e._http_post("/api/conductor/hold", {"who": "Andy"})
        check(len(built) == 1, f"built once for ten requests: {len(built)}")
    finally:
        UR.build_opener = real
        del sd._OPENER[:]
        sd._OPENER.extend(saved)
    print("  ok")


def _pillow_missing(what):
    """True when Pillow cannot be imported, after saying so. On a developer's
    box that is a note and the pixel checks are skipped. In CI it is a FAIL:
    the mutate job ran without Pillow for weeks while this file said "CI
    installs Pillow", so the three "Deck latched" mutations in streamdeck.py
    were NOT CAUGHT in every sweep there (PR #43, #46 and #49, shards 14 and
    15) and caught on any box that had it. A runner without Pillow now fails
    the baseline loudly instead of hiding what these tests prove."""
    try:
        import PIL.Image  # noqa: F401
        return False
    except Exception:                     # noqa: BLE001
        if os.environ.get("GITHUB_ACTIONS"):
            check(False, f"Pillow is not installed on this CI runner, so "
                         f"{what} cannot be checked: every job that runs "
                         f"this suite must pip install pillow")
        else:
            print(f"  note: Pillow is not installed here, so {what} is "
                  f"not checked on this machine.")
        return True


def test_streamdeck_draw_latched_shows_real_state_not_flat_off():
    section("Stream Deck: a latched screen (post-Abort, pre-Reset) must "
            "show any group flamesafe is STILL actually reporting armed, "
            "and must keep showing the spoof alarm, never a flat painted-"
            "over OFF (item 1, round 2 of the safety review: a latched "
            "screen that hides a real armed state is worse than no fix)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatus()
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True,
                      clock=lambda: t[0])
    c._latched = True
    status.set({"arm_input": {"state": "live", "seq": 1}, "fault": "",
               "confirmed": True,
               "groups": [{"name": "front row", "armed": "armed",
                           "wanted": True, "reason": "", "amber": "",
                           "dwell_s": 0},
                          {"name": "cat-walk", "armed": "disarmed",
                           "wanted": False, "reason": "", "amber": "",
                           "dwell_s": 0},
                          {"name": "wave flamer", "armed": "disarmed",
                           "wanted": False, "reason": "", "amber": "",
                           "dwell_s": 0}]})
    # Pixels need Pillow. Without it Fonts() raises SystemExit, which used
    # to end the whole suite here (round 5). Both CI jobs install Pillow
    # (the mutate job did not until PR #46's fix round, which is how the
    # "Deck latched" mutations below went uncaught there); a developer's
    # box without it says so and carries on, a CI runner without it FAILS.
    if _pillow_missing("the latched screen's pixels and taps"):
        return
    fonts = sd.Fonts()
    # This CI box has none of the system font paths Fonts._sans_bold() /
    # the serif fallback look for (all macOS/Windows paths) -- drawing is
    # hardware-adjacent and, as this file's own closing comment says,
    # "exercised on the bench, not in selftest.py". text_block is a no-op
    # here so the REST of draw() (the fill colour decision this test is
    # actually about) still runs without needing a real font file.
    fonts.text_block = lambda *a, **kw: None
    canvas = c.draw(fonts, blink_on=True, chase=0)
    box = sd.face_box(sd.GROUP_KEYS[0])
    # The real look for "armed" fills the body with sd.GREEN; a flat OFF
    # look would never put a green pixel anywhere in that key's body.
    body_pixels = [canvas.getpixel((x, y))
                  for x in range(box[0], box[2], 3)
                  for y in range(box[1] + 18, box[3], 3)]
    check(any(p == sd.GREEN for p in body_pixels),
          f"front row, still really armed, shows GREEN on the key even "
          f"while latched, not the old flat dim OFF: "
          f"{set(body_pixels)}")
    box1 = sd.face_box(sd.GROUP_KEYS[1])
    body1 = {canvas.getpixel((x, y)) for x in range(box1[0], box1[2], 3)
             for y in range(box1[1] + 18, box1[3], 3)}
    check(sd.LATCHED_GREY in body1 and (44, 36, 24) not in body1,
          f"cat-walk, really off, greys out while latched: {body1}")
    # A tap on a group flamesafe still reports armed disarms it, even
    # though this deck never wanted it (an arm from somewhere else).
    sends0 = len(arm.sends)
    down = [False] * 6
    down[sd.GROUP_KEYS[0]] = True
    c.run_once(down)
    c.run_once([False] * 6)
    check(len(arm.sends) > sends0 and arm.wanted[0] is False,
          "while latched, a tap on a group still reported armed sends its "
          "disarm")

    def key_px(cv, key):
        b = sd.face_box(key)
        return {cv.getpixel((x, y)) for x in range(b[0], b[2], 3)
                for y in range(b[1], b[3], 3)}
    check(key_px(canvas, sd.SPARE_KEY) <= {sd.BLACK, sd.RED},
          "latched: the spare key stays blank inside the red border")

    # The spoof alarm must also stay visible while latched.
    c._spoof_alarm = "flamesafe reports a mismatch"
    canvas2 = c.draw(fonts, blink_on=True, chase=0)
    body_pixels2 = [canvas2.getpixel((x, y))
                   for x in range(box[0], box[2], 3)
                   for y in range(box[1] + 18, box[3], 3)]
    check(any(p == sd.RED for p in body_pixels2),
          f"the spoof alarm (RED) stays visible on the key even while "
          f"latched: {set(body_pixels2)}")


def test_streamdeck_unconfirmed_config_never_marks_a_key():
    section("Stream Deck: flamesafe's `confirmed: false` draws NOTHING on "
            "the group keys (Jeff, 2026-10-19: the amber corner mark is "
            "gone); the keys show the real state pixel for pixel as a "
            "confirmed config does. The unconfirmed config is still said, "
            "quietly: one journal line from the deck when it first sees "
            "it, and the engine's status (flames.confirmed) for the rack "
            "screen's Info popup")
    from ltcplay import streamdeck as sd
    from ltcplay import remote as RM
    import json as _j

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    def doc(confirmed):
        return {"arm_input": {"state": "live", "seq": arm.seq}, "fault": "",
                "confirmed": confirmed,
                "groups": [{"name": "front row", "armed": "armed",
                            "wanted": True, "reason": "", "amber": "",
                            "dwell_s": 0},
                           {"name": "cat-walk", "armed": "disarmed",
                            "wanted": False, "reason": "", "amber": "",
                            "dwell_s": 0},
                           {"name": "wave flamer", "armed": "held",
                            "wanted": False, "reason": "cycle the arm",
                            "amber": "flashing", "dwell_s": 0}]}
    arm.set_group(0, True)
    arm.send(names)

    # The journal: nothing for a confirmed config, one line the first time
    # a fresh frame says false, no repeat while it stands, one line when it
    # is confirmed later, and nothing while the status is stale.
    def noted(outcome):
        return [e for e in events if e[1].get("outcome") == outcome
                and e[1].get("action") == "config"]
    status.set(doc(True))
    c.check_links()
    c.check_links()
    check(not noted("unconfirmed") and not noted("confirmed"),
          f"a confirmed config is nothing to journal: {events}")
    status.set(doc(False))
    for _ in range(5):
        c.check_links()
    check(len(noted("unconfirmed")) == 1
          and "not confirmed by Andy" in noted("unconfirmed")[0][0]
          and noted("unconfirmed")[0][0].startswith("Stream Deck: "),
          f"the first fresh frame saying confirmed false earns exactly one "
          f"journal line, however many passes follow: {events}")
    check(not any(ch in e[0] for e in events
                  for ch in (chr(0x2014), chr(0x2013))),
          "the deck's line carries no em or en dash")
    status.last = doc(True)
    status._stale = True
    c.check_links()
    check(not noted("confirmed"),
          f"a STALE frame says nothing, whatever it holds: {events}")
    status._stale = False
    c.check_links()
    c.check_links()
    check(len(noted("confirmed")) == 1 and len(noted("unconfirmed")) == 1,
          f"confirmed later, and fresh: one line says so, once: {events}")
    status.set(doc(False))
    c.check_links()
    check(len(noted("unconfirmed")) == 2,
          "back to unconfirmed is a new episode, journaled again")
    check(arm.wanted == [True, False, False] and all(
        s == [True, False, False] for s in arm.sends[-1:]),
          "none of it touched the arm link: display and journal only")

    # The keys: pixels need Pillow (a CI runner without it FAILS here, a
    # developer's box is told).
    if _pillow_missing("the group keys with an unconfirmed config"):
        print("  ok")
        return
    fonts = sd.Fonts()
    fonts.text_block = lambda *a, **kw: None    # no system fonts on CI

    def corner(cv, key):
        """The 8 by 8 px block in the key face's bottom-right corner where
        the mark used to be drawn."""
        x0, y0, x1, y1 = sd.face_box(key)
        return {cv.getpixel((x, y)) for x in range(x1 - 9, x1 - 1)
                for y in range(y1 - 9, y1 - 1)}
    status.set(doc(False))
    off = c.draw(fonts, blink_on=True, chase=0)
    for k, word in zip(sd.GROUP_KEYS[:2], ("ARMED", "OFF")):
        px = corner(off, k)
        check(sd.AMBER not in px,
              f"confirmed false: no amber corner mark on the {word} key "
              f"({px})")
    status.set(doc(True))
    on = c.draw(fonts, blink_on=True, chase=0)
    check(list(off.getdata()) == list(on.getdata()),
          "confirmed false and confirmed true draw the SAME deck, pixel "
          "for pixel: the keys carry nothing for it")
    body = sd.face_box(sd.GROUP_KEYS[0])
    greens = [off.getpixel((x, y)) for x in range(body[0], body[2], 3)
              for y in range(body[1] + 18, body[3], 3)]
    check(any(p == sd.GREEN for p in greens),
          "and the real state (front row ARMED, green) is still what the "
          "key shows: the mark went, the state did not")

    # The engine's status for the rack screen: FlameStatus.view carries
    # flamesafe's own `confirmed`, None while nothing fresh says either way.
    mono = [0.0]
    fs = RM.FlameStatus("127.0.0.1", 0, "k" * 20, names,
                        clock=lambda: mono[0])
    check(fs.view()["confirmed"] is None,
          "no frame yet: the status does not claim either way")
    frame = {"t": "status", "k": "k" * 20, "fault": "", "confirmed": False,
             "groups": [{"name": "front row", "armed": "armed",
                         "wanted": True, "reason": ""}]}
    fs.note(_j.dumps(frame).encode())
    v = fs.view()
    check(v["confirmed"] is False and v["groups"][0]["armed"] == "armed",
          f"a fresh frame with confirmed false says so, beside the real "
          f"armed state: {v}")
    fs.note(_j.dumps(dict(frame, confirmed=True)).encode())
    check(fs.view()["confirmed"] is True, "confirmed true reads true")
    fs.note(_j.dumps({k: x for k, x in frame.items()
                      if k != "confirmed"}).encode())
    check(fs.view()["confirmed"] is True,
          "a frame that leaves the field out counts as confirmed, as the "
          "deck has always read it")
    fs.note(_j.dumps(frame).encode())
    mono[0] += RM.FLAME_STALE_S + 0.5
    check(fs.view()["confirmed"] is None and fs.view()["stale"],
          "stale: None again, never an old answer shown as now")
    # The rack screen says it in the Info popup only (not a banner, not
    # the keys): the page wires flames.confirmed to #info-flames.
    here = os.path.dirname(os.path.abspath(__file__))
    page = open(os.path.join(here, "ltcplay", "web", "remote.html"),
                encoding="utf-8").read()
    check('id="info-flames" hidden' in page
          and "s.flames.confirmed === false" in page
          and '$("info-flames").hidden = !unconf;' in page
          and "not yet confirmed by Andy" in page,
          "the rack screen's Info popup carries the unconfirmed config, "
          "hidden otherwise")
    print("  ok")


def test_streamdeck_spoof_alarm():
    section("Stream Deck: a visible, journaled alarm when flamesafe's "
            "reported arm state diverges from what this deck itself sent "
            "(item 1's second line of defence, safety review of PR #31)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    def status_doc(seq, wanted):
        return {"arm_input": {"state": "live", "seq": seq},
               "groups": [{"name": n, "wanted": w}
                          for n, w in zip(names, wanted)]}

    arm.send(names)      # arm.seq == 1
    status.set(status_doc(1, [False, False, False]))
    c.check_links()
    check(not c._spoof_alarm, "matching state, nothing to alarm about")
    t[0] += sd.RECONNECT_GRACE_S + 0.1   # round 4: past the start-up grace

    # Reported seq AHEAD of what this deck has sent: something else is
    # feeding flamesafe arm frames. The debounce window has to PERSIST
    # across two checks before it is trusted, so the first call only
    # starts the clock.
    status.set(status_doc(99, [False, False, False]))
    c.check_links()
    check(not c._spoof_alarm,
          "a fresh mismatch does not alarm on the very first sighting: "
          "the debounce clock has only just started")
    t[0] += sd.SPOOF_GRACE_S + 0.1   # outlast the debounce grace window
    c.check_links()
    check(c._spoof_alarm and "ahead of" in c._spoof_alarm,
          f"...but the SAME mismatch, still there after SPOOF_GRACE_S, "
          f"raises the alarm: {c._spoof_alarm!r}")
    check(any("ALARM" in t_ for t_, kw in events),
          f"and it is journaled, loudly: {events}")

    # Clears once the state matches again.
    status.set(status_doc(1, [False, False, False]))
    c.check_links()
    check(not c._spoof_alarm, "the alarm clears once state matches again")
    check(any("cleared" in t_ for t_, kw in events[-2:]),
          f"and the clearing is itself journaled: {events[-2:]}")

    # A brief one-tick lag (reported wanted momentarily behind what we
    # just sent) must NOT alarm: only a mismatch that PERSISTS does.
    arm.set_group(0, True)
    arm.send(names)
    status.set(status_doc(2, [False, False, False]))   # status lags behind
    c.check_links()
    check(not c._spoof_alarm,
          "a one-tick send/receive lag is not treated as a spoof")

    # But a wanted mismatch that persists past SPOOF_GRACE_S IS an alarm.
    t[0] += sd.SPOOF_GRACE_S + 0.1
    c.check_links()
    check(c._spoof_alarm and "front row" in c._spoof_alarm,
          f"a persistent wanted mismatch raises the alarm, naming the "
          f"group: {c._spoof_alarm!r}")

    # A reconnect (ArmSocket.open() resets our own seq) must not itself
    # read as a spoof: the grace window covers it.
    arm.open()                       # arm.seq -> 0
    status.set(status_doc(2, [False, False, False]))
    c.check_links()
    t[0] += sd.SPOOF_GRACE_S + 0.1
    c.check_links()
    check(not c._spoof_alarm,
          "right after a reconnect, a stale-looking status is not an "
          "alarm even after the debounce window: RECONNECT_GRACE_S "
          "covers it")


def test_streamdeck_spoof_alarm_on_foreign_sender_flag_alone():
    section("Stream Deck: flamesafe reporting a foreign sender interacting "
            "with the arm link raises this deck's own alarm even when the "
            "deck's OWN view of `wanted` happens to match (round 3 of the "
            "safety review, item 6: the review found the deck usually "
            "raised NO alarm at all while a rogue held the lock, because "
            "the foreign-disarm AND (arminput.py) can leave `wanted` "
            "looking exactly like what the deck itself expects, and the "
            "seq check only fires if the rogue's own counter races ahead "
            "of this deck's)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    def status_doc(seq, wanted, foreign):
        return {"arm_input": {"state": "live", "seq": seq,
                              "foreign_senders": foreign},
               "groups": [{"name": n, "wanted": w}
                          for n, w in zip(names, wanted)]}

    arm.send(names)      # arm.seq == 1
    # The deck's own wanted ([False]*3) matches exactly what flamesafe
    # reports, and the seq is not ahead either: by the two OLD checks
    # alone, nothing here would ever alarm.
    status.set(status_doc(1, [False, False, False], foreign=0))
    c.check_links()
    check(not c._spoof_alarm, "nothing foreign reported: no alarm")
    t[0] += sd.RECONNECT_GRACE_S + 0.1   # round 4: past the start-up grace

    status.set(status_doc(1, [False, False, False], foreign=1))
    c.check_links()
    check(not c._spoof_alarm,
          "a fresh foreign-sender report does not alarm on the very first "
          "sighting: the debounce clock has only just started")
    t[0] += sd.SPOOF_GRACE_S + 0.1
    c.check_links()
    check(c._spoof_alarm and "other sender" in c._spoof_alarm,
          f"but the SAME foreign-sender report, still there after "
          f"SPOOF_GRACE_S, raises the alarm even though wanted and seq "
          f"both still look fine: {c._spoof_alarm!r}")
    check(any("ALARM" in t_ for t_, kw in events),
          f"and it is journaled: {events}")

    status.set(status_doc(1, [False, False, False], foreign=0))
    c.check_links()
    check(not c._spoof_alarm,
          "clears once flamesafe reports nobody else is on the link")


def test_streamdeck_spoof_alarm_dedup_survives_a_changing_sequence_number():
    section("Stream Deck: the spoof/divergence alarm logs ONCE for a "
            "PERSISTENT condition, even though the arm-seq-ahead reason's "
            "own text embeds this deck's own seq, which ArmSocket advances "
            "on every single send (round 3 of the safety review, item 5 -- "
            "a PROVEN bug, flagged once already and never actually fixed: "
            "the dedup compared the FULL sentence, which was a brand new "
            "string every main-loop pass, so the alarm line repeated once "
            "per pass for as long as the condition lasted)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    for _ in range(5):
        arm.send(names)                      # arm.seq is now 5
    c.check_links()                          # round 4: start-up grace...
    t[0] += sd.RECONNECT_GRACE_S + 0.1       # ...stepped past
    status.set({"arm_input": {"state": "live", "seq": 99999}, "groups": []})
    c.check_links()
    t[0] += sd.SPOOF_GRACE_S + 0.1

    before = len(events)
    for i in range(30):
        arm.send(names)                      # arm.seq keeps climbing
        status.set({"arm_input": {"state": "live", "seq": 99999 + i},
                   "groups": []})
        c.check_links()
    alarms = [e for e in events[before:] if "ALARM" in e[0]]
    check(len(alarms) == 1,
          f"30 passes of a PERSISTENT arm-seq-ahead condition, with this "
          f"deck's own seq and flamesafe's reported seq both changing "
          f"every pass, still produce exactly ONE alarm line, not 30: "
          f"{len(alarms)}")


def test_streamdeck_arm_socket_logs_failed_sends_once():
    section("Stream Deck: ArmSocket logs a persistent send failure once, "
            "not once per dropped frame (item 10)")
    from ltcplay import streamdeck as sd

    events = []

    class _BoomSocket:
        def sendto(self, *a):
            raise OSError("Network is unreachable")

        def close(self):
            pass

    arm = sd.ArmSocket("127.0.0.1", 1, "k" * 20, 1,
                       journal=lambda t, **kw: events.append((t, kw)))
    arm._sock = _BoomSocket()
    for _ in range(5):
        arm.send(["front row"])
    faults = [e for e in events if e[1].get("fault")]
    check(len(faults) == 1,
          f"five dropped frames in a row log exactly one fault line, not "
          f"five: {events}")

    class _OkSocket:
        def sendto(self, *a):
            pass

    arm._sock = _OkSocket()
    arm._send_failing = True
    arm.send(["front row"])
    check(any("working again" in t for t, kw in events),
          f"recovery is logged too: {events}")


def test_streamdeck_local_schedule_never_blocks_the_main_loop():
    section("Stream Deck: LocalSchedule polls the operator and show-"
            "running state on a BACKGROUND thread; the main-loop-facing "
            "reads never touch the network (item 5)")
    from ltcplay import streamdeck as sd
    import threading as _threading

    calls = []
    ready = _threading.Event()

    def fetcher(path):
        calls.append(path)
        ready.set()
        if path == "/api/schedule/operator":
            return {"current_operator": "Andy"}
        if path == "/api/schedule/state":
            return {"ok": True, "state": "SHOW"}
        return None

    sched = sd.LocalSchedule("http://127.0.0.1:1", poll_hz=50.0,
                             fetcher=fetcher)
    check(sched.current_operator() == "" and sched.show_running() is None,
          "before start(), both read their safe defaults forever, never "
          "the network")
    sched.start()
    try:
        check(wait_for(lambda: ready.is_set(), timeout=2.0),
              "the background thread is actually polling")
        check(wait_for(lambda: sched.current_operator() == "Andy",
                       timeout=2.0),
              "current_operator() reads the cache the background thread "
              "filled")
        check(sched.show_running() is True,
              "show_running() reads the same cache")
    finally:
        sched.stop()
    calls.clear()
    t0 = time.monotonic()
    check(sched.current_operator() == "Andy", "still cached after stop()")
    # `not calls` below is the proof that nothing was fetched; the time is
    # only a backstop against a wait on something else, so it is generous.
    check(time.monotonic() - t0 < 1.0,
          "reading the cache after stop() is instant: no network call")
    check(not calls, "and no fetch happened: the thread is really stopped")


def test_streamdeck_local_schedule_operator_reverts_when_server_drops():
    section("Stream Deck: LocalSchedule reverts the cached operator to \"\" "
            "the moment a poll fails, never keeping a stale name once the "
            "server goes down (item 8, round 2 of the safety review: a "
            "regression kept the LAST successfully fetched name forever, "
            "which could let a group arm under a name no longer actually "
            "confirmed present)")
    from ltcplay import streamdeck as sd

    up = [True]

    def fetcher(path):
        if not up[0]:
            return None
        if path == "/api/schedule/operator":
            return {"current_operator": "Andy"}
        if path == "/api/schedule/state":
            return {"ok": True, "state": "SHOW"}
        return None

    sched = sd.LocalSchedule("http://127.0.0.1:1", poll_hz=50.0,
                             fetcher=fetcher)
    sched.start()
    try:
        check(wait_for(lambda: sched.current_operator() == "Andy",
                       timeout=2.0),
              "the operator is cached while the server answers")
        up[0] = False
        check(wait_for(lambda: sched.current_operator() == "",
                       timeout=2.0),
              "and reverts to \"\" on the very next failed poll, matching "
              "the docstring's documented default -- not kept forever")
        check(wait_for(lambda: sched.show_running() is None, timeout=2.0),
              "show_running() already did this; unchanged")
        up[0] = True
        check(wait_for(lambda: sched.current_operator() == "Andy",
                       timeout=2.0),
              "and comes back once the server does")
    finally:
        sched.stop()


def test_streamdeck_deck_journal_prints_and_posts():
    section("Stream Deck: DeckJournal prints locally at once and posts to "
            "ltc serve's real journal on its OWN background thread (item "
            "9); a server that cannot be reached never blocks the caller")
    from ltcplay import streamdeck as sd

    printed = []
    posted = []
    dj = sd.DeckJournal("http://127.0.0.1:1",
                        poster=lambda text, kw: posted.append((text, kw))
                                              or True,
                        echo=lambda line: printed.append(line))
    dj("front row arm pressed by Andy.", action="arm", who="Andy",
      screen="Stream Deck")
    check(printed == ["front row arm pressed by Andy."],
          f"printed at once, on the calling thread: {printed}")
    check(wait_for(lambda: posted == [
        ("front row arm pressed by Andy.",
         {"action": "arm", "who": "Andy", "screen": "Stream Deck"})],
        timeout=2.0),
        f"and posted (here: handed to the injected poster) on the "
        f"background thread: {posted}")
    check(dj.dropped == 0, "a poster returning True never counts as dropped")

    # The real _post must never raise into the background thread even when
    # the server cannot be reached at all -- it is caught by the loop, but
    # _post itself should also degrade quietly.
    dj2 = sd.DeckJournal("http://127.0.0.1:1")   # the real HTTP poster
    dj2("a line nobody is listening for.", action="deck")
    time.sleep(0.2)   # give the background thread a moment; nothing to
                      # assert except that the process is still alive

    # Item 7 (round 2 of the safety review): `dropped` and the FAULT line
    # used to exist in name only -- a poster that actually FAILS (as
    # opposed to a queue-full drop) silently vanished, counted nowhere,
    # logged nowhere beyond this process's own console. Now it counts, and
    # logs once per OUTAGE (not once per event), with a matching recovery
    # line once posting works again.
    printed3 = []
    failing = [True]
    dj3 = sd.DeckJournal(
        "http://127.0.0.1:1",
        poster=lambda text, kw: False if failing[0] else True,
        echo=lambda line: printed3.append(line))
    dj3("event one.", action="arm")
    dj3("event two.", action="arm")
    dj3("event three.", action="arm")
    check(wait_for(lambda: dj3.dropped == 3, timeout=2.0),
          f"every failed post is counted, not just a queue-full drop: "
          f"dropped={dj3.dropped}")
    fault_lines = [p for p in printed3 if p.startswith("FAULT")
                  and "journal" in p.lower()]
    check(len(fault_lines) == 1,
          f"one FAULT line for the whole outage, not one per failed event: "
          f"{fault_lines}")
    failing[0] = False
    dj3("event four.", action="arm")
    check(wait_for(lambda: dj3.dropped == 3, timeout=2.0),
          "a successful post after an outage is not itself counted dropped")
    check(wait_for(lambda: any("reachable again" in p for p in printed3),
                   timeout=2.0),
          f"and a recovery line is printed once posting works again: "
          f"{printed3}")


def test_streamdeck_reconnect_never_remembers_old_state():
    section("Stream Deck: a reconnect (or first connect) always starts "
            "every group OFF, never replaying what was armed before")
    from ltcplay import streamdeck as sd
    arm = _FakeArmSocket(3)
    arm.set_group(0, True)          # pretend it was armed before a gap
    check(arm.wanted == [True, False, False], "set up: group 0 was wanted")
    arm.open()
    check(arm.wanted == [False, False, False],
          "open() (every connect and reconnect) resets wanted to all-false, "
          "exactly as a real ArmSocket's open() does -- see module "
          "docstring, failure mode 2")


def _round4_run_forever(c, decks, t, on_sleep=None, journal=None):
    """Drive the REAL sd.run_forever() through `decks`: each element is a
    fake deck object, or None for "deck_factory raises DeckDisconnected"
    (no deck plugged in), or an Exception instance deck_factory raises
    as-is (round 5). Ends when the list runs out. Fake clock/sleep;
    drawing stubbed by _deck_draw_stubs, as the tests above."""
    from ltcplay import streamdeck as sd

    class _StopTest(BaseException):
        pass        # a deliberate stop: run_forever lets only these through

    def deck_factory():
        if not decks:
            raise _StopTest()
        d = decks.pop(0)
        if d is None:
            raise sd.DeckDisconnected("probe: nothing plugged in")
        if isinstance(d, Exception):
            raise d             # round 5: any other error opening the deck
        return d

    restore_drawing = _deck_draw_stubs(sd)
    try:
        sd.run_forever(c, deck_factory=deck_factory,
                       journal=journal or (lambda t_, **kw: None),
                       sleep=lambda s: (t.__setitem__(0, t[0] + s),
                                        on_sleep and on_sleep()),
                       clock=lambda: t[0])
    except _StopTest:
        pass
    finally:
        restore_drawing()


class _Round4Deck:
    """A fake deck: on_pass(i) runs on each keys_down() call; after
    `passes` calls it unplugs (DeckDisconnected)."""

    def __init__(self, passes, on_pass=None):
        self.passes = passes
        self.on_pass = on_pass
        self.i = 0

    def keys_down(self):
        from ltcplay import streamdeck as sd
        self.i += 1
        if self.on_pass is not None:
            self.on_pass(self.i)
        if self.i > self.passes:
            raise sd.DeckDisconnected("probe: unplugged")
        return []

    def set_key(self, image, key, img):
        pass

    def close(self):
        pass


# ---------------------------------------------------------------------------
# The conductor wired to the real device layer: a real Conductor, driven
# through conductor.ConductorDevices into a real beyond.Beyond and a real
# madmapper.Link, whose sockets are fakes that stamp every packet into the
# same call log as the show side (_CondRig). So one ordered list holds the
# flame cut, every BEYOND packet, the music, the pixels and every MadMapper
# packet, and the ordering guarantees devices.py's on_hold()/on_resume()/
# on_abort() were written to give can be checked against what the
# conductor actually sends.
# ---------------------------------------------------------------------------


class _StampSock(_FakeMMSock):
    """A fake socket that also writes (kind, (address, value), now) into a
    shared log as each packet goes out. value is None for an OSC message
    with no float (MadMapper's conductor/stop)."""

    def __init__(self, kind, log, now):
        super().__init__()
        self.kind, self.log, self.now = kind, log, now

    def sendto(self, pkt, addr):
        from ltcplay import madmapper as MM
        super().sendto(pkt, addr)
        address, _at = MM._read_osc_string(pkt, 0)
        f = MM.decode_float(pkt)
        self.log.append((self.kind, (address, None if f is None else f[1]),
                         self.now()))


def _cond_devices(gate=None, mm=True, beyond=True, beyond_factory=None):
    from ltcplay import madmapper as MM, beyond as B
    C = _cond_mod()
    T = _CondTime()
    rig = _CondRig(T.now)
    rig.slow_by = lambda s: setattr(T, "t", T.t + s)
    lines = []

    def journal(text, **f):
        lines.append((text, f.get("fault", False)))
    steps = _Steps()
    link = bey = None
    if mm:
        link = MM.Link(_mm_cfg(ramp_steps=5),
                       socket_factory=lambda: _StampSock("mm", rig.calls,
                                                         T.now),
                       clock=steps.clock, sleep=steps.sleep, journal=journal)
        # Packets leave from the Link's own worker thread, so their place
        # in the log depends on thread timing. The CALL into the Link is
        # made on the conductor's thread: log that too ("mm_call"), so an
        # order check never passes by luck of scheduling.
        for name in ("fade_surfaces", "set_surfaces", "cancel", "stop_bank",
                     "fade_audio", "set_audio", "fade_all",
                     "restore_levels", "select_bank", "play",
                     "play_from_beginning"):
            def rec(*a, _name=name, _fn=getattr(link, name), **k):
                rig.calls.append(("mm_call", (_name,) + a, T.now()))
                return _fn(*a, **k)
            setattr(link, name, rec)
    if beyond:
        bey = B.Beyond(B.BeyondConfig.parse({}),
                       socket_factory=beyond_factory or (
                           lambda: _StampSock("beyond", rig.calls, T.now)),
                       clock=steps.clock, sleep=steps.sleep, journal=journal)
    dev = C.ConductorDevices(link, bey, show=1, journal=journal)
    c = C.Conductor(dev, rig, gate if gate is not None else (lambda: None),
                    journal=journal, clock=T.now, waiter=T.wait,
                    threaded=False)
    return c, rig, T, lines, link, bey


def _mm_flush(link):
    """Wait for the Link's worker to finish every job already queued (the
    conductor starts video fades with wait=False)."""
    if link is not None:
        link._submit(lambda: None, wait=True)


def _cd_live(c, rig, link):
    check(c.show_starting("Andy", "rack screen").ok, "show start accepted")
    c.run_pending()
    _mm_flush(link)
    rig.frozen_at = rig.moving_at = None
    del rig.calls[:]


def _cd_idx(calls, kind):
    return [i for i, e in enumerate(calls) if e[0] == kind]


def _cd_sends(calls):
    """The log without the Link's cancel() calls. A cancel sends nothing:
    it only stops a fade still running where it is, at a Hold's or an
    Abort's press (independent review of PR #29, finding C)."""
    return [e for e in calls if e[:2] != ("mm_call", ("cancel",))]


def test_conductor_devices_hold_blanks_beyond_before_anything_fades():
    section("conductor + devices: a Hold sends BEYOND a real blank, and it "
            "is out before the music or the video starts to fade; "
            "MadMapper's audio is never touched")
    from ltcplay import madmapper as MM, beyond as B
    C = _cond_mod()
    c, rig, T, lines, link, bey = _cond_devices()
    check(c.wired and c.snapshot()["devices_wired"],
          "with BEYOND and MadMapper both given, the conductor is wired")
    check(not any("not connected" in t for t, _f in lines),
          f"no 'not connected' fault line when wired: {lines}")
    _cd_live(c, rig, link)
    T.t = 300.0
    check(c.hold("Andy", "rack screen").ok, "Hold accepted")
    check(rig.calls and rig.calls[0][:2] == ("mm_call", ("cancel",)),
          f"the press stops any video fade where it is, sending nothing: "
          f"{rig.calls[:1]}")
    c.run_pending()
    _mm_flush(link)
    ev = _cd_sends(rig.calls)
    names = [e[0] for e in ev]
    b = _cd_idx(ev, "beyond")
    m = _cd_idx(ev, "mm")
    check(names[0] == "flames_zero", f"the flame cues go first: {names}")
    check(len(b) == B.RETRY_COUNT and
          all(ev[i][1] == (B.BRIGHTNESS_ADDR, B.BLANK_VALUE) for i in b),
          f"BEYOND gets a real blank, brightness 0, {B.RETRY_COUNT} "
          f"packets: {[ev[i] for i in b]}")
    check(b and max(b) < names.index("music_hold"),
          f"the blank is out before the music starts to fade: {names}")
    check(m and b and min(m) > max(b),
          f"every MadMapper packet comes after the blank: {names}")
    mc = _cd_idx(ev, "mm_call")
    check(mc and b and min(mc) > max(b),
          f"the conductor calls MadMapper only after the blank is out: "
          f"{names}")
    check([ev[i][1][:3] for i in mc] == [("fade_surfaces", 1.0, 0.0)],
          f"one call: the surfaces fade from 1 to 0, nothing else: "
          f"{[ev[i][1] for i in mc]}")
    check(all(ev[i][2] == 300.0 for i in b),
          "the blank goes at the press, with no fade of its own")
    hold = rig.first("music_hold")
    check(hold is not None and hold[1] == (C.HOLD_FADE_S,),
          f"the music fades over 0.25 s, then the clock freezes: {hold}")
    check(all(ev[i][1][0] != MM.AUDIO_ADDR for i in m),
          "MadMapper's audio level is never sent: ltcplay plays the music "
          "(clock source audio_master), MadMapper only the video")
    surf = [ev[i][1] for i in m]
    check(all(a.startswith("/surfaces/") for a, _v in surf),
          f"a production Hold fades the video surfaces (Jeff 2026-09-30): "
          f"{surf}")
    for s in ("Quad-1", "Quad-2"):
        vals = [v for a, v in surf if a == f"/surfaces/{s}/opacity"]
        check(vals and vals[0] == 1.0 and vals[-1] == 0.0,
              f"{s} fades from 1 to black: {vals}")
    check(not any(f for t, f in lines),
          f"no fault, and no slow call: {[t for t, f in lines if f]}")
    check(c.snapshot()["applied"]["lasers"] == "black", "lasers black")
    # Finding A: the video is recorded black only once the Link says the
    # packets went out (it has: flushed above).
    check(c.snapshot()["applied"]["video"] == "black",
          f"video black, as reported by the Link: {c.snapshot()['applied']}")
    link.close()

    # Rehearsal: still a real blank first, but the video freezes in place.
    c, rig, T, lines, link, bey = _cond_devices()
    _cd_live(c, rig, link)
    c.set_mode(C.REHEARSAL)
    c.hold("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    ev = _cd_sends(rig.calls)
    check([e[1][1] for e in ev if e[0] == "beyond"]
          == [B.BLANK_VALUE] * B.RETRY_COUNT,
          f"a rehearsal Hold blanks BEYOND too: {ev}")
    check(_cd_idx(ev, "mm") == [] and _cd_idx(ev, "mm_call") == [],
          f"a rehearsal Hold sends MadMapper nothing: the video freezes "
          f"with the timecode: {ev}")
    check(rig.first("music_hold")[1] == (0.0,), "and the music stops at once")
    link.close()
    print("  ok")


def test_conductor_devices_abort_blanks_at_once_never_ramps():
    section("conductor + devices: Abort blanks BEYOND at once (never a "
            "brightness ramp; beyond.py's 0/100 allow-list is unchanged), "
            "before the video and music fade, then stops the video bank")
    from ltcplay import madmapper as MM, beyond as B
    C = _cond_mod()
    check(B.ALLOWED_VALUES == (0.0, 100.0),
          f"beyond.py's allow-list is still exactly 0.0 and 100.0: "
          f"{B.ALLOWED_VALUES}")
    c, rig, T, lines, link, bey = _cond_devices()
    check(c.show_starting("Andy", "rack screen").ok, "show start")
    c.run_pending()
    _mm_flush(link)
    check([e[1][1] for e in rig.calls if e[0] == "beyond"]
          == [B.UNBLANK_VALUE] * B.RETRY_COUNT,
          f"the show starts with the lasers up: {rig.calls}")
    rig.frozen_at = rig.moving_at = None
    del rig.calls[:]
    T.t = 400.0
    check(c.abort("Andy", "rack screen").ok, "Abort accepted")
    pressed = _cd_sends(rig.calls)
    check([e[0] for e in pressed][:2] == ["flames_zero", "flames_disarm_all"]
          and [e[1][1] for e in pressed[2:]]
          == [B.BLANK_VALUE] * B.RETRY_COUNT,
          f"the flames are cut on the press, before anything else, and "
          f"BEYOND is blanked before the press returns (finding D): "
          f"{rig.calls}")
    check(("mm_call", ("cancel",), 400.0) in rig.calls,
          "and any video fade is stopped where it is, at the press")
    c.run_pending()
    _mm_flush(link)
    ev = _cd_sends(rig.calls)
    names = [e[0] for e in ev]
    b = _cd_idx(ev, "beyond")
    m = _cd_idx(ev, "mm")
    check([ev[i][1] for i in b]
          == [(B.BRIGHTNESS_ADDR, B.BLANK_VALUE)] * (2 * B.RETRY_COUNT),
          f"Abort sends BEYOND brightness 0 only, never anything between "
          f"0 and 100: at the press, and again once the press's blank is "
          f"out (review of PR #43, P0-3): {[ev[i] for i in b]}")
    bp = b[:B.RETRY_COUNT]          # the press's own blank
    check(all(ev[i][2] == 400.0 for i in b),
          f"all at the press, not spread over the 1 s fade: "
          f"{[ev[i][2] for i in b]}")
    for later in ("pixels_fade_out", "music_halt"):
        check(later in names and max(bp) < names.index(later),
              f"BEYOND is dark before {later} starts: {names}")
    check(m and min(m) > max(bp),
          f"BEYOND is dark before MadMapper is sent anything: {names}")
    mc = _cd_idx(ev, "mm_call")
    check([ev[i][1][0] for i in mc] == ["fade_surfaces", "stop_bank"]
          and min(mc) > max(bp),
          f"the conductor calls MadMapper (fade, then stop) only after "
          f"BEYOND is dark: {names}")
    check(not any("faded" in t and "BEYOND" in t for t, _f in lines),
          f"the journal never says the lasers faded: {lines}")
    mm_ev = [ev[i][1] for i in m]
    check(all(a != MM.AUDIO_ADDR for a, _v in mm_ev),
          f"MadMapper's audio level is not sent: {mm_ev}")
    stop = f"/timelines/{link.cfg.show_bank}/conductor/stop"
    check(mm_ev and mm_ev[-1] == (stop, None),
          f"the show bank is stopped last, after the fade: {mm_ev[-3:]}")
    for s in ("Quad-1", "Quad-2"):
        vals = [v for a, v in mm_ev if a == f"/surfaces/{s}/opacity"]
        check(vals and vals[0] == 1.0 and vals[-1] == 0.0,
              f"{s} fades to black before the stop: {vals}")
    check(rig.first("music_halt")[1] == (C.ABORT_FADE_S,),
          "the music fades over 1 s")
    link.close()

    # Abort after a Hold: the lasers are already dark, and the blank is
    # sent again anyway (never trusted to have landed), still first.
    c, rig, T, lines, link, bey = _cond_devices()
    _cd_live(c, rig, link)
    c.hold("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    del rig.calls[:]
    T.t = 450.0
    c.abort("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    ev = _cd_sends(rig.calls)
    names = [e[0] for e in ev]
    b = _cd_idx(ev, "beyond")
    check([ev[i][1][1] for i in b] ==
          [B.BLANK_VALUE] * (2 * B.RETRY_COUNT),
          f"Abort after a Hold sends BEYOND the blank again, at the press "
          f"and once more after it: {ev}")
    check(b and max(b[:B.RETRY_COUNT]) < names.index("music_halt"),
          f"and still before the music: {names}")
    mm_ev = [e[1] for e in ev if e[0] == "mm"]
    check([e[1][0] for e in ev if e[0] == "mm_call"]
          == ["fade_surfaces", "stop_bank"]
          and names.index("mm_call") > max(b[:B.RETRY_COUNT]),
          f"after the blank, MadMapper is told black again, then stop: "
          f"{names}")
    stop = (f"/timelines/{link.cfg.show_bank}/conductor/stop", None)
    check(mm_ev == [("/surfaces/Quad-1/opacity", 0.0),
                    ("/surfaces/Quad-2/opacity", 0.0), stop],
          f"the video the Hold already faded is not faded up and down "
          f"again (finding C: it starts where it is, black, so one 0 per "
          f"surface), then stopped: {mm_ev}")
    link.close()
    print("  ok")


def test_conductor_devices_resume_unblanks_only_after_timecode_and_gate():
    section("conductor + devices: Resume unblanks BEYOND only once the "
            "timecode moves and the laser gate says yes; in intermission it "
            "re-sends the blank instead, every time")
    from ltcplay import beyond as B
    C = _cond_mod()
    state = ["SHOW"]
    gate = C.laser_gate_for(lambda: state[0])
    c, rig, T, lines, link, bey = _cond_devices(gate=gate)
    _cd_live(c, rig, link)
    c.hold("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    del rig.calls[:]
    rig.move_s = 0.3
    T.t = 500.0
    check(c.resume("Andy", "rack screen").ok, "Resume accepted")
    c.run_pending()
    _mm_flush(link)
    ev = rig.calls
    names = [e[0] for e in ev]
    b = _cd_idx(ev, "beyond")
    check([ev[i][1][1] for i in b] == [B.UNBLANK_VALUE] * B.RETRY_COUNT,
          f"BEYOND comes back up (100): {[ev[i] for i in b]}")
    check(b and min(b) > names.index("music_resume"),
          f"after the music starts back: {names}")
    check(min(b) > names.index("mm_call"),
          f"and after the video has been asked back up: {names}")
    check(all(ev[i][2] >= 500.3 - 1e-9 for i in b),
          f"and not before the timecode moves (0.3 s): "
          f"{[ev[i][2] for i in b]}")
    check(names.index("flames_release") > max(b),
          f"the flame cues are released last, after the lasers: {names}")
    up = [e[1] for e in ev if e[0] == "mm"]
    for s in ("Quad-1", "Quad-2"):
        vals = [v for a, v in up if a == f"/surfaces/{s}/opacity"]
        check(vals and vals[0] == 0.0 and vals[-1] == 1.0,
              f"{s} fades back up: {vals}")
    link.close()

    # A Resume in intermission: no unblank, ever, and a real blank re-sent
    # even though the record already says black (devices.py's defensive
    # re-blank, kept).
    state[0] = "SHOW"
    c, rig, T, lines, link, bey = _cond_devices(gate=gate)
    _cd_live(c, rig, link)
    c.hold("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    check(c.snapshot()["applied"]["lasers"] == "black", "held: black")
    del rig.calls[:]
    state[0] = "STANDBY"
    c.resume("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    vals = [e[1][1] for e in rig.calls if e[0] == "beyond"]
    check(B.UNBLANK_VALUE not in vals,
          f"no unblank during intermission: {vals}")
    check(vals == [B.BLANK_VALUE] * B.RETRY_COUNT,
          f"the blank is re-sent, not assumed: {vals}")
    check(any("no lasers during intermission" in t for t, _f in lines),
          "the journal says why")
    check(bey.last_command == "blank" and bey.last_result == "ok",
          f"BEYOND's own record agrees: {bey.health()}")
    # Leaving the show blanks them again too.
    del rig.calls[:]
    c.intermission("scheduler")
    c.run_pending()
    vals = [e[1][1] for e in rig.calls if e[0] == "beyond"]
    check(vals == [B.BLANK_VALUE] * B.RETRY_COUNT,
          f"intermission() sends BEYOND the blank: {vals}")
    link.close()
    print("  ok")


def test_conductor_devices_failures_missing_links_and_speed():
    section("conductor + devices: a failed or broken device is a failed "
            "Result, never a raise; a show without BEYOND or MadMapper says "
            "it is not wired; every call returns at once")
    import time as _time
    from ltcplay import madmapper as MM, beyond as B
    C = _cond_mod()

    def no_socket():
        raise OSError("no network")
    c, rig, T, lines, link, bey = _cond_devices(beyond_factory=no_socket)
    c.show_starting("Andy", "rack screen")
    c.run_pending()
    _mm_flush(link)
    c.hold("Andy", "rack screen")
    c.run_pending()
    check(c.snapshot()["applied"]["lasers"] == C.UNKNOWN,
          f"a blank that never got out leaves the lasers UNKNOWN, never "
          f"black: {c.snapshot()['applied']}")
    check(any(f and "may still be showing" in t for t, f in lines),
          f"and says so as a fault: {[t for t, f in lines if f]}")
    link.close()

    # Missing links: nothing sent, every call still a Result, and a
    # Conductor built with it says it is not wired.
    for mm_ok, b_ok in ((False, True), (True, False), (False, False)):
        c, rig, T, lines, link, bey = _cond_devices(mm=mm_ok, beyond=b_ok)
        check(not c.wired and any("not connected" in t and f
                                  for t, f in lines),
              f"MadMapper {mm_ok}, BEYOND {b_ok}: the conductor says the "
              f"rig is not wired: {lines}")
        if link is not None:
            link.close()
    dev = C.ConductorDevices(None, None)
    for name, args in (("lasers_blank", ()),
                       ("lasers_restore", ()), ("video_fade_out", (1.0,)),
                       ("video_restore", (0.0,)), ("video_stop", ())):
        r = getattr(dev, name)(*args)
        check(isinstance(r, C.Result) and r.ok and "no " in r.sentence,
              f"{name} with nothing configured: {r}")
        r = getattr(C.ConductorDevices(object(), object()), name)(*args)
        check(isinstance(r, C.Result) and not r.ok,
              f"{name} on a broken device is a failed Result, not a "
              f"raise: {r}")
    link, socks, _steps = _mm_link()
    link.close()
    r = C.ConductorDevices(link, None).video_fade_out(1.0)
    check(not r.ok and "closed" in r.sentence,
          f"a closed MadMapper link is not reported as sent: {r}")

    # Real time: every call hands its work to the Link's or BEYOND's own
    # worker and returns, the 1 s fades included. A call that ran a fade
    # itself would take the fade (1 s); the bound is half of that. It is
    # not SLOW_CALL_S (100 ms): that is the conductor's own fault threshold,
    # judged on the show PC's clock, and a shared CI runner has taken 110
    # to 300 ms over a thread handoff with nothing wrong.
    link = MM.Link(_mm_cfg(), socket_factory=_FakeMMSock)
    bey = B.Beyond(B.BeyondConfig.parse({}), socket_factory=_FakeMMSock,
                   sleep=_on_time_sleep)
    dev = C.ConductorDevices(link, bey)
    for name, args in (("lasers_blank", ()),
                       ("lasers_restore", ()), ("video_fade_out", (1.0,)),
                       ("video_restore", (1.0,)), ("video_fade_out", (0.0,)),
                       ("video_stop", ())):
        t0 = _time.perf_counter()
        r = getattr(dev, name)(*args)
        took = _time.perf_counter() - t0
        check(r.ok and took < 0.5,
              f"{name}{args} returns at once, not after a fade: "
              f"{took * 1000:.0f} ms, {r}")
    link.close()
    bey.close()
    print("  ok")


def test_conductor_devices_instant_video_lands_after_a_running_fade():
    section("conductor + devices: an instant video level (rehearsal) "
            "cancels a fade still running and lands after its last step")
    C = _cond_mod()
    link, socks, steps = _mm_link(_mm_cfg(ramp_steps=31))
    dev = C.ConductorDevices(link, None)
    gate = threading.Event()
    link._submit(gate.wait, wait=False)       # hold the worker
    dev.video_restore(1.0)                    # a fade up, queued
    dev.video_fade_out(0.0)                   # then black at once
    gate.set()
    _mm_flush(link)
    sent = [MM_v for _a, MM_v in _mm_values(socks)]
    check(sent and sent[-2:] == [0.0, 0.0],
          f"black is the last thing each surface is told: {sent[-4:]}")
    check(len(sent) < 31 * 2,
          f"the fade up was cancelled, not run to the end first: "
          f"{len(sent)} packets")
    link.close()
    print("  ok")


def test_conductor_devices_every_dark_path_fades_the_video_down_to_zero():
    section("conductor + devices: every path that takes the video dark (a "
            "production Hold, an announcement, Abort, a stopped or ended "
            "show, a failed start) fades MadMapper's surfaces DOWN from the "
            "lit picture and ends on opacity 0.0, never up")
    # Through the real ConductorDevices and a real madmapper.Link (fake
    # sockets, a fake clock, no real waits): what is checked is what
    # MadMapper is actually sent, and the level the Link records as sent.
    C = _cond_mod()
    who = ("Andy", "rack screen")
    cases = (
        ("a production Hold", lambda c: c.hold(*who)),
        ("an announcement", lambda c: c.announce("delayed", *who)),
        ("Abort", lambda c: c.abort(*who)),
        ("a stopped or ended show",
         lambda c: c.show_stopped("the scheduler", "")),
        ("a failed start", lambda c: c.failed_start("the scheduler", "")),
    )
    for label, press in cases:
        c, rig, T, lines, link, bey = _cond_devices()
        c.hold_gate = lambda _w, _s, _d: (None, 1)
        c.announcer = lambda *a: None
        try:
            _cd_live(c, rig, link)
            check(link.surfaces_level == 1.0,
                  f"{label}: setup: the video is up before the press: "
                  f"{link.surfaces_level}")
            T.t = 500.0
            r = press(c)
            check(r.ok, f"{label}: accepted: {r}")
            c.run_pending()
            _mm_flush(link)
            fades = [e[1] for e in rig.calls if e[0] == "mm_call"
                     and e[1][0] == "fade_surfaces"]
            check(len(fades) == 1 and fades[0][1:3] == (1.0, 0.0),
                  f"{label}: one video fade, from 1.0 DOWN to 0.0: {fades}")
            sent = [e[1] for e in rig.calls if e[0] == "mm"
                    and e[1][0].startswith("/surfaces/")]
            for s in ("Quad-1", "Quad-2"):
                vals = [v for a, v in sent if a == f"/surfaces/{s}/opacity"]
                check(len(vals) >= 2 and vals[0] == 1.0 and vals[-1] == 0.0
                      and all(b <= a for a, b in zip(vals, vals[1:])),
                      f"{label}: {s} only ever goes down, from 1.0 to "
                      f"0.0: {vals}")
            check(link.surfaces_level == 0.0,
                  f"{label}: the last opacity MadMapper was sent is 0.0: "
                  f"{link.surfaces_level}")
            check(c.snapshot()["applied"]["video"] in ("black", "stopped"),
                  f"{label}: the video is recorded dark: "
                  f"{c.snapshot()['applied']}")
        finally:
            link.close()
    print("  ok")


def test_conductor_devices_unknown_video_level_never_fades_from_full():
    section("conductor + devices: with the video level unknown (nothing sent "
            "since this program started), a fade to black is opacity 0 at "
            "once, never a fade that starts at 1.0 (PR #43 review, item 6)")
    C = _cond_mod()
    link, socks, steps = _mm_link(_mm_cfg(ramp_steps=31))
    dev = C.ConductorDevices(link, None)
    check(dev.video_level() is None, "setup: the level is unknown")
    dev.video_fade_out(1.0)
    _mm_flush(link)
    sent = [MM_v for _a, MM_v in _mm_values(socks)]
    check(sent and max(sent) == 0.0,
          f"only opacity 0 is sent, never anything above it: {sent[:6]}")
    link.close()
    # A fade up from unknown still starts at 0 and rises.
    link, socks, steps = _mm_link(_mm_cfg(ramp_steps=31))
    dev = C.ConductorDevices(link, None)
    dev.video_restore(1.0)
    _mm_flush(link)
    sent = [MM_v for _a, MM_v in _mm_values(socks)]
    check(sent and sent[0] == 0.0 and sent[-1] == 1.0,
          f"a fade up from unknown starts at 0: {sent[:2]} ... {sent[-2:]}")
    link.close()
    print("  ok")


# ---------------------------------------------------------------------------
# The independent review of PR #29 (real UDP, real time probes), findings A
# to E. These run on real threads and real time, through a real
# beyond.Beyond and a real madmapper.Link whose sockets stamp every packet
# with perf_counter: when sendto() was entered and when it returned.
# ---------------------------------------------------------------------------


class _RTSock:
    """A real-time fake socket: logs (kind, address, value, entered,
    returned) for every packet. `delay(value)` makes sendto() take that
    long first, the way a stalled send buffer or an ARP wait would."""

    def __init__(self, kind, log, delay=None):
        self.kind, self.log, self.delay = kind, log, delay

    def sendto(self, pkt, addr):
        from ltcplay import madmapper as MM
        address, _at = MM._read_osc_string(pkt, 0)
        f = MM.decode_float(pkt)
        v = None if f is None else f[1]
        t_in = time.perf_counter()
        d = self.delay(v) if self.delay else 0
        if d:
            time.sleep(d)
        self.log.append((self.kind, address, v, t_in, time.perf_counter()))

    def close(self):
        pass


def test_streamdeck_unplug_keeps_wanted_and_counter():
    section("Stream Deck: with NO deck plugged in (before the first connect, "
            "and between a disconnect and the next one) this process keeps "
            "sending its CURRENT wanted vector at ARM_SEND_HZ on the SAME "
            "arm socket, counter advancing, and a reconnect keeps both: an "
            "unplug never disarms a group by itself (Jeff, 2026-10-07; "
            "ruling 4, 2026-10-12). The sender lock still never changes "
            "hands (round 4 of the safety review, item A). This test used "
            "to be test_streamdeck_round4_unplugged_deck_keeps_the_link_"
            "held_off and asserted the opposite: every group OFF.")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0])
    stamps = []          # (fake time, seq, wanted) of every send on an OPEN socket
    orig_send = arm.send

    def send(names_):
        orig_send(names_)
        if arm.is_open:
            stamps.append((t[0], arm.seq, list(arm.wanted)))
    arm.send = send
    seen = {}

    def deck_a(i):
        if i == 1:
            seen["a_first"] = (arm.seq, list(arm.wanted))
            arm.set_group(0, True)     # the operator arms front row
            arm.set_group(2, True)     # and wave flamer
        if i == 3:
            seen["armed_sent"] = any(w[0] and w[2] for _, _, w in stamps)
            seen["unplug_at"] = t[0]

    def deck_b(i):
        if i == 1:
            seen["b_first"] = (arm.seq, list(arm.wanted))
            seen["back_at"] = t[0]

    # No deck for 2 s, a deck for 3 passes, no deck for 1 + 2 s, a deck.
    _round4_run_forever(c, [None, _Round4Deck(3, deck_a), None,
                            _Round4Deck(2, deck_b)], t)
    period = 1.0 / sd.ARM_SEND_HZ
    gaps = [b[0] - a[0] for a, b in zip(stamps, stamps[1:])]
    check(stamps and stamps[0][0] == 0.0,
          f"the very first arm frame goes out at once, before any deck has "
          f"ever been found: {stamps[:1]}")
    check(gaps and max(gaps) <= period + 1e-9,
          f"no gap between two arm frames is ever longer than one "
          f"ARM_SEND_HZ period, through no-deck, connect, unplug and "
          f"reconnect: longest {max(gaps) if gaps else None} s")
    check(seen.get("armed_sent") is True,
          "set up: front row and wave flamer really were sent armed while "
          "the deck was in")
    want = [True, False, True]
    first_true = next(i for i, (_, _, w) in enumerate(stamps) if w == want)
    outage = [x for x in stamps if seen["unplug_at"] <= x[0] <= seen["back_at"]]
    check(len(outage) >= int(3.0 * sd.ARM_SEND_HZ) - 2
          and all(w == want for _, _, w in outage),
          f"every one of the {len(outage)} frames of the 3 s outage carries "
          f"the same vector the deck last wanted, {want}: nothing was "
          f"disarmed by the unplug")
    seqs = [q for _, q, _ in stamps]
    check(all(b == a + 1 for a, b in zip(seqs, seqs[1:])),
          f"the counter advances by one on every frame, through the unplug "
          f"and the reconnect, never restarting: {seqs[:3]} ... "
          f"{seqs[-3:]}")
    check(all(not any(w) for _, _, w in stamps[:first_true]),
          "before the first deck, every frame said OFF (a process start)")
    check(all(w == want for _, _, w in stamps[first_true:]),
          "and from the arm on, every frame says exactly what was armed")
    check(arm.opens == 1 and arm.closes == 0 and arm.restarts == 0,
          f"ONE socket the whole time, never closed and never restarted "
          f"(so flamesafe's sender lock never changes hands and the "
          f"counter never drops): opens={arm.opens} closes={arm.closes} "
          f"restarts={arm.restarts}")
    check(seen.get("a_first") == (int(2.0 * sd.ARM_SEND_HZ),
                                  [False, False, False]),
          f"the first deck finds the process-start state, counter at the "
          f"no-deck frames sent so far and every group OFF: {seen}")
    check(seen.get("b_first", (0,))[0] > seen["a_first"][0] + 60
          and seen.get("b_first", (0, None))[1] == want,
          f"the replugged deck finds the counter still advancing and the "
          f"groups still as they were: {seen.get('b_first')}")
    check(arm.wanted == want, f"and they stay so after it: {arm.wanted}")


def test_streamdeck_unplug_posts_one_deck_alert_and_one_update():
    section("Stream Deck: the first failure of an outage raises ONE deck "
            "alert on the engine (booth note, rack-screen banner, "
            "Acknowledge or Disarm all, no timer), the retries add none, "
            "and the replug updates the same alert to say the deck is back; "
            "it still waits for an Acknowledge (Jeff, 2026-10-07: 'audible "
            "booth note, then Andy confirms'; ruling 4, 2026-10-12)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    posted = []

    class _Engine:
        def snapshot(self):
            return {"latched": False, "look": "PLAYING"}

        def alert(self, body):
            posted.append((t[0], dict(body)))
            return sd.EngineResult(True, "alert sent")
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, conductor=_Engine(),
                      clock=lambda: t[0])
    events = []
    # A deck for 3 passes, then 5 x 2 s with none, then a deck for 2 passes
    # that runs clean, then unplugged again twice.
    _round4_run_forever(c, [_Round4Deck(3), None, None, None, None, None,
                            _Round4Deck(int(12 * sd.ARM_SEND_HZ)), None,
                            None, _Round4Deck(2)], t,
                        journal=lambda t_, **kw: events.append((t_, kw)))
    raises = [b for _, b in posted if b.get("raise") == "deck"]
    check(len(posted) == 5 and len(raises) == 5
          and [b["text"] for b in raises] == [sd.DECK_LOST_TEXT,
                                              sd.DECK_BACK_TEXT,
                                              sd.DECK_LOST_TEXT,
                                              sd.DECK_BACK_TEXT,
                                              sd.DECK_LOST_TEXT],
          f"a post whenever the sentence changes (lost, back, lost again at "
          f"the end), nothing per 2 s retry: "
          f"{[(at, b['text'][:24]) for at, b in posted]}")
    check(raises[0]["text"] == sd.DECK_LOST_TEXT
          and raises[0]["options"] == ["Acknowledge", "Disarm all"]
          and "stays as it was" in sd.DECK_LOST_TEXT
          and "Acknowledge" in sd.DECK_LOST_TEXT,
          f"the alert says the groups stay as they were and what to press: "
          f"{raises[0]}")
    check(raises[1]["text"] == sd.DECK_BACK_TEXT and "is back" in
          sd.DECK_BACK_TEXT and "Acknowledge" in sd.DECK_BACK_TEXT
          and "clear" not in {k for _, b in posted for k in b},
          f"the replug updates the alert (a re-raise of the same kind) "
          f"rather than clearing it: the Acknowledge is still owed: "
          f"{raises[1]}")
    check(posted[0][0] <= 0.2 and posted[1][0] >= posted[0][0] + 10.0,
          f"posted at the unplug and at the replug: {[at for at, _ in posted]}")
    con = [t_ for t_, kw in events if "Stream Deck connected" in t_]
    check(con and all("stays as it was" in t_ for t_ in con)
          and not any("starts OFF" in t_ for t_ in con),
          f"the connect line says the groups stay as they were: {con[:1]}")
    for bad in ("\u2014", "\u2013"):
        check(bad not in sd.DECK_LOST_TEXT + sd.DECK_BACK_TEXT,
              "no em or en dashes in the alert sentences")


def test_streamdeck_hardware_reconnect_keeps_counter():
    section("Stream Deck: a hardware replug inside a living process keeps "
            "the counter and the wanted vector (no seq 0 after it, nothing "
            "sent that flamesafe was not already seeing) and drops only the "
            "holds in progress and the key snapshot (ruling 4, 2026-10-12)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0])
    c._arm_holds = [sd.AbortHold(hold_s=0.1) for _ in names]
    stamps = _round5_stamped(arm, t)
    seqs = []
    orig = arm.send

    def send(names_):
        orig(names_)
        seqs.append(arm.seq)
    arm.send = send
    press_group1 = [False] * 6
    press_group1[sd.GROUP_KEYS[1]] = True

    class _Deck1(_Round4Deck):
        """Arms front row, then holds cat-walk's key down and unplugs
        mid-hold."""

        def keys_down(self):
            self.i += 1
            if self.i == 1:
                arm.set_group(0, True)
                return []
            if self.i == 2:
                return [press_group1]
            raise sd.DeckDisconnected("probe: unplugged mid-hold")
    # Four passes of the replugged deck, none reporting any key (real
    # hardware reports a key only on change).
    _round4_run_forever(c, [_Deck1(99), None, _Round4Deck(4)], t)
    check(0 not in seqs[1:] and seqs == sorted(seqs)
          and len(set(seqs)) == len(seqs),
          f"the counter never goes back to 0 and never repeats after the "
          f"process start: {seqs[:2]} ... {seqs[-2:]}")
    check(arm.wanted == [True, False, False] and arm.restarts == 0,
          f"front row stays armed through the unplug and the replug, and "
          f"the hold on cat-walk that the unplug interrupted never fired, "
          f"however long the gap: {arm.wanted} restarts={arm.restarts}")
    check(c._prev_keys == [False] * 6
          and all(h.fraction(t[0]) == 0.0 for h in c._arm_holds),
          "every key reads released and every hold is dropped after it")
    check(all(w in ([False] * 3, [True, False, False])
              for _, w in stamps),
          "no frame ever said anything but OFF or front row armed")


def test_streamdeck_outage_loop_runs_screen_pass():
    section("Stream Deck: while the hardware is away the outage loop still "
            "runs the screen's holds and disarms, so a rack-screen hold "
            "arms a group with no deck plugged in, under the same two-clock "
            "rule, and a screen disarm still lands (the virtual deck, "
            "Phase 1, depends on this)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    scr = _FakeScreen()
    events = []
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0],
                      screen=scr,
                      journal=lambda t_, **kw: events.append((t_, kw)))
    arm.open()
    arm.set_group(1, True)
    # The engine reports a fresh hold on front row, 1.2 s of heartbeats.
    scr.h[0] = {"group": 0, "id": 1, "held_s": 1.2, "fresh": True,
                "who": "Andy", "device": "Rack screen"}
    sd._hold_link_steady(c, lambda s_: t.__setitem__(0, t[0] + s_), 2.0)
    check(arm.wanted == [True, True, False],
          f"a screen hold arms front row with no deck at all, after the "
          f"deck's own ARM_HOLD_S: {arm.wanted}")
    check(any("arm pressed" in t_ and "Rack screen" in t_ for t_, _ in events),
          f"journaled as a press on the rack screen: {events[-1:]}")
    scr.h.clear()
    scr.d.append({"id": 1, "group": 1, "who": "Jeff", "device": "Rack screen"})
    sd._hold_link_steady(c, lambda s_: t.__setitem__(0, t[0] + s_), 0.1)
    check(arm.wanted == [True, False, False],
          f"a screen disarm lands with no deck too: {arm.wanted}")
    check(len(arm.sends) >= int(2.1 * sd.ARM_SEND_HZ),
          f"and the arm frames kept going at ARM_SEND_HZ throughout (plus "
          f"the arm's and the disarm's own sends): {len(arm.sends)}")


def test_streamdeck_hold_off_survives_an_arm_socket_that_will_not_send():
    section("Stream Deck: with the hardware away, an arm socket whose send "
            "raises a plain OSError on every cycle (the port in use, the "
            "interface down) never ends the hold-off loop: it keeps trying "
            "at ARM_SEND_HZ for the whole wait and returns to the reconnect "
            "attempt (round 5 of the safety review, item 2: only "
            "DeckDisconnected used to be caught there)")
    from ltcplay import streamdeck as sd

    class _DeafArm(_FakeArmSocket):
        def __init__(self, n):
            super().__init__(n)
            self.tries = 0

        def send(self, names):
            self.tries += 1
            raise OSError("probe: the arm socket will not send")

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _DeafArm(3)
    t = [0.0]
    events = []
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0],
                      screen=_FakeScreen(),
                      journal=lambda t_, **kw: events.append((t_, kw)))
    arm.open()
    outage = sd._DeckOutage(lambda t_, **kw: events.append((t_, kw)))
    sleep = lambda s_: t.__setitem__(0, t[0] + s_)  # noqa: E731
    try:
        sd._hold_link_steady(c, sleep, 2.0, outage)
        ended = "returned"
    except Exception as e:                           # noqa: BLE001
        ended = f"raised {type(e).__name__}: {e}"
    check(ended == "returned",
          f"the hold-off loop ran its 2 s out past a send that raised on "
          f"every cycle, and returned to the reconnect attempt: {ended}")
    check(arm.tries == int(2.0 * sd.ARM_SEND_HZ) and t[0] >= 2.0,
          f"and it kept trying to send at ARM_SEND_HZ for the whole wait: "
          f"{arm.tries} tries over {t[0]:.1f} s")
    print("  ok")


def test_streamdeck_no_deck_loop_keeps_sending_past_a_screen_error():
    section("Stream Deck: with the hardware away, a screen pass or tick that "
            "raises on every cycle never stops the arm frames (the link "
            "going silent would disarm every group within arm_stale_ms and "
            "lapse the sender lock: round 4, item A); the error is journaled "
            "once per outage (review of PR #59, P1)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [0.0]
    events = []

    class _BadScreen:
        def holds(self):
            raise RuntimeError("probe: the deck-input answer is garbage")

        def new_disarms(self):
            raise RuntimeError("probe: the deck-input answer is garbage")
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0],
                      screen=_BadScreen(),
                      journal=lambda t_, **kw: events.append((t_, kw)))
    arm.open()
    arm.set_group(0, True)
    outage = sd._DeckOutage(lambda t_, **kw: events.append((t_, kw)))
    sleep = lambda s_: t.__setitem__(0, t[0] + s_)  # noqa: E731
    sd._hold_link_steady(c, sleep, 3.0, outage)
    check(len(arm.sends) == int(3.0 * sd.ARM_SEND_HZ)
          and all(w == [True, False, False] for w in arm.sends),
          f"every one of the 3 s of frames went out, unchanged, past a "
          f"screen pass that raised on every cycle: {len(arm.sends)}")
    lines = [t_ for t_, kw in events if "could not be read" in t_]
    check(len(lines) == 1 and events[0][1].get("fault") is True
          and "RuntimeError" in lines[0] and "carries on unchanged"
          in lines[0], f"journaled once per outage, as a fault: {events}")
    check(outage.active, "and the outage is open, so a later clean 10 s "
                         "closes it as usual")
    # Through the real loop too: a deck that never comes, with the screen
    # raising, keeps sending for the whole wait.
    arm2 = _FakeArmSocket(3)
    c2 = sd.Controller(arm2, _FakeStatusSocket(), names,
                       operator_provider=lambda: "Andy",
                       show_running_provider=lambda: True,
                       clock=lambda: t[0], screen=_BadScreen())
    stamps = _round5_stamped(arm2, t)
    _round4_run_forever(c2, [None, None, None], t)
    period = 1.0 / sd.ARM_SEND_HZ
    gaps = [b[0] - a[0] for a, b in zip(stamps, stamps[1:])]
    check(len(stamps) >= int(6.0 * sd.ARM_SEND_HZ) - 1 and gaps
          and max(gaps) <= period + 1e-9,
          f"run_forever with no deck and a raising screen: {len(stamps)} "
          f"frames, longest gap {max(gaps) if gaps else None} s")
    print("  ok")


def test_streamdeck_deck_alert_is_posted_again_until_the_engine_answers():
    section("Stream Deck: the deck alert is posted again on every retry "
            "while the engine has not answered 200 to it (engine down, post "
            "queue full), and not again once it has; the engine's answer is "
            "recorded by the conductor's own post (review of PR #59, P2)")
    from ltcplay import streamdeck as sd
    posted = []
    landed = [False]
    outage = sd._DeckOutage(lambda t_, **kw: None,
                            alert=lambda body: posted.append(dict(body)),
                            delivered=lambda: landed[0])
    e = sd.DeckDisconnected("probe")
    for _ in range(3):
        outage.failed(e, "tail")
    # Never connected in this process (Jeff, 2026-10-17): the sentence
    # says what the first failure said, once per outage, the same on
    # every retry, so the retries are posts of ONE sentence.
    never = sd.DECK_NEVER_TEXT.format(why="probe")
    check(len(posted) == 3 and all(b["text"] == never for b in posted)
          and "No Stream Deck has answered" in never
          and "probe" in never,
          f"posted on every retry while the engine has not taken it, the "
          f"never-connected sentence with the failure's words: "
          f"{len(posted)} {[b['text'][:40] for b in posted]}")
    landed[0] = True
    outage.failed(e, "tail")
    outage.failed(e, "tail")
    check(len(posted) == 3, "and not again once the engine answered 200")
    outage.connected()
    check(len(posted) == 4 and posted[-1]["text"] == sd.DECK_BACK_TEXT,
          f"the replug posts the update once: {posted[-1:]}")
    outage.connected()
    check(len(posted) == 4, "a second reconnect in the outage posts nothing")
    # No way to know (a conductor without alert_delivered): one post.
    posted2 = []
    o2 = sd._DeckOutage(lambda t_, **kw: None,
                        alert=lambda body: posted2.append(dict(body)))
    for _ in range(3):
        o2.failed(e, "tail")
    check(len(posted2) == 1, "with no answer to read, one post per outage")
    # The conductor records the engine's answer.
    answers = [(False, "refused", {}), (True, "ok", {})]
    eng = sd.EngineConductor("http://127.0.0.1:9",
                             poster=lambda p, b: answers.pop(0),
                             fetcher=lambda p: None)
    check(eng.alert_delivered is None, "nothing posted yet: unknown")
    eng.alert({"raise": "deck", "text": "x", "options": ["Acknowledge"]})
    check(eng.alert_delivered is False, "queued: not delivered yet")
    eng._post_one(*eng._q.get_nowait())
    check(eng.alert_delivered is False, "the engine refused: still not")
    eng.alert({"raise": "deck", "text": "x", "options": ["Acknowledge"]})
    eng._post_one(*eng._q.get_nowait())
    check(eng.alert_delivered is True, "the engine answered 200: delivered")
    eng.acknowledge(who="Andy")
    check(eng.alert_delivered is True,
          "an Acknowledge post does not count as an alert raise")
    # run_forever wires the conductor's answer in.
    src = open(sd.__file__, encoding="utf-8").read()
    check("delivered=(lambda: cond.alert_delivered)" in src,
          "run_forever gives the outage the conductor's answer to read")
    print("  ok")


def test_streamdeck_ack_key_while_an_alert_is_open():
    section("Stream Deck: while the engine has an alert open the Start key "
            "reads ACK / ALERT in a look of its own (never Abort's red, an "
            "armed green or a hold's amber); the first press of ANY key "
            "acknowledges, and the key still does its own job; Start does "
            "only the acknowledge; the key reads START NOW again once the "
            "alert is cleared (Jeff's ruling 2, 2026-10-12)")
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    status = _FakeStatus()
    status.set({"arm_input": {"state": "live", "seq": 1}, "fault": "",
                "confirmed": True, "groups": [
                    {"name": n, "armed": "disarmed", "wanted": False,
                     "reason": "", "amber": "", "dwell_s": 0}
                    for n in names]})
    lines, calls = [], []

    class _Engine:
        def snapshot(self):
            return {"latched": False, "look": "BETWEEN"}

        def acknowledge(self, who, screen):
            calls.append(("acknowledge", who, screen))
            return sd.EngineResult(True, "alert sent to the engine")

        def hold(self, who, screen):
            calls.append(("hold", who, screen))
            return sd.EngineResult(True, "Hold: ok.")

    class _Screen(_FakeScreen):
        def __init__(self):
            super().__init__()
            self.a = []

        def alerts(self):
            return tuple(self.a)
    scr = _Screen()
    t = [10.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      conductor=_Engine(), clock=lambda: t[0], screen=scr,
                      journal=lambda text, **kw: lines.append((text, kw)))
    fonts, faces, restore = _deck_face_recorder(sd)
    if fonts is None:
        print("  note: Pillow is not installed here, so the ACK key's "
              "words are not checked on this machine.")
        return
    try:
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["START", "NOW"], sd.CHAMPAGNE, None),
              f"no alert: START NOW as always: {faces[0]}")
        scr.a = [{"id": 1, "kind": "deck", "text": sd.DECK_LOST_TEXT,
                  "options": ["Acknowledge", "Disarm all"]}]
        for on in (True, False):
            c.draw(fonts, blink_on=on, chase=0)
            bg, text = sd.ACK_ON if on else sd.ACK_OFF
            check(faces[0] == (["ACK", "ALERT"], text, bg),
                  f"alert open, flash phase {on}: the Start key reads ACK / "
                  f"ALERT in the ACK look: {faces[0]}")
            check(sd.SPARE_KEY not in faces and
                  faces[sd.GROUP_KEYS[0]][0] == "front row",
                  f"the arm keys keep their own faces, the spare stays "
                  f"blank: {faces}")
        # A fault face outranks ACK (review of PR #59): a refused press or
        # zeroed cues is never hidden behind a waiting alert.
        c.conductor.fault = "Hold: the engine did not take it"
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0][0] == ["ENGINE", "FAULT"],
              f"an engine fault shows over a waiting alert: {faces[0]}")
        c.conductor.fault = ""
        c.conductor.cues_fault = "the render does not fit"
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0][0] == ["CUES", "FAULT"],
              f"a cues fault shows over a waiting alert: {faces[0]}")
        c.conductor.cues_fault = ""
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0][0] == ["ACK", "ALERT"],
              f"and ACK is back once the fault is gone: {faces[0]}")
        for look in (sd.ACK_ON, sd.ACK_OFF):
            bg = look[0]
            check(bg[2] > bg[0] + 60 and bg[2] > bg[1] + 40,
                  f"the ACK look is blue, nothing like Abort's red, an "
                  f"armed green or a hold's amber: {bg}")
            check(bg not in (sd.RED, sd.GREEN, sd.AMBER, sd.AMBER_DIM,
                             sd.GOLD, sd.BRONZE, sd.PLAYING_ON[0],
                             sd.PLAYING_OFF[0], sd.AUDIO_LOST_ON[0],
                             sd.AUDIO_LOST_OFF[0], sd.LATCHED_GREY),
                  f"and reuses no other key's background: {bg}")
        # Start pressed: acknowledge only, no Start Now refusal.
        c.run_once([True, False, False, False, False, False])
        c.run_once([False] * 6)
        check(calls == [("acknowledge", "Andy", "Stream Deck")],
              f"the Start key acknowledges and does nothing else: {calls}")
        check(any("Acknowledge" in t_ and kw.get("action") == "alert"
                  and not kw.get("fault") for t_, kw in lines)
              and not any("Nothing was started" in t_ for t_, _ in lines),
              f"journaled as an acknowledge, not as a Start Now refusal: "
              f"{lines}")
        # The spare key pressed with the alert still open: acknowledge, and
        # nothing else (it has no job of its own).
        del calls[:]
        c.run_once([False, False, False, False, False, True])
        c.run_once([False] * 6)
        check(calls == [("acknowledge", "Andy", "Stream Deck")],
              f"any key acknowledges, the spare one too: {calls}")
        # A group key: acknowledge, and the hold starts as always.
        del calls[:]
        down = [False] * 6
        down[sd.GROUP_KEYS[0]] = True
        c.run_once(down)
        check(calls == [("acknowledge", "Andy", "Stream Deck")]
              and c._arm_holds[0]._down_at == t[0],
              f"a group key acknowledges and its hold starts: {calls} "
              f"{c._arm_holds[0]._down_at}")
        c.run_once([False] * 6)
        # Cleared on the engine: back to normal, and Start starts again.
        scr.a = []
        del calls[:]
        c.draw(fonts, blink_on=True, chase=0)
        check(faces[0] == (["START", "NOW"], sd.CHAMPAGNE, None),
              f"alert cleared: START NOW again: {faces[0]}")
        n = len(lines)
        c.run_once([True, False, False, False, False, False])
        c.run_once([False] * 6)
        check(not calls and any("Nothing was started" in t_
                                for t_, _ in lines[n:]),
              f"and Start is Start again: {calls} {lines[n:]}")
    finally:
        restore()
    # The deck's own posts: Acknowledge and the deck alert both go to the
    # engine's alert route, on the queue, from the show machine.
    posts = []

    def poster(path, body):
        posts.append((path, dict(body)))
        return True, "ok", {}
    eng = sd.EngineConductor("http://127.0.0.1:9", poster=poster,
                             fetcher=lambda p: None, clock=lambda: t[0],
                             wall=lambda: 1_800_000_000.0)
    r1 = eng.acknowledge(who="Andy", screen="Stream Deck")
    r2 = eng.alert({"raise": "deck", "text": sd.DECK_LOST_TEXT,
                    "options": ["Acknowledge", "Disarm all"]})
    check(r1.ok and r2.ok, f"both are queued: {r1} {r2}")
    eng._post_one(*eng._q.get_nowait())
    eng._post_one(*eng._q.get_nowait())
    check([p for p, _ in posts] == ["/api/remote/alert"] * 2
          and posts[0][1].get("action") == "acknowledge"
          and posts[0][1].get("who") == "Andy"
          and posts[1][1].get("raise") == "deck"
          and posts[1][1].get("text") == sd.DECK_LOST_TEXT,
          f"both POST /api/remote/alert with what the engine needs: {posts}")
    # ScreenKeys hands the alerts on only while the answer is fresh.
    ans = {"enabled": False, "holds": [], "disarms": [],
           "alerts": [{"id": 3, "kind": "audio", "text": "x"}]}
    keys = sd.ScreenKeys("http://127.0.0.1:9", fetcher=lambda p: ans,
                         clock=lambda: t[0])
    keys.poll_once()
    check(len(keys.alerts()) == 1 and keys.alerts()[0]["kind"] == "audio",
          "a fresh answer's alerts are handed on")
    t[0] += sd.SCREEN_STALE_S + 0.01
    check(keys.alerts() == (),
          "a stale answer hands on none: a key must not keep reading ACK, "
          "or acknowledge something the engine no longer shows")
    print("  ok")


def test_streamdeck_round4_unplug_keeps_one_real_source_port():
    section("Stream Deck: the same, over a REAL ArmSocket and a real UDP "
            "receiver: every arm frame through no-deck, connect, unplug "
            "and reconnect comes from ONE source port (the one flamesafe's "
            "sender lock holds), the counter never restarts after the "
            "process start, and the no-deck frames carry the vector the "
            "deck last wanted (round 4, item A; ruling 4, 2026-10-12)")
    import json as _json
    import socket as _socket
    from ltcplay import streamdeck as sd

    rx = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
    rx.bind(("127.0.0.1", 0))
    rx.setblocking(False)
    names = ["front row", "cat-walk", "wave flamer"]
    arm = sd.ArmSocket("127.0.0.1", rx.getsockname()[1], "probe-key-0123456789",
                       3)
    t = [0.0]
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, clock=lambda: t[0])
    got = []

    def drain():
        while True:
            try:
                data, addr = rx.recvfrom(65535)
            except (BlockingIOError, OSError):
                return
            got.append((addr, _json.loads(data)))

    def deck_a(i):
        drain()
        if i == 1:
            arm.set_group(1, True)

    try:
        _round4_run_forever(c, [None, _Round4Deck(2, deck_a), None,
                                _Round4Deck(1)], t, on_sleep=drain)
        time.sleep(0.05)
        drain()
    finally:
        arm.close()
        rx.close()
    ports = {a for a, _ in got}
    check(len(got) > 100 and len(ports) == 1,
          f"{len(got)} arm frames, all from one source address: {ports}")
    seqs = [f["seq"] for _, f in got]
    restarts = sum(1 for a, b in zip(seqs, seqs[1:]) if b < a)
    check(restarts == 0 and seqs == sorted(seqs) and len(set(seqs)) == len(seqs),
          f"the counter never restarts after the process start, through "
          f"connect, unplug and reconnect: {restarts} restarts")
    first_on = min(i for i, (_, f) in enumerate(got) if any(f["wanted"]))
    check(all(f["wanted"] == [False, True, False] for _, f in got[first_on:])
          and len(got) - first_on > 60,
          f"from the moment cat-walk was armed, every frame through the "
          f"unplug and the reconnect still says cat-walk armed and nothing "
          f"else: {len(got) - first_on} frames")
    check(all(not any(f["wanted"]) for _, f in got[:first_on]),
          "and before the process had a deck, every frame said OFF")


def test_streamdeck_round4_reconnect_releases_every_hold():
    section("Stream Deck: reset_on_reconnect releases the Stop hold, EVERY "
            "group's arm hold and the key snapshot, each on its own (round "
            "4: hand mutations that skipped only one survived the whole "
            "suite; review of PR #120, P2-3, for the Stop hold)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    t = [0.0]
    events = []
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False,
                      run_live_provider=lambda: True,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    c._prev_keys = [True] * 6
    c._stop_hold.press(0.0)
    for h in c._arm_holds:
        h.press(0.0)
    c.reset_on_reconnect()
    t[0] = 10.0
    check(c._prev_keys == [False] * 6, "every key reads released")
    check(c._stop_hold.fraction(t[0]) == 0.0,
          "the Stop hold is released (no fill drawn, nothing to fire)")
    check(all(h.fraction(t[0]) == 0.0 for h in c._arm_holds),
          f"every arm hold is released: "
          f"{[h.fraction(t[0]) for h in c._arm_holds]}")
    # Stop held on a live run, the deck unplugged, the key let go while it
    # was away, the deck back: the first tick sends nothing.
    c.tick()
    check(not arm.sends and not any(kw.get("action") in ("stop", "disarm")
                                    for _t, kw in events),
          f"no Stop off a hold left over from before the gap: "
          f"{arm.sends} {events}")


def test_streamdeck_round4_foreign_alarm_logs_once_while_the_count_moves():
    section("Stream Deck: the foreign-sender alarm journals ONCE while the "
            "condition lasts, even as flamesafe's count of other senders "
            "goes 1, 2, 1 (round 4: a dedup key that embedded the count "
            "survived the whole suite)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])

    def doc(foreign):
        return {"arm_input": {"state": "live", "seq": arm.seq,
                              "foreign_senders": foreign},
                "groups": [{"name": n, "wanted": False} for n in names]}

    arm.send(names)
    status.set(doc(0))
    c.check_links()
    t[0] += sd.RECONNECT_GRACE_S + 0.1
    for foreign in (1, 1, 2, 2, 1, 1):
        status.set(doc(foreign))
        c.check_links()
        t[0] += sd.SPOOF_GRACE_S + 0.1
        c.check_links()
    alarms = [e for e in events if "ALARM" in e[0]]
    check(c._spoof_alarm and len(alarms) == 1,
          f"one alarm line for one continuous episode: {len(alarms)}")


def test_streamdeck_round4_fresh_process_gets_the_reconnect_grace():
    section("Stream Deck: a deck PROCESS that has just started gets the "
            "same RECONNECT_GRACE_S a reconnect does (round 4, item E: a "
            "restart quicker than flamesafe's arm_stale_ms finds the old "
            "process still holding the sender lock for a moment, which "
            "used to raise a false spoof alarm)")
    from ltcplay import streamdeck as sd

    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    arm.open()
    status = _FakeStatus()
    events = []
    t = [0.0]
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    old = {"arm_input": {"state": "live", "seq": 5000, "foreign_senders": 1},
           "groups": [{"name": n, "wanted": False} for n in names]}
    arm.send(names)
    status.set(old)
    while t[0] < sd.RECONNECT_GRACE_S - 0.05:
        c.check_links()
        arm.send(names)
        t[0] += 0.05
    check(not c._spoof_alarm and not any("ALARM" in e[0] for e in events),
          f"the old process's lock, still there for under a second, is not "
          f"an alarm: {c._spoof_alarm!r}")
    t[0] += sd.SPOOF_GRACE_S + 0.2
    c.check_links()
    t[0] += sd.SPOOF_GRACE_S + 0.1
    c.check_links()
    check(c._spoof_alarm,
          "but the same report persisting past the grace IS an alarm")


def test_streamdeck_round4_other_sender_reason_has_a_label():
    section("Stream Deck: flamesafe's new held reason (a cycle refused while "
            "another sender is on the arm link, round 4 item B) has its own "
            "short label on the key, and the hand-copied sentence matches "
            "flamesafe's own, checked in a separate process so this one "
            "never imports flamesafe")
    import subprocess as _sp
    from ltcplay import streamdeck as sd
    r = _sp.run([sys.executable, "-c",
                 "from flamesafe import composer; "
                 "print(composer.OTHER_SENDER)"],
                cwd=os.path.dirname(os.path.abspath(__file__)),
                capture_output=True, text=True, timeout=60)
    sentence = r.stdout.strip()
    check(sentence in sd._SHORT_REASON,
          f"the deck knows flamesafe's exact sentence: {sentence!r}")
    look = sd.group_look({"armed": "held", "reason": sentence,
                          "amber": "steady", "dwell_s": 0})
    check(look[:2] == ("OTHER", "SENDER") and look[4] is False,
          f"drawn as OTHER SENDER, steady: {look}")


