class _FakeSock:
    """Drives web.Handler with no socket: the request bytes in, the
    response bytes out. Lets a test ask as any client address, which a
    real socket on a test machine cannot."""

    def __init__(self, raw):
        import io
        self._in = io.BytesIO(raw)
        self.out = b""

    def makefile(self, mode, *a, **k):
        if "r" in mode:
            return self._in
        import io
        sock = self

        class W(io.RawIOBase):
            def writable(self):
                return True

            def write(self, b):
                sock.out += bytes(b)
                return len(b)
        return W()

    def sendall(self, b):
        self.out += bytes(b)

    def settimeout(self, t):
        pass

    def setsockopt(self, *a):
        pass

    def shutdown(self, *a):
        pass

    def close(self):
        pass


def _ask(httpd, method, path, body=None, client=("10.20.0.44", 50000),
         headers=None, host=None, raw_body=None, content_length=None):
    """(status, headers, json or text) for one request as `client`."""
    import json as _j
    from ltcplay import web as web_mod
    port = httpd.server_address[1]
    if host is None:
        host = (f"127.0.0.1:{port}" if client[0] in web_mod.LOOPBACK
                else f"{httpd.bind_address}:{port}")
    data = raw_body if raw_body is not None else (
        _j.dumps(body).encode() if body is not None else b"")
    h = {"Host": host}
    if data or method == "POST":
        h["Content-Type"] = "application/json"
        h["Content-Length"] = str(len(data) if content_length is None
                                  else content_length)
    h.update(headers or {})
    head = f"{method} {path} HTTP/1.1\r\n" + "".join(
        f"{k}: {v}\r\n" for k, v in h.items() if v is not None) + \
        "Connection: close\r\n\r\n"
    sock = _FakeSock(head.encode() + data)
    web_mod.Handler(sock, client, httpd)
    raw = sock.out
    head_b, _, payload = raw.partition(b"\r\n\r\n")
    lines = head_b.decode("latin-1").split("\r\n")
    status = int(lines[0].split()[1]) if lines and lines[0] else 0
    hdrs = {}
    for ln in lines[1:]:
        k, _, v = ln.partition(":")
        hdrs.setdefault(k.strip().lower(), []).append(v.strip())
    try:
        out = _j.loads(payload or b"null")
    except ValueError:
        out = payload.decode("utf-8", "replace")
    return status, hdrs, out


class _RemoteRig:
    """A scheduler with a conductor, a web server built round them, and a
    Remote with a clock and wall the test moves. Nothing here listens on a
    network: requests go through _ask."""

    def __init__(self, S, at=None, conductor=True):
        import tempfile
        from ltcplay import web as web_mod
        from ltcplay import remote as remote_mod
        self.S = S
        self.work = tempfile.mkdtemp()
        self.folder = tempfile.mkdtemp()
        self.now = [at or _den(S, 17, 55)]
        if conductor:
            self.c, self.rig, self.T, self.lines = _cond()
        else:
            self.c = self.rig = None
        self.svc = _svc(S, self.work, self.now, conductor=self.c)
        self.svc.tick()
        self.settle()
        self.httpd = web_mod.serve(self.folder, port=0, bind="127.0.0.1")
        self.httpd.bind_address = "10.20.0.5"     # as if on the show network
        self.httpd.schedule = self.svc
        self.mono = [1000.0]
        self.wall = [1_800_000_000.0]
        self.remote = remote_mod.Remote(
            self.httpd.control, self.svc, folder=self.work,
            clock=lambda: self.mono[0], wall=lambda: self.wall[0],
            log=lambda t: None)
        self.httpd.remote = self.remote

    def settle(self):
        if self.c is not None:
            check(self.svc.flush_conductor(5), "the conductor calls all ran")
            self.c.run_pending()

    def ask(self, method, path, body=None, **kw):
        """As a device on the show network (10.20.0.44) unless `client`
        says otherwise. No sign-in (Jeff, 2026-10-07)."""
        hd = dict(kw.pop("headers", None) or {})
        return _ask(self.httpd, method, path, body, headers=hd, **kw)

    def seen(self):
        return int(self.wall[0] * 1000)

    def lines_for(self, action):
        return [r for r in self.svc.journal if r.get("action") == action]

    def close(self):
        self.httpd.server_close()
        self.remote.close_alerts()
        self.svc.stop()
        # A show selection still being written (off the request) lands
        # before its folder goes.
        self.remote.selection_written(5.0)
        import shutil
        shutil.rmtree(self.work, ignore_errors=True)
        shutil.rmtree(self.folder, ignore_errors=True)


def _live_show(R):
    """Show 1 running and confirmed, as tests elsewhere get it."""
    S = R.S
    R.now[0] = _den(S, 18, 0)
    R.svc.tick()
    R.settle()
    R.now[0] = _den(S, 18, 0, 1)
    _confirm(S, R.svc)
    R.settle()
    check(R.svc.machine.state == S.SHOW, "setup: show 1 is running")


def test_remote_no_sign_in_over_the_network():
    section("iPad remote (Jeff, 2026-10-07): no PIN, no sign-in, no operator "
            "names; a device on the show network uses the remote page's own "
            "routes as it is, the journal names the surface by its address, "
            "and the legacy routes and wildcard binds stay refused")
    S = _sched()
    if S is None:
        return
    from ltcplay import remote as RM
    from ltcplay import web as web_mod
    R = _RemoteRig(S)
    try:
        for name in ("PinStore", "Sessions", "Throttle", "PIN_FILE",
                     "COOKIE", "FREE_TRIES", "LOCK_BASE_S", "LOCK_MAX_S"):
            check(not hasattr(RM, name), f"remote.{name} is gone")
        for r in ("login", "logout", "pin", "operator"):
            check(r not in RM.POST_ROUTES, f"no {r} route")
        check(not hasattr(web_mod, "OPEN_POSTS") and
              not hasattr(web_mod.Handler, "_authorised"),
              "web.py has no sign-in gate left")
        for path in ("/api/remote/login", "/api/remote/logout",
                     "/api/remote/pin", "/api/remote/operator"):
            st, _h, out = R.ask("POST", path, {"who": "Andy", "pin": "2468",
                                               "device": "iPad"})
            check(st == 404, f"{path} does not exist: {st} {out}")
        st, _h, out = R.ask("GET", "/")
        # Users (2026-10-20): signing in is optional and lives on its own
        # Users screen; the show screen has no sign-in, PIN or picker.
        page = str(out)
        show = page[page.find('id="v-show"'):page.find('id="v-tonight"')]
        check(st == 200 and "<title>Show remote</title>" in page and
              "li-pin" not in page and "PIN" not in page and
              "Sign in" not in show and "password" not in show and
              'id="op-pick"' not in page
              and "/api/remote/login" not in page,
              f"the network gets the remote page, with no sign-in form, PIN "
              f"or operator picker for presses: {st}")
        st, _h, out = R.ask("GET", "/api/remote/whoami")
        check(st == 200 and out == {"local": False,
                                    "device": "iPad at 10.20.0.44",
                                    "screen": "iPad", "fresh_s": RM.FRESH_S},
              f"whoami names the surface by its address: {out}")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200 and "served_at" in out and
              "operators" not in out["schedule"] and
              "current_operator" not in out["schedule"] and
              "signed_in" not in out["arming"],
              f"the status answers with no sign-in, and names nobody: {st}")
        from ltcplay import version as _ver
        check(out.get("version") == _ver.status() and
              ("build" in out["version"] or "release" in out["version"]),
              f"the status names which LTC Player this is (release and "
              f"build id), as version.status() says it: {out.get('version')!r}")
        st, _h, out = R.ask("POST", "/api/remote/hold",
                            {"who": "Andy", "screen": "Rack screen"})
        held = [r for r in R.svc.journal
                if "Hold" in str(r.get("text", ""))]
        check(held and all(r.get("who") == "iPad at 10.20.0.44" and
                           r.get("screen") == "iPad" for r in held),
              f"a Hold from the iPad is journaled as the iPad at its "
              f"address, never as the name the body gave: "
              f"{[(r.get('who'), r.get('screen')) for r in held]}")
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/whoami",
                           client=("127.0.0.1", 5000))
        check(out.get("device") == "Rack screen" and out.get("local"),
              f"the machine itself is the Rack screen: {out}")
        for method, path, body in (
                ("GET", "/api/state", None),
                ("GET", "/api/timelines", None),
                ("GET", "/api/schedule/state", None),
                ("POST", "/api/stop", {}),
                ("POST", "/api/start", {"timeline": "x.json"}),
                ("POST", "/api/schedule/operator", {"who": "Andy"})):
            st, _h, out = R.ask(method, path, body)
            check(st == 403, f"{method} {path} from the network is still "
                             f"refused: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/network",
                            {"address": "10.20.0.9"})
        check(st == 403, f"the show network is set only on the machine "
                         f"itself: {st}")
        check(not os.path.exists(os.path.join(R.work,
                                              "ltcplay_remote_pins.json")),
              "no PIN file is written")
        # Wildcard binds are refused outright.
        for wild in ("0.0.0.0", "::", "", "0", "0.0", "000.000.000.000"):
            try:
                h2 = web_mod.serve(R.folder, port=0, bind=wild)
                h2.server_close()
                check(False, f"serving on {wild} was allowed")
            except ValueError as e:
                check("show Wi-Fi" in str(e), f"{wild} refused: {e}")
    finally:
        R.close()
    print("  ok")


LEGACY_POSTS = (
    ("/api/stop", {}), ("/api/start", {"timeline": "x.json"}),
    ("/api/go", {"at": "00:00:10:00"}), ("/api/skip", {"seconds": 5}),
    ("/api/release", {}), ("/api/input", {"device": "", "channel": 1}),
    ("/api/showdir", {"timeline": "x.json", "folder": "/tmp"}),
    ("/api/reinput", {}), ("/api/trigger", {"on": True}),
    ("/api/reload", {}), ("/api/override", {"look": "blackout"}),
    ("/api/autoreload", {"on": True}), ("/api/check", {"timeline": "x"}),
    ("/api/find", {"seconds": 0.1}),
    ("/api/schedule/operator", {"who": "Jeff", "screen": "iPad"}),
    ("/api/schedule/deck-event", {"text": "front row arm pressed by Jeff",
                                  "who": "Jeff", "action": "arm"}),
    ("/api/schedule/tonight", {"op": "remove", "show": 5, "who": "Jeff",
                               "screen": "iPad"}),
    ("/api/schedule/incident", {"who": "Jeff", "screen": "iPad"}),
    ("/api/announce/play", {"id": 1}))
LEGACY_GETS = ("/api/state", "/api/devices", "/api/timelines", "/api/log",
               "/api/schedule", "/api/schedule/state",
               "/api/schedule/operator", "/api/schedule/journal",
               "/api/announce")


def test_remote_network_session_reaches_only_remote_routes():
    section("iPad remote, fix round 1 F1: a device on the network "
            "reaches the remote page's own routes and nothing else; every "
            "legacy and scheduler route is refused from the network, and "
            "the Stream Deck's journal route answers only the machine")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        op0 = R.svc.current_operator
        n0 = len(R.svc.journal)
        for path, body in LEGACY_POSTS:
            st, _h, out = R.ask("POST", path, dict(body, seen=R.seen()))
            check(st == 403, f"POST {path} from the iPad is refused: "
                             f"{st} {out}")
        for path in LEGACY_GETS:
            st, _h, out = R.ask("GET", path)
            check(st == 403, f"GET {path} from the iPad is refused: "
                             f"{st}")
        check(R.svc.current_operator == op0,
              f"the operator was not changed from the network: "
              f"{R.svc.current_operator}")
        new = list(R.svc.journal)[n0:]
        check(not any("arm pressed" in r.get("text", "") for r in new) and
              not any(r.get("action") in ("operator", "deck", "arm")
                      for r in new),
              f"no forged deck line or operator change was journaled: "
              f"{[r.get('text') for r in new][:3]}")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200, "the remote page's own status still answers")
        st, _h, out = R.ask("GET", "/")
        check(st == 200 and "<title>Show remote</title>" in str(out),
              "and the remote page itself")
        st, _h, out = R.ask("GET", "/brand/logo_small.png")
        check(st in (200, 404), f"and the logo route: {st}")
        # The machine itself keeps every route, the deck's journal too.
        st, _h, out = _ask(R.httpd, "POST", "/api/schedule/deck-event",
                           {"text": "front row disarm pressed by Andy",
                            "who": "Andy", "action": "disarm"}, client=loop)
        check(st == 200, f"the Stream Deck on this machine still posts its "
                         f"lines: {st} {out}")
        st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop)
        check(st == 200, "and the machine still reads /api/state")
        from ltcplay import web as web_mod
        check(not web_mod.network_may_reach("/api/schedule/deck-event") and
              not web_mod.network_may_reach("/api/stop") and
              web_mod.network_may_reach("/api/remote/hold"),
              "network_may_reach is the remote routes, the page and the logo")
    finally:
        R.close()
    print("  ok")


def test_web_page_icons():
    section("web page icons (Jeff, 2026-10-24): every page the engine "
            "serves names the LTC Player icon, the manifest and the iPad's "
            "home screen icon; the engine serves them itself, with the "
            "right types and a long cache, to the network without sign-in, "
            "and opening them widens nothing else")
    import struct
    import tempfile
    import threading
    import urllib.request
    from ltcplay import web as web_mod
    folder = tempfile.mkdtemp()
    httpd = web_mod.serve(folder, port=0, bind="127.0.0.1")
    t = threading.Thread(target=httpd.serve_forever,
                         kwargs={"poll_interval": 0.05}, daemon=True)
    t.start()
    base = f"http://127.0.0.1:{httpd.server_address[1]}"

    def fetch(path):
        try:
            with urllib.request.urlopen(base + path, timeout=5) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    want = {"/favicon.ico": "image/x-icon",
            "/apple-touch-icon.png": "image/png",
            "/apple-touch-icon-precomposed.png": "image/png",
            "/icon-192.png": "image/png", "/icon-512.png": "image/png",
            "/manifest.webmanifest": "application/manifest+json"}
    got = {}
    try:
        for path, kind in want.items():
            st, h, body = fetch(path)
            got[path] = body
            check(st == 200, f"GET {path} answers: {st}")
            check((h.get("Content-Type") or "") == kind,
                  f"{path} is {kind}: {h.get('Content-Type')}")
            check(len(body) > 0, f"{path} is not empty")
            cc = h.get("Cache-Control") or ""
            m = re.search(r"max-age=(\d+)", cc)
            check("no-store" not in cc and m and int(m.group(1)) >= 86400,
                  f"{path} may be kept by the browser: {cc!r}")
        ico = got.get("/favicon.ico", b"")
        n = struct.unpack("<HHH", ico[:6])[2] if len(ico) >= 6 else 0
        sizes = sorted((ico[6 + 16 * i] or 256)
                       for i in range(n) if len(ico) >= 22 + 16 * i)
        check(ico[:4] == b"\0\0\1\0" and sizes == [16, 32, 48],
              f"favicon.ico holds 16, 32 and 48 px: {sizes}")
        for path, px in (("/apple-touch-icon.png", 180),
                         ("/icon-192.png", 192), ("/icon-512.png", 512)):
            b = got.get(path, b"")
            w, hh = struct.unpack(">II", b[16:24]) if len(b) >= 24 else (0, 0)
            check(b[:8] == b"\x89PNG\r\n\x1a\n" and (w, hh) == (px, px),
                  f"{path} is a {px} px PNG: {(w, hh)}")
        try:
            man = json.loads(got.get("/manifest.webmanifest") or b"{}")
        except ValueError:
            man = {}
        check(man.get("name") == "LTC Player" and
              man.get("short_name") == "LTC Player" and
              man.get("display") == "standalone" and
              man.get("theme_color") == man.get("background_color") ==
              "#070605", f"the manifest names LTC Player in the pages' "
                         f"colours: {man}")
        for icon in man.get("icons") or [{}]:
            st, _h, _b = fetch(icon.get("src") or "/missing")
            check(st == 200, f"the manifest's icon {icon} is served: {st}")
        # Every HTML page the engine serves: the operator page on "/", the
        # rack screen and iPad remote on "/remote" (the Startup page and
        # the rest are views of it).
        for path in ("/", "/remote"):
            st, h, body = fetch(path)
            page = body.decode("utf-8", "replace")
            head = page.split("</head>")[0]
            check(st == 200 and "text/html" in (h.get("Content-Type") or ""),
                  f"{path} is a page: {st}")
            for tag in ('<link rel="icon" href="/favicon.ico"',
                        '<link rel="apple-touch-icon" '
                        'href="/apple-touch-icon.png"',
                        '<link rel="manifest" href="/manifest.webmanifest"'):
                check(tag in head, f"{path} names its icon in <head>: {tag}")
            for href in re.findall(r'<link rel="(?:icon|apple-touch-icon|'
                                   r'manifest)"[^>]*href="([^"]+)"', head):
                st, _h, b = fetch(href)
                check(st == 200 and b, f"{path} links {href}, which is "
                                       f"served: {st}")
            check(re.search(r"<title>[^<]+</title>", head),
                  f"{path} has a title")
        # Only the fixed list: no folder of files opened up.
        for path in ("/icons/favicon.ico", "/favicon.svg",
                     "/favicon.ico/x", "/icon-1024.png"):
            st, _h, _b = fetch(path)
            check(st == 404, f"GET {path} is not an icon: {st}")
    finally:
        httpd.shutdown()
        httpd.server_close()
        import shutil
        shutil.rmtree(folder, ignore_errors=True)
    # From the show network, signed out: the icons answer (an iPad adds the
    # home screen icon before anyone signs in); nothing else was opened.
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        for path, kind in want.items():
            st, h, _out = R.ask("GET", path)
            check(st == 200 and h.get("content-type") == [kind] and
                  int((h.get("content-length") or ["0"])[0]) > 0,
                  f"the iPad, signed out, gets {path}: {st} {h}")
        for path in ("/api/state", "/icons/favicon.ico", "/favicon.svg"):
            st, _h, _out = R.ask("GET", path)
            check(st in (403, 404), f"and not {path} from the network: {st}")
        check(all(web_mod.network_may_reach(p) for p in want) and
              not web_mod.network_may_reach("/favicon.ico/x") and
              not web_mod.network_may_reach("/api/stop"),
              "network_may_reach gained the icon addresses and nothing else")
    finally:
        R.close()
    print("  ok")


def test_remote_countdown_left_in_this_show():
    section("rack screen countdown (Jeff, 2026-10-07): during a running show "
            "the time left in THIS show from the engine's own show clock; "
            "held, it stays still; between shows the countdown to the next; "
            "a show of unknown length shows none")
    from ltcplay import remote as RM
    cv = RM.countdown_view
    run = {"attached": True, "state": "SHOW",
           "next": {"show": 2, "start": "19:00", "in_s": 3600}}
    c = cv(run, {"running": True}, {"duration": 440.0, "elapsed": 100.25})
    check(c == {"kind": "left", "label": "Left in this show", "s": 339.8,
                "running": True},
          f"running: length minus the show clock's place, not the next "
          f"show: {c}")
    c = cv(dict(run, state="PAUSED"), {"running": True},
           {"duration": 440.0, "elapsed": 100.25})
    check(c and c["kind"] == "left" and c["s"] == 339.8 and
          c["running"] is False,
          f"held: the same time left, marked not running so the page does "
          f"not age it: {c}")
    c = cv(dict(run, state="WAITING"), {"running": False}, None)
    check(c == {"kind": "next", "label": "Next show", "s": 3600,
                "running": True},
          f"between shows: the countdown to the next show: {c}")
    for now in (None, {}, {"duration": None, "elapsed": 3.0},
                {"duration": 0, "elapsed": 1.0},
                {"duration": float("nan"), "elapsed": 1.0},
                {"duration": True, "elapsed": 1.0},
                {"duration": 300.0}):
        check(cv(run, {"running": True}, now) is None,
              f"a show of unknown length shows no countdown at all, never "
              f"the next show's: {now}")
    c = cv(run, {"running": True}, {"duration": 300.0, "elapsed": 320.0})
    check(c["s"] == 0.0, "past its end: zero, never negative")
    # Soak 2026-10-21: the page counted down from whole seconds rounded
    # down, so its last digit flickered. The exact figure goes out when
    # the engine has one.
    c = cv(dict(run, state="WAITING",
                next={"show": 2, "start": "19:00", "in_s": 3599,
                      "in_s_exact": 3599.437}), {"running": False}, None)
    check(c == {"kind": "next", "label": "Next show", "s": 3599.437,
                "running": True},
          f"between shows: the exact time to the next show, not whole "
          f"seconds: {c}")
    S0 = _sched()
    if S0 is not None:
        n0 = _Night(S0, _one_night_rule(S0))
        n0.boot(_den(S0, 17, 0))
        v0 = S0.machine_view(n0.m, _den(S0, 17, 59, 57, 600000))
        check(v0["next"]["in_s"] == 2 and
              v0["next"]["in_s_exact"] == 2.4,
              f"the scheduler gives the next show to the millisecond as "
              f"well as in whole seconds: {v0['next']}")
    check(cv({"attached": True, "state": "WAITING", "next": None},
             {}, None) is None, "nothing next: nothing shown")
    c = cv({"attached": False}, {"running": True},
           {"duration": 60.0, "elapsed": 10.0})
    check(c and c["kind"] == "left" and c["s"] == 50.0,
          "with no scheduler, a playing show still shows its time left")
    # Through the real status route: the engine's own snapshot.
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        _live_show(R)
        real = R.httpd.control.state
        R.httpd.control.state = lambda: {"running": True, "show": "x",
                                         "now": {"duration": 444.0,
                                                 "elapsed": 44.0}}
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(st == 200 and out["countdown"] == {
            "kind": "left", "label": "Left in this show", "s": 400.0,
            "running": True}, f"the status carries it: {out.get('countdown')}")
        R.svc.operator_press("hold", "Jeff", "Rack screen")
        R.settle()
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["countdown"]["running"] is False and
              out["countdown"]["s"] == 400.0,
              f"held: frozen: {out['countdown']}")
        names = [x["name"] for x in out.get("subsystems", [])]
        check(names == ["Deck", "Flamesafe", "Audio", "Video", "Lasers",
                        "Pixels"] and all(x["state"] in
                                          ("ok", "warn", "bad", "off")
                                          for x in out["subsystems"]),
              f"the compact status strip names each subsystem: "
              f"{out.get('subsystems')}")
        check(out["subsystems"][0]["state"] == "off",
              "the deck has not asked yet: off")
        R.remote.deck_input("hw=1&arm_ms=10")
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["subsystems"][0]["state"] == "ok",
              "the deck asked, its USB deck here and its arm link fresh: ok")
        R.mono[0] += 5
        st, _h, out = R.ask("GET", "/api/remote/status")
        check(out["subsystems"][0]["state"] == "bad",
              "the deck quiet for 5 s: bad")
        R.httpd.control.state = real
    finally:
        R.close()
    print("  ok")


def test_remote_cross_site_posts_refused_on_loopback():
    section("iPad remote, fix round 1 F2: on the show machine itself, a "
            "press from a sandboxed or data: page (Origin null), from "
            "another site, or not sent as JSON is refused")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        state0 = R.svc.machine.state
        cases = [("Origin null", {"Origin": "null"}, None),
                 ("Origin NULL", {"Origin": "NULL"}, None),
                 ("another site", {"Origin": "http://evil.example"}, None),
                 ("Sec-Fetch-Site cross-site",
                  {"Sec-Fetch-Site": "cross-site"}, None),
                 ("Sec-Fetch-Site same-site",
                  {"Sec-Fetch-Site": "same-site"}, None),
                 ("text/plain", {"Content-Type": "text/plain"}, None),
                 ("form", {"Content-Type":
                           "application/x-www-form-urlencoded"}, None),
                 ("no content type", {"Content-Type": None}, None)]
        for path, body in (("/api/stop", {}),
                           ("/api/remote/network",
                            {"address": "198.51.100.7"}),
                           ("/api/remote/start-now",
                            {"confirmed": True, "seen": R.seen(),
                             "who": "Andy", "screen": "Rack screen"}),
                           ("/api/schedule/deck-event", {"text": "x"})):
            for label, hd, _x in cases:
                st, _h, out = _ask(R.httpd, "POST", path, body,
                                   client=loop, headers=hd)
                check(st == 403, f"{path} with {label} from loopback is "
                                 f"refused: {st} {out}")
        # With no sign-in (Jeff, 2026-10-07) these walls are what keep
        # another site's page off the controls from the show network too.
        for path, body in (("/api/remote/start-now",
                            {"confirmed": True, "seen": R.seen()}),
                           ("/api/remote/arm-hold",
                            {"group": 0, "seen": R.seen()}),
                           ("/api/remote/abort", {"confirmed": True})):
            for label, hd, _x in cases:
                st, _h, out = R.ask("POST", path, body, headers=hd)
                check(st == 403, f"{path} with {label} from the network is "
                                 f"refused: {st} {out}")
        check(not R.lines_for("abort") and not R.lines_for("arm hold"),
              "no Abort or arm hold reached the remote")
        from ltcplay import remote as RM
        check(RM.load_settings(R.work)["show_network_address"] is None,
              "no show network address was planted")
        check(R.svc.machine.state == state0, "nothing was started")
        # The page's own presses still work: same origin, JSON.
        port = R.httpd.server_address[1]
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/network",
                           {"address": "10.20.0.5"}, client=loop,
                           headers={"Origin": f"http://127.0.0.1:{port}",
                                    "Sec-Fetch-Site": "same-origin"})
        check(st == 200, f"a same-origin JSON press from the page is "
                         f"taken: {st} {out}")
        page = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "ltcplay", "web", "index.html"),
                    encoding="utf-8").read()
        check('headers:{"Content-Type":"application/json"}' in page,
              "the operator page sends its presses as JSON")
    finally:
        R.close()
    print("  ok")


def test_remote_localhost_unaffected_and_proxies_refused():
    section("iPad remote: the machine itself is the Rack screen; "
            "anything that looks proxied, misaddressed or cross-site is "
            "refused, loopback included")
    S = _sched()
    if S is None:
        return
    import urllib.request
    import urllib.error
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 5000)
    try:
        st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop)
        check(st == 200, f"loopback reads the state with no session: {st}")
        st, _h, out = _ask(R.httpd, "GET", "/", client=loop)
        check(st == 200 and "<title>Show remote</title>" not in str(out),
              "loopback still gets the operator page at /")
        st, _h, out = _ask(R.httpd, "GET", "/remote", client=loop)
        check(st == 200 and "<title>Show remote</title>" in str(out),
              "and the remote page at /remote")
        st, _h, out = _ask(R.httpd, "GET", "/api/remote/whoami", client=loop)
        check(out["local"] is True and out["device"] == "Rack screen",
              f"whoami says it is the machine itself: {out}")
        # The real thing, over a real loopback socket.
        import threading
        from ltcplay import web as web_mod
        h2 = web_mod.serve(R.folder, port=0, bind="127.0.0.1")
        t = threading.Thread(target=h2.serve_forever,
                             kwargs={"poll_interval": 0.05}, daemon=True)
        t.start()
        try:
            base = f"http://127.0.0.1:{h2.server_address[1]}"
            with urllib.request.urlopen(base + "/api/state", timeout=5) as r:
                check(r.status == 200, "a real loopback request needs no PIN")
            req = urllib.request.Request(base + "/api/state", headers={
                "X-Forwarded-For": "203.0.113.9"})
            try:
                urllib.request.urlopen(req, timeout=5)
                check(False, "a forwarded request from loopback was let in")
            except urllib.error.HTTPError as e:
                check(e.code == 403, f"forwarded is refused: {e.code}")
        finally:
            h2.shutdown()
            h2.server_close()
        for hname, val in (("X-Forwarded-For", "203.0.113.9"),
                           ("Forwarded", "for=203.0.113.9"),
                           ("Via", "1.1 tunnel"),
                           ("X-Real-IP", "203.0.113.9"),
                           ("CF-Connecting-IP", "203.0.113.9")):
            st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop,
                               headers={hname: val})
            check(st == 403 and "proxy" in out["error"],
                  f"{hname} from loopback is refused: {st}")
        st, _h, _o = R.ask("GET", "/api/state",
                           headers={"X-Forwarded-For": "10.0.0.1"})
        check(st == 403, "and from a device on the network too")
        st, _h, _o = R.ask("GET", "/api/state", host="evil.example:7878")
        check(st == 403, f"a Host that is not this server is refused: {st}")
        st, _h, _o = _ask(R.httpd, "GET", "/api/state", client=loop,
                          host="evil.example")
        check(st == 403, "on loopback too (DNS rebinding)")
        st, _h, _o = R.ask("POST", "/api/remote/hold",
                           {"seen": R.seen()},
                           headers={"Origin": "http://evil.example"})
        check(st == 403, f"a press posted from another site is refused: {st}")
        check(not R.lines_for("HOLD"), "and nothing was held")
    finally:
        R.close()
    print("  ok")


def test_live_show_refuses_the_page_transport():
    section("a live scheduled show refuses the page's transport and output "
            "routes (GO, Skip, Stop, Start, looks, reload...) on every door, "
            "loopback included; Hold, Resume and Abort still work (PR #43 "
            "review, item 2)")
    S = _sched()
    if S is None:
        return
    from ltcplay import web as web_mod
    R = _RemoteRig(S)
    loop = ("127.0.0.1", 50000)
    try:
        st, _h, out = _ask(R.httpd, "POST", "/api/go", {}, client=loop)
        check(st != 409, f"no show live: GO is not refused for it: {st}")
        _live_show(R)
        for route in web_mod.LIVE_SHOW_REFUSED:
            st, _h, out = _ask(R.httpd, "POST", route, {}, client=loop)
            check(st == 409 and "show is live" in str(out),
                  f"live show: {route} from the machine's own page is "
                  f"refused: {st} {out}")
        # By name, not only by iterating the list (the second review's
        # R2-H1 to H4 dropped routes from the list itself).
        for route, body in (("/api/go", {}), ("/api/skip", {}),
                            ("/api/override", {"look": "blackout"}),
                            ("/api/override", {"look": "preshow"}),
                            ("/api/stop", {}),
                            ("/api/start", {"timeline": "x.json"}),
                            ("/api/showdir", {}), ("/api/reinput", {}),
                            ("/api/reload", {}), ("/api/release", {})):
            st, _h, out = _ask(R.httpd, "POST", route, body, client=loop)
            check(st == 409 and "show is live" in str(out),
                  f"live show: {route} {body} refused, by name: {st}")
        st, _h, out = R.ask("POST", "/api/go", {})
        # Since #39's fix round (F1) the network never reaches these routes
        # at all (403); either way an iPad's GO is refused.
        check(st in (403, 409), f"and from an iPad: {st} {out}")
        st, _h, out = _ask(R.httpd, "GET", "/api/state", client=loop)
        check(st == 200, f"reading the state still works: {st}")
        R.svc.operator_press("hold", "Jeff", "Rack screen")
        R.settle()
        check(R.svc.machine.state == S.PAUSED, "Hold still works")
        st, _h, out = _ask(R.httpd, "POST", "/api/skip", {}, client=loop)
        check(st == 409, f"held (PAUSED) is still live: Skip refused: {st}")
        R.svc.operator_press("resume", "Jeff", "Rack screen")
        R.settle()
        check(R.svc.machine.state == S.SHOW, "Resume still works")
        R.svc.operator_press("abort", "Jeff", "Rack screen", confirmed=True)
        R.settle()
        check(R.svc.machine.state not in (S.SHOW, S.PAUSED),
              f"Abort still works: {R.svc.machine.state}")
        # Aborted, not yet Reset (fix round 2, E): nothing on the page may
        # bring the rig back up; Stop and Blackout still work.
        for route, body in (("/api/go", {}),
                            ("/api/override", {"look": None}),
                            ("/api/override", {"look": "preshow"}),
                            ("/api/release", {}),
                            ("/api/start", {"timeline": "x.json"})):
            st, _h, out = _ask(R.httpd, "POST", route, body, client=loop)
            check(st == 409 and "aborted" in str(out),
                  f"aborted, not Reset: {route} {body} refused: {st} {out}")
        for route, body in (("/api/override", {"look": "blackout"}),
                            ("/api/stop", {})):
            st, _h, out = _ask(R.httpd, "POST", route, body, client=loop)
            check(st != 409, f"aborted: {route} {body} still works: {st}")
        r = R.svc.reset_conductor("Jeff", "Rack screen")
        R.settle()
        check(r.get("ok"), f"setup: Reset: {r}")
        st, _h, out = _ask(R.httpd, "POST", "/api/go", {}, client=loop)
        check(st != 409, f"after Reset GO is not refused for it: {st} {out}")
    finally:
        R.close()
    print("  ok")


def test_deck_presses_reach_the_engine_conductor():
    section("Stream Deck: Abort, Hold, Resume and Reset reach the engine's "
            "show conductor over loopback, off the deck's main loop, and the "
            "deck reads latched from its own Abort at once (PR #43 review, "
            "item 8)")
    import threading
    from ltcplay import streamdeck as sd
    # The class on its own: fakes for the engine.
    t = [100.0]
    posted, lines = [], []
    answer = {"v": (True, "Abort done.")}
    got_one = threading.Event()

    def poster(path, body):
        posted.append((path, dict(body)))
        got_one.set()
        return answer["v"]
    engine_view = {"v": None}
    e = sd.EngineConductor("http://127.0.0.1:1", journal=lambda x, **k:
                           lines.append((x, k)), poster=poster,
                           fetcher=lambda path: engine_view["v"],
                           clock=lambda: t[0], wall=lambda: 1_800_000_000.0,
                           poll_hz=200.0)
    e.start()
    try:
        check(e.snapshot() == {"latched": False, "look": ""},
              "nothing known: not latched")
        r = e.abort("Andy", "Stream Deck")
        check(r.ok and e.snapshot()["latched"],
              "the deck reads latched from its own Abort at once, before "
              "the engine has answered")
        check(got_one.wait(3) and posted[0][0] == "/api/remote/abort" and
              posted[0][1]["confirmed"] is True and
              posted[0][1]["screen"] == "Stream Deck" and
              posted[0][1]["who"] == "Andy",
              f"the Abort is the engine's own confirmed remote Abort: "
              f"{posted}")
        # The engine's answer, older than the press, does not undo it.
        engine_view["v"] = {"conductor": {"latched": False,
                                          "look": "PLAYING"}}
        time.sleep(0.1)
        check(e.snapshot()["latched"],
              "an engine answer from before the press does not undo it")
        t[0] += 1.0
        time.sleep(0.1)
        check(e.snapshot() == {"latched": False, "look": "PLAYING"},
              f"a newer engine answer is what the deck reads: "
              f"{e.snapshot()}")
        engine_view["v"] = None
        got_one.clear()
        answer["v"] = (False, "nothing is playing")
        e.hold("Andy", "Stream Deck")
        check(got_one.wait(3), "Hold posted")
        for _ in range(100):
            if any("did NOT take it" in x for x, _k in lines):
                break
            time.sleep(0.02)
        check(any("did NOT take it" in x and k.get("fault")
                  for x, k in lines),
              f"an engine refusal is journaled as a fault: {lines}")
        check(posted[-1][0] == "/api/remote/hold" and
              "seen" in posted[-1][1], "Hold carries the page's freshness")
        # Unreachable engine: the deck's own presses alone.
        e.reset("Andy", "Stream Deck")
        t[0] += 1.0
        time.sleep(0.05)
        check(e.snapshot()["latched"] is False,
              "with the engine unreachable, Reset alone clears the deck")
        # A slow engine never holds up the press.
        slow = threading.Event()
        e._poster = lambda path, body: (slow.wait(3), (True, "ok"))[1]
        t0 = time.perf_counter()
        e.abort("Andy", "Stream Deck")
        check(time.perf_counter() - t0 < 0.05,
              "a press returns at once, whatever the engine is doing")
        slow.set()
    finally:
        e.stop()

    # End to end: a real engine web server with a scheduler and conductor.
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    R.httpd.conductor = R.c          # as web.serve sets it for Fire & Ice
    th = threading.Thread(target=R.httpd.serve_forever,
                          kwargs={"poll_interval": 0.05}, daemon=True)
    th.start()
    port = R.httpd.server_address[1]
    lines = []
    eng = sd.EngineConductor(f"http://127.0.0.1:{port}",
                             journal=lambda x, **k: lines.append((x, k)),
                             wall=lambda: R.wall[0], poll_hz=50.0)
    eng.start()

    def wait_for(pred, what):
        for _ in range(200):
            R.settle()
            if pred():
                return True
            time.sleep(0.02)
        check(False, f"timed out waiting for {what}: {lines[-3:]}")
        return False
    try:
        _live_show(R)
        eng.hold("Jeff", "Stream Deck")
        if wait_for(lambda: R.svc.machine.state == S.PAUSED, "Hold"):
            check(any(r.get("screen") == "Stream Deck" and
                      r.get("who") == "Jeff" for r in R.svc.journal),
                  "the deck's Hold is the scheduler's own, journaled with "
                  "who and the Stream Deck")
        wait_for(lambda: eng.snapshot()["look"] in ("HELD", "DARK"),
                 "the deck to read the hold")
        eng.resume("Jeff", "Stream Deck")
        wait_for(lambda: R.svc.machine.state == S.SHOW, "Resume")
        # No operator chosen: an Abort is never refused (PR #43 fix round
        # 1, for Jeff: the safe default is that Abort always works).
        del R.rig.calls[:]
        eng.abort("", "Stream Deck")
        wait_for(lambda: R.c.latched and R.svc.machine.abort_latched,
                 "the deck's Abort with no operator chosen to latch the "
                 "engine's conductor")
        R.c.run_pending()
        names = R.rig.names()
        check(all(x in names for x in ("flames_disarm_all", "lasers_blank",
                                       "video_fade_out", "music_halt")),
              f"a deck Abort with no operator chosen reaches the conductor: "
              f"flames disarmed, lasers blanked, video and music down: "
              f"{names}")
        check(any("Abort pressed on the Stream Deck with no operator "
                  "chosen" in str(r.get("text")) for r in R.svc.journal),
              "journaled as an Abort with no operator chosen")
        wait_for(lambda: eng.snapshot()["latched"],
                 "the deck to read the engine latched")
        check(any("lasers" in str(c) for c in R.rig.calls),
              "the deck's Abort reached the rig through the conductor")
        eng.reset("Jeff", "Stream Deck")
        wait_for(lambda: not R.c.latched and
                 not R.svc.machine.abort_latched, "the deck's Reset")
        check(not any(k.get("fault") for _x, k in lines),
              f"no press was refused: {[x for x, k in lines if k.get('fault')]}")
    finally:
        eng.stop()
        R.httpd.shutdown()
        R.close()
    print("  ok")


def test_api_conductor_reports_audio_loss():
    section("/api/conductor carries a read-only \"audio\" field: the show "
            "audio is lost while a cue is playing and the show clock has "
            "stopped following it (AudioMaster's freerun after a loss); "
            "never between cues; the deck's EngineConductor reads it and "
            "forgets it the moment the engine stops answering")
    import tempfile
    from ltcplay import web as web_mod
    from ltcplay import streamdeck as sd

    class _Cond:
        def snapshot(self):
            return {"look": "PLAYING", "latched": False}

    class _Clk:
        playing = True
        _mode = "follow"
        _fault = None

    class _FI:
        clk = _Clk()

        def clock_nolock(self):
            return self.clk
    httpd = web_mod.serve(tempfile.mkdtemp(), port=0, bind="127.0.0.1")
    try:
        httpd.conductor = _Cond()
        fi = _FI()
        httpd.fire_ice = fi

        def audio():
            st, _h, out = _ask(httpd, "GET", "/api/conductor",
                               client=("127.0.0.1", 50000))
            check(st == 200 and out.get("conductor", {}).get("look") ==
                  "PLAYING", f"/api/conductor answers: {st} {out}")
            return out.get("audio")
        check(audio() == {"playing": True, "lost": False, "fault": None},
              f"a cue playing with the clock following it: not lost: "
              f"{audio()}")
        fi.clk._mode = "freerun"
        fi.clk._fault = ("The show audio stopped playing at 00:01:02.000 "
                         "of 00:07:20.000 with nothing asking it to.")
        check(audio() == {"playing": True, "lost": True,
                          "fault": fi.clk._fault},
              f"the clock freerunning after a loss, a cue still playing: "
              f"lost, with the clock's own sentence: {audio()}")
        fi.clk._mode = "follow"
        fi.clk._fault = None
        check(audio()["lost"] is False, "the audio back: not lost")
        fi.clk._mode = "freerun"
        fi.clk.playing = False
        check(audio() == {"playing": False, "lost": False, "fault": None},
              f"the cue over: nothing is lost between cues: {audio()}")
        fi.clk = None
        check(audio() == {"playing": False, "lost": False, "fault": None},
              f"no show audio clock (Run not pressed): not lost: {audio()}")
        del httpd.fire_ice
        check(audio() == {"playing": False, "lost": False, "fault": None},
              f"no Fire & Ice wiring at all: the field is still there, not "
              f"lost: {audio()}")
    finally:
        httpd.server_close()

    # The deck's own reader of that field.
    t = [100.0]
    view = {"v": {"conductor": {"look": "PLAYING", "latched": False},
                  "audio": {"playing": True, "lost": True, "fault": "x"}}}
    e = sd.EngineConductor("http://127.0.0.1:1", fetcher=lambda p: view["v"],
                           clock=lambda: t[0], poll_hz=200.0)
    check(e.audio_lost() is False, "before any answer: not lost")
    e.start()
    try:
        for _ in range(100):
            if e.audio_lost():
                break
            time.sleep(0.01)
        check(e.audio_lost() is True and
              e.snapshot() == {"latched": False, "look": "PLAYING"},
              f"the engine says lost: the deck reads it, and its snapshot "
              f"is unchanged: {e.snapshot()}")
        view["v"] = {"conductor": {"look": "PLAYING", "latched": False},
                     "audio": {"playing": True, "lost": False,
                               "fault": None}}
        for _ in range(100):
            if not e.audio_lost():
                break
            time.sleep(0.01)
        check(e.audio_lost() is False, "the audio back: not lost")
        view["v"] = {"conductor": {"look": "PLAYING", "latched": False},
                     "audio": {"playing": True, "lost": True, "fault": "x"}}
        for _ in range(100):
            if e.audio_lost():
                break
            time.sleep(0.01)
        view["v"] = None
        for _ in range(100):
            if not e.audio_lost():
                break
            time.sleep(0.01)
        check(e.audio_lost() is False,
              "the engine gone quiet: the loss is not remembered (the deck "
              "shows ENGINE FAULT instead)")
        view["v"] = {"conductor": {"look": "PLAYING", "latched": False}}
        time.sleep(0.05)
        check(e.audio_lost() is False,
              "an older engine without the field: never lost")
    finally:
        e.stop()
    print("  ok")


def test_deck_fix_round_2_abort_reset_and_disarm():
    section("Stream Deck (PR #43 fix round 2, C to E, without the deck's "
            "own Abort key since 2026-10-26): while aborted from a screen "
            "a group key still disarms and nothing arms; the engine "
            "conductor's Abort never waits behind another press; an engine "
            "that did not take a press shows on the deck")
    import threading
    from ltcplay import streamdeck as sd
    names = ["front row", "cat-walk", "wave flamer"]
    arm = _FakeArmSocket(3)
    t = [100.0]
    events = []
    cond = _FakeConductor()
    c = sd.Controller(arm, _FakeStatusSocket(), names,
                      operator_provider=lambda: "Andy",
                      show_running_provider=lambda: True, conductor=cond,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0])
    # An Abort from a screen: the deck reads latched.
    cond._latched = True
    arm.set_group(2, True)
    down = [False] * 6
    down[sd.GROUP_KEYS[2]] = True
    c.run_once(down)
    c.run_once([False] * 6)
    check(arm.wanted[2] is False,
          "while aborted, a group key still drops that group's arm request "
          "(disarm is never behind any gate)")
    down = [False] * 6
    down[sd.GROUP_KEYS[0]] = True
    c.run_once(down)
    t[0] += sd.ARM_HOLD_S + 0.5
    c.tick()
    c.run_once([False] * 6)
    check(arm.wanted == [False, False, False],
          "and nothing can be armed while aborted")
    check(not any(x[0] in ("reset", "abort", "hold", "resume")
                  for x in cond.calls),
          f"the deck never Aborts, Resets, Holds or Resumes: {cond.calls}")

    # D: a deck Abort never waits behind a slow press.
    started = {}
    hold_gate = threading.Event()

    def poster(path, body):
        started[path] = time.perf_counter()
        if path.endswith("/hold"):
            hold_gate.wait(3)
        return True, "ok"
    e = sd.EngineConductor("http://127.0.0.1:1", poster=poster,
                           fetcher=lambda path: None, poll_hz=50.0)
    e.start()
    try:
        e.hold("Andy")
        deadline = time.time() + 2
        while "/api/remote/hold" not in started and time.time() < deadline:
            time.sleep(0.01)
        t0 = time.perf_counter()
        e.abort("Andy")
        deadline = time.time() + 2
        while "/api/remote/abort" not in started and time.time() < deadline:
            time.sleep(0.01)
        lag = started.get("/api/remote/abort", t0 + 99.0) - t0
        check(lag < 0.5, f"the Abort went to the engine at once while a Hold "
                         f"was still waiting on it: {lag:.3f} s")
        hold_gate.set()
    finally:
        e.stop()

    # E: an engine that did not take a press shows on the deck.
    clock = [0.0]
    e2 = sd.EngineConductor("http://127.0.0.1:1",
                            poster=lambda path, body: (False, "unreachable"),
                            fetcher=lambda path: None, poll_hz=50.0,
                            clock=lambda: clock[0])
    e2.start()
    try:
        e2.abort("Andy")
        deadline = time.time() + 2
        while not e2.fault and time.time() < deadline:
            time.sleep(0.01)
        check("unreachable" in e2.fault,
              f"the failed Abort is the deck's engine fault: {e2.fault!r}")
        clock[0] = 3.0
        check(e2.unreachable(), "an engine that never answers reads "
                                "unreachable after 2 s")
    finally:
        e2.stop()
    if _pillow_missing("the deck's ENGINE FAULT key"):
        print("  ok")
        return
    fonts = sd.Fonts()
    fonts.text_block = lambda *a, **kw: None
    c2 = sd.Controller(_FakeArmSocket(3), _FakeStatusSocket(), names,
                       operator_provider=lambda: "Andy",
                       show_running_provider=lambda: True, conductor=e2,
                       clock=lambda: t[0])
    canvas = c2.draw(fonts, blink_on=True, chase=0)
    box = sd.face_box(sd.TOP_START)
    px = {canvas.getpixel((x, y)) for x in range(box[0], box[2], 3)
          for y in range(box[1], box[3], 3)}
    check(sd.RED in px, f"the deck shows ENGINE FAULT on its Start key: "
                        f"{sorted(px)[:4]}")
    print("  ok")


def test_remote_controls_reach_the_same_paths_and_journal_who_and_where():
    section("iPad remote: Start now, Hold, Resume, Abort, Reset and disarm "
            "go through the scheduler and conductor paths every other press "
            "uses, journaled with the surface they came from (no sign-in, "
            "Jeff 2026-10-07)")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        ME = "iPad at 10.20.0.44"
        _live_show(R)
        n0 = len(R.svc.journal)
        st, _h, out = R.ask("POST", "/api/remote/hold",
                            {"who": "Jeff", "screen": "Rack screen"})
        R.settle()
        check(st == 200 and R.svc.machine.state == S.PAUSED and
              R.c.snapshot()["look"] == "HELD",
              f"Hold reached the scheduler and the conductor: {st} {out} "
              f"{R.c.snapshot()}")
        rows = [r for r in list(R.svc.journal)[n0:]
                if r.get("action") == S.HOLD_ON]
        check(rows and rows[-1]["who"] == ME and
              rows[-1]["screen"] == "iPad" and
              "pressed Hold on the iPad" in rows[-1]["text"] and
              "Jeff" not in rows[-1]["text"],
              f"journaled as the iPad at its address, never as the body's "
              f"Jeff: {rows[-1:]}")
        st, _h, out = R.ask("POST", "/api/remote/resume", {"seen": R.seen()})
        R.settle()
        check(st == 200 and R.svc.machine.state == S.SHOW and
              R.c.snapshot()["look"] == "PLAYING",
              f"Resume: {st} {out} {R.c.snapshot()}")
        check(any(r.get("action") == S.RESUME and r["who"] == ME and
                  r["screen"] == "iPad" for r in R.svc.journal),
              "Resume journaled with who and where")
        # The same press straight into the engine reads the same.
        before = R.rig.count("flames_disarm_all")
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        # Twice: the route's own disarm first (P0-1), then the conductor's.
        check(st == 200 and R.svc.machine.abort_latched and
              R.c.snapshot()["look"] == "ABORTED" and
              R.rig.count("flames_disarm_all") == before + 2,
              f"Abort latched the scheduler and the conductor disarmed "
              f"every group: {st} {out} {R.c.snapshot()}")
        check(any(r.get("action") == S.ABORT and r["who"] == ME and
                  r["screen"] == "iPad" for r in R.svc.journal),
              "Abort journaled with who and where")
        st, _h, out = R.ask("POST", "/api/remote/reset", {"seen": R.seen()})
        R.settle()
        check(st == 200 and out["ok"] and not R.svc.machine.abort_latched
              and not R.c.latched,
              f"Reset is the scheduler's reset_conductor: {st} {out}")
        # Disarm every flame group: the show's own flames_disarm_all.
        n = R.rig.count("flames_disarm_all")
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {})
        check(st == 200 and R.rig.count("flames_disarm_all") == n + 1,
              f"disarm-all is the conductor's own flames_disarm_all: {st} "
              f"{out}")
        reason = R.rig.calls[-1][1][0]
        check(ME in reason, f"the reason sent to flamesafe names the "
                            f"surface: {reason}")
        check(any(r.get("action") == "disarm all" and r["who"] == ME and
                  r["screen"] == "iPad" for r in R.svc.journal),
              "disarm-all journaled with who and where")
        # Disarm is never gated on a fresh page or a show.
        st, _h, out = R.ask("POST", "/api/remote/disarm-all",
                            {"seen": 1})
        check(st == 200, f"disarm with a stale page still goes: {st}")
        # Start now: the scheduler's START_NOW.
        R.now[0] = _den(S, 18, 30)
        R.svc.tick()
        R.settle()
        st, _h, out = R.ask("POST", "/api/remote/start-now",
                            {"confirmed": True, "seen": R.seen()})
        check(st in (200, 409), f"Start now answered: {st} {out}")
        check(any(r.get("action") == S.START_NOW and r["who"] == ME and
                  r["screen"] == "iPad" for r in R.svc.journal),
              "Start now journaled with who and where")
        # No operator picker any more: the route is gone.
        st, _h, out = R.ask("POST", "/api/remote/operator",
                            {"pick": "Jeff", "seen": R.seen()})
        check(st == 404, f"no operator route: {st} {out}")
        # On the machine itself the page sends no name: the press is the
        # Rack screen's, a surface press (no operator-list lookup).
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/hold", {},
                           client=("127.0.0.1", 5000))
        R.settle()
        rows = [r for r in R.svc.journal if r.get("action") == S.HOLD_ON]
        check(rows and rows[-1]["who"] == "Rack screen" and
              rows[-1]["screen"] == "Rack screen",
              f"journaled as the Rack screen: {rows[-1:]}")
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/resume",
                           {"seen": R.seen()}, client=("127.0.0.1", 5000))
        R.settle()
        check(st == 200 and R.svc.machine.state == S.SHOW,
              f"the Rack screen's Resume needs no operator name: {st} {out}")
        # The Stream Deck process on this machine names its operator, and
        # that name is still checked against the list, as before.
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/hold",
                           {"who": "Jeff", "screen": "Stream Deck"},
                           client=("127.0.0.1", 5000))
        R.settle()
        state0 = R.svc.machine.state
        st, _h, out = _ask(R.httpd, "POST", "/api/remote/resume",
                           {"who": "Mallory", "screen": "Stream Deck",
                            "seen": R.seen()}, client=("127.0.0.1", 5000))
        R.settle()
        check(st == 400 and "not on the operator list" in out["error"] and
              R.svc.machine.state == state0,
              f"a named press from someone off the list is refused: {st} "
              f"{out}")
        # The scheduler's own list check still holds for everything that
        # is not the remote page (the deck, the engine's own callers).
        state0 = R.svc.machine.state
        try:
            R.svc.operator_press("resume", "Mallory", "Rack screen")
            check(False, "an off-list name was taken without surface=True")
        except ValueError as e:
            check("not on the operator list" in str(e),
                  f"off the list, not a surface: refused: {e}")
        check(R.svc.machine.state == state0, "and nothing changed")
        try:
            R.svc.operator_press("resume", "Rack screen", "Nowhere",
                                 surface=True)
            check(False, "a surface press from an unlisted screen was taken")
        except ValueError as e:
            check("not on the screen list" in str(e),
                  f"a surface press still names a listed screen: {e}")
        # No disarm path connected: refused loudly, never "done".
        R.remote._flame_disarm = None
        cond = R.svc.conductor
        R.svc.conductor = None
        try:
            st, _h, out = R.ask("POST", "/api/remote/disarm-all", {})
            check(st == 409 and "no flame link" in out["error"],
                  f"no flame link is said, not faked: {st} {out}")
            check(any(r.get("action") == "disarm all" and
                      r.get("outcome") == "fault" for r in R.svc.journal),
                  "and journaled as a fault")
        finally:
            R.svc.conductor = cond
    finally:
        R.close()
    print("  ok")


def test_remote_abort_disarms_with_no_show_live():
    section("iPad remote: the screen Abort disarms every flame group first, "
            "every time, with no scheduled show live too, and says what it "
            "did (review of PR #43, P0-1)")
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        sent = []
        R.remote._flame_disarm = lambda reason: (
            sent.append(reason) or _Result(True, "a disarm was sent to "
                                                 "every flame group."))
        # Before the first show: the scheduler is not in SHOW or PAUSED.
        check(R.svc.machine.state not in (S.SHOW, S.PAUSED),
              f"setup: no show live ({R.svc.machine.state})")
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        check(len(sent) == 1 and "Abort" in sent[0],
              f"the Abort sent the flame link's disarm_all with no show "
              f"live: {sent} {st} {out}")
        check(st == 200 and out.get("ok") is True and
              out.get("disarmed") is True and out.get("stopped") is False,
              f"answered as done, with the disarm sent and no show stopped: "
              f"{st} {out}")
        check("Every flame group" in out.get("text", "") and
              "No show was stopped" in out.get("text", ""),
              f"the answer says both halves truthfully: {out}")
        check(not R.svc.machine.abort_latched and not R.c.latched,
              "nothing is latched by an Abort with no show live")
        rows = R.lines_for("abort disarm")
        check(rows and rows[-1]["who"] == "iPad at 10.20.0.44" and
              rows[-1].get("outcome") == "done",
              f"the disarm is journaled with the surface: {rows[-1:]}")
        # The disarm fails: a fault, said, never "done".
        R.remote._flame_disarm = lambda reason: _Result(False, "the socket "
                                                        "is closed")
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        check(st == 409 and out.get("ok") is False and
              "did NOT go out" in out.get("error", ""),
              f"a disarm that did not go out is a fault: {st} {out}")
        # With a show live, the disarm still goes first, before the
        # scheduler or the conductor is asked anything.
        order = []
        R.remote._flame_disarm = lambda reason: (
            order.append(("route", R.svc.machine.state)) or
            _Result(True, "sent."))
        _live_show(R)
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        check(order and order[0] == ("route", S.SHOW) and st == 200 and
              out.get("stopped") is True and R.svc.machine.abort_latched,
              f"with a show live the route's disarm goes first and the show "
              f"is stopped: {order} {st} {out}")
        page = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "ltcplay", "web", "remote.html"),
                    encoding="utf-8").read()
        check("No show is live, so nothing else changes" in page and
              "abortPlan(ST)" in page,
              "the Abort sign's first tap says what an Abort with no show "
              "does, from the engine's state (abortPlan)")
    finally:
        R.close()
    print("  ok")


def test_deck_reads_reset_after_an_engine_restart():
    section("Stream Deck: after an Abort and an engine restart the "
            "scheduler's saved Abort latch is on /api/conductor, so the "
            "deck's Abort key still reads RESET until Reset (review of PR "
            "#43, P1-5)")
    S = _sched()
    if S is None:
        return
    from ltcplay import streamdeck as sd
    R = _RemoteRig(S)
    try:
        R.httpd.conductor = R.c
        _live_show(R)
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        check(R.svc.machine.abort_latched and R.c.latched,
              "setup: aborted and latched")
        # The engine restarts: a new conductor (unlatched) and a scheduler
        # read back from tonight's file.
        R.svc.stop()
        c2, rig2, _T2, _l2 = _cond()
        svc2 = _svc(S, R.work, R.now, conductor=c2)
        svc2.tick()
        check(svc2.machine.abort_latched and not c2.latched,
              "setup: the scheduler kept its latch across the restart, the "
              "new conductor did not")
        R.httpd.schedule = svc2
        R.httpd.conductor = c2

        def fetch(path):
            st, _h, out = _ask(R.httpd, "GET", path,
                               client=("127.0.0.1", 5000))
            return out if st == 200 else None
        got = fetch("/api/conductor")
        check(got and got["conductor"]["latched"] is True and
              got["conductor"]["scheduler_abort_latched"] is True,
              f"/api/conductor says latched after the restart: "
              f"{got and got['conductor']}")
        e = sd.EngineConductor("http://127.0.0.1:1",
                               poster=lambda p, b: (True, "ok"),
                               fetcher=fetch, poll_hz=50.0)
        e.start()
        try:
            deadline = time.time() + 2
            while e._engine is None and time.time() < deadline:
                time.sleep(0.01)
            ctl = sd.Controller(_FakeArmSocket(3), _FakeStatusSocket(),
                                ["front row", "cat-walk", "wave flamer"],
                                operator_provider=lambda: "Andy",
                                show_running_provider=lambda: False,
                                conductor=e)
            check(e.snapshot()["latched"] is True and ctl._latched_now(),
                  f"the deck reads latched, so its Abort key reads RESET: "
                  f"{e.snapshot()}")
            r = svc2.reset_conductor("Andy", "Stream Deck")
            svc2.flush_conductor(5)
            c2.run_pending()
            got = fetch("/api/conductor")
            check(not svc2.machine.abort_latched and
                  got["conductor"]["latched"] is False,
                  f"after Reset it is not: {r} {got['conductor']}")
        finally:
            e.stop()
        svc2.stop()
    finally:
        R.close()
    print("  ok")


def test_deck_requests_share_one_no_proxy_opener():
    section("Stream Deck: the screen holds, the operator lookup and the "
            "journal reach the engine through the one opener with no "
            "proxies, never a fresh urlopen per request (on macOS that "
            "looked up the system proxy every time, and the deck's screen "
            "poll fell behind the engine's 0.3 s freshness)")
    from ltcplay import streamdeck as sd
    seen = []

    class Opener:
        def open(self, req, timeout=None):
            seen.append(getattr(req, "full_url", req))
            raise OSError("not reachable in this test")
    saved = list(sd._OPENER)
    sd._OPENER[:] = [Opener()]
    try:
        sd.ScreenKeys("http://127.0.0.1:9")._http_fetch(
            "/api/remote/deck-input")
        sd.LocalSchedule("http://127.0.0.1:9")._http_fetch("/api/state")
        sd.DeckJournal("http://127.0.0.1:9")._post("a line", {})
    finally:
        sd._OPENER[:] = saved
    check(len(seen) == 3 and any("deck-input" in str(u) for u in seen),
          f"all three went through the shared opener: {seen}")
    print("  ok")


def test_deck_abort_with_no_show_reads_what_the_engine_did():
    section("Stream Deck: an Abort the engine answered with every group "
            "disarmed and no show stopped leaves the Abort key reading "
            "ABORT, not RESET, and journals what the engine said (review "
            "of PR #43, P0-1)")
    from ltcplay import streamdeck as sd
    lines = []
    said = ("Every flame group: a disarm was sent. No show was stopped: No "
            "show is running; the scheduler is in STANDBY.")
    clock = [10.0]
    e = sd.EngineConductor(
        "http://127.0.0.1:1", journal=lambda x, **k: lines.append((x, k)),
        poster=lambda path, body: (True, said, {"ok": True, "text": said,
                                                "disarmed": True,
                                                "stopped": False}),
        fetcher=lambda path: None, poll_hz=50.0, clock=lambda: clock[0])
    e.start()
    try:
        e.abort("Andy")
        deadline = time.time() + 2
        while not lines and time.time() < deadline:
            time.sleep(0.01)
        clock[0] += 0.1
        check(e.snapshot()["latched"] is False,
              f"once the engine says no show was stopped, the deck is not "
              f"latched: {e.snapshot()}")
        check(lines and said in lines[-1][0] and
              not lines[-1][1].get("fault") and e.fault == "",
              f"the engine's own words are journaled, not as a fault: "
              f"{lines[-1:]}")
    finally:
        e.stop()
    # A show the engine did stop: latched, as before.
    lines2 = []
    e2 = sd.EngineConductor(
        "http://127.0.0.1:1", journal=lambda x, **k: lines2.append(x),
        poster=lambda path, body: (True, "stopped", {"stopped": True}),
        fetcher=lambda path: None, poll_hz=50.0)
    e2.start()
    try:
        e2.abort("Andy")
        deadline = time.time() + 2
        while not lines2 and time.time() < deadline:
            time.sleep(0.01)
        check(e2.snapshot()["latched"] is True,
              "an Abort that stopped a show keeps the deck latched")
    finally:
        e2.stop()
    print("  ok")


def test_remote_reset_and_abort_1_ms_apart_under_a_slow_save():
    section("iPad remote: a Reset and an Abort pressed 1 ms apart, with "
            "the tonight.json save slow, keep their press order: a Reset "
            "pressed before the Abort never ends it, whichever reaches the "
            "scheduler first (review of #48)")
    S = _sched()
    if S is None:
        return
    from ltcplay import schedule_service as SV
    real_save = SV.write_json_atomic

    def slow_save(path, doc, **kw):
        time.sleep(0.3)
        return real_save(path, doc, **kw)
    for first in ("reset", "abort"):
        R = _RemoteRig(S)
        real_reset = R.svc.reset_conductor
        try:
            _live_show(R)
            SV.write_json_atomic = slow_save
            if first == "reset":
                # The Reset arrives first, then is slow on its way in, so
                # the Abort pressed 1 ms after it reaches the scheduler
                # first.
                def late_reset(*a, **k):
                    # Held up on its way in until the Abort (pressed 1 ms
                    # after it) is decided and done fading, so the
                    # conductor would take the Reset if it were sent.
                    end = time.time() + 3
                    while time.time() < end and not (
                            R.c.latched and not R.c.snapshot()["busy"]):
                        time.sleep(0.01)
                    return real_reset(*a, **k)
                R.svc.reset_conductor = late_reset
            got = {}

            def press(route, body):
                got[route] = R.ask("POST", f"/api/remote/{route}", body)
            ts = {"reset": threading.Thread(target=press, args=(
                      "reset", {"seen": R.seen()})),
                  "abort": threading.Thread(target=press, args=(
                      "abort", {"confirmed": True}))}
            second = "abort" if first == "reset" else "reset"
            # The conductor's own effects run as they would on its thread,
            # so the Abort has finished fading by the time the Reset is
            # answered (otherwise "still fading" refuses it, and the order
            # is never tested).
            pumping = threading.Event()

            def pump():
                while not pumping.is_set():
                    try:
                        R.c.run_pending()
                    except Exception:
                        pass
                    time.sleep(0.005)
            pt = threading.Thread(target=pump, daemon=True)
            pt.start()
            ts[first].start()
            time.sleep(0.001)
            ts[second].start()
            for t in ts.values():
                t.join(10)
            pumping.set()
            pt.join(2)
            SV.write_json_atomic = real_save
            R.settle()
            latched = R.svc.machine.abort_latched
            st, _h, out = got.get("reset", (0, None, {}))
            if first == "reset":
                check(latched and R.svc._aborted() and R.c.latched and
                      not out.get("ok"),
                      f"a Reset pressed 1 ms before the Abort does not end "
                      f"it, though it reached the scheduler after it: "
                      f"latched={latched} conductor={R.c.latched} {out}")
            else:
                check(bool(out.get("ok")) == (not latched) and
                      latched == R.c.latched,
                      f"a Reset pressed 1 ms after the Abort ends it or "
                      f"says it did not, and the scheduler and the "
                      f"conductor agree: latched={latched} "
                      f"conductor={R.c.latched} {out}")
        finally:
            SV.write_json_atomic = real_save
            R.svc.reset_conductor = real_reset
            R.close()
    print("  ok")


def test_remote_abort_disarm_never_waits_on_the_tonight_save():
    section("iPad remote: a slow or failing tonight.json save never delays "
            "the screen Abort's disarm (review of PR #43, P0-5)")
    S = _sched()
    if S is None:
        return
    from ltcplay import schedule_service as SV
    R = _RemoteRig(S)
    real = SV.write_json_atomic
    try:
        _live_show(R)
        seen = {}

        def disarm(reason):
            seen.setdefault("disarm", time.monotonic())
            # The scheduler's lock is free while the disarm goes: a thread
            # of its own can take it at once.
            got = []

            def probe():
                ok = R.svc.lock.acquire(timeout=0.05)
                if ok:
                    R.svc.lock.release()
                got.append(ok)
            t = threading.Thread(target=probe)
            t.start()
            t.join()
            seen["lock_free"] = bool(got and got[0])
            return _Result(True, "sent.")
        R.remote._flame_disarm = disarm
        real_blank = R.c.devices.lasers_blank

        def blank():
            seen.setdefault("blank", time.monotonic())
            return real_blank()
        R.c.devices.lasers_blank = blank

        def stalled(path, doc, **kw):
            seen.setdefault("save", time.monotonic())
            time.sleep(0.4)
            raise OSError(28, "No space left on device")
        SV.write_json_atomic = stalled
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True})
        R.settle()
        check("disarm" in seen and "save" in seen and
              seen["disarm"] < seen["save"],
              f"the disarm went before the tonight.json save began: {seen}")
        check(seen.get("lock_free") is True,
              "the scheduler's lock was not held while the disarm went")
        check("blank" in seen and seen["blank"] < seen["save"],
              f"the lasers were blanked before the tonight.json save began "
              f"too (re-review P1-A), not after it: {seen}")
        check(out.get("lasers_blanked") is True and
              "Lasers blanked at the press" in out.get("text", ""),
              f"and the answer says so: {out}")
        check(st == 200 and out.get("disarmed") is True,
              f"a failing save does not undo or hide the disarm: {st} {out}")
    finally:
        SV.write_json_atomic = real
        R.close()
    print("  ok")


