class _FakePurgeLink:
    """What morning.py asks of the flame link: the purge frame and the
    locked channels. Records every call."""

    def __init__(self):
        self.frames = []
        self.cleared = 0
        self.locked = set()

    def purge_set(self, values):
        self.frames.append(bytes(values))
        return True

    def purge_clear(self):
        self.cleared += 1

    def set_locked_channels(self, slots):
        self.locked = set(slots)


class _FakeLaserOutput:
    """What laserarm.LaserArm asks of the conductor's BEYOND
    (beyondtc.Blanking): output_fault, output_enable(), output_disable()
    and blank(). Records every call in order in `calls`; `fault` is the
    standing "not set up" sentence or None; `ok` what a send answers."""

    def __init__(self):
        self.calls = []
        self.fault = None
        self.ok = True
        self.osc = object()

    @property
    def output_fault(self):
        return self.fault

    def output_enable(self, show=None, still_wanted=None):
        if still_wanted is not None and still_wanted() is not True:
            self.calls.append("enable-cut")
            return False
        self.calls.append("enable")
        return self.ok

    def output_disable(self, show=None):
        self.calls.append("disable")
        return self.ok

    def blank(self, show=None):
        self.calls.append("blank")
        return self.ok


def _morning_rig(S, config=None, link=None):
    """An _arm_rig (flamesafe's status fed on the test's clock, screen
    arming on) with a Morning attached, built the way web.serve builds it
    but on the test's clocks and with no watcher thread."""
    import json as _j
    from ltcplay import morning as MO
    R = _arm_rig(S)
    fs = os.path.join(R.work, "flamesafe.json")
    with open(fs, "w", encoding="utf-8") as fh:
        _j.dump(_MO_FLAMESAFE, fh)
    if config is not None:
        with open(os.path.join(R.work, MO.CONFIG_FILE), "w",
                  encoding="utf-8") as fh:
            _j.dump(config, fh)
    R.link = link if link is not None else _FakePurgeLink()
    names = [g["name"] for g in _MO_FLAMESAFE["groups"]]
    R.lines = []
    R.osc = []
    # flamesafe's word on the lockout file, fed with its status: None for a
    # flamesafe that says nothing about it, else {"slots", "state"}.
    R.fs_lockout = None

    def feed():
        doc = {"t": "status", "k": "k" * 20, "fault": "", "groups": R.groups}
        if R.fs_lockout is not None:
            doc["lockout"] = R.fs_lockout
        R.remote.flame_status.note(_j.dumps(doc).encode())
    R.feed = feed
    feed()

    class _Sock:
        def sendto(self, pkt, addr):
            R.osc.append((addr, pkt))

        def close(self):
            pass
    R.laser_out = _FakeLaserOutput()
    R.m = MO.Morning(R.work, flamesafe_config=fs,
                     link_get=lambda: R.link,
                     flames_get=lambda: R.remote.flame_status.view(),
                     live_check=R.remote.show_live_refusal,
                     group_names=lambda: names,
                     journal=R.remote._morning_journal, night=R.svc._night,
                     clock=lambda: R.mono[0], wall=lambda: R.wall[0],
                     threaded=False, socket_factory=_Sock,
                     laser_output=lambda: R.laser_out,
                     laser_blockers=R.remote.laser_arm_blockers,
                     night_state=lambda: getattr(R.svc.machine, "state",
                                                 None))
    R.remote.morning = R.m
    R.remote._deck_seen = R.mono[0]          # the deck is reading the engine
    return R


def _mo_arm(R, *ids):
    """Arm lasers on the Morning rig (laserarm.py): a test needs its laser
    armed (Jeff, 2026-10-22)."""
    ok, text = R.m.laser_arm.arm(list(ids), who="Andy", screen="Rack screen",
                                 confirmed=True)
    check(ok, f"setup: {', '.join(ids)} armed: {text}")
    R.m.laser_arm.run_pending()


def _mo_advance(R, dt, beat=True):
    """Time passes on every clock; the deck keeps reading; the page keeps
    saying it is open unless `beat` is False; the watcher runs."""
    R.mono[0] += dt
    R.wall[0] += dt
    R.feed()
    R.remote._deck_seen = R.mono[0]
    if beat:
        R.m.open_beat("Rack screen")
    R.m.tick()


def test_flamesafe_multi_safety_ltcplay_side():
    """flamesafe multi-safety (Jeff, 2026-10-26): the wave flamer is ONE
    arm group driving three 6-channel fixtures, each with its own safety
    slot. Everything in ltcplay that read a group's safety as one slot
    reads a list too; the Stream Deck is unchanged; the rack screen card
    says how many safeties are up for such a group only."""
    section("flamesafe multi-safety: ltcplay reads a list of safety slots; "
            "the deck is unchanged; the rack screen card counts safeties")
    import json as _json
    import types as _types
    import shutil as _sh
    import subprocess
    from ltcplay import fire_ice as FI
    from ltcplay import morning as MO
    from ltcplay import remote as RM
    from ltcplay import streamdeck as sd
    here = os.path.dirname(os.path.abspath(__file__))
    ex = _json.load(open(os.path.join(here, "flamesafe",
                                      "flamesafe.example.json"),
                         encoding="utf-8"))
    wave = ex["groups"][2]
    check(wave["name"] == "wave flamer" and wave["safety"] == [6, 12, 18]
          and wave["fire"] == [1, 2, 3, 4, 5, 7, 8, 9, 10, 11,
                               13, 14, 15, 16, 17],
          f"the example's wave flamer: three safety slots and the 15 "
          f"control slots, explicitly: {wave}")
    work = tempfile.mkdtemp()
    try:
        def fs_with(groups):
            d = dict(ex, groups=groups)
            p = os.path.join(work, "fs.json")
            with open(p, "w", encoding="utf-8") as fh:
                _json.dump(d, fh)
            return p
        three = ex["groups"][:3]
        cfg = _types.SimpleNamespace(flamesafe_config=fs_with(three),
                                     flame_controller=None)
        try:
            FI.check_flame_groups(work, cfg)
            check(True, "")
        except FI.FireIceConfigError as e:
            check(False, f"fire_ice refused a list of safety slots: {e}")
        for bad, why in (([6, 12, 21], "a safety slot that is front row's "
                                       "fire channel"),
                         ([6, 12, "18"], "a safety that is not a number"),
                         ([], "an empty list of safety slots")):
            g = [dict(three[0]), dict(three[1]), dict(wave, safety=bad)]
            g[0]["fire"] = [21, 22]
            cfg.flamesafe_config = fs_with(g)
            try:
                FI.check_flame_groups(work, cfg)
                check(False, f"fire_ice accepted {why}")
            except FI.FireIceConfigError as e:
                check("—" not in str(e) and "–" not in str(e),
                      f"fire_ice refuses {why}: {e}")
        # The deck: the same three keys, the same names, whatever a
        # group's safety is.
        fs3 = fs_with(three)
        got = sd.load_flamesafe_link(fs3)
        check(got[5] == ["front row", "cat-walk", "wave flamer"] and
              sd.GROUP_KEY_LIMIT == 4 and sd.GROUP_KEYS == (1, 2, 3, 4),
              f"the Stream Deck: four arm keys, one per group, the wave "
              f"flamer one key: {got[5]}")
        base = {"name": "wave flamer", "armed": "armed", "wanted": True,
                "reason": "", "amber": "", "dwell_s": 0}
        more = dict(base, safety_slots=[6, 12, 18],
                    safeties_up=[True, False, True],
                    safeties_locked=[False, True, False])
        for st in ("armed", "held", "disarmed"):
            check(sd.group_look(dict(base, armed=st), slot=2) ==
                  sd.group_look(dict(more, armed=st), slot=2),
                  f"the deck key shows the group's one state ({st}), not "
                  f"the per-safety list")
        # Morning: one machine per fixture, each with its own safety slot,
        # so locking one machine puts its safety in the lockout file.
        groups = MO.load_flamesafe_groups(fs3)
        check(groups[2]["safeties"] == [6, 12, 18] and
              groups[0]["safeties"] == [ex["groups"][0]["safety"]],
              f"the morning engine reads every safety slot: {groups}")
        mc = MO.MorningConfig.parse({}, "x", groups)
        wm = [m for m in mc.machines if m.group == "wave flamer"]
        check([(m.id, m.fire, m.safety) for m in wm] ==
              [("wave-flamer-1", [1, 2, 3, 4, 5], 6),
               ("wave-flamer-2", [7, 8, 9, 10, 11], 12),
               ("wave-flamer-3", [13, 14, 15, 16, 17], 18)],
              f"three wave flamer machines, five fire slots and a safety "
              f"each: {[(m.id, m.fire, m.safety) for m in wm]}")
        check(wm[1].channels() == {7, 8, 9, 10, 11, 12} and
              all(m.safety is None for m in mc.machines
                  if m.group != "wave flamer"),
              "a locked fixture names its safety slot too; no other "
              "machine has one")
        doc = {"machines": [{"id": "w1", "kind": "gflame",
                             "group": "wave flamer", "fire": [1, 2],
                             "safety": 6}]}
        check(MO.MorningConfig.parse(doc, "x", groups).by_id["w1"].safety
              == 6, "a machine may name its own safety in a multi-safety "
                    "group")
        for bad in ({"group": "wave flamer", "fire": [1], "safety": 7},
                    {"group": "front row",
                     "fire": [ex["groups"][0]["fire"][0]],
                     "safety": ex["groups"][0]["safety"]}):
            try:
                MO.MorningConfig.parse(
                    {"machines": [dict(bad, id="b1", kind="gflame")]},
                    "x", groups)
                check(False, f"a machine safety was accepted: {bad}")
            except MO.MorningConfigError as e:
                check("safety" in str(e), f"refused: {e}")
    finally:
        _sh.rmtree(work, ignore_errors=True)
    # The rack screen: flamesafe's per-safety lists reach the card.
    fs = RM.FlameStatus("127.0.0.1", 1, "k" * 16, ["wave flamer"],
                        clock=lambda: 10.0)
    fs.last, fs.last_at = {"groups": [dict(more, locked_fire=[])]}, 10.0
    g = fs.view()["groups"][0]
    check(g["safeties_up"] == [True, False, True] and
          g["safeties_locked"] == [False, True, False],
          f"the rack screen gets the per-safety state: {g}")
    fs.last = {"groups": [dict(base)]}
    g = fs.view()["groups"][0]
    check(g["safeties_up"] == [] and g["safeties_locked"] == [],
          "an older flamesafe without the lists: empty, no line")
    # safety_profile (2026-10-26): each group's own arm value reaches the
    # card's tooltip; an older flamesafe or a bad value gives none.
    fs.last = {"groups": [dict(base, arm_value=178)]}
    check(fs.view()["groups"][0]["arm_value"] == 178,
          "the rack screen gets the group's arm value (178)")
    for bad in (None, 0, 256, True, "178"):
        fs.last = {"groups": [dict(base, arm_value=bad)]}
        check(fs.view()["groups"][0]["arm_value"] is None,
              f"an arm value of {bad!r} reaches the card as none")
    fs.last = {"groups": [dict(base)]}
    check(fs.view()["groups"][0]["arm_value"] is None,
          "an older flamesafe without arm_value: none")
    page = open(os.path.join(here, "ltcplay", "web", "remote.html"),
                encoding="utf-8").read()
    logic = page[page.find("// LOGIC BEGIN"):page.find("// LOGIC END")]
    check("function safetyLine" in logic and
          'const sl = safetyLine(g, c) || machineCountLine(g, c, ST && '
          'ST.morning && ST.morning.group_machines), se = '
          'el.querySelector(".saf");' in page,
          "the card draws the safety line (or, with one safety, the "
          "machine count) from page logic")
    node = _sh.which("node")
    if node:
        js = logic + r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const W = {name:"wave flamer"};
t(safetyLine(Object.assign({safeties_up:[true,true,false], safeties_locked:[false,false,false]}, W), "held") === "wave flamer: 2 of 3 safeties up; NOT armed", "2 of 3, not armed");
t(safetyLine(Object.assign({safeties_up:[true,false,true], safeties_locked:[false,true,false]}, W), "armed") === "wave flamer: 2 of 2 unlocked safeties up, 1 locked out; ARMED", "one locked, armed");
t(safetyLine(Object.assign({safeties_up:[true,true,true], safeties_locked:[false,false,false]}, W), "armed") === "wave flamer: 3 of 3 safeties up; ARMED", "all up");
t(safetyLine(Object.assign({safeties_up:[false,false,false], safeties_locked:[true,true,true]}, W), "held") === "wave flamer: 0 of 0 unlocked safeties up, 3 locked out; NOT armed", "all locked");
t(safetyLine({name:"front row", safeties_up:[true], safeties_locked:[false]}, "armed") === "", "one safety: no line");
t(safetyLine({name:"front row"}, "armed") === "", "an older flamesafe: no line");
t(safetyLine(Object.assign({safeties_up:[true,true,true], safeties_locked:[false,false,false]}, W), "unknown") === "", "not known: no line");
console.log(JSON.stringify(out));
"""
        r = _node_js(node, js, capture_output=True, text=True,
                           timeout=30)
        try:
            bad = _json.loads(r.stdout.strip().splitlines()[-1])
        except Exception:
            bad = [f"node did not run: {r.stderr[-300:]}"]
        check(not bad, f"the card's safety line: {bad}")


def test_morning_multi_safety_machines_pair_by_layout():
    """flamesafe multi-safety (2026-10-26), cold review of PR #107, P2-1: a
    wave flamer machine's safety slot is paired with its own fire slots by
    the slot layout, never by list order, and locking a machine always
    locks its own safety slot with its fire slots."""
    section("morning: a multi-safety machine locks its own fixture's safety "
            "slot, paired by the layout, whatever the list order")
    from ltcplay import morning as MO
    fire = [1, 2, 3, 4, 5, 7, 8, 9, 10, 11, 13, 14, 15, 16, 17]
    front = {"name": "front row", "safety": 401, "safeties": [401],
             "fire": [411, 412]}
    for saf in ([6, 12, 18], [18, 12, 6], [12, 18, 6]):
        groups = [front, {"name": "wave flamer", "safety": saf,
                          "safeties": saf, "fire": list(fire)}]
        cfg = MO.MorningConfig.parse({}, "x", groups)
        wm = [(m.id, m.fire, m.safety) for m in cfg.machines
              if m.group == "wave flamer"]
        check(wm == [("wave-flamer-1", [1, 2, 3, 4, 5], 6),
                     ("wave-flamer-2", [7, 8, 9, 10, 11], 12),
                     ("wave-flamer-3", [13, 14, 15, 16, 17], 18)],
              f"safety {saf}: each machine has its own fixture's safety "
              f"slot: {wm}")
        check(cfg.by_id["wave-flamer-1"].channels() == {1, 2, 3, 4, 5, 6},
              f"safety {saf}: locking wave flamer 1 locks slots 1 to 6")
    # A layout the pairing cannot read: one machine for the whole group,
    # and locking it locks every safety slot.
    odd = [front, {"name": "wave flamer", "safety": [6, 12, 18],
                   "safeties": [6, 12, 18], "fire": [1, 2, 3, 20, 21]}]
    cfg = MO.MorningConfig.parse({}, "x", odd)
    wm = [m for m in cfg.machines if m.group == "wave flamer"]
    check(len(wm) == 1 and wm[0].channels() == {1, 2, 3, 20, 21, 6, 12, 18},
          f"fixtures that cannot be told apart: one machine that locks "
          f"every slot of the group: {[(m.id, sorted(m.channels())) for m in wm]}")
    # Every safety has a run below it, but a fire slot belongs to none.
    odd[1] = dict(odd[1], fire=fire + [30])
    cfg = MO.MorningConfig.parse({}, "x", odd)
    wm = [m for m in cfg.machines if m.group == "wave flamer"]
    check(len(wm) == 1 and wm[0].channels() == set(fire + [30, 6, 12, 18]),
          f"a fire slot on no fixture: one machine for the whole group: "
          f"{[(m.id, sorted(m.channels())) for m in wm]}")
    groups = [front, {"name": "wave flamer", "safety": [18, 12, 6],
                      "safeties": [18, 12, 6], "fire": list(fire)}]
    ok = MO.MorningConfig.parse({"machines": [
        {"id": "w1", "kind": "gflame", "group": "wave flamer",
         "fire": [1, 2, 3, 4, 5], "safety": 6}]}, "x", groups)
    check(ok.by_id["w1"].channels() == {1, 2, 3, 4, 5, 6},
          "a machine naming its own fixture's safety is taken")
    for bad, says in (
            ({"fire": [1, 2, 3, 4, 5]}, "has to name its own"),
            ({"fire": [1, 2, 3, 4, 5], "safety": 18}, "fixture whose safety"),
            ({"fire": [5, 7], "safety": 6}, "fixture whose safety")):
        try:
            MO.MorningConfig.parse({"machines": [dict(
                bad, id="b1", kind="gflame", group="wave flamer")]},
                "x", groups)
            check(False, f"a wave flamer machine was taken: {bad}")
        except MO.MorningConfigError as e:
            check(says in str(e) and "—" not in str(e),
                  f"refused in a sentence ({says!r}): {e}")


def test_morning_fireball_is_never_purged():
    """Jeff's fireball (2026-10-26): Fuel Charge 55, Air Charge 56, Valve
    Open 57, Ignite 58, safety 99. The purge writes one value to every
    fire slot at once, which is not a fireball sequence and could be
    dangerous, so a fireball is never purged: refused on a click (its
    group is never armed for a purge), never listed for the deck, never
    given a value in the frame, and the page says why. The MORNING.md
    example parses against a flamesafe group list with the fireball."""
    section("morning: a fireball is never purged and never armed for one; "
            "the MORNING.md fireball machine parses against flamesafe's "
            "four groups")
    import json as _json
    import re as _re
    from ltcplay import morning as MO
    UNI = MO.UNIVERSE_SIZE
    reason = "a fireball has no purge sequence yet"
    check(MO.NO_FIREBALL_PURGE == reason, "the reason, word for word")

    class _Lock:
        def is_locked(self, kind, mid):
            return False

    class _Link:
        def __init__(self):
            self.frames = []

        def purge_set(self, vals):
            self.frames.append(bytes(vals))
            return True

        def purge_clear(self):
            pass

    groups = [{"name": "front row", "safety": 401, "safeties": [401],
               "fire": [411, 412]},
              {"name": "cat-walk", "safety": 402, "safeties": [402],
               "fire": [421]},
              {"name": "wave flamer", "safety": [6, 12, 18],
               "safeties": [6, 12, 18],
               "fire": [1, 2, 3, 4, 5, 7, 8, 9, 10, 11, 13, 14, 15, 16, 17]},
              {"name": "fireball", "safety": 99, "safeties": [99],
               "fire": [55, 56, 57, 58]}]
    names = [g["name"] for g in groups]
    # The flamesafe group and the machine, exactly as MORNING.md gives them.
    here = os.path.dirname(os.path.abspath(__file__))
    doc = open(os.path.join(here, "MORNING.md"), encoding="utf-8").read()
    # Every json block that is one whole object; a fragment (a key and its
    # value, shown for reading, like MORNING.md's "lasers") is not one and
    # is left out, never a crash.
    blocks = []
    for blk in _re.findall(r"```json\n(.*?)\n```", doc, _re.S):
        try:
            v = _json.loads(blk)
        except ValueError:
            continue
        if isinstance(v, dict):
            blocks.append(v)
    fs_group = [b for b in blocks if b.get("name") == "fireball"
                and "safety" in b]
    machine = [b for b in blocks if b.get("kind") == "fireball"]
    check(fs_group == [{"name": "fireball", "safety": 99,
                        "fire": [55, 56, 57, 58]}] and len(machine) == 1,
          f"MORNING.md carries the fireball group and machine: {blocks}")
    machines = MO.parse_machines(machine, "MORNING.md", groups)
    m = machines[0]
    check(m.kind == "fireball" and m.group == "fireball" and
          m.fire == [55, 56, 57, 58] and m.safety is None and
          m.channels() == {55, 56, 57, 58},
          f"parse_machines accepts it against the four groups: {m.view()}")
    cfg = MO.MorningConfig.parse({"machines": [
        {"id": "g1", "name": "Ground 1", "kind": "gflame",
         "group": "front row", "fire": [411]}] + machine,
        "purge": {"fireball": {"fire": 200}}}, "x", groups)
    check(cfg.banks["Fireball"] == ["fireball"] and
          cfg.purge["fireball"]["fire"] == 200,
          "it sits in the Fireball group; an old purge.fireball still loads")
    for bad, why in (([55, 56, 57, 58, 99], "its safety slot as fire"),
                     ([55, 56, 57, 59], "a slot that is not the group's")):
        try:
            MO.parse_machines([dict(machine[0], fire=bad)], "x", groups)
            check(False, f"parse_machines accepted {why}")
        except MO.MorningConfigError as e:
            check("is not one of 'fireball''s fire slots" in str(e),
                  f"{why} is refused: {e}")
    # With no machines list: ONE machine for the whole fireball.
    dflt = MO.MorningConfig.parse({}, "x", groups)
    fb = [x for x in dflt.machines if x.group == "fireball"]
    check(len(fb) == 1 and fb[0].id == "fireball" and
          fb[0].fire == [55, 56, 57, 58] and fb[0].kind == "fireball" and
          fb[0].notes == f"Never purged: {reason}." and
          dflt.banks["Fireball"] == ["fireball"],
          f"the default is one fireball machine, its notes say why: "
          f"{[x.view() for x in fb]}")
    check(m.purge_refusal() == reason and
          cfg.by_id["g1"].purge_refusal() == "",
          "a fireball is purge-refused; a G-Flame is not")
    t = [100.0]
    link = _Link()
    fl = {"stale": False, "connected": True, "age_ms": 10,
          "groups": [{"name": n, "armed": "armed"} for n in names]}
    p = MO.Purge(lambda: cfg, _Lock(), lambda: link, lambda: fl,
                 lambda: "", lambda: names, clock=lambda: t[0])
    code, out = p.select("fireball", True, "Rack screen", True)
    check(code == 409 and reason in out.get("error", "") and
          p.selected == [] and p.groups_wanted() == [],
          f"a click on the fireball is refused and arms nothing: "
          f"{code} {out}")
    check("—" not in out["error"] and "–" not in out["error"],
          "no em or en dash")
    # Even if it were in the selection (a config edited under it), its
    # group is never asked for and no value is ever written to it.
    p.selected = ["fireball"]
    p.owner = "Rack screen"
    check(p.groups_wanted() == [],
          "a fireball in the selection never asks the deck to arm")
    vals, firing, waiting = p.frame(t[0])
    check(vals == bytes(UNI) and firing == [] and
          waiting == [f"Fireball: {reason}"],
          f"the frame writes nothing for it, with the reason: {waiting}")
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    check(code == 409 and reason in out.get("error", "") and
          link.frames == [],
          f"a fire press on only the fireball is refused cleanly: "
          f"{code} {out}")
    # A G-Flame beside it fires as before; the fireball's slots stay 0.
    p.selected = ["g1", "fireball"]
    check(p.groups_wanted() == [0], "only the G-Flame's group is asked for")
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    v = link.frames[-1] if link.frames else b""
    check(code == 200 and out["firing"] == ["Ground 1"] and
          v[410] == cfg.purge["gflame_fire"] and
          all(v[s - 1] == 0 for s in (55, 56, 57, 58, 99)),
          f"the G-Flame fires, every fireball slot stays zero: {code} {out}")
    p.stop("test")
    print("  ok")


def test_morning_fireball_group_is_never_purged():
    """Review of PR #120, P1: the never-purge rule is by FLAMESAFE GROUP,
    not by a machine's kind. A fireball group (declared in
    fireball_groups, named fireball or ball, or holding a fireball
    machine) is never selected, never asked of the deck and never written
    by the purge frame; and every machine in it has to say kind
    "fireball", so a kind left out (a G-Flame by default) or a waver with
    pan and tilt on the valve and ignite slots is refused in a sentence."""
    section("morning: a fireball GROUP is never purged, whatever a machine "
            "in it says; a machine there must be kind fireball")
    from ltcplay import morning as MO
    reason = MO.NO_FIREBALL_PURGE
    fb = {"name": "fireball", "safety": 99, "safeties": [99],
          "fire": [55, 56, 57, 58]}
    front = {"name": "front row", "safety": 401, "safeties": [401],
             "fire": [411, 412]}
    groups = [front, fb]
    for bad, why in (
            ({"id": "fb", "group": "fireball", "fire": [55, 56, 57, 58]},
             "a kind left out"),
            ({"id": "fb", "kind": "gflame", "group": "fireball",
              "fire": [55, 56]}, "a G-Flame"),
            ({"id": "fb", "kind": "waver", "group": "fireball",
              "fire": [55, 56], "pan": 57, "tilt": 58}, "a waver")):
        try:
            MO.MorningConfig.parse({"machines": [bad]}, "x", groups)
            check(False, f"{why} in the fireball group was accepted")
        except MO.MorningConfigError as e:
            check("'fireball' is a fireball group" in str(e) and
                  "\"kind\": \"fireball\"" in str(e) and
                  not any(c in str(e) for c in "—–"),
                  f"{why} in the fireball group is refused: {e}")
    # A group with a fireball machine is a fireball group, whatever its
    # name: another machine in it must be a fireball too.
    boom = {"name": "Big Boom", "safety": 98, "safeties": [98],
            "fire": [61, 62, 63, 64]}
    try:
        MO.MorningConfig.parse({"machines": [
            {"id": "a", "kind": "fireball", "group": "Big Boom",
             "fire": [61, 62]},
            {"id": "b", "group": "Big Boom", "fire": [63, 64]}]}, "x",
            [front, boom])
        check(False, "a G-Flame beside a fireball machine was accepted")
    except MO.MorningConfigError as e:
        check("'Big Boom' is a fireball group" in str(e), str(e))
    # Declared, with no machines list: one fireball machine, never purged.
    for name in ("Big Boom", "FB", "poofer"):
        g = dict(boom, name=name)
        cfg = MO.MorningConfig.parse({"fireball_groups": [name]}, "x",
                                     [front, g])
        ms = [m for m in cfg.machines if m.group == name]
        check(len(ms) == 1 and ms[0].kind == "fireball" and
              ms[0].fire == [61, 62, 63, 64] and
              cfg.purge_refusal(ms[0]) == reason,
              f"{name!r} declared a fireball: one fireball machine, never "
              f"purged: {[m.view() for m in ms]}")
    # Named with "ball": a fireball group with nothing declared.
    ball = dict(boom, name="Big Ball")
    cfg = MO.MorningConfig.parse({}, "x", [front, ball])
    check("Big Ball" in cfg.fireball_groups and
          [m.kind for m in cfg.machines if m.group == "Big Ball"] ==
          ["fireball"], "a group named ... ball is a fireball group")
    try:
        MO.MorningConfig.parse({"fireball_groups": ["nope"]}, "x", groups)
        check(False, "an unknown fireball group was accepted")
    except MO.MorningConfigError as e:
        check("'nope', which is not a flamesafe group" in str(e), str(e))
    try:
        MO.MorningConfig.parse({"fireball_groups": "fireball"}, "x", groups)
        check(False, "fireball_groups as text was accepted")
    except MO.MorningConfigError as e:
        check("has to be a list" in str(e), str(e))
    # The purge, given a config whose fireball group holds a G-Flame (a
    # MorningConfig built past the parser): still never purged.
    gf = MO.Machine("fb", "Fireball", "gflame", "fireball", [55, 56, 57, 58])
    g1 = MO.Machine("g1", "Ground 1", "gflame", "front row", [411])
    cfg = MO.MorningConfig([g1, gf], {}, MO.parse_purge(None, "x"), [], [],
                           [], None, fireball_groups=["fireball"])
    check(cfg.purge_refusal(gf) == reason and cfg.purge_refusal(g1) == "",
          "refused by its group, whatever its kind")

    class _Lock:
        def is_locked(self, kind, mid):
            return False

    class _Link:
        def __init__(self):
            self.frames = []

        def purge_set(self, vals):
            self.frames.append(bytes(vals))
            return True

        def purge_clear(self):
            pass
    link = _Link()
    names = ["front row", "fireball"]
    fl = {"stale": False, "connected": True, "age_ms": 10,
          "groups": [{"name": n, "armed": "armed"} for n in names]}
    p = MO.Purge(lambda: cfg, _Lock(), lambda: link, lambda: fl,
                 lambda: "", lambda: names, clock=lambda: 100.0)
    code, out = p.select("fb", True, "Rack screen", True)
    check(code == 409 and reason in out["error"] and p.selected == [],
          f"a click on it is refused: {code} {out}")
    p.selected = ["g1", "fb"]
    p.owner = "Rack screen"
    check(p.groups_wanted() == [0], "its group is never asked of the deck")
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    v = link.frames[-1] if link.frames else b""
    check(code == 200 and out["firing"] == ["Ground 1"] and
          all(v[s - 1] == 0 for s in (55, 56, 57, 58)),
          f"the frame never writes its slots: {code} {out}")
    p.stop("test")
    print("  ok")


def test_morning_unknown_multi_channel_group_is_never_purged():
    """Review of PR #120, P2-1: a flamesafe group with several fire slots
    and one safety that nothing declares (named "FB", "Boom", "Poofer")
    could be a fireball by another name. With no machines list its
    machines are built (one per fire slot, so locking and the lamps
    work) but none is purged or armed for a purge until it is declared in
    fireball_groups or gflame_groups; the journal and the Startup page say
    so. Jeff's front row and cat-walk rows stay purgeable by name."""
    section("morning: an unknown multi-channel group is never purged until "
            "declared (fireball_groups or gflame_groups); rows named row or "
            "cat-walk stay purgeable; journaled and on the tile")
    from ltcplay import morning as MO
    reason = MO.NO_UNKNOWN_PURGE
    check(reason.startswith("unknown flame group, declare it in "
                            "fireball_groups") and
          not any(c in reason for c in "—–"), f"the words: {reason}")
    front = {"name": "front row", "safety": 401, "safeties": [401],
             "fire": [411, 412, 413]}
    cat = {"name": "cat-walk", "safety": 402, "safeties": [402],
           "fire": [421, 422]}
    one = {"name": "pump", "safety": 404, "safeties": [404], "fire": [441]}
    for name in ("FB", "Boom", "Poofer"):
        fb = {"name": name, "safety": 99, "safeties": [99],
              "fire": [55, 56, 57, 58]}
        groups = [front, cat, one, fb]
        cfg = MO.MorningConfig.parse({}, "x", groups)
        ms = [m for m in cfg.machines if m.group == name]
        check(cfg.unknown_groups == {name, "pump"} and len(ms) == 4 and
              all(cfg.purge_refusal(m) == reason for m in ms) and
              all(m.notes == f"Never purged: {reason}." for m in ms),
              f"{name!r}: four machines, none purged, the notes say why: "
              f"{[m.view() for m in ms]}")
        check(all(cfg.purge_refusal(m) == "" for m in cfg.machines
                  if m.group in ("front row", "cat-walk")) and
              all(cfg.purge_refusal(m) == reason for m in cfg.machines
                  if m.group == "pump"),
              "front row and cat-walk (Jeff's rows, by their whole name) "
              "stay purgeable; a one-slot group nothing declares is not "
              "(review of #126, P2-3)")
        view = {m["id"]: m for m in cfg.view()["machines"]}
        check(view[ms[0].id]["never_purged"] == reason and
              view["front-row-1"]["never_purged"] == "",
              "the page's view carries the engine's reason per machine")
        check(cfg.journal_lines() and name in cfg.journal_lines()[0] and
              reason in cfg.journal_lines()[0],
              f"one journal line names it: {cfg.journal_lines()}")
        # Declared a fireball: one never-purged fireball machine.
        c2 = MO.MorningConfig.parse({"fireball_groups": [name]}, "x", groups)
        check(c2.unknown_groups == {"pump"} and
              [m.kind for m in c2.machines if m.group == name] ==
              ["fireball"], f"{name!r} declared a fireball")
        # Declared a row of G-Flames: purgeable, one by one.
        c3 = MO.MorningConfig.parse({"gflame_groups": [name]}, "x", groups)
        check(c3.unknown_groups == {"pump"} and
              all(c3.purge_refusal(m) == "" for m in c3.machines
                  if m.group == name), f"{name!r} declared a row")
    # A name is no proof (review of #126, P2-3): only Jeff's rows by
    # their whole name, any case; "row", "cat" or "walk" inside another
    # word proves nothing.
    loose = ["Crowd Poofers", "Walkway Poofer", "Arrow", "Flame Thrower",
             "Scatter Boom", "Ground Row", "catwalk G"]
    gl = [{"name": x, "safety": 300 + i, "safeties": [300 + i],
           "fire": [200 + 4 * i, 201 + 4 * i]} for i, x in enumerate(loose)]
    cl = MO.MorningConfig.parse({}, "x", gl + [
        dict(front, name="Front Row"), dict(cat, name="CAT-WALK")])
    check(cl.unknown_groups == set(loose),
          f"loose names are never purged, Jeff's rows in any case are: "
          f"{sorted(cl.unknown_groups)}")
    # A group with several safety slots (several fixtures) nothing
    # declares (third review of #126, P2-1: "Big Boom", fire 21 to 24 and
    # 26 to 29, safeties 25 and 30, was two purgeable G-Flame machines).
    # Purged only as a waver or when gflame_groups lists it.
    boom = {"name": "Big Boom", "safety": 25, "safeties": [25, 30],
            "fire": [21, 22, 23, 24, 26, 27, 28, 29]}
    wave = {"name": "wave flamer", "safety": 6, "safeties": [6, 12],
            "fire": [1, 2, 3, 4, 5, 7, 8, 9, 10, 11]}
    for nm in ("Big Boom", "front row"):
        b = dict(boom, name=nm)
        cb = MO.MorningConfig.parse({}, "x", [b, wave])
        bm = [m for m in cb.machines if m.group == nm]
        check(nm in cb.unknown_groups and len(bm) == 2 and
              all(cb.purge_refusal(m) == reason for m in bm) and
              "wave flamer" not in cb.unknown_groups,
              f"{nm!r} with two safeties: never purged until declared, "
              f"even by a row's name: {[m.view() for m in bm]}")
        check(any(nm in x for x in cb.journal_lines()),
              f"and journaled: {cb.journal_lines()}")
        cg = MO.MorningConfig.parse({"gflame_groups": [nm]}, "x", [b, wave])
        check(nm not in cg.unknown_groups and
              all(cg.purge_refusal(m) == "" for m in cg.machines
                  if m.group == nm),
              f"{nm!r} listed in gflame_groups: purged, fixture by fixture")
    try:
        MO.MorningConfig.parse({"gflame_groups": ["FB"],
                                "fireball_groups": ["FB"]}, "x",
                               [front, dict(one, name="FB")])
        check(False, "a group both a fireball and a row was accepted")
    except MO.MorningConfigError as e:
        check("cannot also be a row" in str(e), str(e))
    try:
        MO.MorningConfig.parse({"gflame_groups": ["nope"]}, "x", [front])
        check(False, "an unknown gflame group was accepted")
    except MO.MorningConfigError as e:
        check("'nope', which is not a flamesafe group" in str(e), str(e))
    # A machines list is Andy's own word: trusted as written.
    fb = {"name": "FB", "safety": 99, "safeties": [99],
          "fire": [55, 56, 57, 58]}
    c4 = MO.MorningConfig.parse({"machines": [
        {"id": "fb1", "group": "FB", "fire": [55, 56, 57, 58]}]}, "x",
        [front, fb])
    check(not c4.unknown_groups, "a machines list is trusted as written")
    # The purge refuses the click and never asks the deck.
    cfg = MO.MorningConfig.parse({}, "x", [front, fb])

    class _Lock:
        def is_locked(self, kind, mid):
            return False

    class _Link:
        frames = []

        def purge_set(self, vals):
            self.frames.append(bytes(vals))
            return True

        def purge_clear(self):
            pass
    names = ["front row", "FB"]
    fl = {"stale": False, "connected": True, "age_ms": 10,
          "groups": [{"name": n, "armed": "armed"} for n in names]}
    p = MO.Purge(lambda: cfg, _Lock(), lambda: _Link(), lambda: fl,
                 lambda: "", lambda: names, clock=lambda: 100.0)
    code, out = p.select("fb-4", True, "Rack screen", True)
    check(code == 409 and reason in out["error"] and p.selected == [],
          f"a click on it is refused and arms nothing: {code} {out}")
    p.selected = ["fb-4", "front-row-1"]
    check(p.groups_wanted() == [0], "its group is never asked of the deck")
    vals, firing, waiting = p.frame(100.0)
    check(all(vals[s - 1] == 0 for s in (55, 56, 57, 58)) and
          firing == ["front row 1"],
          f"the frame never writes its slots: {firing} {waiting}")
    # The engine journals it once at start.
    work = tempfile.mkdtemp()
    try:
        import json as _json
        fs = os.path.join(work, "fs.json")
        with open(fs, "w", encoding="utf-8") as fh:
            _json.dump({"groups": [
                {"name": "front row", "safety": 401, "fire": [411, 412]},
                {"name": "FB", "safety": 99, "fire": [55, 56, 57, 58]}]},
                fh)
        lines = []
        m = MO.Morning(work, flamesafe_config=fs,
                       journal=lambda t_, **kw: lines.append((t_, kw)),
                       threaded=False)
        said = [t_ for t_, kw in lines if kw.get("outcome") ==
                "never-purged"]
        check(len(said) == 1 and "'FB'" in said[0],
              f"the engine journals the unknown group once: {said}")
        check(m.deck_view()["purge"]["never_groups"] == [1],
              f"and tells the Stream Deck it is never purged, a second "
              f"barrier (review of #126, P2-4): {m.deck_view()['purge']}")
        try:
            m.close()
        except Exception:                        # noqa: BLE001
            pass
    finally:
        import shutil
        shutil.rmtree(work, ignore_errors=True)
    print("  ok")


def test_morning_default_wave_flamer_is_never_purged():
    """A default wave flamer machine (built from flamesafe's groups, with
    no pan and no tilt slot) is never purged and never raises: the purge
    frame leaves it out with a plain reason, the page says so, and a fire
    press on nothing else is refused cleanly. A custom waver with pan and
    tilt, and a G-Flame, purge exactly as before (Jeff's wave flamers:
    six channels, 1 to 5 control, 6 safety, control meanings not known)."""
    section("morning: a default wave flamer has no pan, tilt and fire map, "
            "so it is never purged and never raises")
    from ltcplay import morning as MO
    UNI = MO.UNIVERSE_SIZE

    class _Lock:
        def __init__(self):
            self.locked = set()

        def is_locked(self, kind, mid):
            return mid in self.locked

    class _Link:
        def __init__(self):
            self.frames, self.cleared = [], 0

        def purge_set(self, vals):
            self.frames.append(bytes(vals))
            return True

        def purge_clear(self):
            self.cleared += 1

    def rig(cfg, names):
        t = [100.0]
        link = _Link()
        lock = _Lock()
        fl = {"stale": False, "connected": True, "age_ms": 10,
              "groups": [{"name": n, "armed": "armed"} for n in names]}
        p = MO.Purge(lambda: cfg, lock, lambda: link, lambda: fl,
                     lambda: "", lambda: names, clock=lambda: t[0])
        return p, link, lock, t

    reason = "no pan, tilt and fire map yet (set it in " \
             "ltcplay_morning.json machines)"
    front = {"name": "front row", "safety": 401, "safeties": [401],
             "fire": [411, 412]}
    # Jeff's three-safety wave flamer: fire 1 to 5, 7 to 11, 13 to 17.
    fire = [1, 2, 3, 4, 5, 7, 8, 9, 10, 11, 13, 14, 15, 16, 17]
    groups = [front, {"name": "wave flamer", "safety": [6, 12, 18],
                      "safeties": [6, 12, 18], "fire": list(fire)}]
    names = [g["name"] for g in groups]
    cfg = MO.MorningConfig.parse({}, "x", groups)
    waves = [m for m in cfg.machines if m.group == "wave flamer"]
    check([m.id for m in waves] == ["wave-flamer-1", "wave-flamer-2",
                                    "wave-flamer-3"] and
          all(m.kind == "waver" and m.pan is None and m.tilt is None
              for m in waves),
          f"the default machines are still built, one per fixture, so "
          f"locking and the lamps work: {[m.view() for m in waves]}")
    check(all(m.purge_refusal() == reason for m in waves),
          f"each is purge-refused with the reason: "
          f"{[m.purge_refusal() for m in waves]}")
    check(all(reason in m.view()["notes"] for m in waves),
          "the page's view carries the reason in the machine's notes")
    p, link, lock, t = rig(cfg, names)
    p.selected = [m.id for m in waves]
    p.owner = "Rack screen"
    try:
        vals, firing, waiting = p.frame(t[0])
        raised = None
    except Exception as e:                                # noqa: BLE001
        raised = e
    check(raised is None, f"the purge frame never raises: {raised!r}")
    check(vals == bytes(UNI) and firing == [],
          f"no value at all is written for them: firing {firing}")
    check(waiting == [f"wave flamer {n}: {reason}" for n in (1, 2, 3)],
          f"every one is left out, with the reason: {waiting}")
    check(not any(c in text for text in waiting for c in "–—"),
          "the reason has no em or en dash")
    # A fire press on nothing but those: a clean refusal, not a 500.
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    check(code == 409 and out.get("let_go") is True and
          reason in out.get("error", "") and link.frames == [] and
          p.fire is None,
          f"fire_beat refuses cleanly and nothing is set: {code} {out}")
    # With a G-Flame in the selection the G-Flame fires as before and the
    # wave flamers are left out with the reason.
    p.selected = ["front-row-1"] + [m.id for m in waves]
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    gf = cfg.purge["gflame_fire"]
    check(code == 200 and out["firing"] == ["front row 1"] and
          len(out["waiting"]) == 3 and reason in out["waiting"][0],
          f"a G-Flame with them still fires; they wait with the reason: "
          f"{code} {out}")
    want = bytearray(UNI)
    want[410] = gf
    check(link.frames and link.frames[-1] == bytes(want),
          "only the G-Flame's slot carries its fire value")
    p.stop("test")
    # The single-safety default wave flamer (one machine per fire slot)
    # is refused the same way.
    one = [front, {"name": "wave flamer", "safety": 403, "safeties": [403],
                   "fire": [431, 432, 433]}]
    cfg1 = MO.MorningConfig.parse({}, "x", one)
    p1, link1, _l, t1 = rig(cfg1, [g["name"] for g in one])
    p1.selected = ["wave-flamer-1"]
    p1.owner = "Rack screen"
    vals, firing, waiting = p1.frame(t1[0])
    check(vals == bytes(UNI) and firing == [] and
          waiting == [f"wave flamer 1: {reason}"],
          f"a one-safety default wave flamer is refused too: {waiting}")
    # A custom waver with pan and tilt purges exactly as before: head up
    # at once, fire after head_settle_s.
    cfgc = MO.MorningConfig.parse(_MO_CONFIG, "x", None)
    w1 = cfgc.by_id["w1"]
    check(w1.purge_refusal() == "" and cfgc.by_id["g1"].purge_refusal() ==
          "", "a custom waver with pan and tilt, and a G-Flame, are not "
              "refused")
    pc, linkc, _l, tc = rig(cfgc, ["front row", "cat-walk", "wave flamer"])
    pc.selected = ["w1", "g1"]
    pc.owner = "Rack screen"
    code, out = pc.fire_beat({"on": True}, "Rack screen", True)
    w = cfgc.purge["waver"]
    v = linkc.frames[-1]
    check(code == 200 and v[431] == w["pan_up"] and v[432] == w["tilt_up"]
          and v[430] == 0 and v[410] == cfgc.purge["gflame_fire"] and
          out["firing"] == ["Ground 1"] and
          out["waiting"] == [f"Waver 1: head going up "
                             f"({w['head_settle_s']:g} s)"],
          f"the custom waver's head goes up first, the G-Flame fires: "
          f"{code} {out}")
    tc[0] += w["head_settle_s"] + 0.05
    pc.fire["beat"] = tc[0]
    code, out = pc.fire_beat({"on": True, "fire_id": out["fire_id"]},
                             "Rack screen", True)
    v = linkc.frames[-1]
    check(code == 200 and v[430] == w["fire"] and v[431] == w["pan_up"] and
          v[432] == w["tilt_up"] and set(out["firing"]) ==
          {"Waver 1", "Ground 1"} and out["waiting"] == [],
          f"after the settle time the custom waver fires as before: "
          f"{code} {out}")
    print("  ok")


def test_waver_head_settle_may_be_zero():
    """Jeff, 2026-10-26: purge.waver.head_settle_s may be 0. Then the head
    values and the fire value go out in the same frame, on the first
    heartbeat on which the Waver is selected, unlocked and in an ARMED
    group. Below 0 is refused, the default stays 1.5, every other purge
    rule is unchanged."""
    section("Morning: a Waver's head settle time may be 0 (head up and "
            "fire in the same frame); below 0 is refused; the default "
            "stays 1.5 s")
    import json as _j
    from ltcplay import morning as MO
    check(MO.PURGE_DEFAULTS["waver"]["head_settle_s"] == 1.5 and
          MO.MorningConfig.parse({}, "x", _MO_FLAMESAFE["groups"])
          .purge["waver"]["head_settle_s"] == 1.5,
          "the default head settle time stays 1.5 s")

    def cfg_with(settle):
        d = _j.loads(_j.dumps(_MO_CONFIG))
        d["purge"]["waver"]["head_settle_s"] = settle
        return MO.MorningConfig.parse(d, "x", _MO_FLAMESAFE["groups"])
    for ok_v in (0, 0.0, 10):
        try:
            c = cfg_with(ok_v)
            check(c.purge["waver"]["head_settle_s"] == float(ok_v),
                  f"a head settle time of {ok_v} is accepted")
        except MO.MorningConfigError as e:
            check(False, f"a head settle time of {ok_v} was refused: {e}")
    for bad_v in (-0.1, -1, 10.5, float("nan"), True, "0"):
        try:
            cfg_with(bad_v)
            check(False, f"a head settle time of {bad_v!r} was accepted")
        except MO.MorningConfigError as e:
            check("0 to 10 seconds" in str(e) and "—" not in str(e) and
                  "–" not in str(e) and "always goes up first" not in
                  str(e), f"{bad_v!r} is refused in plain words: {e}")

    class _Lock:
        def __init__(self):
            self.locked = set()

        def is_locked(self, kind, mid):
            return mid in self.locked

    class _Link:
        def __init__(self):
            self.frames = []

        def purge_set(self, vals):
            self.frames.append(bytes(vals))
            return True

        def purge_clear(self):
            pass
    names = ["front row", "cat-walk", "wave flamer"]
    cfg = cfg_with(0)
    w = cfg.purge["waver"]
    t = [100.0]
    link, lock = _Link(), _Lock()
    armed = {"wave flamer"}
    fl = {"stale": False, "connected": True, "age_ms": 10,
          "groups": [{"name": n, "armed": "armed" if n in armed else
                      "disarmed"} for n in names]}
    p = MO.Purge(lambda: cfg, lock, lambda: link, lambda: fl, lambda: "",
                 lambda: names, clock=lambda: t[0])
    p.selected = ["w1"]
    p.owner = "Rack screen"
    vals, firing, waiting = p.frame(t[0])
    check(vals[431] == w["pan_up"] and vals[432] == w["tilt_up"] and
          vals[430] == w["fire"] and firing == ["Waver 1"] and
          waiting == [],
          f"settle 0: head up AND fire in the very first frame: "
          f"{firing} {waiting}")
    code, out = p.fire_beat({"on": True}, "Rack screen", True)
    f = link.frames[-1] if link.frames else bytes(MO.UNIVERSE_SIZE)
    check(code == 200 and f[430] == w["fire"] and f[431] == w["pan_up"] and
          f[432] == w["tilt_up"] and out["firing"] == ["Waver 1"],
          f"settle 0: the first fire heartbeat carries the fire value: "
          f"{code} {out}")
    p.stop("test")
    # Still only an ARMED group, an unlocked machine, a selected one.
    fl["groups"][2]["armed"] = "disarmed"
    vals, firing, waiting = p.frame(t[0])
    check(vals == bytes(MO.UNIVERSE_SIZE) and firing == [] and
          any("not armed" in x for x in waiting),
          f"settle 0, group not armed: nothing at all, not even the head: "
          f"{waiting}")
    fl["groups"][2]["armed"] = "armed"
    lock.locked.add("w1")
    vals, firing, waiting = p.frame(t[0])
    check(vals == bytes(MO.UNIVERSE_SIZE) and firing == [] and
          waiting == ["Waver 1: locked out"],
          f"settle 0, locked out: nothing at all: {waiting}")
    lock.locked.clear()
    p.selected = []
    vals, firing, _w = p.frame(t[0])
    check(vals == bytes(MO.UNIVERSE_SIZE) and firing == [],
          "settle 0, not selected: nothing")
    # The default still waits: the first frame is head only.
    cfg15 = cfg_with(1.5)
    p2 = MO.Purge(lambda: cfg15, _Lock(), lambda: _Link(), lambda: fl,
                  lambda: "", lambda: names, clock=lambda: t[0])
    p2.selected = ["w1"]
    vals, firing, waiting = p2.frame(t[0])
    check(vals[430] == 0 and vals[431] == w["pan_up"] and firing == [] and
          waiting == ["Waver 1: head going up (1.5 s)"],
          f"settle 1.5: the first frame is the head only: {waiting}")
    print("  ok")


def test_open_beyond_window_finder_and_front():
    """Open BEYOND (windowfront.py, Jeff, 2026-10-26): BEYOND's window is
    found by its process's program file (beyond*.exe, beyondwatch.py's
    names), restored, put in front with the AttachThreadInput and Alt key
    workaround, and its taskbar button flashed when Windows refuses. Every
    refusal is plain. Nothing is ever sent to BEYOND."""
    section("Open BEYOND: the window finder on a fake Windows, restore, "
            "the foreground workaround, the flash when Windows refuses, "
            "and the refusals (not Windows, another machine, not running)")
    from ltcplay import windowfront as WF
    from ltcplay import beyondwatch as BW
    check(WF.IMAGES == BW.IMAGES, "the same program names as the BEYOND "
                                  "watch")
    for p, want in (("C:\\Program Files\\Pangolin\\BEYOND\\BEYOND.exe", True),
                    ("beyond64.EXE", True), ("D:\\x\\Beyond Ultimate.exe",
                                             True),
                    ("C:\\x\\notbeyond.exe", False), ("beyond.dll", False),
                    ("", False), (None, False),
                    ("C:\\beyond.exe\\other.exe", False)):
        check(WF.is_beyond_image(p) is want, f"{p!r} is "
              f"{'' if want else 'not '}BEYOND's program")

    class FakeWin:
        """[(hwnd, visible, owner, pid, minimized)], {pid: image}. The
        foreground follows set_foreground unless `refuse` is set."""

        def __init__(self, wins, images, fg=1, refuse=False, hung=()):
            self.wins = wins
            self.images = images
            self.fg = fg
            self.refuse = refuse
            self.hung_set = set(hung)
            self.calls = []
            self.attached = set()

        def hung(self, h):
            return h in self.hung_set

        def _w(self, h):
            return [w for w in self.wins if w[0] == h][0]

        def windows(self):
            return [w[0] for w in self.wins]

        def visible(self, h):
            return self._w(h)[1]

        def owner(self, h):
            return self._w(h)[2]

        def pid(self, h):
            return self._w(h)[3]

        def thread(self, h):
            return 500 + h

        def image(self, pid):
            if pid == 666:
                raise OSError("access denied")
            return self.images.get(pid, "")

        def minimized(self, h):
            return self._w(h)[4]

        def restore(self, h):
            self.calls.append(("restore", h))

        def foreground(self):
            return self.fg

        def current_thread(self):
            return 42

        def attach(self, me, other, on):
            self.calls.append(("attach", me, other, on))
            (self.attached.add if on else self.attached.discard)(other)
            return True

        def set_foreground(self, h):
            self.calls.append(("fg", h))
            if not self.refuse:
                self.fg = h
            return not self.refuse

        def raise_async(self, h):
            self.calls.append(("raise", h))

        def flash(self, h):
            self.calls.append(("flash", h))
            return True
    imgs = {10: "C:\\Windows\\explorer.exe", 20: "C:\\BEYOND\\BEYOND.exe",
            30: "C:\\ltcplay\\ltcplay.exe"}
    wins = [(1, True, 0, 30, False),      # the rack screen, in front
            (2, False, 0, 20, False),     # BEYOND's hidden window
            (3, True, 7, 20, False),      # a BEYOND dialog (owned)
            (4, True, 0, 666, False),     # a process that cannot be read
            (5, True, 0, 20, True),       # BEYOND's main window, minimized
            (6, True, 0, 10, False)]
    api = FakeWin(wins, imgs)
    check(WF.find_beyond_window(api) == 5,
          "the finder picks BEYOND's visible main window, not a hidden "
          "one, not its dialog, not another program's")
    check(WF.find_beyond_window(FakeWin([w for w in wins if w[0] != 5],
                                        imgs)) == 3,
          "with no main window, an owned BEYOND window is still found")
    check(WF.find_beyond_window(FakeWin([wins[0], wins[5]], imgs)) is None,
          "no BEYOND window: None")
    ok, text = WF.open_beyond(None, windows=True, api=api)
    check(ok and api.fg == 5 and ("restore", 5) in api.calls and
          ("raise", 5) in api.calls and
          ("attach", 42, 501, True) in api.calls
          and ("attach", 42, 501, False) in api.calls and not api.attached
          and api.calls.index(("restore", 5)) < api.calls.index(("fg", 5))
          and api.calls.index(("attach", 42, 501, True)) <
          api.calls.index(("fg", 5)) and "in front" in text,
          f"restored, the input attached before SetForegroundWindow, "
          f"raised, the attach let go after; no key is pressed (the fake "
          f"has no key call at all): {ok} {text} {api.calls}")
    import inspect
    wsrc = inspect.getsource(WF)
    check("keybd_event" not in wsrc and "SendInput" not in wsrc and
          "VK_MENU" not in wsrc and "BringWindowToTop" not in wsrc and
          "ShowWindowAsync" in wsrc and "SWP_ASYNCWINDOWPOS" in wsrc and
          "u.ShowWindow(" not in wsrc,
          "windowfront presses no key and never waits on BEYOND's window "
          "(ShowWindowAsync, SetWindowPos with SWP_ASYNCWINDOWPOS)")
    # A BEYOND that is not responding is left alone.
    hung = FakeWin(wins, imgs, hung=(5,))
    ok, text = WF.open_beyond(None, windows=True, api=hung)
    check(not ok and text == WF.NOT_RESPONDING and not hung.calls,
          f"a hung BEYOND: not moved, said: {text} {hung.calls}")

    # The attach is let go even when the foreground call raises.
    class Raises(FakeWin):
        def set_foreground(self, h):
            raise OSError("stuck")
    rz = Raises(wins, imgs)
    ok, text = WF.open_beyond(None, windows=True, api=rz)
    check(not ok and ("attach", 42, 501, False) in rz.calls and
          not rz.attached, f"detached in finally: {rz.calls}")
    # The Opener: a worker thread, 3 s by default, one press at a time.
    import threading as _th
    check(WF.OPEN_TIMEOUT_S == 3.0 and WF.OPENER.timeout_s == 3.0,
          "Open BEYOND waits 3 s at most")
    gate = _th.Event()
    started = []

    def stuck(host):
        started.append(host)
        gate.wait(10)
        return True, "late"
    op = WF.Opener(stuck, timeout_s=0.2)
    t0 = time.monotonic()
    ok, text = op("127.0.0.2")
    check(not ok and text == WF.NOT_RESPONDING and
          time.monotonic() - t0 < 2.0 and started == ["127.0.0.2"],
          f"a press that hangs answers within the limit: {text}")
    ok, text = op("127.0.0.2")
    check(not ok and text == WF.BUSY and started == ["127.0.0.2"],
          f"a second press while the first is out starts nothing: {text}")
    gate.set()
    deadline = time.monotonic() + 5
    while op.busy() and time.monotonic() < deadline:
        time.sleep(0.01)
    op2 = WF.Opener(lambda host: (True, f"front {host}"), timeout_s=1.0)
    check(not op.busy() and op2("127.0.0.2") == (True, "front 127.0.0.2"),
          "once it ends a press goes again; a quick one answers")

    def boom(host):
        raise OSError("x")
    ok, text = WF.Opener(boom, timeout_s=1.0)(None)
    check(not ok and "could not be brought forward" in text,
          f"an error in the worker is said: {text}")
    api = FakeWin(wins, imgs, refuse=True)
    ok, text = WF.open_beyond("127.0.0.2", windows=True, api=api)
    check(not ok and ("flash", 5) in api.calls and "flashing" in text and
          "taskbar" in text and not api.attached,
          f"Windows refuses: the taskbar button flashes and it says so: "
          f"{text}")
    for t in (text,):
        check("—" not in t and "–" not in t, "no dashes")
    ok, text = WF.open_beyond(None, windows=False, api=FakeWin(wins, imgs))
    check(not ok and "Windows show PC" in text,
          f"not Windows: refused plainly: {text}")
    ok, text = WF.open_beyond("10.20.0.30", windows=True,
                              api=FakeWin(wins, imgs))
    check(not ok and "another machine" in text and "10.20.0.30" in text,
          f"BEYOND on another machine: refused plainly: {text}")
    none = FakeWin([wins[0], wins[5]], imgs)
    ok, text = WF.open_beyond(None, windows=True, api=none,
                              probe=lambda: False)
    check(not ok and "not running" in text and not none.calls,
          f"BEYOND not running: said, nothing moved: {text}")
    ok, text = WF.open_beyond(None, windows=True, api=none,
                              probe=lambda: True)
    check(not ok and "no window" in text, f"running, no window: {text}")
    ok, text = WF.open_beyond(None, windows=True, api=none,
                              probe=lambda: None)
    check(not ok and "No BEYOND window" in text, f"cannot tell: {text}")

    class Broken(FakeWin):
        def windows(self):
            raise OSError("boom")
    ok, text = WF.open_beyond(None, windows=True,
                              api=Broken(wins, imgs), probe=lambda: None)
    check(not ok and "No BEYOND window" in text,
          f"a failing window list never raises: {text}")
    import ast
    src = open(WF.__file__, encoding="utf-8").read()
    mods = {n.names[0].name for n in ast.walk(ast.parse(src))
            if isinstance(n, ast.Import)} | {
        n.module for n in ast.walk(ast.parse(src))
        if isinstance(n, ast.ImportFrom) and n.module}
    check(not ({"socket", "beyond", "lasertest", "laserarm"} & mods) and
          "sendto" not in src and "socket" not in src and
          "encode_osc" not in src,
          f"windowfront sends nothing anywhere: imports {sorted(mods)}")
    print("  ok")


def test_calibrate_all_lasers_rules_and_order():
    """Calibrate all lasers and Calibration off (lasertest.set_all, Jeff,
    2026-10-26): every armed, unlocked laser in config order through the
    one-laser rules; locked and unarmed lasers skipped and named; an
    undecided laser refused in words saying what to configure; the show
    state asked before each laser; off turns every test off."""
    section("Calibrate all lasers: armed, unlocked lasers in turn; locked "
            "and unarmed ones skipped and named; mechanism none says what "
            "to configure; a show going live stops it; Calibration off")
    from ltcplay import lasertest as LT
    sent = []

    class _Sock:
        def sendto(self, pkt, addr):
            sent.append((addr, pkt))

        def close(self):
            pass

    def osc(i):
        return {"id": f"l{i}", "name": f"Laser {i}", "mechanism": "osc",
                "host": "127.0.0.2", "port": 8100,
                "on": [["/beyond/general/startcue", i]],
                "off": [["/beyond/general/stopcue", i]]}
    lasers = LT.parse_lasers([osc(1), {"id": "l2", "name": "Laser 2"},
                              osc(3), osc(4), osc(5)], "x")
    locked, armed, lines = {"l4"}, {"l1", "l2", "l3", "l4"}, []
    lt = LT.LaserTests(lasers, locked=lambda lid: lid in locked,
                       journal=lambda t, **f: lines.append((t, f)),
                       socket_factory=_Sock, sleep=lambda s: None,
                       armed=lambda lid: lid in armed)
    order = []
    real = lt.set

    def spy(lid, on, **kw):
        order.append((lid, on))
        return real(lid, on, **kw)
    lt.set = spy
    ok, text = lt.set_all(True, who="Andy", device="Rack screen")
    check(ok and order == [("l1", True), ("l2", True), ("l3", True)] and
          sorted(lt.on) == ["l1", "l3"],
          f"armed, unlocked lasers in config order; locked l4 and unarmed "
          f"l5 never asked: {order} {sorted(lt.on)}")
    starts = [p for _a, p in sent if p.startswith(b"/beyond/general/startcue")]
    check(len(starts) == 6 and starts[0][-1] == 1 and starts[-1][-1] == 3,
          "each on list goes three times, Laser 1 first then Laser 3")
    check("Laser 1, Laser 3" in text and "Laser 4 (locked out)" in text and
          "Laser 5 (not armed)" in text and "Laser 2" in text and
          '"l2"' in text and '"mechanism": "osc"' in text and
          "MORNING.md" in text and "—" not in text and "–" not in text,
          f"skipped lasers named, the undecided one says what to set: "
          f"{text}")
    check(lines and "Calibrate all lasers" in lines[-1][0],
          f"journaled: {lines[-1] if lines else None}")
    # Off: every laser, whatever it was.
    del order[:]
    del sent[:]
    ok, text = lt.set_all(False, who="Andy")
    check(ok and not lt.on and [o for o in order] ==
          [(f"l{i}", False) for i in range(1, 6)] and
          "every laser test is off" in text,
          f"Calibration off turns every test off: {order} {text}")
    # Nothing armed: nothing goes on, and it says why.
    armed.clear()
    ok, text = lt.set_all(True, who="Andy")
    check(not ok and not lt.on and "No laser test went on" in text and
          "Laser 1 (not armed)" in text, f"nothing armed: {text}")
    # The show goes live part way: nothing after that goes on.
    armed.update({"l1", "l3", "l5"})
    asks = []

    def still_ok():
        asks.append(1)
        return "" if len(asks) < 3 else "a scheduled show is live (SHOW)"
    del order[:]
    ok, text = lt.set_all(True, who="Andy", still_ok=still_ok)
    check(ok and sorted(lt.on) == ["l1"] and ("l3", True) not in order and
          "Stopped there" in text and "show is live" in text,
          f"asked before each laser; once a show is live nothing more "
          f"goes on: {order} {text}")
    lt.set_all(False)
    # The show-state check itself failing stops it: fail closed (review
    # of PR #125, P2-4).
    del order[:]
    del sent[:]

    def raises():
        raise RuntimeError("no state")
    ok, text = lt.set_all(True, who="Andy", still_ok=raises)
    check(not ok and not lt.on and not order and not sent and
          "Stopped there" in text and "could not be read" in text,
          f"a still_ok that raises: nothing goes on, nothing is sent: "
          f"{text}")
    # A lockout that cannot be read counts as locked: skipped, named,
    # nothing sent.
    lt3 = LT.LaserTests(lasers, locked=lambda lid: 1 / 0,
                        socket_factory=_Sock, sleep=lambda s: None,
                        armed=lambda lid: True)
    ok, text = lt3.set_all(True, who="Andy")
    check(not ok and not lt3.on and not sent and
          "Laser 1 (locked out)" in text and "Laser 5 (locked out)" in text,
          f"a lockout that raises: every laser skipped as locked: {text}")
    # MORNING.md's example lasers entry is valid JSON (inside {}) and a
    # valid laser.
    import re as _re
    import json as _json
    md = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                           "MORNING.md"), encoding="utf-8").read()
    sec = md[md.find("### How to set up the laser calibration cue"):]
    # A plain block (not ```json: the fireball test reads every json
    # block of the file as a whole document), a fragment of the file.
    ex = _re.findall(r"```\n(.*?)\n```", sec, _re.S)
    try:
        got = LT.parse_lasers(_json.loads("{" + ex[0] + "}")["lasers"],
                              "MORNING.md")
        ok_ex = got[0].mechanism == "osc" and got[0].on and got[0].off
    except Exception as e:                       # noqa: BLE001
        ok_ex = f"{type(e).__name__}: {e}"
    check(ok_ex is True or (ok_ex and not isinstance(ok_ex, str)),
          f"MORNING.md's calibration cue example parses: {ok_ex}")
    # The single-laser refusal names what to configure too.
    lt2 = LT.LaserTests(lasers, socket_factory=_Sock, sleep=lambda s: None,
                        armed=lambda lid: True)
    ok, text = lt2.set("l2", True)
    check(not ok and "placeholder" in text and '"l2"' in text and
          '"on"' in text and '"off"' in text, f"one laser: {text}")
    print("  ok")


def test_calibrate_all_and_open_beyond_routes():
    """The Startup page's Calibrate all lasers, Calibration off and Open
    BEYOND through the engine's routes: every rule of a laser test ON
    (no show live, no Abort, screen_arming from the network, Arrange mode,
    the unlock row), and Open BEYOND only on the show machine, never while
    a show is live or an Abort stands, signed in or not."""
    section("Startup page: Calibrate all lasers and Open BEYOND through the "
            "engine, with every rule")
    S = _sched()
    if S is None:
        return
    from dataclasses import replace as _rep
    from ltcplay import remote as RM
    from ltcplay import users as U
    R = _morning_rig(S, config=_MO_CONFIG)
    loop = ("127.0.0.1", 5000)
    ipad = ("10.20.0.44", 50000)
    try:
        R.m.tick()
        check(U.classify("/api/remote/open-beyond", {}) is None and
              U.classify("/api/remote/laser-test",
                         {"all": True, "on": True}) == "unlock" and
              U.classify("/api/remote/laser-test",
                         {"all": True, "on": False}) == "safety",
              "Open BEYOND is harmless; Calibrate all is a test ON; "
              "Calibration off is safety")
        check("open-beyond" in RM.MORNING_POST_ROUTES, "the route exists")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 409 and "No laser test went on" in out["error"] and
              not R.m.lasers.on, f"nothing armed: refused: {out}")
        _mo_arm(R, "laser-1", "laser-3", "laser-4")
        R.m.lockout.set(R.m.cfg, "laser", "laser-4", True, "Andy", "Rack")
        R.m.tick()
        _mo_arm(R, "laser-3")
        del R.osc[:]
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 200 and sorted(R.m.lasers.on) == ["laser-3"] and
              "Laser 4 (locked out)" in out["text"] and
              "Laser 2 (not armed)" in out["text"] and
              '"laser-1"' in out["text"] and R.osc,
              f"armed Laser 3 goes on; locked Laser 4 and unarmed Laser 2 "
              f"skipped; undecided Laser 1 says what to set: {out}")
        RM.save_settings(R.work, screen_arming=False)
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=ipad)
        check(st == 403 and "screen_arming" in out["error"],
              f"from the network it needs screen_arming: {out}")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": False}, client=ipad)
        check(st == 200 and not R.m.lasers.on,
              f"Calibration off goes from anywhere: {out}")
        RM.save_settings(R.work, screen_arming=True)
        R.m.open_beat("Rack screen", arranging=True, inst="c", seq=1)
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 409 and "Arrange" in out["error"] and
              not R.m.lasers.on, f"Arrange holds it back: {out}")
        R.m.open_beat("Rack screen", arranging=False, inst="c", seq=2)
        live = R.m._live_check
        R.m._live_check = lambda: "a scheduled show is live (SHOW)"
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 409 and "not allowed now" in out["error"] and
              not R.m.lasers.on, f"not while a show is live: {out}")
        # The show goes live part way through: the engine asks again
        # before each laser, so nothing after that goes on.
        asks = []

        def goes_live():
            asks.append(1)
            return "" if len(asks) < 3 else "a scheduled show is live (SHOW)"
        R.m._live_check = goes_live
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 409 and not R.m.lasers.on and "Stopped there" in
              out["error"] and len(asks) == 3,
              f"live part way: Laser 3 never goes on: {out} {len(asks)}")
        R.m._live_check = live
        # Open BEYOND.
        calls = []

        def fake(host):
            calls.append(host)
            return True, "BEYOND is in front on the show PC."
        R.remote.open_beyond_fn = fake
        R.remote.beyond_host = "127.0.0.2"
        n_osc = len(R.osc)
        # Between shows (STANDBY) the rack screen stays in front (review
        # of PR #125, P2-3); so does it on Hold.
        check(R.svc.machine.state == "STANDBY", "setup: between shows")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "STANDBY" in out["error"] and not calls,
              f"Open BEYOND between shows: refused: {out}")
        m_standby = R.svc.machine
        R.svc.machine = _rep(m_standby, state="HOLD")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "Hold" in out["error"] and not calls,
              f"Open BEYOND on Hold: refused: {out}")
        R.svc.machine = _rep(m_standby, state="IDLE")
        # With the calibration test ON, Open BEYOND goes: bringing BEYOND
        # forward to adjust is the point of it (Jeff, 2026-10-26). And
        # Calibration off still works from the rack screen afterwards.
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": True}, client=loop)
        check(st == 200 and "laser-3" in R.m.lasers.on,
              f"setup: the calibration test is on: {out}")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 200 and calls == ["127.0.0.2"] and
              "laser-3" in R.m.lasers.on,
              f"Open BEYOND with the calibration test on: it goes, the "
              f"test stays on: {out}")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"all": True, "on": False}, client=loop)
        check(st == 200 and not R.m.lasers.on,
              f"Calibration off from the rack screen afterwards: {out}")
        del calls[:]
        n_osc = len(R.osc)
        # Anything else going on at the rig keeps the rack screen in front.
        R.m.purge.selected = ["g1"]
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "purge" in out["error"] and not calls,
              f"a purge selection: refused: {out}")
        R.m.purge.selected = []
        R.m.purge.fire = {"id": 1}
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "purge is firing" in out["error"] and not calls,
              f"a purge press: refused: {out}")
        R.m.purge.fire = None
        R.remote._holds[0] = {"token": "t", "who": "x", "device": "d",
                              "start": 0, "beat": 0, "id": 1,
                              "group": "front row"}
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "hold to arm" in out["error"] and not calls,
              f"a hold to arm in progress: refused: {out}")
        R.remote._holds.clear()
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=ipad)
        check(st == 403 and "show machine" in out["error"] and not calls,
              f"Open BEYOND from the network: refused: {out}")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 200 and calls == ["127.0.0.2"] and
              len(R.osc) == n_osc and "in front" in out["text"],
              f"on the show machine: the window call, BEYOND's host, "
              f"nothing sent: {out}")
        check(any(r.get("action") == "open-beyond"
                  for r in R.svc.journal), "journaled")
        m0 = R.svc.machine
        R.svc.machine = _rep(m0, abort_latched=True)
        try:
            st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                                client=loop)
            check(st == 409 and "aborted" in out["error"] and
                  len(calls) == 1, f"not while an Abort stands: {out}")
        finally:
            R.svc.machine = m0
        R.remote.open_beyond_fn = lambda host: (False, "BEYOND is not "
                                                "running on this PC.")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "not running" in out["error"],
              f"a refusal from the finder is said: {out}")
        R.remote.open_beyond_fn = None
        # With nothing injected the press goes through windowfront's
        # Opener (a worker thread and a time limit), never the bare call.
        from ltcplay import windowfront as _WF
        real_opener, via = _WF.OPENER, []
        _WF.OPENER = lambda host: via.append(host) or (False, "spy")
        try:
            st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                                client=loop)
        finally:
            _WF.OPENER = real_opener
        check(via == ["127.0.0.2"] and out.get("error") == "spy",
              f"the press uses windowfront.OPENER: {via} {out}")
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        if sys.platform != "win32":
            check(st == 409 and "Windows show PC" in out["error"],
                  f"the real call off Windows refuses plainly: {out}")
        R.svc.machine = m_standby
        _live_show(R)
        R.remote.open_beyond_fn = fake
        st, _h, out = R.ask("POST", "/api/remote/open-beyond", {},
                            client=loop)
        check(st == 409 and "live" in out["error"] and len(calls) == 1,
              f"not while a show is live: {out}")
        page = open(os.path.join(os.path.dirname(os.path.abspath(
            __file__)), "ltcplay", "web", "remote.html"),
            encoding="utf-8").read()
        for need in ('moPress("laser-test", {all:true, on:true}, "mo-lmsg")',
                     'moPress("laser-test", {all:true, on:false}, "mo-lmsg")',
                     'moPress("open-beyond", {}, "mo-lmsg")',
                     ">Calibrate all lasers<", ">Calibration off<",
                     ">Open BEYOND<",
                     '$("mo-beyond").hidden = !(ME && ME.local);'):
            check(need in page, f"the Startup page has {need!r}")
    finally:
        R.close()
    print("  ok")


def test_witness_checker_rules():
    """The stress witness checker's own rules (tools/stress/witness), run
    here so a change to them is caught per PR. Cold review of PR #107,
    P2-3: a locked safety slot carrying the arm value is flagged; fire with
    every safety of a multi-safety group locked is fire without arm; a
    one-safety group's safety counts even when it is in the locked list."""
    section("stress witness checker: its rules, multi-safety included")
    import subprocess
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                        "tools", "stress", "witness")
    r = subprocess.run([sys.executable, "-m", "unittest", "-q",
                        "test_witness.TestChecker"], cwd=here,
                       capture_output=True, text=True, timeout=120)
    tail = (r.stdout + r.stderr).strip().splitlines()[-12:]
    check(r.returncode == 0, "the witness checker's tests pass: "
          + " | ".join(tail))


def test_morning_config_layout_and_lockout_file():
    section("Morning and Shutdown: ltcplay_morning.json (machines, Jeff's four "
            "groups, placeholder purge values, lasers, checklists, names, "
            "the tally), the default machine list from flamesafe's groups, "
            "the layout file, and the lockout file with one writer")
    import json as _j
    import shutil
    import tempfile
    from ltcplay import morning as MO
    from ltcplay import lasertest as LT
    here = os.path.dirname(os.path.abspath(__file__))
    check(MO.GROUP_NAMES == ("Ground G-Flames", "Scaffold G-Flames",
                             "Scaffold Wavers", "Fireball"),
          f"Jeff's group names, exactly: {MO.GROUP_NAMES}")
    groups = MO.load_flamesafe_groups(
        os.path.join(here, "flamesafe", "flamesafe.example.json"))
    cfg = MO.MorningConfig.parse({}, "x", groups)
    check(len(cfg.machines) == sum(len(g["safeties"]) if
                                   len(g["safeties"]) > 1 else len(g["fire"])
                                   for g in groups),
          f"no file: one machine per flamesafe fire slot, and one per "
          f"fixture of a multi-safety group ({len(cfg.machines)})")
    check(set(cfg.banks) == set(MO.GROUP_NAMES) and
          cfg.banks["Fireball"] == ["fireball"] and
          cfg.banks["Scaffold Wavers"] == ["wave-flamer-1", "wave-flamer-2",
                                            "wave-flamer-3"],
          f"the default groups sort by name: {cfg.banks}")
    check(cfg.purge == MO.PURGE_DEFAULTS and
          cfg.purge["gflame_fire"] == 255 and
          cfg.purge["waver"]["head_settle_s"] == 1.5,
          f"placeholder purge values: {cfg.purge}")
    check([l.id for l in cfg.lasers] == ["laser-1", "laser-2", "laser-3",
                                         "laser-4"] and
          all(l.mechanism == "none" for l in cfg.lasers),
          "four undecided lasers")
    check(set(cfg.checklists) == {"morning", "shutdown"} and
          not cfg.checklists["morning"]["steps"] and cfg.names == [] and
          cfg.tally["enabled"] is False, "empty checklists, no names, tally off")
    # The shipped example loads against flamesafe's example config.
    ex = MO.MorningConfig.load(
        os.path.join(here, "ltcplay", "ltcplay_morning.example.json"), groups)
    check([m.id for m in ex.machines][:2] == ["ground-1", "ground-2"] and
          ex.by_id["waver-1"].kind == "waver" and
          ex.by_id["waver-1"].channels() == {421, 422, 423} and
          ex.banks["Scaffold Wavers"] == ["waver-1"] and
          ex.names == ["Andy", "Jeff"] and ex.tally["enabled"] is False and
          ex.checklists["morning"]["steps"][0]["id"] == "sample-1",
          "ltcplay_morning.example.json loads: machines, groups, names, the "
          "sample checklist, the tally off")
    txt = open(os.path.join(here, "ltcplay", "ltcplay_morning.example.json"),
               encoding="utf-8").read()
    check("—" not in txt and "–" not in txt and "PLACEHOLDER" in txt,
          "the example has no dashes and marks its placeholders")
    # A real config, and every refusal in a sentence.
    c = MO.MorningConfig.parse(_j.loads(_j.dumps(_MO_CONFIG)), "x",
                               _MO_FLAMESAFE["groups"])
    check([m.id for m in c.machines] == ["g1", "g2", "s1", "w1"] and
          c.banks == {"Ground G-Flames": ["g1", "g2"],
                      "Scaffold G-Flames": ["s1"], "Scaffold Wavers": ["w1"],
                      "Fireball": []} and c.purge["gflame_fire"] == 240 and
          c.by_id["w1"].channels() == {431, 432, 433},
          f"a written config parses: {c.banks}")

    def bad(what, doc, groups=_MO_FLAMESAFE["groups"]):
        try:
            MO.MorningConfig.parse(doc, "x", groups)
            check(False, f"accepted: {what}")
        except MO.MorningConfigError as e:
            check(str(e).endswith(".") and "—" not in str(e) and
                  "–" not in str(e), f"{what}: refused in a sentence "
                                           f"with no dashes: {e}")

    def with_(**over):
        d = _j.loads(_j.dumps(_MO_CONFIG))
        d.update(over)
        return d
    bad("an unknown top key", with_(machins=[]))
    bad("a slot not in the machine's flamesafe group",
        with_(machines=[{"id": "x", "group": "front row", "fire": [421]}]))
    bad("a group flamesafe does not have",
        with_(machines=[{"id": "x", "group": "upstairs", "fire": [411]}]))
    bad("two machines on one slot",
        with_(machines=[{"id": "a", "group": "front row", "fire": [411]},
                        {"id": "b", "group": "front row", "fire": [411]}]))
    bad("a waver without pan and tilt",
        with_(machines=[{"id": "w", "kind": "waver", "group": "wave flamer",
                         "fire": [431]}]))
    bad("a waver whose pan is its tilt",
        with_(machines=[{"id": "w", "kind": "waver", "group": "wave flamer",
                         "fire": [431], "pan": 432, "tilt": 432}]))
    bad("a gflame with a pan",
        with_(machines=[{"id": "x", "group": "front row", "fire": [411],
                         "pan": 412}]))
    bad("a slot out of range",
        with_(machines=[{"id": "x", "group": "front row", "fire": [0]}],
              ), groups=None)
    bad("a group name that is not one of Jeff's four",
        with_(groups={"Ground": ["g1"]}))
    bad("a group naming a machine that does not exist",
        with_(groups={"Fireball": ["nope"]}))
    bad("a machine in two groups",
        with_(groups={"Fireball": ["g1"], "Ground G-Flames": ["g1"]}))
    bad("a purge value over 255", with_(purge={"gflame_fire": 256}))
    bad("a purge key nobody has", with_(purge={"gflame": 1}))
    bad("a head settle time of a minute",
        with_(purge={"waver": {"head_settle_s": 60}}))
    bad("a head settle time below 0",
        with_(purge={"waver": {"head_settle_s": -0.1}}))
    bad("a laser mechanism nobody has",
        with_(lasers=[{"id": "l1", "mechanism": "magic"}]))
    bad("an osc laser with no messages",
        with_(lasers=[{"id": "l1", "mechanism": "osc", "host": "127.0.0.2",
                       "port": 8100}]))
    bad("BEYOND's BlackOut as a laser message",
        with_(lasers=[{"id": "l1", "mechanism": "osc", "host": "127.0.0.2",
                       "port": 8100,
                       "on": [["/beyond/general/BlackOut", 1]]}]))
    bad("an OSC wildcard in a laser message",
        with_(lasers=[{"id": "l1", "mechanism": "osc", "host": "127.0.0.2",
                       "port": 8100, "on": [["/beyond/zones/*/x", 1]]}]))
    bad("two lasers with one id",
        with_(lasers=[{"id": "l1"}, {"id": "l1"}]))
    bad("a name listed twice", with_(names=["Andy", "Andy"]))
    bad("a tally over plain http",
        with_(tally={"enabled": False, "url": "http://x.example/t"}))
    bad("a tally enabled with no URL", with_(tally={"enabled": True}))
    bad("a tally enabled with a word", with_(tally={"enabled": "yes",
                                                     "url": "https://x/"}))
    bad("a checklist step with no words",
        with_(checklists={"morning": {"steps": [{"id": "a", "text": ""}]}}))
    bad("two steps with one id",
        with_(checklists={"morning": {"steps": [{"id": "a", "text": "x"},
                                                {"id": "a", "text": "y"}]}}))
    # A laser with messages parses, and encodes what it will send.
    ok = MO.MorningConfig.parse(with_(lasers=[
        {"id": "l1", "name": "Laser 1", "mechanism": "osc", "host": "127.0.0.2",
         "port": 8100, "on": [["/beyond/general/startcue", 3]],
         "off": [["/beyond/general/stopcue", 3]],
         "lock": [["/beyond/zones/1/enable", 0.0]]}]), "x",
        _MO_FLAMESAFE["groups"])
    check(ok.lasers[0].on == [("/beyond/general/startcue", 3)] and
          ok.lasers[0].view()["configured"] is True, "an osc laser parses")
    # The layout: a default by group row, saved positions, refusals.
    d = tempfile.mkdtemp()
    try:
        lay = MO.Layout(os.path.join(d, MO.LAYOUT_FILE))
        pos, saved = lay.load(c)
        check(not saved and set(pos) == {"g1", "g2", "s1", "w1"} and
              pos["g1"]["y"] > pos["s1"]["y"] > pos["w1"]["y"],
              f"the default layout: ground at the front, wavers behind: {pos}")
        got = lay.save(c, {"g1": {"x": 10, "y": 90.44}})
        check(got == {"g1": {"x": 10.0, "y": 90.4}}, "saved, rounded")
        pos2, saved2 = lay.load(c)
        check(saved2 and pos2["g1"] == {"x": 10.0, "y": 90.4} and
              pos2["s1"] == pos["s1"], "a saved position is read back; the "
                                       "rest keep the default")
        for badpos in ({"nope": {"x": 1, "y": 1}}, {"g1": {"x": 101, "y": 1}},
                       {"g1": {"x": "a", "y": 1}}, [1]):
            try:
                lay.save(c, badpos)
                check(False, f"a bad layout was saved: {badpos}")
            except ValueError:
                check(True, "a bad layout is refused")
        # The lockout file: one writer, atomic, read back after a restart.
        lines = []
        lk = MO.Lockout(os.path.join(d, MO.LOCKOUT_FILE),
                        journal=lambda t, **f: lines.append((t, f)),
                        wall=lambda: 1_800_000_000.0)
        ok, text = lk.set(c, "machine", "w1", True, "", "Rack screen",
                          reason="valve sticks")
        check(ok and "locked out" in text, f"locked: {text}")
        doc = _j.load(open(os.path.join(d, MO.LOCKOUT_FILE), encoding="utf-8"))
        check(doc["lockout_format"] == 1 and
              doc["flame_channels"] == [431, 432, 433] and
              "w1" in doc["machines"] and
              doc["machines"]["w1"]["reason"] == "valve sticks",
              f"the file carries every slot the machine owns for flamesafe: "
              f"{doc['flame_channels']}")
        check(lines and "LOCKED OUT" in lines[-1][0] and
              lines[-1][1].get("action") == "lockout",
              f"journaled: {lines[-1]}")
        ok, text = lk.set(c, "machine", "w1", False, "", "Rack screen")
        check(not ok and "confirm" in text and lk.is_locked("machine", "w1"),
              f"unlock without the confirm is refused: {text}")
        lk2 = MO.Lockout(os.path.join(d, MO.LOCKOUT_FILE))
        check(lk2.is_locked("machine", "w1") and
              lk2.channels(c) == {431, 432, 433},
              "a new engine reads the lock back: it survives a restart")
        ok, text = lk2.set(c, "laser", "laser-1", True, "Andy", "iPad")
        check(ok and lk2.is_locked("laser", "laser-1"), "a laser locks too")
        ok, text = lk2.set(c, "machine", "nope", True, "", "x")
        check(not ok, "an unknown machine is refused")
        ok, text = lk2.set(c, "machine", "w1", False, "Andy", "Rack screen",
                           confirmed=True)
        check(ok and not lk2.is_locked("machine", "w1") and
              _j.load(open(os.path.join(d, MO.LOCKOUT_FILE)))["flame_channels"]
              == [], "unlocked with the confirm, and the file says so")
        with open(os.path.join(d, MO.LOCKOUT_FILE), "w") as fh:
            fh.write("{ broken")
        lk3 = MO.Lockout(os.path.join(d, MO.LOCKOUT_FILE))
        check(lk3.load_error and not lk3.machines,
              f"a broken file is said, not guessed: {lk3.load_error}")
    finally:
        shutil.rmtree(d, ignore_errors=True)
    check(LT.FORBIDDEN_ADDRESSES == frozenset(("/beyond/general/BlackOut",
                                               "/beyond/general/MasterPause")),
          "the laser tests refuse the same two BEYOND addresses beyond.py "
          "does, by name")
    print("  ok")


def test_purge_frame_on_the_flame_link():
    section("Morning and Shutdown, the flame link: the purge frame goes out "
            "only while the show is not live, only for 0.25 s after the last "
            "heartbeat on the link's own clock, never after zero() or "
            "disarm_all(); locked channels are zero in every frame (T1, T2, "
            "T5, T7)")
    from ltcplay import flamelink as fl
    key = _fl_key()
    cfg = fl.FlameLinkConfig("127.0.0.1", 5571, 1, key, frame_stale_ms=500)
    t = [100.0]
    state = {"tc": None, "live": False}
    sent = []
    link = fl.FlameLink(cfg, cues=lambda tc: [200] * 512,
                        show_state=lambda: (state["tc"], state["live"]),
                        clock=lambda: t[0], seek_guard=False)
    link._send = lambda data: sent.append(data) or True
    check(fl.PURGE_HOLD_S == 0.25, "the purge frame lives 0.25 s")
    frame = bytes([0] * 410 + [240] + [0] * 101)
    check(link.purge_set(frame) is True and link.purge_active(),
          "a purge frame is taken")
    tc, vals = link.values_now()
    check(vals == frame, "with no show live the purge frame goes out")
    link.send_frame()
    import json as _j
    got = _j.loads(sent[-1])
    check(got["values"][410] == 240 and sum(got["values"]) == 240,
          "and reaches the wire while the conductor has the cues zeroed "
          "(zeroed is True between shows)")
    t[0] += fl.PURGE_HOLD_S + 0.01
    tc, vals = link.values_now()
    check(vals == bytes(512) and not link.purge_active(),
          "0.26 s after the last heartbeat it is gone, on the link's clock")
    link.purge_set(frame)
    state.update(tc="00:00:01:00", live=True)
    link.release()
    t[0] += 0.03
    tc, vals = link.values_now()
    check(vals != frame and vals[410] != 240,
          "a live show: the purge frame is ignored, the cue path decides")
    state.update(live=False)
    link.purge_set(frame)
    check(link.values_now()[1] == frame, "not live again: the purge frame")
    link.zero()
    check(not link.purge_active() and link.values_now()[1] == bytes(512),
          "zero() clears it")
    link.purge_set(frame)
    state.update(live=True)
    t[0] += 0.03
    check(link.zeroed and link.values_now()[1] == bytes(512),
          "a live show with the cues zeroed (a Hold): still no purge frame")
    state.update(live=False)
    link.purge_set(frame)
    link.disarm_all("Abort from the rack screen")
    check(not link.purge_active() and link.values_now()[1] == bytes(512),
          "disarm_all() clears it")
    link.purge_set(frame)
    link.purge_clear()
    check(not link.purge_active(), "purge_clear() clears it")
    check(link.purge_set(b"short") is False and link.purge_set(None) is False,
          "a frame that is not 512 bytes is refused")
    # Locked channels are zero in a purge frame and in a cue frame.
    link.set_locked_channels({411, 2})
    link.purge_set(frame)
    check(link.values_now()[1] == bytes(512), "a locked slot's purge is zero")
    state.update(live=True)
    link.release()
    t[0] += 0.03
    vals = link.values_now()[1]
    check(vals[410] == 0 and vals[1] == 0 and vals[0] == 200 and
          vals[2] == 200, f"locked slots are zero in a cue frame too, the "
                          f"rest untouched: {vals[:3]} {vals[410]}")
    snap = link.snapshot()
    check(snap["locked_channels"] == [2, 411] and snap["purge"] is True and
          snap["purges_sent"] >= 2, f"the snapshot says so: {snap}")
    print("  ok")


def test_purge_rules_at_the_engine():
    section("Morning and Shutdown, the engine: a click arms a machine for the "
            "purge only from a listed device with purge arming on, a fresh "
            "page, a fresh flamesafe, the deck reading, no show live, no "
            "Abort standing, the machine not locked; one device owns the "
            "selection; the fire heartbeat sets the purge frame for armed "
            "groups only, a Waver's head first; a gap, a lost page, an Abort "
            "or a lock stop it (T1 to T9, T12, T13)")
    S = _sched()
    if S is None:
        return
    import json as _j
    from ltcplay import remote as RM
    from ltcplay import morning as MO
    check(MO.BEAT_STALE_S == 0.25 and MO.OPEN_STALE_S == 2.0 and
          MO.FRESH_S == 1.0, "the purge numbers are what MORNING.md says")
    R = _morning_rig(S, _MO_CONFIG)
    loop = ("127.0.0.1", 5000)
    ipad = ("10.20.0.44", 50000)
    try:
        link = R.link
        # The view, and the routes exist only here.
        st, _h, out = R.ask("GET", "/api/remote/morning", client=loop)
        check(st == 200 and [m["id"] for m in out["machines"]] ==
              ["g1", "g2", "s1", "w1"] and out["groups"]["Scaffold Wavers"] ==
              ["w1"] and out["purge_enabled"] is True and
              out["lasers"][0]["configured"] is False and
              out["checklists"]["names"] == ["Andy", "JH"] and
              "g1" in out["layout"],
              f"the page's view: machines, groups, layout, lasers, names: {st}")
        # Switched off: refused before anything is looked at.
        RM.save_settings(R.work, purge_arming=False)
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 403 and "switched off" in out["error"],
              f"purge_arming false refuses: {st} {out}")
        try:
            RM.save_settings(R.work, purge_arming="yes")
            check(False, "purge_arming of \"yes\" was read")
        except ValueError:
            check(True, "purge_arming has to be true or false")
        RM.save_settings(R.work, purge_arming=True, screen_arming=False)
        check(RM.load_settings(R.work)["purge_arming"] is True,
              "and true is on (the default when the key is absent)")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=ipad)
        check(st == 403 and "screen_arming" in out["error"],
              f"a device on the show network needs screen_arming too: {st}")
        RM.save_settings(R.work, screen_arming=True)
        # The deck must be reading: it is what arms the group.
        R.remote._deck_seen = R.mono[0] - 3.0
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "Stream Deck" in out["error"],
              f"no deck reading the engine: nothing is armed: {st} {out}")
        R.remote._deck_seen = R.mono[0]
        # A stale page, a stale flamesafe.
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen() - 1500},
                            client=loop)
        check(st == 409 and "1 s old" in out["error"],
              f"a page status 1.5 s old: {st} {out}")
        R.mono[0] += 1.1
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "flamesafe" in out["error"],
              f"flamesafe quiet 1.1 s: {st} {out}")
        R.feed()
        # Unknown and locked machines.
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "zz", "seen": R.seen()}, client=loop)
        check(st == 400, "an unknown machine")
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "machine", "id": "g2", "on": True,
                             "reason": "leaks"}, client=loop)
        check(st == 200 and R.m.lockout.is_locked("machine", "g2") and
              link.locked == {412},
              f"a lock writes the file and tells the flame link: {st} {out}")
        # flamesafe has not confirmed the lock (it says nothing about a
        # lockout file, or has none): no purge at all until it does, and
        # the journal says so once (review of PR #68, P2-2).
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "not confirmed" in out["error"] and
              "Ground 2" in out["error"],
              f"flamesafe silent on the lock: no purge of anything: {st} {out}")
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        check(out["morning"]["locked_machines"] == ["Ground 2"] and
              out["morning"]["flamesafe_confirmed"] is None,
              f"the status carries the lock banner, unconfirmed: "
              f"{out['morning']}")
        R.fs_lockout = {"slots": [], "state": "none"}
        R.feed()
        R.m.tick()
        check(any(r.get("action") == "lockout" and r.get("outcome") ==
                  "unconfirmed" for r in R.svc.journal),
              "flamesafe with no lockout_file: a fault line in the journal")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "asked for [412]" in out["error"],
              f"flamesafe holding other slots than asked: no purge: {out}")
        R.fs_lockout = {"slots": [412], "state": "read"}
        R.feed()
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        check(out["morning"]["flamesafe_confirmed"] is True,
              "and says when flamesafe reports the same slots locked")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g2", "seen": R.seen()}, client=loop)
        check(st == 409 and "locked out" in out["error"],
              f"a locked machine cannot be armed for a purge: {st} {out}")
        # A clean click: the selection, and the deck is told which group.
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 200 and out["selected"] == ["g1"],
              f"a click arms Ground 1 for the purge: {st} {out}")
        R.m.open_beat("Rack screen")
        d = R.remote.deck_input()
        check(d["morning"]["open"] is True and
              d["morning"]["purge"]["wanted_groups"] == [0] and
              d["morning"]["purge_enabled"] is True,
              f"deck-input says the page is open and group 0 is wanted: "
              f"{d['morning']}")
        check(any(r.get("action") == "purge" and r.get("outcome") ==
                  "selected" for r in R.svc.journal),
              "journaled with the surface")
        # Another device cannot take or add to the selection.
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "s1", "seen": R.seen()}, client=ipad)
        check(st == 409 and "One device at a time" in out["error"],
              f"a second device is refused: {st} {out}")
        # Fire: nothing is armed at flamesafe yet (front row disarmed), so
        # the frame is empty and the page is told why.
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=loop)
        check(st == 200 and out["firing"] == [] and
              "not armed" in out["waiting"][0] and link.frames == [],
              f"a fire press with the group not armed sends nothing: {out}")
        fid = out["fire_id"]
        # flamesafe arms the group (the deck did its part): the next beat
        # carries the fire value on that machine's slot only.
        R.groups[0]["armed"] = "armed"
        R.groups[0]["wanted"] = True
        R.feed()
        R.mono[0] += 0.1
        R.wall[0] += 0.1
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        check(st == 200 and out["firing"] == ["Ground 1"] and link.frames and
              link.frames[-1][410] == 240 and sum(link.frames[-1]) == 240,
              f"armed: 240 on slot 411 and nothing else: {out}")
        # A heartbeat from another device, or with a stale id, is refused.
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=ipad)
        check(st == 409 and out.get("let_go"),
              f"another device cannot carry the fire on: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid,
                             "who": "Stream Deck", "screen": "Stream Deck"},
                            client=loop)
        check(st == 409 and "only that device" in out["error"] and
              out.get("let_go") and R.m.purge.fire is not None,
              f"nor can the deck process carry on the page's press with its "
              f"id; the page's own press is not ended by the refusal: {st} "
              f"{out}")
        # Nor can another device end the owner's press or selection
        # (review of PR #68, P2-11); Abort is the path everyone has.
        st, _h, out = R.ask("POST", "/api/remote/purge-stop", {}, client=ipad)
        check(st == 409 and R.m.purge.fire is not None,
              f"another device cannot stop the owner's press: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-clear", {},
                            client=ipad)
        check(st == 409 and R.m.purge.selected == ["g1"],
              f"nor clear the owner's selection: {st} {out}")
        # A gap of more than 0.25 s ends the press.
        before = link.cleared
        R.mono[0] += 0.3
        R.wall[0] += 0.3
        R.feed()
        R.m.tick()
        check(link.cleared > before and R.m.purge.fire is None,
              "0.3 s without a heartbeat: the frame is cleared by the watcher")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        check(st == 409 and "interrupted" in out["error"],
              f"and the old press cannot carry on: {out}")
        # A Waver: head up first, fire only after head_settle_s of beats
        # counted from the first beat on which it is selected AND its group
        # is armed, never from the press's start (review of PR #68, P1-1):
        # here the group arms 0.5 s into the press.
        R.groups[2]["armed"] = "disarmed"
        R.groups[2]["wanted"] = False
        R.feed()
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "w1", "seen": R.seen()}, client=loop)
        check(st == 200 and out["selected"] == ["g1", "w1"], "the Waver joins")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=loop)
        f = link.frames[-1]
        check(st == 200 and f[431] == 0 and f[432] == 0 and f[430] == 0 and
              f[410] == 240 and "not armed" in out["waiting"][0],
              f"first beat: the Waver's group is not armed, so not even its "
              f"head moves; Ground 1 fires: {out}")
        fid = out["fire_id"]
        for _ in range(5):
            R.mono[0] += 0.1
            R.wall[0] += 0.1
            R.feed()
            st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                                {"on": True, "seen": R.seen(), "fire_id": fid},
                                client=loop)
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "s1", "seen": R.seen()}, client=loop)
        check(st == 409 and "firing right now" in out["error"] and
              R.m.purge.selected == ["g1", "w1"],
              f"a machine never joins a live fire press: {st} {out}")
        R.groups[2]["armed"] = "armed"
        R.groups[2]["wanted"] = True
        R.feed()
        R.mono[0] += 0.1
        R.wall[0] += 0.1
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        f = link.frames[-1]
        check(st == 200 and f[431] == 100 and f[432] == 200 and f[430] == 0
              and f[410] == 240 and "head going up" in out["waiting"][0],
              f"0.6 s into the press the group arms: pan 100 and tilt 200 at "
              f"once, no fire on the Waver yet, Ground 1 fires: {out}")
        for _ in range(9):
            R.mono[0] += 0.1
            R.wall[0] += 0.1
            R.feed()
            st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                                {"on": True, "seen": R.seen(), "fire_id": fid},
                                client=loop)
        check(link.frames[-1][430] == 0 and out["firing"] == ["Ground 1"],
              "0.9 s in: the head is still settling, no Waver fire")
        R.mono[0] += 0.15
        R.wall[0] += 0.15
        R.feed()
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        f = link.frames[-1]
        check(f[430] == 230 and f[431] == 100 and f[432] == 200 and
              out["firing"] == ["Ground 1", "Waver 1"],
              f"past head_settle_s: the Waver fires with its head up: {out}")
        # The group drops out of ARMED mid press (a deck tap, flamesafe
        # holding it): the head falls, and the next arm waits the full
        # settle time over again (review of PR #68, P2-10).
        R.groups[2]["armed"] = "disarmed"
        R.feed()
        R.mono[0] += 0.1
        R.wall[0] += 0.1
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        f = link.frames[-1]
        check(st == 200 and f[430] == 0 and f[431] == 0 and f[432] == 0 and
              any("not armed" in w for w in out["waiting"]),
              f"disarmed mid press: nothing on the Waver, not even its head: "
              f"{out}")
        R.groups[2]["armed"] = "armed"
        R.feed()
        R.mono[0] += 0.1
        R.wall[0] += 0.1
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": fid}, client=loop)
        f = link.frames[-1]
        check(st == 200 and f[431] == 100 and f[432] == 200 and f[430] == 0
              and any("head going up" in w for w in out["waiting"]),
              f"armed again: the head goes up first, no fire, the settle "
              f"time starts over: {out}")
        # The key comes up: cleared at once.
        before = link.cleared
        st, _h, out = R.ask("POST", "/api/remote/purge-stop", {}, client=loop)
        check(st == 200 and link.cleared > before and R.m.purge.fire is None,
              "purge-stop clears the frame now")
        # Locking a selected machine drops it from the selection.
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "machine", "id": "w1", "on": True},
                            client=loop)
        check(st == 200 and R.m.purge.selected == ["g1"] and
              link.locked == {412, 431, 432, 433},
              f"a lock drops the machine from the purge and tells the link: "
              f"{R.m.purge.selected} {link.locked}")
        R.fs_lockout = {"slots": [412, 431, 432, 433], "state": "read"}
        R.feed()
        # Review of #122, P1-B: no unlock while the machine's group is
        # armed or asked for; a lock is never held back.
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "machine", "id": "w1", "on": False,
                             "confirmed": True}, client=loop)
        check(st == 409 and out["error"] == "Disarm wave flamer first, then "
              "unlock Waver 1." and R.m.lockout.is_locked("machine", "w1"),
              f"no unlock while its group is armed: {st} {out}")
        for g in R.groups:
            if g["name"] == "wave flamer":
                g.update(armed="disarmed", wanted=False)
        R.feed()
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "machine", "id": "w1", "on": False},
                            client=loop)
        check(st == 409 and "confirm" in out["error"],
              "unlock needs the confirm")
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "machine", "id": "w1", "on": False,
                             "confirmed": True}, client=loop)
        check(st == 200 and not R.m.lockout.is_locked("machine", "w1"),
              "and with it unlocks")
        R.fs_lockout = {"slots": [412], "state": "read"}
        R.feed()
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        check(out["morning"]["locked_machines"] == ["Ground 2"] and
              out["morning"]["flamesafe_confirmed"] is True and
              out["morning"]["lock_error"] == "",
              f"the status carries the lock banner: {out['morning']}")
        # The page goes away: 2 s later the selection is gone.
        for _ in range(4):
            _mo_advance(R, 0.5, beat=True)
        check(R.m.purge.selected == ["g1"], "while the page beats it stays")
        for _ in range(5):
            _mo_advance(R, 0.5, beat=False)
        check(R.m.purge.selected == [] and
              R.remote.deck_input()["morning"]["purge"]["wanted_groups"] == []
              and R.remote.deck_input()["morning"]["open"] is False,
              "2 s without the page: the selection is cleared and the deck "
              "is told the page is closed")
        # The deck process fires a selection an iPad owns (review of PR
        # #68, P1-2): it names itself in `screen`, over loopback, whatever
        # operator name it carries; the owner check is for pages.
        st, _h, out = R.ask("POST", "/api/remote/morning-open", {},
                            client=ipad)
        check(st == 200 and out.get("open") is True, "the iPad's page is open")
        R.m.open_beat("Rack screen")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=ipad)
        check(st == 200 and R.m.purge.owner == "iPad at 10.20.0.44",
              f"the iPad arms Ground 1: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "who": "Andy",
                             "screen": "Stream Deck"}, client=loop)
        check(st == 200 and out["firing"] == ["Ground 1"] and
              R.m.purge.fire["device"] == "Stream Deck",
              f"the deck's FIRE key fires the iPad's selection: {st} {out}")
        deck_fid = out["fire_id"]
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=ipad)
        check(st == 409 and "Stream Deck is already firing" in out["error"],
              f"the owner's own press waits for the deck to let go: {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=loop)
        check(st == 409 and "has the purge selection" in out["error"] and
              R.m.purge.fire is not None and
              R.m.purge.fire["device"] == "Stream Deck",
              f"the Rack screen is neither the owner nor the deck: refused, "
              f"and the deck's press is not ended by it: {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen(), "fire_id": deck_fid,
                             "who": "Andy", "screen": "Stream Deck"},
                            client=loop)
        check(st == 200 and out["fire_id"] == deck_fid,
              "the deck carries its own press on")
        st, _h, out = R.ask("POST", "/api/remote/purge-stop",
                            {"who": "Andy", "screen": "Stream Deck"},
                            client=loop)
        check(st == 200 and R.m.purge.fire is None, "and lets go")
        # The selection lives only while ITS OWNER's page is open (review
        # of PR #68, P2-1): the Rack screen keeps beating, the iPad stops.
        for _ in range(5):
            _mo_advance(R, 0.5, beat=True)
        check(R.m.purge.selected == [] and R.m.page_open(),
              "2 s without the iPad's own beat: its selection is cleared, "
              "though the Rack screen's page is open")
        # A configured laser's test goes on between shows, and over the
        # laser's own socket, never the flame link (once it is armed).
        _mo_arm(R, "laser-3")
        del R.osc[:]
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-3", "on": True}, client=loop)
        check(st == 200 and "laser-3" in R.m.lasers.on and len(R.osc) == 3
              and R.osc[0][0] == ("127.0.0.2", 8100),
              f"a configured laser's test turns on, three OSC packets: {out}")
        # Abort, with nothing live: the purge selection and the laser test
        # end AT THE PRESS, before any watcher pass (T7).
        R.m.open_beat("Rack screen")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 200, "armed again")
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True},
                            client=loop)
        check(R.m.purge.selected == [] and not R.m.lasers.on and
              R.osc[-1][1].startswith(b"/beyond/general/stopcue"),
              f"Abort cleared the purge and turned the laser test off at "
              f"the press: {R.m.purge.selected} {R.m.lasers.on}")
        R.settle()
        R.feed()
        check(R.m.laser_arm.armed_ids() == [],
              "the Abort disarmed every laser (Jeff, 2026-10-22)")
        _mo_arm(R, "laser-3")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-3", "on": True}, client=loop)
        check(st == 200 and "laser-3" in R.m.lasers.on, "test on again")
        # Locking a configured laser sends its lock messages (a placeholder
        # list until BEYOND's way to shut one laser is known) at the lock.
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "laser", "id": "laser-4", "on": True},
                            client=loop)
        check(st == 200 and R.m.lockout.is_locked("laser", "laser-4") and
              R.osc[-1][1].startswith(b"/beyond/zones/4/enable"),
              f"locking Laser 4 sends its lock messages: {st} {out}")
        n_osc = len(R.osc)
        R.m.tick()
        check(len(R.osc) == n_osc, "and not again on an idle watcher pass")
        # A show live: refused, a selection is cleared and the laser tests
        # go off on the watcher's next pass.
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 200, "armed again")
        _live_show(R)
        R.feed()
        R.m.tick()
        check(R.m.purge.selected == [],
              "a show going live clears the purge selection")
        check(not R.m.lasers.on,
              "and turns every laser test off within one watcher pass")
        check(any(p.startswith(b"/beyond/zones/4/enable")
                  for _a, p in R.osc[n_osc:]),
              "and a locked laser's lock messages go to BEYOND again as the "
              "show goes live (MORNING.md: at every show start while locked)")
        n_osc = len(R.osc)
        R.m.tick()
        check(not any(p.startswith(b"/beyond/zones/4/enable")
                      for _a, p in R.osc[n_osc:]),
              "once per show start, not every pass")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "live" in out["error"],
              f"and nothing can be armed for a purge while it is: {out}")
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=loop)
        check(st == 409 and "live" in out["error"],
              "nor fired")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-1", "on": True}, client=loop)
        check(st == 409 and "not allowed now" in out["error"],
              f"nor a laser test turned on: {out}")
        # An Abort: latched until Reset, and the purge is refused.
        st, _h, out = R.ask("POST", "/api/remote/abort", {"confirmed": True},
                            client=loop)
        R.settle()
        R.feed()
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 409 and "aborted" in out["error"],
              f"aborted: no purge until Reset: {out}")
        # Lasers: a placeholder refuses; a lock refuses; the view says so.
        st, _h, out = R.ask("POST", "/api/remote/reset", {"seen": R.seen()},
                            client=loop)
        R.settle()
        R.now[0] = _den(S, 18, 30)
        R.svc.tick()
        R.settle()
        R.feed()
        _mo_arm(R, "laser-1")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-1", "on": True}, client=loop)
        check(st == 409 and "placeholder" in out["error"],
              f"an undecided laser refuses its test: {out}")
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "laser", "id": "laser-2", "on": True},
                            client=loop)
        check(st == 200 and R.m.lockout.is_locked("laser", "laser-2"),
              "a laser locks")
        st, _h, out = R.ask("GET", "/api/remote/morning", client=loop)
        check(out["lasers"][1]["locked"] is True and
              out["lockout"]["lasers"].get("laser-2"), "and the view says so")
        # The layout route.
        st, _h, out = R.ask("POST", "/api/remote/layout",
                            {"positions": {"g1": {"x": 5, "y": 95}}},
                            client=loop)
        check(st == 200 and out["layout"]["g1"] == {"x": 5.0, "y": 95.0},
              "the layout saves from the page")
        st, _h, out = R.ask("POST", "/api/remote/layout",
                            {"positions": {"g1": {"x": 500, "y": 95}}},
                            client=loop)
        check(st == 400, "a bad position is refused")
        # From the show network, unlocking and turning a laser test ON need
        # screen_arming (review of PR #68, P2-4, P2-5); locking does not. A
        # device that may not purge does not hold the page open (P2-8).
        RM.save_settings(R.work, screen_arming=False)
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "laser", "id": "laser-1", "on": True},
                            client=ipad)
        check(st == 200 and R.m.lockout.is_locked("laser", "laser-1"),
              f"an iPad may lock: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "laser", "id": "laser-1", "on": False,
                             "confirmed": True}, client=ipad)
        check(st == 403 and "screen_arming" in out["error"] and
              R.m.lockout.is_locked("laser", "laser-1"),
              f"but not unlock without screen_arming: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-3", "on": True}, client=ipad)
        check(st == 403 and "screen_arming" in out["error"] and
              not R.m.lasers.on,
              f"nor turn a laser test on: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/morning-open", {},
                            client=ipad)
        check(st == 200 and out.get("open") is False and
              "iPad at 10.20.0.44" not in R.m._open_devices,
              f"a device that may not purge does not hold the page open: "
              f"{out}")
        st, _h, out = R.ask("POST", "/api/remote/lock",
                            {"kind": "laser", "id": "laser-1", "on": False,
                             "confirmed": True}, client=loop)
        check(st == 200 and not R.m.lockout.is_locked("laser", "laser-1"),
              "the show machine itself unlocks")
        RM.save_settings(R.work, screen_arming=True)
        if "laser-3" not in R.m.laser_arm.armed_ids():
            _mo_arm(R, "laser-3")
        st, _h, out = R.ask("POST", "/api/remote/laser-test",
                            {"laser": "laser-3", "on": True}, client=ipad)
        check(st == 200 and "laser-3" in R.m.lasers.on,
              f"with screen_arming the iPad may turn a test on: {st} {out}")
        R.ask("POST", "/api/remote/laser-test",
              {"laser": "laser-3", "on": False}, client=ipad)
        # A broken ltcplay_remote.json: no purge from anywhere.
        rpath = os.path.join(R.work, "ltcplay_remote.json")
        with open(rpath, encoding="utf-8") as fh:
            saved_settings = fh.read()
        with open(rpath, "w", encoding="utf-8") as fh:
            fh.write("{ broken")
        st, _h, out = R.ask("GET", "/api/remote/morning", client=loop)
        check(st == 200 and out["purge_enabled"] is False,
              "a broken ltcplay_remote.json: purge arming reads as off")
        st, _h, out = R.ask("POST", "/api/remote/purge-select",
                            {"machine": "g1", "seen": R.seen()}, client=loop)
        check(st == 403, "and a purge click is refused")
        with open(rpath, "w", encoding="utf-8") as fh:
            fh.write(saved_settings)
        # The page's own fire key: one keydown starts it, the browser's key
        # repeat events are the evidence the key is still down, and every
        # way of losing the key stops it (review of PR #68, P1-4).
        html = open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "ltcplay", "web", "remote.html"),
                    encoding="utf-8").read()
        for want in ('if(e.repeat){ if(FIRE) FIRE.repeatAt = Date.now(); return; }',
                     "const KEY_REPEAT_GRACE_MS = 2500, KEY_REPEAT_GAP_MS = 1000;",
                     "if(fireKeyLapsed(now, f.startAt, f.repeatAt, "
                     "KEY_REPEAT_GRACE_MS, KEY_REPEAT_GAP_MS)){",
                     'addEventListener("keyup"',
                     'addEventListener("blur"', '"visibilitychange"',
                     '"pagehide"', '/api/remote/purge-clear'):
            check(want in html, f"the page's script carries {want!r} (wording "
                                f"only: the script has no test harness here, "
                                f"so this proves presence, not behaviour; "
                                f"the rule itself, fireKeyLapsed, runs in "
                                f"node in the remote page logic test)")
        # The rewrite dialog (second review of PR #68, P3-4) says exactly
        # which ids the rewrite KEEPS (machines and lasers) and which it
        # DROPS, and its LIFTED clause does not rest on flamesafe_extra,
        # which is empty while flamesafe's report is stale or inside the
        # settle time: a stale flamesafe may still hold slots this lifts.
        for want in ('const keptM = Object.keys(lo.machines || {}).filter(id => '
                     '!(lo.unknown_machines || []).includes(id));',
                     'const keptL = Object.keys(lo.lasers || {}).filter(id => '
                     '!(lo.unknown_lasers || []).includes(id));',
                     'const dropped = (lo.unknown_machines || []).concat('
                     'lo.unknown_lasers || []);',
                     '"; locked lasers: " + (keptL.length ? keptL.join(", ") '
                     ': "none")',
                     '", dropping " + dropped.join(", ") + " which the settings '
                     'no longer name"',
                     '" Any flame slot flamesafe holds locked beyond these is '
                     'LIFTED by this."'):
            check(want in html, f"the rewrite dialog carries {want!r} (wording "
                                f"only, as above)")
        _morning_page_logic_in_node()
        # Every one of these routes is refused from another site's page.
        st, _h, out = R.ask("POST", "/api/remote/purge-fire",
                            {"on": True, "seen": R.seen()}, client=loop,
                            headers={"Origin": "http://evil.example"})
        check(st == 403, "a cross-site purge-fire is refused")
        # And the arm-route test's rule holds: no route here names "arm",
        # but the laser arm's own (laserarm.py, Jeff 2026-10-22), which
        # arms lasers and never reaches the flame arm link.
        import re as _re
        check([r for r in RM.MORNING_POST_ROUTES + RM.MORNING_GET_ROUTES
               if _re.search(r"(?<!dis)arm", r)] == ["laser-arm"],
              "no Morning route is a flame arm route")
    finally:
        R.m.close()
        R.close()
    print("  ok")


class _FakeMorningScreen(_FakeScreen):
    def __init__(self):
        super().__init__()
        self.mo = None

    def morning(self):
        return self.mo


class _FakePurgeFire:
    def __init__(self):
        self.calls = []
        self.firing = False

    def start(self, who=""):
        self.calls.append(("start", who))
        self.firing = True
        return True

    def stop(self, who=""):
        self.calls.append(("stop", who))
        was = self.firing
        self.firing = False
        return was


def test_morning_deck_remap_and_purge_arming():
    section("Morning and Shutdown, the Stream Deck: a group entering the "
            "engine's purge list is armed (a click, Jeff's exception), one "
            "leaving it is disarmed, a closed page or a quiet engine disarms "
            "every purge group, latched and the refractory window still "
            "refuse, an operator's tap is never undone; the Start key is "
            "FIRE while the page is open and START NOW again after (T4, T8, "
            "T11)")
    from ltcplay import streamdeck as sd
    arm = _FakeArmSocket(3)
    status = _FakeStatusSocket()
    names = ["front row", "cat-walk", "wave flamer"]
    events = []
    t = [100.0]
    scr = _FakeMorningScreen()
    cond = _FakeConductor()
    c = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                      show_running_provider=lambda: False, conductor=cond,
                      journal=lambda t_, **kw: events.append((t_, kw)),
                      clock=lambda: t[0], screen=scr)
    pf = _FakePurgeFire()
    c.purge_fire = pf

    def mo(open_=True, wanted=(), enabled=True, locked=()):
        scr.mo = {"open": open_, "purge_enabled": enabled,
                  "purge": {"wanted_groups": list(wanted), "selected":
                            len(wanted), "firing": False},
                  "locks": {"groups_fully_locked": list(locked)}}

    def step(dt=0.05):
        t[0] += dt
        c.screen_pass()
        c.tick()
    mo(True, [0])
    step()
    check(arm.wanted == [True, False, False] and 0 in c._purge_armed,
          f"group 0 entering the purge list is armed at once, no hold: "
          f"{arm.wanted}")
    check("PURGE" in events[-1][0] and events[-1][1].get("screen") ==
          "Morning page", f"journaled as a purge arm from the page: "
                          f"{events[-1]}")
    step()
    step()
    check(arm.sends.count([True, False, False]) >= 1 and
          arm.wanted == [True, False, False], "and stays armed while listed")
    # The operator taps the group off on the deck: it is NOT re-armed
    # while it stays in the list.
    down = [False] * 6
    d2 = list(down)
    d2[sd.GROUP_KEYS[0]] = True
    c.run_once(d2)
    c.run_once(down)
    check(arm.wanted[0] is False and 0 not in c._purge_armed,
          "a deck tap disarms it")
    step()
    step()
    check(arm.wanted[0] is False, "and the purge list does not re-arm it")
    # Leaving and re-entering the list arms it again (after the refractory).
    mo(True, [])
    step()
    mo(True, [0])
    step()
    check(arm.wanted[0] is False and "refractory" in events[-1][0],
          f"inside the refractory window after that tap: refused: "
          f"{events[-1][0][:80]}")
    t[0] += sd.REARM_REFRACTORY_S
    mo(True, [])
    step()
    mo(True, [0, 2])
    step()
    check(arm.wanted == [True, False, True] and c._purge_armed == {0, 2},
          f"past it, both groups arm: {arm.wanted}")
    # One leaves the list: disarmed, the other stays.
    mo(True, [2])
    step()
    check(arm.wanted == [False, False, True] and c._purge_armed == {2},
          f"group 0 left the list: disarmed: {arm.wanted}")
    check("disarm pressed" in events[-1][0] and "Morning page" in
          events[-1][0], f"journaled: {events[-1][0][:90]}")
    # FIRE: the Start key while the page is open.
    d2 = list(down)
    d2[sd.TOP_START] = True
    c.run_once(d2)
    check(pf.calls[-1] == ("start", "Andy") and pf.firing,
          f"the Start key is FIRE while the page is open: {pf.calls}")
    c.run_once(down)
    check(pf.calls[-1] == ("stop", "Andy") and not pf.firing,
          "letting go stops the heartbeats")
    # The page closes: every purge group disarms, a fire stops, the key
    # is START NOW again.
    c.run_once(d2)
    check(pf.firing, "firing again")
    mo(False, [2])
    step()
    check(arm.wanted == [False, False, False] and not c._purge_armed and
          not pf.firing, f"the page closed: disarmed and the fire stopped: "
                         f"{arm.wanted}")
    c.run_once(down)
    before = len(events)
    c.run_once(d2)
    check(any("no real 'start" in e[0] for e in events[before:]),
          "with the page closed the Start key is Start Now again")
    c.run_once(down)
    # The engine goes quiet: morning() reads None; everything disarms.
    mo(True, [1])
    step()
    check(arm.wanted == [False, True, False], "armed for the purge")
    scr.mo = None
    step()
    check(arm.wanted == [False, False, False],
          "no fresh word from the engine: the purge group is disarmed")
    # Purge arming off at the engine, or the rig latched: nothing arms.
    mo(True, [1], enabled=False)
    step()
    check(arm.wanted == [False, False, False],
          "purge_enabled false at the engine: nothing arms")
    t[0] += sd.REARM_REFRACTORY_S     # past the window of the last disarm
    mo(True, [1])
    cond._latched = True
    n_sends = len(arm.sends)
    step()
    check(arm.wanted == [False, False, False] and
          not any(any(s) for s in arm.sends[n_sends:]),
          f"latched: nothing arms for a purge, and no arm value went out "
          f"on the arm link even for one pass: {arm.sends[n_sends:]}")
    cond._latched = False
    # The Reset starts every group's re-arm wait (the deck sees the latch
    # go, 2026-10-26); let it run out.
    mo(True, [])
    step()
    t[0] += sd.REARM_REFRACTORY_S
    # No operator chosen on the deck: a purge arm is refused like any arm
    # (review of PR #68, P2-6: the same guards as a completed hold).
    step()
    c.operator_provider = lambda: ""
    mo(True, [1])
    n_sends = len(arm.sends)
    step()
    check(arm.wanted == [False, False, False] and
          not any(any(s) for s in arm.sends[n_sends:]) and
          any("operator" in e[0].lower() for e in events[-3:]),
          f"no operator: nothing arms for a purge, and it is said: "
          f"{[e[0][:70] for e in events[-3:]]}")
    c.operator_provider = lambda: "Andy"
    mo(True, [])
    step()
    # A group the OPERATOR armed is not touched by the purge list.
    t[0] += sd.REARM_REFRACTORY_S
    arm.set_group(1, True)
    mo(True, [1])
    step()
    check(1 not in c._purge_armed and arm.wanted[1] is True,
          "a group already armed by the operator is left as it is")
    mo(True, [])
    step()
    check(arm.wanted[1] is True,
          "and is not disarmed when the purge list empties")
    arm.set_group(1, False)
    # Drawing: the re-mapped faces exist, and only while the page is open.
    if not _pillow_missing("the deck's Morning faces"):
        fonts = sd.Fonts()
        fonts.text_block = lambda *a, **kw: None   # no font files on CI
        mo(True, [0], locked=[2])
        step()
        img = c.draw(fonts, True, 0)
        check(img.size == (sd.W, sd.H), "the re-mapped deck draws")
        mo(False)
        step()
        img2 = c.draw(fonts, True, 0)
        check(img2.size == (sd.W, sd.H), "and the restored one")
    # PurgeFire itself: heartbeats to the engine, a refusal ends the press,
    # stop posts purge-stop. On a fake poster, no network.
    posts = []
    answers = [(True, "ok", {"fire_id": 7, "firing": ["Ground 1"]}),
               (True, "ok", {"fire_id": 7}),
               (False, "the show is live", {})]

    def poster(path, body):
        posts.append((path, dict(body)))
        return answers.pop(0) if answers else (True, "ok", {})
    import threading as _th
    gate = _th.Event()
    lines = []
    fire = sd.PurgeFire(poster, journal=lambda t_, **kw: lines.append(t_),
                        wall=lambda: 1234.5)
    fire.start(who="Andy")
    for _ in range(100):
        if not fire.firing:
            break
        gate.wait(0.02)
    beats = [p for p in posts if p[0] == "/api/remote/purge-fire"]
    check(len(beats) == 3 and "fire_id" not in beats[0][1] and
          beats[1][1]["fire_id"] == 7 and beats[2][1]["fire_id"] == 7 and
          beats[0][1]["screen"] == "Stream Deck" and
          beats[0][1]["who"] == "Andy" and beats[0][1]["seen"] == 1234500,
          f"the first beat has no id, the next carry the engine's, each "
          f"names the deck: {beats}")
    check(not fire.firing and any("refused" in l for l in lines),
          "a refused beat ends the press and is journaled")
    fire.start(who="Andy")
    gate.wait(0.05)
    fire.stop(who="Andy")
    for _ in range(50):
        if any(p[0] == "/api/remote/purge-stop" for p in posts):
            break
        gate.wait(0.02)
    check(any(p[0] == "/api/remote/purge-stop" for p in posts),
          "stop posts purge-stop to the engine")
    check(all(p[1].get("on") is True for p in posts
              if p[0] == "/api/remote/purge-fire") and
          all("on" not in p[1] for p in posts
              if p[0] == "/api/remote/purge-stop"),
          f"every FIRE heartbeat says on true (the engine fires on nothing "
          f"else) and the purge-stop does not: {posts}")
    check(sd.PURGE_BEAT_S == 0.1, "the deck beats every 100 ms, like the page")
    # ScreenKeys itself: the engine's morning block is read only while the
    # engine's last answer is fresh (SCREEN_STALE_S), like the holds.
    tt = [50.0]
    ans = {"enabled": True, "holds": [], "disarms": [], "alerts": [],
           "morning": {"open": True, "purge_enabled": True,
                       "purge": {"wanted_groups": [1]}, "locks": {}}}
    sk = sd.ScreenKeys("http://127.0.0.1:1", fetcher=lambda path: ans,
                       clock=lambda: tt[0])
    sk.poll_once()
    check(sk.morning() == ans["morning"], "a fresh answer's morning block")
    tt[0] += sd.SCREEN_STALE_S + 0.01
    check(sk.morning() is None,
          "0.31 s after the engine's last answer it reads as nothing: the "
          "deck un-maps and disarms the purge groups")
    sk._fetch = lambda path: None
    sk.poll_once()
    check(sk.morning() is None, "an unreachable engine: nothing")
    print("  ok")


def test_laser_tests_placeholders_lockout_and_allow_list():
    section("Morning and Shutdown, the laser tests: an undecided laser "
            "refuses and sends nothing, a configured one sends its on and "
            "off lists three times, a locked laser's ON is refused at the "
            "sender, all_off turns every test off, and only exact OSC "
            "addresses that are not BlackOut or MasterPause ever leave (T10)")
    from ltcplay import lasertest as LT
    from ltcplay import beyond as BY
    check(LT.FORBIDDEN_ADDRESSES == BY.FORBIDDEN_ADDRESSES,
          "the same two forbidden addresses as beyond.py")
    for addr in ("/beyond/general/BlackOut", "/beyond/general/MasterPause",
                 "/beyond/zones/*/x", "/a b", "beyond/x", "#bundle", "/",
                 "/x[1]", "/x{a,b}", "/x?", "/é", "", None, 7):
        check(not LT.allowed_address(addr), f"{addr!r} is not an address "
                                            f"this program may send to")
    check(LT.allowed_address("/beyond/general/startcue"), "an exact one is")
    check(LT.encode_osc("/a", 3) == b"/a\x00\x00,i\x00\x00\x00\x00\x00\x03"
          and LT.encode_osc("/a", 0.0)[-4:] == b"\x00\x00\x00\x00"
          and LT.encode_osc("/a", "hi") == b"/a\x00\x00,s\x00\x00hi\x00\x00",
          "whole numbers, decimals and text encode as OSC")
    for v in (True, float("nan"), [1], 2 ** 40, "x" * 300):
        try:
            LT.encode_osc("/a", v)
            check(False, f"{v!r} encoded")
        except ValueError:
            check(True, f"{str(v)[:20]!r} is not an argument")
    sent = []

    class _Sock:
        def sendto(self, pkt, addr):
            sent.append((addr, pkt))

        def close(self):
            pass
    lasers = LT.parse_lasers([
        {"id": "l1", "name": "Laser 1", "mechanism": "osc", "host": "127.0.0.2",
         "port": 8100, "on": [["/beyond/general/startcue", 3]],
         "off": [["/beyond/general/stopcue", 3]],
         "lock": [["/beyond/zones/1/enable", 0.0]]},
        {"id": "l2", "name": "Laser 2"}], "x")
    locked = set()
    lines = []
    armed = set()
    lt = LT.LaserTests(lasers, locked=lambda lid: lid in locked,
                       journal=lambda t, **f: lines.append((t, f)),
                       socket_factory=_Sock, sleep=lambda s: None,
                       armed=lambda lid: lid in armed)
    # The laser arm (Jeff, 2026-10-22): a test is that laser's cue, so a
    # laser that is not armed refuses it and sends nothing.
    ok, text = lt.set("l1", True, who="Andy")
    check(not ok and "not armed" in text and not sent and "l1" not in lt.on,
          f"a laser that is not armed refuses its test and sends nothing: "
          f"{text}")
    lt_none = LT.LaserTests(lasers, socket_factory=_Sock,
                            sleep=lambda s: None)
    ok, text = lt_none.set("l1", True, who="Andy")
    check(not ok and "not armed" in text and not sent,
          f"with no arm wired at all, nothing is armed: {text}")
    lt_err = LT.LaserTests(lasers, socket_factory=_Sock, sleep=lambda s: None,
                           armed=lambda lid: 1 / 0)
    ok, text = lt_err.set("l1", True, who="Andy")
    lt_truthy = LT.LaserTests(lasers, socket_factory=_Sock,
                              sleep=lambda s: None, armed=lambda lid: "yes")
    ok2, _t = lt_truthy.set("l1", True, who="Andy")
    check(not ok and not ok2 and not sent,
          "an arm that raises, or answers anything but True, is not armed")
    armed.update(("l1", "l2"))
    ok, text = lt.set("l2", True, who="Andy")
    check(not ok and "placeholder" in text and not sent,
          f"an undecided laser refuses and sends nothing: {text}")
    ok, text = lt.set("l1", True, who="Andy")
    check(ok and len(sent) == 3 and all(
        a == ("127.0.0.2", 8100) and b.startswith(b"/beyond/general/startcue")
        for a, b in sent) and "l1" in lt.on,
          f"a configured laser's on list goes three times: {len(sent)}")
    check(lines and "ON" in lines[-1][0] and lines[-1][1].get("action") ==
          "laser-test", f"journaled: {lines[-1]}")
    del sent[:]
    ok, text = lt.set("l1", False, who="Andy")
    check(ok and len(sent) == 3 and sent[0][1].startswith(
        b"/beyond/general/stopcue") and "l1" not in lt.on,
          "off sends the off list")
    del sent[:]
    locked.add("l1")
    ok, text = lt.set("l1", True, who="Andy")
    check(not ok and "locked out" in text and not sent,
          f"a locked laser's ON is refused at the sender: {text}")
    locked.clear()
    lt.set("l1", True)
    del sent[:]
    gone = lt.all_off("a show started")
    check(gone == ["l1"] and not lt.on and sent and
          sent[0][1].startswith(b"/beyond/general/stopcue"),
          "all_off turns the test off with the off list")
    del sent[:]
    lt.send_lock("l1", "locked out")
    check(sent and sent[-1][1].startswith(b"/beyond/zones/1/enable"),
          "the lock list goes when a laser is locked")
    v = lt.view()
    check(v[0]["configured"] and not v[1]["configured"] and
          v[0]["on"] is False, f"the view: {v}")
    try:
        lt._osc.send("127.0.0.2", 8100, "/beyond/general/BlackOut", 1)
        check(False, "the socket layer sent BlackOut")
    except LT.LaserConfigError:
        check(True, "the socket layer itself refuses BlackOut")
    print("  ok")


def test_checklist_audit_chain_pdf_export_and_tally():
    section("Morning and Shutdown, the checklists: a tick needs a listed "
            "name; every tick, untick and note is an append-only hash chained "
            "record with UTC and local time, the step's words, who, device "
            "and address; verify finds any edit; ticks reset each night; a "
            "completed routine writes the day's JSON and PDF; Export all is "
            "a zip of every day's PDF, a combined PDF with contents and "
            "VERIFY.txt; the tally sends nothing until configured and keeps "
            "a disk queue when it is (T14)")
    import json as _j
    import shutil
    import tempfile
    import zipfile as _zf
    from ltcplay import checklist as CL
    from ltcplay import morning as MO
    from ltcplay import pdfmini as PM
    import ast as _ast
    here = os.path.dirname(os.path.abspath(__file__))
    # pdfmini stands on the standard library alone, so it bundles as it is.
    tree = _ast.parse(open(os.path.join(here, "ltcplay", "pdfmini.py"),
                           encoding="utf-8").read())
    mods = {n.names[0].name.split(".")[0] for n in _ast.walk(tree)
            if isinstance(n, _ast.Import)} | {
        n.module.split(".")[0] for n in _ast.walk(tree)
        if isinstance(n, _ast.ImportFrom) and n.module}
    check(mods <= {"re"}, f"pdfmini imports only the standard library: {mods}")
    spec = open(os.path.join(here, "packaging", "windows", "ltcplay.spec"),
                encoding="utf-8").read()
    check('collect_submodules("ltcplay")' in spec,
          "the Windows app bundles every ltcplay module, pdfmini included")
    cfg = MO.MorningConfig.parse(_j.loads(_j.dumps(_MO_CONFIG)), "x",
                                 _MO_FLAMESAFE["groups"])
    d = tempfile.mkdtemp()
    try:
        import datetime as _dt
        wall = [1_800_000_000.0]
        night = [_dt.date(2026, 11, 14)]
        sends = []
        lines = []
        svc = CL.ChecklistService(cfg, os.path.join(d, "checklists"),
                                  night=lambda: night[0],
                                  journal=lambda t, **f: lines.append((t, f)),
                                  wall=lambda: wall[0],
                                  clock=lambda: wall[0],
                                  transport=lambda *a: sends.append(a) or
                                  (200, "ok"), threaded=False)
        day1 = svc.show_date()
        # A tick needs a name from the list.
        st, out = svc.post("checklist-tick", {"checklist": "morning",
                                              "step": "gas"},
                           "Rack screen", "Rack screen", True)
        check(st == 409 and "Pick a name" in out["error"],
              f"no name: refused: {out}")
        st, out = svc.post("checklist-tick", {"checklist": "morning",
                                              "step": "gas", "who": "Bob"},
                           "Rack screen", "Rack screen", True)
        check(st == 409, "a name not on the list: refused")
        st, out = svc.post("checklist-tick", {"checklist": "morning",
                                              "step": "nope", "who": "Andy"},
                           "Rack screen", "Rack screen", True)
        check(st == 409 and "no step" in out["error"], "an unknown step")
        st, out = svc.post("checklist-tick", {"checklist": "morning",
                                              "step": "gas", "who": "Andy"},
                           "Rack screen", "Rack screen", True)
        check(st == 200 and out["record"] == 1 and "ticked by Andy" in
              out["text"], f"Andy ticks: {out}")
        r = svc.chain.records[0]
        check(r["seq"] == 1 and r["prev"] == CL.GENESIS and
              r["hash"] == CL.record_hash(r) and r["utc"].endswith("Z") and
              r["local"][:10] and r["show_date"] == day1 and
              r["checklist"] == "morning" and r["step"] == "gas" and
              r["step_text"] == "Gas on at the manifold" and
              r["state"] == "done" and r["who"] == "Andy" and
              r["device"] == "Rack screen" and r["ip"] == "127.0.0.1",
              f"the record carries everything the ruling asks: {r}")
        wall[0] += 60
        st, out = svc.post("checklist-note", {"checklist": "morning",
                                              "step": "gas", "who": "JH",
                                              "note": "Pressure low, 40 psi"},
                           "iPad at 10.20.0.44", "iPad", False)
        check(st == 200 and svc.chain.records[-1]["state"] == "note" and
              svc.chain.records[-1]["ip"] == "10.20.0.44" and
              svc.chain.records[-1]["device"] == "iPad at 10.20.0.44",
              "a note is its own record, with the device and address")
        st, out = svc.post("checklist-tick", {"checklist": "morning",
                                              "step": "gas", "who": "JH",
                                              "done": False},
                           "Rack screen", "Rack screen", True)
        check(st == 200 and svc.chain.records[-1]["state"] == "undone",
              "an untick is a new record, never an edit")
        v = svc.view()
        m = v["checklists"][0]
        check(m["steps"][0]["done"] is False and m["steps"][0]["note"] ==
              "Pressure low, 40 psi" and m["done"] == 0 and not m["complete"]
              and v["verify"]["ok"] and v["verify"]["records"] == 3,
              f"the view replays the records: {m}")
        check(sends == [] and not os.path.isdir(svc.tally.outbox) and
              v["tally"]["enabled"] is False,
              "the tally is off: nothing sent, nothing queued")
        # Completing the routine writes the day's record, JSON and PDF.
        for sid in ("gas", "walk"):
            wall[0] += 30
            st, out = svc.post("checklist-tick", {"checklist": "morning",
                                                  "step": sid, "who": "Andy"},
                               "Rack screen", "Rack screen", True)
            check(st == 200, f"tick {sid}")
        recs = svc.chain.records
        check(recs[-1]["state"] == "routine_complete" and
              svc.view()["checklists"][0]["complete"],
              "every step ticked: a routine_complete record")
        base = os.path.join(svc.day_dir(day1), f"checklist_{day1}")
        check(os.path.isfile(base + ".json") and os.path.isfile(base + ".pdf"),
              "the day's JSON and PDF are written beside the chain")
        doc = _j.load(open(base + ".json", encoding="utf-8"))
        check(doc["show_date"] == day1 and doc["routines"][0]["complete"] and
              len(doc["records"]) == len(recs) and doc["chain_verified"]["ok"],
              "the JSON holds every record and the verification")
        pdf = open(base + ".pdf", "rb").read()
        txt = PM.extract_text(pdf)
        check(pdf.startswith(b"%PDF-1.4") and pdf.rstrip().endswith(b"%%EOF"),
              "a PDF file")
        for want in (f"Show date {day1}", "Morning: COMPLETE", "Gas on at the "
                     "manifold", "Walk the field", "Andy at", "Note: Pressure "
                     "low, 40 psi", "Record trail", "Hash chain verification: "
                     "INTACT", "Page 1 of", "Shutdown: not complete"):
            check(want in txt, f"the PDF reads {want!r}")
        check("—" not in txt and "–" not in txt,
              "no dashes in the PDF")
        check(len(_re_findall(r"Page \d+ of \d+", txt)) == PM.page_count(pdf)
              and PM.page_count(pdf) >= 1, "every page is numbered")
        # Verify finds an edit, a deletion and an insertion.
        chain_path = svc.chain.path
        raw = open(chain_path, encoding="utf-8").read().splitlines()
        ok0 = CL.Chain(chain_path).verify()
        check(ok0[0] and ok0[1] == len(recs), f"the chain verifies: {ok0}")
        with open(chain_path, "w", encoding="utf-8") as fh:
            fh.write("\n".join(raw[:1] + [raw[1].replace("Pressure low",
                                                         "Pressure fine")]
                               + raw[2:]) + "\n")
        bad = CL.Chain(chain_path).verify()
        check(not bad[0] and bad[1] == 1 and "changed" in bad[2],
              f"an edited note is caught at record 2: {bad}")
        with open(chain_path, "w", encoding="utf-8") as fh:
            fh.write("\n".join(raw[:1] + raw[2:]) + "\n")
        bad = CL.Chain(chain_path).verify()
        check(not bad[0] and "missing or out of order" in bad[2],
              f"a deleted record is caught: {bad}")
        forged = dict(_j.loads(raw[1]))
        forged["who"] = "Nobody"
        forged["hash"] = CL.record_hash(forged)
        with open(chain_path, "w", encoding="utf-8") as fh:
            fh.write("\n".join(raw[:2] + [_j.dumps(forged, sort_keys=True)]
                               + raw[2:]) + "\n")
        bad = CL.Chain(chain_path).verify()
        check(not bad[0] and bad[1] == 2, f"an inserted record is caught: {bad}")
        with open(chain_path, "w", encoding="utf-8") as fh:
            fh.write("\n".join(raw) + "\n")
        check(CL.Chain(chain_path).verify()[0], "restored: intact")
        # The CLI says the same.
        from ltcplay import cli as _cli
        import argparse as _ap
        import io as _io
        import contextlib as _ctx
        buf = _io.StringIO()
        with _ctx.redirect_stdout(buf):
            rc = _cli.cmd_checklist_verify(_ap.Namespace(folder=svc.folder))
        check(rc == 0 and "intact" in buf.getvalue(),
              f"ltc checklist-verify: {buf.getvalue()[:80]}")
        # A new night: the ticks reset, the records stay.
        night[0] = _dt.date(2026, 11, 15)
        wall[0] += 86400
        v2 = svc.view()
        check(v2["show_date"] == "2026-11-15" and
              v2["checklists"][0]["done"] == 0 and
              v2["verify"]["records"] == len(recs),
              f"a new night starts clean, the chain keeps every record: "
              f"{v2['show_date']} {v2['checklists'][0]['done']}")
        for sid in ("gas", "walk"):
            svc.post("checklist-tick", {"checklist": "morning", "step": sid,
                                        "who": "JH"}, "Rack screen",
                     "Rack screen", True)
        night[0] = _dt.date(2026, 11, 16)
        wall[0] += 86400
        svc.post("checklist-tick", {"checklist": "shutdown", "step": "step-1",
                                    "who": "Andy"}, "Rack screen",
                 "Rack screen", True)
        dates = svc.chain.dates()
        check(dates == [day1, "2026-11-15", "2026-11-16"], f"three days: {dates}")
        # Export all: a zip of every day, a combined PDF, VERIFY.txt.
        name, data = svc.export_zip()
        z = _zf.ZipFile(_io.BytesIO(data))
        names = sorted(z.namelist())
        check(name == f"checklist_records_{day1}_to_2026-11-16.zip" and
              f"checklist_{day1}.pdf" in names and
              "checklist_2026-11-16.pdf" in names and
              "checklist_2026-11-16.json" in names and
              "checklist_records_all.pdf" in names and "VERIFY.txt" in names,
              f"the zip holds every day's PDF and JSON, the combined PDF and "
              f"VERIFY.txt: {names}")
        ver = z.read("VERIFY.txt").decode("utf-8")
        check("Hash chain verification: INTACT" in ver and
              "Days in this export: 3" in ver and
              svc.chain.records[-1]["hash"] in ver, f"VERIFY.txt: {ver[:200]}")
        allpdf = z.read("checklist_records_all.pdf")
        at = PM.extract_text(allpdf)
        check("Contents" in at and f"Show date {day1}" in at and
              "Show date 2026-11-16" in at and "page 2" in at and
              "Hash chain verification for the whole set: INTACT" in at,
              "the combined PDF has a table of contents with page numbers "
              "and the whole-set verification")
        check(PM.page_count(allpdf) >= 4, "and a page per day plus contents")
        day16 = PM.extract_text(z.read("checklist_2026-11-16.pdf"))
        check("Gas off" in day16 and "Andy at" in day16 and
              "Morning: not complete" in day16, "each day's PDF is its own")
        name2, data2 = svc.export_zip("2026-11-15", "2026-11-15")
        n2 = _zf.ZipFile(_io.BytesIO(data2)).namelist()
        check("checklist_2026-11-15.pdf" in n2 and
              f"checklist_{day1}.pdf" not in n2 and
              "checklist_2026-11-16.pdf" not in n2,
              f"a date range narrows the export: {n2}")
        # The tally: configured, it queues on disk and retries.
        tok = os.path.join(d, "tally.token")
        open(tok, "w").write("secret-token-123\n")
        cfg2 = MO.MorningConfig.parse(dict(_j.loads(_j.dumps(_MO_CONFIG)),
                                           tally={"enabled": True,
                                                  "url": "https://tally.example/in",
                                                  "token_file": tok}), "x",
                                      _MO_FLAMESAFE["groups"])
        fail = [True]
        sent = []
        tl = []

        def transport(url, data, headers, timeout):
            sent.append((url, _j.loads(data), dict(headers), timeout))
            if fail[0]:
                raise OSError("no route to host")
            return 200, "ok"
        svc2 = CL.ChecklistService(cfg2, os.path.join(d, "cl2"),
                                   night=lambda: _dt.date(2026, 11, 20),
                                   journal=lambda t, **f: tl.append((t, f)),
                                   wall=lambda: wall[0],
                                   clock=lambda: wall[0],
                                   transport=transport, threaded=False)
        st, out = svc2.post("checklist-tick", {"checklist": "shutdown",
                                               "step": "step-1",
                                               "who": "Andy"}, "Rack screen",
                            "Rack screen", True)
        check(st == 200, "a tick with the tally on")
        pend = svc2.tally.pending()
        # Three payloads: the tick's record, the routine_complete record
        # (the one step was the whole routine) and the routine itself.
        check(len(pend) == 3 and sent and sent[0][0] ==
              "https://tally.example/in" and
              sent[0][2]["Authorization"] == "Bearer secret-token-123" and
              sent[0][1]["kind"] == "checklist_record" and
              sent[0][1]["v"] == 1 and sent[0][1]["record"]["who"] == "Andy",
              f"offline: the record and the completed routine wait on disk, "
              f"the try carried the token: {len(pend)} {sent[0][1]['kind']}")
        stt = svc2.tally.status()
        check(stt["queued"] == 3 and stt["failures"] >= 1 and
              "no route" in stt["last_error"] and
              "secret-token" not in _j.dumps(stt) and
              not any("secret-token" in t for t, _f in tl),
              f"the status says what is waiting and never the token: {stt}")
        n = svc2.tally.send_pending(wall[0])
        check(n == 0, "inside the backoff nothing is retried")
        fail[0] = False
        wall[0] += 10
        n = svc2.tally.send_pending(wall[0])
        check(n == 3 and svc2.tally.pending() == [] and
              svc2.tally.status()["sent"] == 3 and
              svc2.tally.status()["last_error"] == "",
              f"back online: all three delivered in order and the queue is "
              f"empty: {n}")
        kinds = [s[1]["kind"] for s in sent]
        check(kinds[-3:] == ["checklist_record", "checklist_record",
                             "checklist_routine"] and
              sent[-1][1]["routine"]["steps"][0]["done"] is True,
              f"the routine payload follows the record: {kinds}")
        st, out = svc2.post("checklist-tally-retry", {}, "Rack screen",
                            "Rack screen", True)
        check(st == 200, "the page's retry button")
        st, out = svc.post("checklist-tally-retry", {}, "Rack screen",
                           "Rack screen", True)
        check(st == 409 and "not switched on" in out["error"],
              "and with the tally off it says so")
    finally:
        shutil.rmtree(d, ignore_errors=True)
    print("  ok")


def test_morning_no_unlock_while_group_armed():
    section("Morning lockout at the engine (review of #122, P1-B): an UNLOCK "
            "of a machine is refused while its flame group is armed or "
            "asked for, or flamesafe's state is not known (none, stale, not "
            "connected), with 'Disarm <group> first, then unlock "
            "<machine>'; a lock is never held back; a laser is not "
            "affected; every surface (the page, the deck, a direct POST) "
            "comes through this route")
    import json as _j
    import shutil
    import tempfile
    from ltcplay import morning as MO
    d = tempfile.mkdtemp()
    try:
        fs = os.path.join(d, "flamesafe.json")
        with open(fs, "w", encoding="utf-8") as fh:
            _j.dump(_MO_FLAMESAFE, fh)
        with open(os.path.join(d, MO.CONFIG_FILE), "w",
                  encoding="utf-8") as fh:
            _j.dump(_MO_CONFIG, fh)
        names = [g["name"] for g in _MO_FLAMESAFE["groups"]]
        fsview = {"slots": [], "state": "read"}
        arm = {"front row": ("disarmed", False)}
        mode = ["live"]

        def flames():
            if mode[0] == "none":
                return None
            return {"connected": mode[0] != "gone", "stale": mode[0] == "stale",
                    "age_ms": 10, "fault": "", "lockout": dict(fsview),
                    "groups": [{"name": n,
                                "armed": arm.get(n, ("armed", True))[0],
                                "wanted": arm.get(n, ("armed", True))[1],
                                "reason": "", "dwell_s": 0} for n in names]}

        class _Sock:
            def sendto(self, pkt, addr):
                pass

            def close(self):
                pass
        m = MO.Morning(d, flamesafe_config=fs, link_get=lambda: None,
                       flames_get=flames, laser_output=_FakeLaserOutput,
                       live_check=lambda: "", group_names=lambda: names,
                       journal=lambda t, **f: None, clock=lambda: 100.0,
                       wall=lambda: 1_800_000_000.0, threaded=False,
                       socket_factory=_Sock)
        rack = ("Rack screen", "", "Rack screen", True, True)
        unlock = {"kind": "machine", "id": "g1", "on": False,
                  "confirmed": True}
        # Locking is never held back, armed or not.
        arm["front row"] = ("armed", True)
        st, out = m.post("lock", {"kind": "machine", "id": "g1", "on": True},
                         *rack)
        check(st == 200 and m.lockout.is_locked("machine", "g1"),
              f"a lock goes while the group is armed: {st} {out}")
        fsview["slots"] = sorted(m.lockout.channels(m.cfg))
        for name, a, md in (("armed", ("armed", False), "live"),
                            ("asked for", ("held", True), "live"),
                            ("flamesafe stale", ("disarmed", False), "stale"),
                            ("flamesafe not connected", ("disarmed", False),
                             "gone"),
                            ("flamesafe not known", ("disarmed", False),
                             "none")):
            arm["front row"] = a
            mode[0] = md
            st, out = m.post("lock", unlock, *rack)
            want = ("Disarm front row first, then unlock Ground 1."
                    if md == "live" else "flamesafe's armed groups are not "
                    "known right now, so Ground 1 stays locked out.")
            check(st == 409 and out.get("error", "").startswith(want) and
                  m.lockout.is_locked("machine", "g1"),
                  f"{name}: no unlock, said plainly: {st} {out}")
        # Disarmed and known: the unlock goes.
        arm["front row"] = ("disarmed", False)
        mode[0] = "live"
        st, out = m.post("lock", unlock, *rack)
        check(st == 200 and not m.lockout.is_locked("machine", "g1"),
              f"front row off: the unlock goes: {st} {out}")
        # A laser is not a flame group's: unaffected, every group armed.
        arm.clear()
        st, out = m.post("lock", {"kind": "laser", "id": "laser-1",
                                  "on": True}, *rack)
        check(st == 200, f"a laser locks: {st} {out}")
        st, out = m.post("lock", {"kind": "laser", "id": "laser-1",
                                  "on": False, "confirmed": True}, *rack)
        check(st == 200 and not m.lockout.is_locked("laser", "laser-1"),
              f"and unlocks, flame groups armed or not: {st} {out}")
        check(m.unlock_refusal("nope") == "",
              "an id the config does not know: no word from this check (the "
              "lock table says the rest)")
    finally:
        shutil.rmtree(d, ignore_errors=True)
    print("  ok")


def test_morning_lockout_trust_link_and_close():
    section("Morning and Shutdown, the lock table when it cannot be trusted: "
            "an unreadable lockout file, or one naming a machine the config "
            "no longer has, is never written over, shows on every screen, "
            "and stops the purge and the laser tests until it is fixed; the "
            "flame link learns the locks when it appears later; closing the "
            "engine turns every laser test off (review of PR #68, P1-3, P2-9)")
    import json as _j
    import shutil
    import tempfile
    from ltcplay import morning as MO
    d = tempfile.mkdtemp()
    try:
        fs = os.path.join(d, "flamesafe.json")
        with open(fs, "w", encoding="utf-8") as fh:
            _j.dump(_MO_FLAMESAFE, fh)
        cfg_path = os.path.join(d, MO.CONFIG_FILE)
        with open(cfg_path, "w", encoding="utf-8") as fh:
            _j.dump(_MO_CONFIG, fh)
        names = [g["name"] for g in _MO_FLAMESAFE["groups"]]
        fsview = {"slots": [], "state": "read"}
        # Every group armed, until a test unlocks (review of #122, P1-B:
        # no unlock while the group is armed).
        fsarm = {"armed": "armed", "wanted": True}

        def flames():
            return {"connected": True, "stale": False, "age_ms": 10,
                    "fault": "", "lockout": dict(fsview),
                    "groups": [{"name": n, "armed": fsarm["armed"],
                                "wanted": fsarm["wanted"],
                                "reason": "", "dwell_s": 0} for n in names]}
        lines = []
        holder = [None]
        osc = []
        clk = [100.0]

        class _Sock:
            def sendto(self, pkt, addr):
                osc.append((addr, pkt))

            def close(self):
                pass

        laser_out = _FakeLaserOutput()

        def build():
            return MO.Morning(d, flamesafe_config=fs,
                              link_get=lambda: holder[0], flames_get=flames,
                              laser_output=lambda: laser_out,
                              live_check=lambda: "",
                              group_names=lambda: names,
                              journal=lambda t, **f: lines.append((t, f)),
                              clock=lambda: clk[0],
                              wall=lambda: 1_800_000_000.0, threaded=False,
                              socket_factory=_Sock)
        rack = ("Rack screen", "", "Rack screen", True, True)
        lk = os.path.join(d, MO.LOCKOUT_FILE)
        # (a) The lockout file cannot be read: what is locked is unknown.
        with open(lk, "w", encoding="utf-8") as fh:
            fh.write("{ broken")
        m = build()
        sv = m.status_view()
        check("could not be read" in sv["lock_error"],
              f"an unreadable lockout file is said on every screen: {sv}")
        st, out = m.post("lock", {"kind": "machine", "id": "g1", "on": True},
                         *rack)
        check(st == 409 and "could not be read" in out["error"] and
              open(lk, encoding="utf-8").read() == "{ broken",
              f"a lock is refused and the file is not written over: {out}")
        ok, text = m.lockout.set(m.cfg, "machine", "g1", True, "", "Rack")
        check(not ok and "not touched" in text and
              open(lk, encoding="utf-8").read() == "{ broken",
              f"and the table itself refuses too (the belt): {text}")
        st, out = m.post("purge-select", {"machine": "g1"}, *rack)
        check(st == 409 and "lockout file" in out["error"] and
              m.purge.selected == [], f"no purge: {out}")
        st, out = m.post("laser-test", {"laser": "laser-3", "on": True},
                         *rack)
        check(st == 409 and not m.lasers.on and not osc,
              f"no laser test: {out}")
        m.close()
        # (b), (c) The file names a machine the config does not (renamed,
        # or ltcplay_morning.json fell back to the defaults): its slots are
        # unknown, so the file keeps what flamesafe is enforcing.
        with open(lk, "w", encoding="utf-8") as fh:
            _j.dump({"lockout_format": 1, "flame_channels": [412, 999],
                     "machines": {"g2": {"since": "x"}, "ghost": {}},
                     "lasers": {}}, fh)
        before = open(lk, encoding="utf-8").read()
        m = build()
        sv = m.status_view()
        check("ghost" in sv["lock_error"] and
              "ghost (not in ltcplay_morning.json)" in sv["locked_machines"]
              and "Ground 2" in sv["locked_machines"],
              f"a locked id the config lacks is named, as unknown: {sv}")
        st, out = m.post("lock", {"kind": "machine", "id": "g2", "on": False,
                                  "confirmed": True}, *rack)
        check(st == 409 and open(lk, encoding="utf-8").read() == before and
              m.lockout.is_locked("machine", "g2"),
              f"an unlock is refused and the file keeps flamesafe's slots "
              f"412 and 999: {out}")
        st, out = m.post("lock", {"kind": "machine", "id": "g1", "on": True},
                         *rack)
        check(st == 409 and open(lk, encoding="utf-8").read() == before,
              "and so is a lock")
        st, out = m.post("purge-select", {"machine": "g1"}, *rack)
        check(st == 409 and m.purge.selected == [], "no purge")
        m.close()
        # The config fixed (the machine back under its id): everything
        # resolves and the file is written again from a trusted table.
        cfg2 = _j.loads(_j.dumps(_MO_CONFIG))
        cfg2["machines"].append({"id": "ghost", "name": "Ghost",
                                 "kind": "gflame", "group": "front row",
                                 "fire": [413]})
        with open(cfg_path, "w", encoding="utf-8") as fh:
            _j.dump(cfg2, fh)
        m = build()
        sv = m.status_view()
        check("config changed under a lock" in sv["lock_error"] and
              set(sv["locked_machines"]) == {"Ground 2", "Ghost"},
              f"both ids resolve now, but the file's slots (412, 999) and "
              f"the config's (412, 413) differ: said, not guessed: {sv}")
        st, out = m.post("lock", {"kind": "machine", "id": "ghost",
                                  "on": False, "confirmed": True}, *rack)
        check(st == 409 and open(lk, encoding="utf-8").read() == before,
              "still nothing is written until it is rewritten on purpose")
        # The one way out: a confirmed rewrite on the show machine itself.
        st, out = m.post("lock", {"kind": "rewrite", "confirmed": True},
                         "iPad at 10.20.0.44", "", "iPad", True, False)
        check(st == 403 and open(lk, encoding="utf-8").read() == before,
              f"a rewrite from the network is refused: {out}")
        st, out = m.post("lock", {"kind": "rewrite"}, *rack)
        check(st == 409 and "confirm" in out["error"], "and needs a confirm")
        st, out = m.post("lock", {"kind": "rewrite", "confirmed": True}, *rack)
        check(st == 200 and _j.load(open(lk, encoding="utf-8"))
              ["flame_channels"] == [412, 413] and
              m.status_view()["lock_error"] == "",
              f"rewritten from the table: 412 and 413, resolved: {out}")
        check(any(f.get("outcome") == "rewritten" and f.get("fault")
                  for t, f in lines), "and journaled as a fault")
        fsview["slots"] = [412, 413]
        st, out = m.post("lock", {"kind": "machine", "id": "ghost",
                                  "on": False, "confirmed": True}, *rack)
        check(st == 409 and out.get("error") == "Disarm front row first, "
              "then unlock Ghost.",
              f"review of #122, P1-B: no unlock while the group is armed, "
              f"at the engine: {st} {out}")
        fsarm.update(armed="disarmed", wanted=False)
        st, out = m.post("lock", {"kind": "machine", "id": "ghost",
                                  "on": False, "confirmed": True}, *rack)
        check(st == 200 and _j.load(open(lk, encoding="utf-8"))
              ["flame_channels"] == [412],
              f"an unlock writes the file again: {out}")
        # The flame link appears after the engine started (fire_ice built
        # later): the next watcher pass hands it the locks.
        check(holder[0] is None and m.lockout.channels(m.cfg) == {412},
              "no link yet")
        link = _FakePurgeLink()
        holder[0] = link
        m.tick()
        check(link.locked == {412},
              "the link learns the locked slots on the next watcher pass")
        # Closing the engine turns every laser test off.
        fsview["slots"] = [412]
        ok, text = m.laser_arm.arm(["laser-3"], who="Andy", confirmed=True)
        check(ok, f"Laser 3 arms: {text}")
        st, out = m.post("laser-test", {"laser": "laser-3", "on": True},
                         *rack)
        check(st == 200 and "laser-3" in m.lasers.on, f"a test on: {out}")
        n = len(osc)
        del laser_out.calls[:]
        m.close()
        check(not m.lasers.on and len(osc) > n and
              osc[-1][1].startswith(b"/beyond/general/stopcue"),
              "close turns it off with the laser's off list")
        check(m.laser_arm.armed_ids() == [] and
              laser_out.calls == ["blank", "disable"],
              f"and the engine stopping disarms every laser and tells "
              f"BEYOND: {laser_out.calls}")
        # (d) The engine starts with NO lockout file while flamesafe still
        # holds a set (the file was deleted; flamesafe kept it, missing_kept):
        # nothing is written and nothing fires until it is resolved on
        # purpose, or writing the table would lift flamesafe's lock
        # silently (review of PR #68, P1-5).
        os.remove(lk)
        fsview.clear()
        fsview.update(slots=[412], state="missing_kept")
        del lines[:]
        m = build()
        sv = m.status_view()
        check("does not know about" in sv["lock_error"] and
              sv["flamesafe_extra"] == [412] and sv["locked_machines"] == [],
              f"flamesafe holds 412, this engine knows nothing: said: {sv}")
        st, out = m.post("lock", {"kind": "machine", "id": "w1", "on": True},
                         *rack)
        check(st == 409 and not os.path.exists(lk),
              f"a lock is refused and no file is written, so flamesafe keeps "
              f"412: {out}")
        st, out = m.post("purge-select", {"machine": "g1"}, *rack)
        check(st == 409 and "does not know about" in out["error"],
              f"no purge: {out}")
        m.tick()
        check(any(f.get("outcome") == "unconfirmed" and "disappeared" in t
                  for t, f in lines), "journaled as a fault")
        st, out = m.post("lock", {"kind": "rewrite", "confirmed": True}, *rack)
        check(st == 200 and _j.load(open(lk, encoding="utf-8"))
              ["flame_channels"] == [], "the deliberate way out writes an "
                                          "empty file (flamesafe then lifts "
                                          "412)")
        # flamesafe takes up to its poll time to read the new file: for
        # LOCK_SETTLE_S after this engine's own write its old report is not
        # a problem (review of PR #68, P3-12), after that it is again.
        check(m.status_view()["lock_error"] == "" and
              m.lock_problem() == "",
              "just after the write flamesafe's old report is not a problem")
        clk[0] += MO.LOCK_SETTLE_S + 0.5
        check("does not know about" in m.lock_problem(),
              "flamesafe still holding 412 after the settle time is")
        fsview.update(slots=[], state="read")
        check(m.status_view()["lock_error"] == "", "resolved")
        # A file with machines but no flame_channels list is not a lockout
        # file flamesafe can read: said as such (P3-13), not as a change.
        m.close()
        with open(lk, "w", encoding="utf-8") as fh:
            _j.dump({"lockout_format": 1, "machines": {"g2": {}}}, fh)
        m = build()
        check("no flame_channels" in m.status_view()["lock_error"],
              f"a file with no flame_channels list: {m.status_view()['lock_error']}")
        m.close()
        with open(lk, "w", encoding="utf-8") as fh:
            _j.dump({"lockout_format": 1, "flame_channels": [],
                     "machines": {}, "lasers": {}}, fh)
        m = build()
        st, out = m.post("lock", {"kind": "machine", "id": "w1", "on": True},
                         *rack)
        check(st == 200 and m.lockout.is_locked("machine", "w1") and
              m.lockout.wrote,
              "and locks work again")
        # The settle time belongs to a REAL write only (second review,
        # P3-1): flamesafe starts holding a slot this engine does not know
        # right after the write; a no-op lock ("already locked", nothing
        # written) every second must not keep hiding it past LOCK_SETTLE_S.
        fsview.update(slots=[431, 432, 433, 999], state="read")
        check(m.lock_problem() == "", "inside the settle time: not yet said")
        for _ in range(4):
            clk[0] += 1.0
            st, out = m.post("lock", {"kind": "machine", "id": "w1",
                                      "on": True}, *rack)
            if st != 200:
                break
            check("already locked" in out["text"] and not m.lockout.wrote,
                  f"a no-op lock answers without writing: {out}")
        check(st == 409 and "does not know about" in out["error"],
              f"4 s of no-op locks later the extra slot is said and the "
              f"lock refused; the no-ops did not restart the settle time: "
              f"{st} {out}")
        # An unlock does earn it (P3-12's own case, the lock route): right
        # after, flamesafe's old report of w1's slots is not a problem.
        fsview.update(slots=[431, 432, 433], state="read")
        check(m.lock_problem() == "", "flamesafe agrees again")
        st, out = m.post("lock", {"kind": "machine", "id": "w1", "on": False,
                                  "confirmed": True}, *rack)
        check(st == 200 and m.lockout.wrote and
              m.lockout.channels(m.cfg) == set() and
              m.lock_problem() == "" and m.status_view()["lock_error"] == "",
              f"an unlock is written and flamesafe's old report (431 to 433) "
              f"is not a problem for the settle time: {out} "
              f"{m.lock_problem()!r}")
        clk[0] += MO.LOCK_SETTLE_S + 0.5
        check("does not know about" in m.lock_problem(),
              "but after the settle time it is")
        fsview.update(slots=[], state="read")
        m.close()
        # (e) flamesafe reading another lockout file than this engine writes
        # is said at start (review of PR #68, P2-12).
        d2 = tempfile.mkdtemp()
        try:
            fs2 = os.path.join(d2, "flamesafe.json")
            with open(fs2, "w", encoding="utf-8") as fh:
                _j.dump(_MO_FLAMESAFE, fh)
            del lines[:]
            m = MO.Morning(d, flamesafe_config=fs2, link_get=lambda: None,
                           flames_get=flames, live_check=lambda: "",
                           group_names=lambda: names,
                           journal=lambda t, **f: lines.append((t, f)),
                           threaded=False, socket_factory=_Sock)
            m.close()
            # The paths are named as realpath() gives them (on Windows the
            # temp folder's 8.3 short name becomes the long one).
            check(any(f.get("outcome") == "unconfirmed" and "never seen there"
                      in t and os.path.realpath(d2) in t and
                      os.path.realpath(d) in t for t, f in lines),
                  f"flamesafe.json in another folder: both paths named: "
                  f"{[t[:80] for t, f in lines]}")
            with open(fs2, "w", encoding="utf-8") as fh:
                _j.dump(dict(_MO_FLAMESAFE, lockout_file=False), fh)
            del lines[:]
            m = MO.Morning(d, flamesafe_config=fs2, link_get=lambda: None,
                           flames_get=flames, live_check=lambda: "",
                           group_names=lambda: names,
                           journal=lambda t, **f: lines.append((t, f)),
                           threaded=False, socket_factory=_Sock)
            m.close()
            check(any(f.get("outcome") == "unconfirmed" and "false" in t
                      for t, f in lines), "lockout_file false: said")
            del lines[:]
            m = build()
            m.close()
            check(not any(f.get("outcome") == "unconfirmed" for t, f in lines),
                  "the same folder: nothing to say")
        finally:
            shutil.rmtree(d2, ignore_errors=True)
    finally:
        shutil.rmtree(d, ignore_errors=True)
    print("  ok")


def test_morning_arrange_mode_arms_nothing():
    section("Morning page, Arrange mode (Jeff, 2026-10-19, bench "
            "2026.10.19-6a32ff9: a picked-up machine followed the mouse for "
            "ever and the next click ARMED it): Arrange is a distinct mode "
            "in which no click, key, touch or drag arms, fires, locks or "
            "lights anything; a drag is pointer-down to pointer-up and "
            "pointerup, pointercancel, Escape, Save, Cancel, Reset, leaving "
            "the page, blur and the page hidden all end it; Save layout "
            "leaves the mode and only then does a press arm again; the "
            "engine refuses the same routes for a screen whose open beat "
            "says it is arranging (page logic in node on a small DOM, and "
            "the engine's routes)")
    import json as _j
    import shutil
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
