def test_rack_lasers_strip_engine():
    section("LASERS on the show screen (Jeff, 2026-10-22): the status "
            "carries every laser's arm state and whether an arm from this "
            "screen is refused before anyone confirms; Disarm all lasers "
            "goes signed out, from the show network with the screen arming "
            "switch off, while that screen arranges, and never waits on "
            "the show conductor; an arm from the strip is refused with its "
            "reason; Disarm every flame group leaves the lasers armed")
    import threading
    from ltcplay import remote as RM
    from ltcplay import laserarm as LA
    S = _sched()
    if S is None:
        return
    R = _morning_rig(S, config=_MO_CONFIG)
    loop = ("127.0.0.1", 5000)
    ipad = ("10.20.0.44", 50000)
    ids = ["laser-1", "laser-2", "laser-3", "laser-4"]
    threaded = None
    try:
        R.m.tick()
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        la = out.get("laser_arm") or {}
        check(st == 200 and [x.get("id") for x in la.get("lasers") or []]
              == ids and la.get("groups") == {"All lasers": ids} and
              la.get("armed") == 0 and la.get("arm_here") == "" and
              "per_laser_osc" not in la,
              f"the status carries the strip: every laser, the groups, "
              f"nothing armed, arming open on the rack screen: {la}")
        RM.save_settings(R.work, screen_arming=False)
        st, _h, out = R.ask("GET", "/api/remote/status", client=ipad)
        why = (out.get("laser_arm") or {}).get("arm_here") or ""
        check("screen_arming" in why and "Turn on" in why,
              f"from the show network with the switch off, the strip "
              f"says so before any confirm: {why!r}")
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        check((out.get("laser_arm") or {}).get("arm_here") == "",
              "the rack screen arms a laser without the switch, as on the "
              "Morning page")
        # An arm from the strip: the same route and rules as the Morning
        # page, refused with its reason.
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1"], "on": True,
                             "confirmed": True}, client=ipad)
        check(st == 403 and "screen_arming" in out.get("error", "") and
              not R.m.laser_arm.armed_ids(),
              f"no arm from the network with the switch off: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1"], "on": True},
                            client=loop)
        check(st == 409 and "confirm" in out.get("error", "") and
              not R.m.laser_arm.armed_ids(), f"no confirm, no arm: {out}")
        R.m.lockout.set(R.m.cfg, "laser", "laser-3", True, "Andy",
                        "Rack screen")
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ids, "on": True, "confirmed": True},
                            client=loop)
        check(st == 409 and "Laser 3 is locked out" in out.get("error", "")
              and not R.m.laser_arm.armed_ids(),
              f"a group with a locked laser: refused, named: {out}")
        R.m.lockout.set(R.m.cfg, "laser", "laser-3", False, "Andy",
                        "Rack screen", confirmed=True)
        real_blockers = R.m._laser_blockers
        R.m._laser_blockers = lambda: ("the show is aborted; press Reset "
                                       "first, then arm")
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1"], "on": True,
                             "confirmed": True}, client=loop)
        R.m._laser_blockers = real_blockers
        check(st == 409 and "aborted; press Reset" in out.get("error", ""),
              f"the Abort latch refuses, in words: {out}")
        R.laser_out.fault = "Lasers: blanking not set up"
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1"], "on": True,
                             "confirmed": True}, client=loop)
        R.laser_out.fault = None
        check(st == 409 and "blanking not set up" in out.get("error", ""),
              f"no blanking, no arm, in words: {out}")
        st, _h, who = R.ask("GET", "/api/remote/whoami", client=loop)
        R.m.open_beat(who["device"], arranging=True, inst="lz", seq=1)
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1"], "on": True,
                             "confirmed": True}, client=loop)
        check(st == 409 and "Arrange" in out.get("error", "") and
              not R.m.laser_arm.armed_ids(),
              f"Arrange blocks an arm: {out}")
        R.m.open_beat(who["device"], arranging=False, inst="lz", seq=2)
        st, _h, out = R.ask("POST", "/api/remote/laser-arm",
                            {"lasers": ["laser-1", "laser-2"], "on": True,
                             "confirmed": True}, client=loop)
        R.m.laser_arm.run_pending()
        check(st == 200 and R.m.laser_arm.armed_ids() ==
              ["laser-1", "laser-2"], f"a confirmed arm goes: {out}")
        st, _h, out = R.ask("GET", "/api/remote/status", client=loop)
        la = out.get("laser_arm") or {}
        check([x["armed"] for x in la.get("lasers") or []] ==
              [True, True, False, False] and la.get("armed") == 2 and
              la.get("output_permitted") is False,
              f"the strip reads two armed, the output off: {la}")
        # Disarm every flame group (the flame button and the alert's
        # Disarm all) leaves the lasers alone (Jeff, 2026-10-22).
        del R.laser_out.calls[:]
        nb = R.rig.count("lasers_blank")
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {},
                            client=loop)
        R.m.tick()
        R.m.laser_arm.run_pending()
        R.settle()
        check(R.m.laser_arm.armed_ids() == ["laser-1", "laser-2"] and
              "disable" not in R.laser_out.calls and
              R.rig.count("lasers_blank") == nb,
              f"Disarm every flame group did not disarm, blank or switch "
              f"off a laser: {st} {out} {R.laser_out.calls}")
        # Disarm all lasers: signed out (a role matrix that forbids
        # arming), from the show network, the switch off, that screen
        # arranging, the conductor's lock held by a stuck thread.
        # As in the engine (threaded: the route only queues the dark job),
        # but with no sender thread of its own, so nothing races the
        # request for the job: a route that ran the queue itself would
        # block on the conductor's lock, every time.
        threaded = LA.LaserArm(
            [(l.id, l.name) for l in R.m.cfg.lasers],
            groups=R.m.cfg.laser_groups, output=lambda: R.laser_out,
            blank_now=R.c.lasers_dark_now, threaded=False)
        threaded.run_pending()
        threaded._threaded = True
        threaded.arm(ids, who="Andy", confirmed=True)
        threaded.run_pending()
        check(threaded.armed_ids() == ids, "setup: every laser armed")
        real_arm, R.m.laser_arm = R.m.laser_arm, threaded

        class _NoArm:
            def may(self, role, perm):
                return perm != "arm"

            def machine_user(self):
                return None

            def active(self):
                return True
        R.remote.users = _NoArm()
        st, _h, who = R.ask("GET", "/api/remote/whoami", client=ipad)
        R.m.open_beat(who["device"], arranging=True, inst="lz", seq=3)
        check(R.m.device_arranging(who["device"]),
              "setup: the iPad is arranging")
        held, go = threading.Event(), threading.Event()

        def stuck():
            with R.c._lock:
                held.set()
                go.wait(10.0)
        th = threading.Thread(target=stuck, daemon=True)
        th.start()
        held.wait(5.0)
        got = []
        del R.laser_out.calls[:]
        t0 = time.perf_counter()
        pr = threading.Thread(target=lambda: got.append(R.ask(
            "POST", "/api/remote/laser-arm", {"all": True, "on": False},
            client=ipad)), daemon=True)
        pr.start()
        pr.join(1.5)
        took = time.perf_counter() - t0
        go.set()
        th.join(5.0)
        check(not pr.is_alive() and got and got[0][0] == 200 and
              threaded.armed_ids() == [],
              f"Disarm all lasers answered in {took:.2f} s with the "
              f"conductor stuck for 10 s, signed out, from the network with "
              f"the switch off, while that screen arranged: "
              f"{got[0][:3:2] if got else 'no answer'}")
        check(threaded.pending() == ["dark"],
              f"the route left the blank and DisableLaserOutput to the "
              f"sender: {threaded.pending()}")
        threaded.run_pending()
        check("disable" in R.laser_out.calls,
              f"and once the conductor let go, BEYOND was blanked and its "
              f"laser output switched off: {R.laser_out.calls}")
        R.m.laser_arm = real_arm
    finally:
        if threaded is not None:
            threaded._threaded = False
            threaded.close()
        R.close()
    print("  ok")


def test_rack_lasers_strip_page():
    section("LASERS on the show screen, the page (Jeff, 2026-10-22): its own "
            "strip outside the flame block, violet, never sharing a button "
            "with the flames; Disarm all lasers goes stale, arranging, with "
            "arming switched off and with no confirm; a chip disarms an "
            "armed laser at once and arms only after the page's own "
            "refusals, Arrange and a confirm; refusals are said in words "
            "(page logic in node, and the wiring)")
    import shutil
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    page = open(os.path.join(here, "ltcplay", "web", "remote.html"),
                encoding="utf-8").read()
    vs = page.find('<section id="v-show"')
    fl = page.find('<div class="flames">', vs)
    lz = page.find('<div class="lz" id="lz" hidden aria-label="Lasers">', vs)
    end = page.find("</section>\n\n  <!-- Schedule (was Tonight", vs)
    flames = page[fl:page.find("<!-- LASERS", fl)]
    check(0 < vs < fl < len(flames) + fl <= lz < end,
          "the LASERS strip is on the show screen, after the flame block")
    check(flames.count("<div") == flames.count("</div>"),
          "the LASERS strip is not inside the flame block")
    check('<button id="b-disarm" class="disarm"' in flames and
          '<span class="lbl">Disarm all flame groups</span><small>' in flames
          and "laser" not in flames.lower(),
          "the flame block keeps its own Disarm all flame groups and "
          "nothing of the lasers")
    check('<button class="lzdis" id="lz-disarm">Disarm all lasers</button>'
          in page[lz:end] and 'class="disarm"' not in page[lz:end],
          "Disarm all lasers is its own button, not styled as a flame one")
    line = [ln for ln in page.splitlines()
            if 'ALL_BTN.addEventListener("click"' in ln]
    check(len(line) == 1 and 'press("disarm-all")' in line[0] and
          "laser" not in line[0].lower() and
          'const ALL_BTN = $("b-disarm");' in page,
          f"Disarm every flame group presses disarm-all only: {line}")
    check("  renderLaserStrip(ST && ST.laser_arm, stale);\n  renderMode(stale);"
          in page, "the strip is drawn every 250 ms, stale or not")
    rules = _css_rules(page)
    lzr = _css_rule(rules, ".lz") or {}
    chips = _css_rule(rules, ".lz-chips") or {}
    dis = _css_rule(rules, "button.lzdis") or {}
    check(lzr.get("flex") == "0 0 auto" and
          "var(--laser)" in lzr.get("border", ""),
          f"the strip keeps its height and its violet frame: {lzr}")
    check(chips.get("min-width") == "0" and
          chips.get("overflow") == "hidden",
          f"the chips can never widen the page: {chips}")
    check("var(--laser)" in dis.get("border", "") and
          "var(--laser-deep)" in dis.get("background", ""),
          f"Disarm all lasers is violet, never the flames' bronze: {dis}")
    check((_css_rule(rules, ".lz .toast:empty") or {}).get("display") ==
          "none", "the strip's message line takes no room until it says "
                  "something")
    a = page.find("// LASER STRIP BEGIN")
    b = page.find("// LASER STRIP END")
    check(0 < a < b, "the page has its LASER STRIP block")
    block = page[a:b]
    for bad in ("—", "–"):
        check(bad not in block, "no em or en dashes in the strip")
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner, so the LASERS "
                         "strip cannot be run; install node in the workflow")
        print("  note: node is not on this machine, so the strip was "
              "checked by reading only (CI runs it)")
        print("  ok")
        return
    prelude = r"""
"use strict";
class Node {
  constructor(id){ this.id = id; this.listeners = {}; this.dataset = {}; this.hidden = false; this.textContent = ""; this.title = ""; this.className = ""; this.innerHTML = ""; }
  addEventListener(t, f){ (this.listeners[t] = this.listeners[t] || []).push(f); }
  fire(t, e){ for(const f of this.listeners[t] || []) f(e || {}); }
}
const byId = {};
for(const id of ["lz", "lz-st", "lz-chips", "lz-disarm", "lz-msg", "mo-msg"]) byId[id] = new Node(id);
const $ = id => byId[id];
const esc = (t) => String(t == null ? "" : t).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
let posts = [], asked = [], ANSWER = true, ARRANGE = false, FAIL = null;
function post(p, body){ posts.push([p, body]); return FAIL ? Promise.reject(new Error(FAIL)) : Promise.resolve({text:"ok from the engine"}); }
function actor(extra){ return Object.assign({seen: 123}, extra || {}); }
async function confirmBox(q){ asked.push(q); return ANSWER; }
function arrangeBlocked(route, extra){
  if(!ARRANGE) return false;
  if(route === "laser-arm" && extra && extra.on === true){ $("mo-msg").textContent = "ARRANGING"; return true; }
  return false;
}
"""
    body = r"""
const out = [];
const t = (c, m) => { if(!c) out.push(m); };
const L = (id, armed, locked) => ({id:id, name:"Laser " + id.slice(-1), armed:!!armed, locked:!!locked});
const VIEW = {lasers:[L("laser-1"), L("laser-2", true), L("laser-3", false, true), L("laser-4")],
  groups:{"All lasers":["laser-1", "laser-2", "laser-3", "laser-4"]}, output_permitted:false,
  why_off:"not every laser is armed", arm_refusal:null, arm_here:""};
const reset = () => { posts = []; asked = []; ANSWER = true; ARRANGE = false; FAIL = null; $("lz-msg").textContent = ""; };
(async () => {
// What it shows.
t(laserStripLook(undefined, false).show === false, "no laser arm in this engine: no strip");
t(laserStripLook({lasers:[], groups:{}}, false).show === false, "no lasers: no strip");
let k = laserStripLook({error:"boom"}, false);
t(k.show === true && k.chips.length === 0 && /Disarm all lasers still works/.test(k.title), "a broken view: the strip and its Disarm all lasers stay");
k = laserStripLook(VIEW, false);
t(k.state === "1 of 4 ARMED" && k.armed === true, "one armed: " + k.state);
t(k.chips.length === 5 && k.chips[0].label === "All lasers" && k.chips[0].word === "1 of 4" && k.chips[0].ids.length === 4, "the group chip first, with its count: " + JSON.stringify(k.chips[0]));
t(k.chips[2].cls === "armed" && k.chips[2].word === "armed" && /Click to disarm/.test(k.chips[2].title), "an armed laser reads ARMED and says a click disarms");
t(k.chips[1].cls === "" && k.chips[1].word === "off", "a disarmed laser reads off");
t(k.chips[3].cls === "locked" && k.chips[3].word === "locked", "a locked laser reads locked");
t(k.chips.every(c => c.off === false), "fresh: every chip can be pressed");
const all = Object.assign({}, VIEW, {lasers:VIEW.lasers.map(x => Object.assign({}, x, {armed:true, locked:false})), output_permitted:true});
t(laserStripLook(all, false).state === "ALL ARMED, output on" && laserStripLook(all, false).chips[0].word === "armed", "all armed and permitted: ALL ARMED, output on");
t(laserStripLook(Object.assign({}, all, {output_permitted:false}), false).state === "ALL ARMED, output off", "all armed, output not permitted: said");
t(laserStripLook(Object.assign({}, VIEW, {lasers:VIEW.lasers.map(x => Object.assign({}, x, {armed:false}))}), false).state === "All disarmed", "none armed: All disarmed");
k = laserStripLook(VIEW, true);
t(/Not known/.test(k.state) && k.chips.every(c => c.off === true && c.cls.indexOf("armed") < 0), "stale: not known, no chip pressable, nothing shown as armed");
t(/Arming from here is off: no switch/.test(laserStripLook(Object.assign({}, VIEW, {arm_here:"no switch"}), false).title), "the switch's refusal is in the strip's words");
// Drawing it, and the wiring.
renderLaserStrip(VIEW, false);
t($("lz").hidden === false && $("lz-st").textContent === "1 of 4 ARMED" && $("lz-st").className === "armed", "drawn: the state line");
t(($("lz-chips").innerHTML.match(/data-lz=/g) || []).length === 5 && !/ disabled/.test($("lz-chips").innerHTML), "drawn: five chips, none disabled");
renderLaserStrip(VIEW, true);
t(($("lz-chips").innerHTML.match(/ disabled/g) || []).length === 5, "stale: every chip disabled");
renderLaserStrip({lasers:[], groups:{}}, false);
t($("lz").hidden === true, "no lasers: hidden");
// Disarm all lasers: stale, arranging, the switch off, nobody confirming.
renderLaserStrip(Object.assign({}, VIEW, {arm_here:"no switch"}), true);
reset(); ARRANGE = true; ANSWER = false;
$("lz-disarm").fire("click");
await new Promise(r => setTimeout(r, 0));
t(posts.length === 1 && posts[0][0] === "/api/remote/laser-arm" && posts[0][1].all === true && posts[0][1].on === false, "Disarm all lasers posts all:true on:false whatever the page's state: " + JSON.stringify(posts));
t(asked.length === 0, "and asks no confirm");
t($("lz-msg").textContent === "ok from the engine", "and says the engine's answer");
reset(); FAIL = "the engine said no";
await lzDisarmAll();
t($("lz-msg").textContent === "the engine said no", "a failed disarm says why, never silent");
// A chip.
renderLaserStrip(VIEW, false);
reset(); ARRANGE = true; ANSWER = false;
$("lz-chips").fire("click", {target:{closest:() => ({disabled:false, dataset:{lz:"laser-2"}})}});
await new Promise(r => setTimeout(r, 0));
t(posts.length === 1 && posts[0][1].on === false && posts[0][1].lasers.join() === "laser-2" && asked.length === 0, "an armed laser's chip disarms at once, arranging, no confirm: " + JSON.stringify(posts));
reset();
$("lz-chips").fire("click", {target:{closest:() => ({disabled:true, dataset:{lz:"laser-1"}})}});
t(posts.length === 0 && asked.length === 0, "a disabled chip does nothing");
reset(); ANSWER = false;
await lzClick(["laser-1"]);
t(asked.length === 1 && /Arm Laser 1\?/.test(asked[0]) && posts.length === 0, "an arm asks to confirm; no, and nothing is posted");
reset();
await lzClick(["laser-1"]);
t(posts.length === 1 && posts[0][1].on === true && posts[0][1].confirmed === true && posts[0][1].lasers.join() === "laser-1", "confirmed: posted with on:true and confirmed:true");
reset(); FAIL = "Not armed: the show is aborted; press Reset first, then arm. Nothing was armed.";
await lzClick(["laser-1"]);
t($("lz-msg").textContent.indexOf("the show is aborted") >= 0, "the engine's refusal is said in its words: " + $("lz-msg").textContent);
reset(); ARRANGE = true;
await lzClick(["laser-1"]);
t(posts.length === 0 && asked.length === 0 && $("mo-msg").textContent === "ARRANGING", "Arrange holds an arm back before the confirm");
reset();
await lzClick(["laser-3"]);
t(posts.length === 0 && asked.length === 0 && /Laser 3 is locked out/.test($("lz-msg").textContent), "a locked laser: refused in words, no confirm: " + $("lz-msg").textContent);
reset();
renderLaserStrip(Object.assign({}, VIEW, {arm_here:"arming a laser from a device on the show network needs screen_arming"}), false);
await lzClick(["laser-1"]);
t(posts.length === 0 && asked.length === 0 && /needs screen_arming/.test($("lz-msg").textContent), "the switch off: refused in words, no confirm");
reset();
renderLaserStrip(VIEW, true);
await lzClick(["laser-1"]);
t(posts.length === 0 && asked.length === 0 && /no contact/.test($("lz-msg").textContent), "stale: no arm, said");
reset();
renderLaserStrip(VIEW, false);
await lzClick(["laser-1", "laser-2", "laser-3", "laser-4"].filter(x => x !== "laser-3"));
t(posts.length === 1 && posts[0][1].on === true && posts[0][1].lasers.length === 3, "a group with one armed: an arm of all of them, confirmed");
reset();
await lzClick([]);
t(posts.length === 0 && /no laser was named/.test($("lz-msg").textContent), "nothing named: nothing posted");
console.log(JSON.stringify(out));
process.exit(0);
})().catch(e => { console.log(JSON.stringify(["threw: " + e])); process.exit(0); });
"""
    r = _node_js(node, prelude + block + body, capture_output=True,
                text=True, timeout=60)
    try:
        bad = json.loads(r.stdout.strip().splitlines()[-1] or "null")
    except (ValueError, IndexError):
        bad = None
    check(r.returncode == 0 and bad == [],
          f"the LASERS strip, in node: {r.stdout[-1500:]!r} "
          f"{r.stderr[-600:]!r}")
    print("  ok")



def test_disarm_all_is_a_plain_disarm_and_never_gated():
    section("Disarm all flame groups (Jeff, 2026-10-23): a plain disarm of "
            "every group through the Stream Deck, no Abort latch and no "
            "forced cycle; signed out, screen arming off, a stale page; the "
            "lasers untouched; the Abort's disarm only when the deck is not "
            "reading or flamesafe does not confirm every group off in 1 s, "
            "and an alert that says COULD NOT when even that fails")
    import json as _j
    import types
    from ltcplay import remote as RM
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        rem = R.remote
        names = ["front row", "cat-walk", "wave flamer"]
        rem.flame_status = RM.FlameStatus("127.0.0.1", 0, "k" * 20, names,
                                          clock=lambda: R.mono[0])

        def fs(armed, wanted=None):
            rem.flame_status.note(_j.dumps({
                "t": "status", "k": "k" * 20, "fault": "",
                "groups": [{"name": n, "armed": a,
                            "wanted": (a == "armed") if wanted is None
                            else wanted[k], "reason": ""}
                           for k, (n, a) in enumerate(zip(names, armed))]}
            ).encode())
        later = []
        rem._later = lambda s, fn: later.append((s, fn))
        order = []
        lz = []
        rem.morning = types.SimpleNamespace(
            on_abort=lambda *a: order.append("on_abort"),
            lasers_disarm_now=lambda *a: lz.append(a),
            purge=types.SimpleNamespace(
                clear=lambda why: order.append(("purge", len(rem._disarms)))),
            lasers=types.SimpleNamespace(
                all_off=lambda why: order.append(
                    ("tests", len(rem._disarms)))))
        RM.save_settings(R.work, screen_arming=False)
        fs(["armed", "disarmed", "armed"])
        rem.deck_input()                       # the deck reads: fresh
        n = R.rig.count("flames_disarm_all")
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {"seen": 1})
        ev = [e for e in rem.deck_input()["disarms"] if e.get("all")]
        check(st == 200 and out.get("plain") is True and
              [e["group"] for e in ev] == [0, 1, 2] and
              R.rig.count("flames_disarm_all") == n,
              f"a plain disarm: every group handed to the deck, no "
              f"flame-link disarm_all, with screen arming off and a stale "
              f"page: {st} {out} {ev}")
        check(order == [("purge", 0), ("tests", 3)],
              f"the purge selection is cleared before the disarm, the laser "
              f"tests end after it, and Abort's on_abort is not called: "
              f"{order}")
        check("needs no reset" in out.get("text", "") and
              "Abort" not in out.get("text", ""),
              f"the answer says it is the plain one: {out.get('text')}")
        _no_dashes(out.get("text", ""), "the plain disarm answer")
        check(lz == [], f"the lasers are not touched: {lz}")
        check(len(later) == 1 and later[0][0] == RM.PLAIN_CONFIRM_S == 1.0,
              f"its confirmation is checked 1 s later: {later}")
        # flamesafe reports every group off: confirmed, nothing forced.
        fs(["disarmed", "disarmed", "disarmed"])
        check(later[0][1]() is True and
              R.rig.count("flames_disarm_all") == n and
              not [a for a in rem.alerts.view() if a["kind"] == "flames"],
              "confirmed off: no Abort-style disarm, no alert")
        # Off but still wanted is not confirmed.
        del later[:]
        fs(["armed", "armed", "armed"])
        rem.deck_input()
        R.ask("POST", "/api/remote/disarm-all", {})
        fs(["disarmed", "disarmed", "disarmed"], [False, True, False])
        check(later[0][1]() is False and
              R.rig.count("flames_disarm_all") == n + 1,
              "a group still wanted at the check: forced")
        rem.alerts.clear(kind="flames", action="Acknowledge")
        n = R.rig.count("flames_disarm_all")
        # Still armed at the check: the Abort's disarm goes, said.
        del later[:]
        fs(["armed", "armed", "armed"])
        rem.deck_input()
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {})
        check(st == 200 and out.get("plain") is True and len(later) == 1,
              f"again, signed out: {st} {out}")
        R.mono[0] += 0.2
        fs(["armed", "disarmed", "disarmed"])
        check(later[0][1]() is False and
              R.rig.count("flames_disarm_all") == n + 1,
              "not confirmed off in time: the flame link's disarm_all goes")
        al = [a for a in rem.alerts.view() if a["kind"] == "flames"]
        check(len(al) == 1 and "front row" in al[0]["text"] and
              "Arm again" in al[0]["text"] and
              "COULD NOT" not in al[0]["text"],
              f"and an alert names the group and what it means: {al}")
        rows = [r for r in R.svc.journal if r.get("action") == "disarm all"]
        check(rows and "plain disarm could not go" in rows[-1]["text"],
              f"journaled as the forced disarm: {rows[-1:]}")
        rem.alerts.clear(kind="flames", action="Acknowledge")
        # A newer press supersedes an older confirmation.
        del later[:]
        rem.deck_input()
        R.ask("POST", "/api/remote/disarm-all", {})
        R.ask("POST", "/api/remote/disarm-all", {})
        m = R.rig.count("flames_disarm_all")
        fs(["armed", "armed", "armed"])
        check(later[0][1]() is None and
              R.rig.count("flames_disarm_all") == m,
              "an older press's check is superseded by the newer one")
        # The status stale at the check: not confirmed, so forced.
        R.mono[0] += 5
        check(later[1][1]() is False and
              R.rig.count("flames_disarm_all") == m + 1,
              "a stale flamesafe status confirms nothing: forced")
        rem.alerts.clear(kind="flames", action="Acknowledge")
        # The status stale AT THE PRESS: every group is checked later.
        del later[:]
        R.mono[0] += 5
        rem.deck_input()
        m = R.rig.count("flames_disarm_all")
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {})
        fs(["disarmed", "armed", "disarmed"])
        check(out.get("plain") is True and later and
              later[0][1]() is False and
              R.rig.count("flames_disarm_all") == m + 1,
              f"a press while flamesafe's status was stale watches every "
              f"group: {out}")
        rem.alerts.clear(kind="flames", action="Acknowledge")
        # No way to schedule the check: forced at once, never unconfirmed.
        rem._later = lambda s, fn: 1 / 0
        fs(["armed", "armed", "armed"])
        rem.deck_input()
        m = R.rig.count("flames_disarm_all")
        R.ask("POST", "/api/remote/disarm-all", {})
        check(R.rig.count("flames_disarm_all") == m + 1,
              "a confirmation that cannot be scheduled forces at once")
        rem.alerts.clear(kind="flames", action="Acknowledge")
        rem._later = lambda s, fn: later.append((s, fn))
        # A screen hold is let go by Disarm all itself, whoever calls it.
        rem._holds[0] = {"token": "x", "who": "A", "device": "iPad",
                         "start": R.mono[0], "beat": R.mono[0], "id": 9}
        rem.deck_input()
        rem.disarm_all("Andy", "Rack screen")
        check(not rem._holds, f"no screen hold survives it: {rem._holds}")
        # The deck not reading this engine: the Abort's disarm at once.
        del later[:]
        fs(["armed", "armed", "armed"])
        check(RM.PLAIN_DECK_FRESH_S <= 0.5,
              f"the deck must have read within 0.5 s: "
              f"{RM.PLAIN_DECK_FRESH_S}")
        R.mono[0] += 0.6
        k = R.rig.count("flames_disarm_all")
        st, _h, out = R.ask("POST", "/api/remote/disarm-all", {})
        check(st == 200 and out.get("plain") is False and
              R.rig.count("flames_disarm_all") == k + 1 and not later and
              "Stream Deck program is not reading" in out.get("text", ""),
              f"a deck that last read 0.6 s ago: the flame link's "
              f"disarm_all at once, said: {st} {out}")
        check(lz == [], f"the lasers are still not touched: {lz}")
        # The forced disarm failing too: the alert says COULD NOT.
        real = rem._flame_disarm
        rem._flame_disarm = lambda reason: types.SimpleNamespace(
            ok=False, sentence="no flame link frame went out")
        rem.deck_input()
        R.ask("POST", "/api/remote/disarm-all", {})
        fs(["armed", "armed", "armed"])
        later[-1][1]()
        al = [a for a in rem.alerts.view() if a["kind"] == "flames"]
        check(al and "COULD NOT" in al[-1]["text"] and
              "press Abort" in al[-1]["text"] and
              "Every group was sent" not in al[-1]["text"],
              f"a forced disarm that failed is never said as done: {al}")
        rem._flame_disarm = real
        # The page says which one a press does.
        page = open(os.path.join(os.path.dirname(os.path.abspath(
            __file__)), "ltcplay", "web", "remote.html"),
            encoding="utf-8").read()
        check('<span class="lbl">Disarm all flame groups</span><small>plain '
              'disarm: arm again with a hold</small>' in page and
              'abort-sub").textContent = idle ? "Nothing to abort right '
              'now" : "Stops the show. Flames then need Arm again"' in page,
              "the page labels the plain disarm and the Abort apart")
    finally:
        R.close()
    print("  ok")


def test_disarm_ids_survive_an_engine_restart():
    section("review of PR #97, P2-3: the Stream Deck keeps the highest "
            "disarm id across an engine restart, so a new engine's ids "
            "start above the old one's and its first plain disarm lands "
            "with no fallback")
    import json as _j
    import types
    import tempfile
    from ltcplay import remote as RM
    from ltcplay import streamdeck as sd
    t = [1000.0]
    w = [1_800_000_000.0]
    names = ["front row", "cat-walk"]

    def engine():
        r = RM.Remote(types.SimpleNamespace(session=None), None,
                      folder=tempfile.gettempdir(), clock=lambda: t[0],
                      wall=lambda: w[0])
        r.flame_status = RM.FlameStatus("127.0.0.1", 0, "k" * 20, names,
                                        clock=lambda: t[0])
        r.flame_status.note(_j.dumps({
            "t": "status", "k": "k" * 20, "fault": "",
            "groups": [{"name": n, "armed": "armed", "wanted": True,
                        "reason": ""} for n in names]}).encode())
        r._later = lambda s, fn: None
        return r
    old = engine()
    for _ in range(40):
        old.disarm_all("Andy", "Rack screen")
        old.deck_input()
    current = [old]
    keys = sd.ScreenKeys("http://x", fetcher=lambda p: (
        current[0].deck_input() if current[0] is not None else None),
        clock=lambda: t[0])
    keys.poll_once()                         # the deck starts: history
    current[0] = None
    keys.poll_once()                         # the engine is restarting
    w[0] += 5.0
    new = engine()
    current[0] = new
    keys.poll_once()
    code, out = new.disarm_all("Andy", "Rack screen")
    keys.poll_once()
    got = keys.new_disarms()
    check(out.get("plain") is True and
          sorted(e["group"] for e in got) == [0, 1],
          f"after the restart the deck is handed the new disarms: {out} "
          f"{got}")
    check(min(e["id"] for e in new.deck_input()["disarms"]) >
          max(e["id"] for e in old.deck_input()["disarms"]),
          "a new engine's ids are above the old engine's")
    # The PC's clock stepped back two minutes between two engine runs
    # (second review, P3-3): the range the last engine reserved in the
    # settings folder still puts the new ids above the old.
    folder = tempfile.mkdtemp()
    try:
        a = RM.Remote(types.SimpleNamespace(session=None), None,
                      folder=folder, wall=lambda: 1_800_000_000.0)
        a.reserve_disarm_ids()
        for _ in range(3):
            a._disarm_ids += 1
        b = RM.Remote(types.SimpleNamespace(session=None), None,
                      folder=folder, wall=lambda: 1_800_000_000.0 - 90)
        b.reserve_disarm_ids()
        web_src = open(os.path.join(os.path.dirname(os.path.abspath(
            __file__)), "ltcplay", "web.py"), encoding="utf-8").read()
        check("    if accounts:\n" in web_src and
              "        httpd.remote.reserve_disarm_ids()" in web_src,
              "the show engine reserves its disarm id range at start")
        check(b._disarm_ids > a._disarm_ids,
              f"a clock stepped back: still above ({a._disarm_ids} then "
              f"{b._disarm_ids})")
    finally:
        import shutil as _shu
        _shu.rmtree(folder, ignore_errors=True)
    print("  ok")


def test_disarm_all_end_to_end_rearms_without_a_cycle():
    section("Disarm all flame groups end to end: the real flamesafe, deck "
            "controller and engine; armed groups go off with screen "
            "arming switched off, flamesafe takes no disarm_all, and a "
            "plain hold arms again; after an Abort the same hold cannot")
    import json as _j
    import socket as _so
    import subprocess
    import tempfile
    import threading
    import types
    import urllib.request
    from ltcplay import flamelink as fl
    from ltcplay import streamdeck as sd
    from ltcplay import remote as RM
    from ltcplay import web as web_mod
    S = _sched()
    if S is None:
        return
    here = os.path.dirname(os.path.abspath(__file__))
    key = _fl_key()
    names = ["front row", "cat-walk"]

    def free_port():
        s = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
        s.bind(("127.0.0.1", 0))
        p = s.getsockname()[1]
        s.close()
        return p
    node = _so.socket(_so.AF_INET, _so.SOCK_DGRAM)
    node.bind(("127.0.0.1", 0))
    # Four ports that are really four: a port closed by free_port() can
    # come straight back from the next call, and flamesafe refuses a link
    # port that is another link port (it would be talking to itself).
    ports = []
    while len(ports) < 4:
        p_ = free_port()
        if p_ not in ports and p_ != node.getsockname()[1]:
            ports.append(p_)
    listen, armp, statusp, mirror = ports
    work = tempfile.mkdtemp()
    cfg_path = os.path.join(work, "flamesafe.json")
    _j.dump({
        "flamesafe_config": 1, "confirmed": False, "note": "selftest",
        "universe": 1,
        "destination": {"ip": "127.0.0.1", "port": node.getsockname()[1]},
        "link": {"listen_ip": "127.0.0.1", "listen_port": listen,
                 "status_ip": "127.0.0.1", "status_port": statusp,
                 "status_mirror_port": mirror, "arm_port": armp,
                 "key": key},
        "gflame_range": "30-50%", "arm_value": 78,
        "accept_unsourced_risk": False, "min_arm_dwell_ms": 1000,
        "arm_stale_ms": 500, "frame_stale_ms": 500, "fire_hold_ms": 100,
        "tick_hz": 40, "overrun_ms": 250, "log_dir": None,
        "groups": [{"name": n, "safety": 401 + i, "fire": [411 + 10 * i]}
                   for i, n in enumerate(names)]}, open(cfg_path, "w"))
    proc = subprocess.Popen([sys.executable, "-u", "-m", "flamesafe",
                             cfg_path], cwd=here, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)
    stop = threading.Event()
    fs_out = []
    threading.Thread(target=lambda: [fs_out.append(_l.rstrip())
                                     for _l in proc.stdout],
                     daemon=True).start()
    cfg = fl.FlameLinkConfig.from_flamesafe_config(cfg_path)
    t0 = time.perf_counter()

    def show_tc():
        n = int((time.perf_counter() - t0) * 30)
        return f"00:{n // 1800 % 60:02d}:{n // 30 % 60:02d}:{n % 30:02d}"
    link = fl.FlameLink(cfg, show_state=lambda: (show_tc(), True)).start()
    folder = tempfile.mkdtemp()
    httpd = web_mod.serve(folder, port=0, bind="127.0.0.1",
                          remote_folder=work, flamesafe_config=cfg_path)
    rem = httpd.remote
    # The Abort's disarm is the flame link's disarm_all (no scheduler here).
    rem._flame_disarm = lambda reason: types.SimpleNamespace(
        ok=link.disarm_all(reason), sentence="sent")
    RM.save_settings(work, screen_arming=True)
    threading.Thread(target=httpd.serve_forever,
                     kwargs={"poll_interval": 0.05}, daemon=True).start()
    base = f"http://127.0.0.1:{httpd.server_address[1]}"
    _noproxy = urllib.request.build_opener(urllib.request.ProxyHandler({}))

    def http(path, body=None):
        req = urllib.request.Request(
            base + path, data=None if body is None else
            _j.dumps(body).encode(), method="GET" if body is None else "POST",
            headers={"Content-Type": "application/json"})
        try:
            with _noproxy.open(req, timeout=5) as r:
                return r.status, _j.loads(r.read())
        except urllib.error.HTTPError as e:
            return e.code, _j.loads(e.read() or b"{}")
    arm = sd.ArmSocket("127.0.0.1", armp, key, 2)
    arm.open()
    status = sd.StatusSocket("127.0.0.1", statusp, key)
    status.open()
    screen = sd.ScreenKeys(base).start()
    events = []
    ctl = sd.Controller(arm, status, names, operator_provider=lambda: "Andy",
                        show_running_provider=lambda: None,
                        journal=lambda t_, **kw: events.append(t_),
                        screen=screen)
    lock = threading.Lock()

    def deck_loop():
        while not stop.is_set():
            with lock:
                ctl.screen_pass()
                ctl.tick()
                status.poll()
                arm.send(names)
            time.sleep(0.05)
    threading.Thread(target=deck_loop, daemon=True).start()

    def group(i):
        st = status.last
        return st["groups"][i] if st else {}

    def armed(i):
        return group(i).get("armed") == "armed"

    def hold(gname, seconds=1.6):
        """Like the page: a heartbeat every 100 ms with a fresh served_at,
        up to three tries for a slow runner's lapsed hold. True once the
        group reads armed."""
        i = names.index(gname)
        for _try in range(3):
            hid, end = None, time.perf_counter() + seconds
            while time.perf_counter() < end and not armed(i):
                seen = http("/api/remote/status")[1]["served_at"]
                body = {"group": gname, "seen": seen}
                if hid is not None:
                    body["hold_id"] = hid
                code, out = http("/api/remote/arm-hold", body)
                if code != 200:
                    break
                hid = out["hold_id"]
                time.sleep(0.1)
            end = time.perf_counter() + 2
            while time.perf_counter() < end and not armed(i):
                time.sleep(0.02)
            if armed(i):
                return True
            time.sleep(sd.REARM_REFRACTORY_S + 0.2)
        return False

    def wait(pred, s=3.0):
        end = time.perf_counter() + s
        while time.perf_counter() < end:
            if pred():
                return True
            time.sleep(0.02)
        return pred()
    try:
        # Wait on what the holds need, not a fixed time: flamesafe's own
        # status reaching both the engine and the deck (a loaded runner
        # can take a while to start a Python process).
        end = time.perf_counter() + 30
        up = False
        while time.perf_counter() < end and proc.poll() is None:
            s = http("/api/remote/status")[1]
            if s["flames"].get("connected") and not s["flames"]["stale"] \
                    and status.last:
                up = True
                break
            time.sleep(0.1)
        check(up, f"setup: flamesafe's status reached the engine and the "
                  f"deck (flamesafe "
                  f"{'exited ' + str(proc.returncode) if proc.poll() is not None else 'running'}"
                  f"; its last lines: {fs_out[-6:]})")
        # The deck's lows prove a cycle: its arm input live in flamesafe.
        wait(lambda: (status.last or {}).get("arm_input", {}).get("state")
             == "live", 10)
        time.sleep(1.2)
        check(hold("front row") and hold("cat-walk"),
              f"setup: both groups armed from the screen: {status.last}; "
              f"{events[-4:]}")
        accepted0 = (status.last.get("disarm_all") or {}).get("accepted", 0)
        # Screen arming off, and Disarm all flame groups.
        RM.save_settings(work, screen_arming=False)
        code, out = http("/api/remote/disarm-all", {})
        check(code == 200 and out.get("plain") is True,
              f"a plain Disarm all with screen arming off: {code} {out}")
        check(wait(lambda: not armed(0) and not armed(1)),
              f"both groups off on flamesafe's own wire: {status.last}")
        wait(lambda: not any(g.get("wanted")
                             for g in status.last["groups"]), 1.0)
        check(all(g["armed"] == "disarmed" and not g["wanted"] and
                  "Abort" not in g.get("reason", "")
                  for g in status.last["groups"]) and
              (status.last.get("disarm_all") or {}).get("accepted", 0) ==
              accepted0,
              f"flamesafe took no disarm_all, and no group reads the "
              f"Abort's cycle: {status.last['groups']} "
              f"{status.last.get('disarm_all')}")
        time.sleep(RM.PLAIN_CONFIRM_S + 0.3)
        rows = [r for r in rem.schedule.journal
                if r.get("action") == "disarm all"] \
            if getattr(rem.schedule, "journal", None) else []
        check(not [a for a in rem.alerts.view() if a["kind"] == "flames"],
              f"confirmed off: no alert {rem.alerts.view()} {rows[-2:]}")
        # Re-armed by a plain hold: no fresh cycle, no Reset.
        time.sleep(max(0.0, sd.REARM_REFRACTORY_S - RM.PLAIN_CONFIRM_S))
        RM.save_settings(work, screen_arming=True)
        check(hold("front row"),
              f"after a plain disarm one hold arms again: {group(0)} "
              f"{events[-4:]}")
        # The contrast: the Abort's disarm (the flame link's disarm_all)
        # leaves the deck still asking, and flamesafe holds the group
        # until it is cycled; the same hold does not arm it.
        http("/api/remote/abort", {"confirmed": True})
        check(wait(lambda: not armed(0)),
              f"Abort disarms it: {group(0)}")
        check(wait(lambda: "Abort" in group(0).get("reason", "")),
              f"and flamesafe reads the Abort's cycle: {group(0)}")
        time.sleep(sd.REARM_REFRACTORY_S + 0.2)
        seen = http("/api/remote/status")[1]["served_at"]
        code, out = http("/api/remote/arm-hold",
                         {"group": "front row", "seen": seen})
        time.sleep(1.5)
        check(not armed(0),
              f"after an Abort a hold alone does not arm: {group(0)} "
              f"{code} {out}")
        # Disarm all during a standing Abort (review of PR #97): its plain
        # disarm is the low half of a cycle, but the Abort latch still
        # refuses every hold until Reset.
        rem.schedule = types.SimpleNamespace(
            machine=types.SimpleNamespace(abort_latched=True,
                                          state="ABORTED"),
            conductor=None)
        code, out = http("/api/remote/disarm-all", {})
        check(code == 200, f"Disarm all during the Abort: {code} {out}")
        wait(lambda: not group(0).get("wanted"), 2.0)
        time.sleep(sd.REARM_REFRACTORY_S + 0.2)
        RM.save_settings(work, screen_arming=True)
        seen = http("/api/remote/status")[1]["served_at"]
        code, out = http("/api/remote/arm-hold",
                         {"group": "front row", "seen": seen})
        check(code != 200 and "Abort" in str(out.get("error", "")),
              f"a hold with the Abort standing is refused, Disarm all or "
              f"not: {code} {out}")
        time.sleep(1.5)
        check(not armed(0), f"and nothing armed: {group(0)}")
    finally:
        stop.set()
        screen.stop()
        try:
            httpd.shutdown()
        except Exception:
            pass
        try:
            httpd.server_close()
        except Exception:
            pass
        rs = getattr(httpd.remote, "flame_status", None)
        if rs is not None:
            rs.stop()
        link.stop()
        arm.close()
        status.close()
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            proc.kill()
        node.close()
        import shutil
        shutil.rmtree(work, ignore_errors=True)
        shutil.rmtree(folder, ignore_errors=True)
    print("  ok")


def test_lasers_lamp_follows_the_beyond_link():
    section("BEYOND exited at 03:27 and the Lasers lamp said lit for hours "
            "(2026-10-23): the watch says up, lost or unknown, a look older "
            "than STALE_S says nothing, the lamp reads LINK LOST with BEYOND "
            "gone and 'lit, unconfirmed' with it running, and a BEYOND that "
            "was running and exits is an alert, once")
    import tempfile
    import types
    from ltcplay import beyondwatch as BW, remote as RM
    t = [100.0]
    res = [True]
    said = []
    w = BW.BeyondWatch(lambda: res[0], clock=lambda: t[0],
                       on_change=lambda l, why: said.append(l))
    check(w.state()["link"] == "unknown", "never looked: unknown")
    w.check_once()
    check(w.state()["link"] == "up" and said == ["up"], "running: up")
    t[0] += BW.STALE_S + 0.1
    check(w.state()["link"] == "unknown",
          "a look older than STALE_S says nothing: unknown")
    res[0] = False
    w.check_once()
    check(w.state()["link"] == "lost" and said == ["up", "lost"],
          f"not running: lost, said once: {said}")
    w.check_once()
    check(said == ["up", "lost"], "the same word is not said again")
    res[0] = None
    w.check_once()
    check(w.state()["link"] == "unknown", "cannot tell: unknown")

    def boom():
        raise OSError("x")
    w2 = BW.BeyondWatch(boom, clock=lambda: t[0])
    check(w2.check_once() is None and w2.state()["link"] == "unknown",
          "a probe that raises is unknown, never up")
    # The Windows process list.
    run = lambda out: (lambda *a, **k: types.SimpleNamespace(stdout=out))
    check(BW.windows_probe(run('"System","4","Services","0","1 K"\n'
                               '"BEYOND.exe","812","Console","1","9 K"\n'))
          is True and
          BW.windows_probe(run('"System","4","Services","0","1 K"\n')) is
          False and BW.windows_probe(run("")) is None,
          "BEYOND.exe in the list: True; a list without it: False; "
          "nothing read: None")

    def raises(*a, **k):
        raise OSError("no tasklist")
    check(BW.windows_probe(raises) is None, "tasklist missing: None")
    check(BW.on_this_pc("127.0.0.2") and BW.on_this_pc("localhost") and
          not BW.on_this_pc("10.0.0.9") and not BW.on_this_pc(None),
          "only the loopback is this PC")
    check(BW.probe_for("127.0.0.2", windows=True) is BW.windows_probe and
          BW.probe_for("10.0.0.9", windows=True)() is None and
          BW.probe_for("127.0.0.2", windows=False)() is None,
          "the process is looked for only on Windows, BEYOND on loopback")
    # The lamp, through a Remote with a conductor that last sent lit.
    cond = types.SimpleNamespace(
        snapshot=lambda: {"applied": {"lasers": "lit", "video": "playing"}},
        devices=types.SimpleNamespace(beyond=types.SimpleNamespace(
            fault="")), _ver={"lasers": 3, "video": 1})
    sched = types.SimpleNamespace(conductor=cond, state_dir=None)
    r = RM.Remote(types.SimpleNamespace(session=None), sched,
                  folder=tempfile.gettempdir(), clock=lambda: t[0])

    def lamp():
        got = [x for x in r.subsystems({}) if x["name"] == "Lasers"]
        return (got[0]["state"], got[0]["word"]) if got else None
    check(lamp() == ("warn", "lit? link unknown"),
          f"no watch: lit is a warning, never plain ok: {lamp()}")
    res[0] = True
    r.beyond_watch = BW.BeyondWatch(lambda: res[0], clock=lambda: t[0],
                                    on_change=r.beyond_link_changed)
    r.beyond_watch.check_once()
    check(lamp() == ("ok", "lit, unconfirmed"),
          f"BEYOND running: sent lit, unconfirmed: {lamp()}")
    chip = [x for x in r.subsystems({}) if x["name"] == "Lasers"][0]
    check("only sees that BEYOND's program is running" in
          chip.get("title", ""),
          f"the lamp's tooltip says it is a process check only: {chip}")
    res[0] = False                       # BEYOND exits (stubbed dead)
    r.beyond_watch.check_once()
    check(lamp() == ("bad", "LINK LOST"),
          f"BEYOND gone: LINK LOST, whatever was sent: {lamp()}")
    al = [a for a in r.alerts.view() if a["kind"] == "lasers"]
    check(len(al) == 1 and al[0]["severity"] == "fault" and
          "BEYOND was running and is not any more" in al[0]["text"],
          f"and an alert says so: {al}")
    _no_dashes(al[0]["text"] if al else "", "the BEYOND alert")
    t[0] += 3600                         # hours later, still dead
    r.beyond_watch.check_once()
    check(lamp() == ("bad", "LINK LOST") and
          len([a for a in r.alerts.view() if a["kind"] == "lasers"]) == 1,
          f"hours later it still says LINK LOST, one alert: {lamp()}")
    # A laser command recorded while BEYOND is gone reaches nobody: it
    # never counts as the new process's unblank (second review, P2-b).
    cond._ver["lasers"] += 1
    # BEYOND starts again: the new process has had no unblank, so the
    # lamp waits for the conductor to send lit again (review of PR #97,
    # P2-2).
    res[0] = True
    r.beyond_watch.check_once()
    check(lamp() == ("warn", "BEYOND restarted: dark until lit again"),
          f"BEYOND back, nothing sent since: never lit: {lamp()}")
    cond._ver["lasers"] += 1             # the conductor sends lit again
    check(lamp() == ("ok", "lit, unconfirmed"),
          f"lit sent again after the restart: {lamp()}")
    # up, then unknown, then lost: still a loss with an alert (P3).
    r.alerts.clear(kind="lasers", action="Acknowledge")
    res[0] = None
    r.beyond_watch.check_once()
    res[0] = False
    r.beyond_watch.check_once()
    check(len([a for a in r.alerts.view() if a["kind"] == "lasers"]) == 1,
          f"up, unknown, then lost: an alert: {r.alerts.view()}")
    t[0] += BW.STALE_S + 1               # the watch stopped looking
    cond._ver["lasers"] += 1
    check(lamp() == ("warn", "lit? link unknown"),
          f"a watch that stopped looking: unknown, never lit: {lamp()}")
    # Dead from the start: the lamp, and no alert.
    r2 = RM.Remote(types.SimpleNamespace(session=None), sched,
                   folder=tempfile.gettempdir(), clock=lambda: t[0])
    r2.beyond_watch = BW.BeyondWatch(lambda: False, clock=lambda: t[0],
                                     on_change=r2.beyond_link_changed)
    r2.beyond_watch.check_once()
    check([x["word"] for x in r2.subsystems({}) if x["name"] == "Lasers"]
          == ["LINK LOST"] and
          not [a for a in r2.alerts.view() if a["kind"] == "lasers"],
          "BEYOND not started yet: LINK LOST on the lamp, no alert")
    st = r2.status(RM.Ctx(True, "127.0.0.1"))
    check((st.get("beyond_link") or {}).get("link") == "lost",
          f"the page is told: {st.get('beyond_link')}")
    print("  ok")


def test_video_lamp_follows_the_madmapper_watch():
    section("The Video lamp read 'not known' until a show sent something "
            "(Jeff, 2026-10-26): the MadMapper watch says up, lost or "
            "unknown before any show plays, from Windows' process list on "
            "its own thread; MadMapper on another machine is said, never "
            "guessed; the heartbeat speaks only when the show file has one "
            "and a show is playing; a MadMapper that was running and exits "
            "is an alert, once; the lamp is a link check, never a picture "
            "check")
    import shutil
    import subprocess
    import tempfile
    import types
    from ltcplay import madmapperwatch as MW, madmapper as MM, remote as RM
    HERE = os.path.dirname(os.path.abspath(__file__))
    t = [100.0]
    res = [True]
    said = []
    w = MW.MadMapperWatch(lambda: res[0], clock=lambda: t[0],
                          on_change=lambda l, why: said.append(l))
    check(w.state()["link"] == "unknown" and
          "MadMapper has not been looked for yet" in w.state()["why"],
          f"never looked: unknown: {w.state()}")
    w.check_once()
    check(w.state()["link"] == "up" and said == ["up"] and
          w.state()["why"] == "MadMapper is running on this PC",
          f"running: up: {w.state()}")
    t[0] += MW.STALE_S + 0.1
    check(w.state()["link"] == "unknown",
          "a look older than STALE_S says nothing: unknown")
    res[0] = False
    w.check_once()
    check(w.state()["link"] == "lost" and said == ["up", "lost"],
          f"not running: lost, said once: {said}")
    res[0] = None
    w.check_once()
    check(w.state()["link"] == "unknown", "cannot tell: unknown")

    def boom():
        raise OSError("x")
    check(MW.MadMapperWatch(boom, clock=lambda: t[0]).check_once() is None,
          "a probe that raises is unknown, never up")
    # The Windows process list: MadMapper*.exe, the demo too (soak_apps).
    run = lambda out: (lambda *a, **k: types.SimpleNamespace(stdout=out))
    check(MW.windows_probe(run('"System","4","Services","0","1 K"\n'
                               '"MadMapperDemo.exe","90","Console","1",'
                               '"9 K"\n')) is True and
          MW.windows_probe(run('"MadMapper.exe","90","Console","1","9 K"\n'))
          is True and
          MW.windows_probe(run('"BEYOND.exe","812","Console","1","9 K"\n'))
          is False and MW.windows_probe(run("")) is None,
          "MadMapper(Demo).exe in the list: True; BEYOND only: False; "
          "nothing read: None")

    def raises(*a, **k):
        raise OSError("no tasklist")
    check(MW.windows_probe(raises) is None, "tasklist missing: None")
    sys.path.insert(0, os.path.join(HERE, "packaging", "windows"))
    try:
        import soak_apps
        check(tuple(p.lower() for p in soak_apps.APPS["MadMapper"]["exe"])
              == MW.IMAGES, "the image name is the soak's own")
    finally:
        sys.path.pop(0)
    check(MW.probe_for("127.0.0.1", windows=True) is MW.windows_probe and
          MW.probe_for("10.0.0.9", windows=True) is not MW.windows_probe
          and MW.probe_for("10.0.0.9", windows=True)() is None and
          MW.probe_for("127.0.0.1", windows=False)() is None,
          "the process is looked for only on Windows, MadMapper on loopback")
    far = MW.watch("10.0.0.9", windows=True, clock=lambda: t[0])
    far.check_once()
    check(far.state()["link"] == "unknown" and
          far.state()["why"].startswith("unknown, MadMapper is on another "
                                        "machine"),
          f"MadMapper on another machine: said, not guessed: {far.state()}")
    mac = MW.watch("127.0.0.1", windows=False, clock=lambda: t[0])
    mac.check_once()
    check(mac.state()["link"] == "unknown" and
          "not the Windows show PC" in mac.state()["why"],
          f"not Windows: said: {mac.state()}")
    _no_dashes(far.state()["why"] + mac.state()["why"], "the watch's words")
    # The heartbeat: the real watchdog hears a packet, armed or not, and
    # nothing about arming, counting or alarming changes.
    hb_t = [50.0]
    dog = MM.Watchdog(MM.HeartbeatConfig(show_len_s=444.0),
                      clock=lambda: hb_t[0])
    check(dog.heard_age_s() is None, "nothing heard yet: None")
    dog.on_packet(0.5)
    hb_t[0] += 1.0
    check(dog.heard_age_s() == 1.0 and dog.packets_in == 0 and
          not dog.armed and dog.health()["state"] == "quiet",
          f"heard while disarmed: an age, never counted or armed: "
          f"{dog.heard_age_s()} {dog.health()}")
    cfg = MM.HeartbeatConfig(show_len_s=444.0)
    hv = MW.heartbeat_view
    check(hv(dog, cfg, True)["heartbeat"] == "ok", "fresh: ok")
    hb_t[0] += 10
    check(hv(dog, cfg, True)["heartbeat"] == "silent" and
          hv(dog, cfg, False)["heartbeat"] == "quiet",
          "silent while a show plays: silent; between shows: quiet")
    check(hv(dog, MM.HeartbeatConfig(), True) is None and
          hv(None, cfg, True) is None,
          "no heartbeat block, or no watchdog: never mentioned")
    dog.bind_error = "The MadMapper heartbeat could not listen"
    check(hv(dog, cfg, False)["heartbeat"] == "silent",
          "a listener that could not open its port: silent")
    dog.bind_error = None
    # The lamp, through a Remote with a conductor.
    snap = {"applied": {"video": "unknown", "lasers": "unknown"},
            "look": "BETWEEN"}
    cond = types.SimpleNamespace(
        snapshot=lambda: snap,
        devices=types.SimpleNamespace(beyond=types.SimpleNamespace(
            fault="")), _ver={"lasers": 0, "video": 0})
    sched = types.SimpleNamespace(conductor=cond, state_dir=None)
    r = RM.Remote(types.SimpleNamespace(session=None), sched,
                  folder=tempfile.gettempdir(), clock=lambda: t[0])

    def chip(cs=None):
        got = [x for x in r.subsystems(cs or {}) if x["name"] == "Video"]
        return got[0] if got else {}

    def lamp(cs=None):
        c = chip(cs)
        return (c.get("state"), c.get("word"))
    check(lamp() == ("off", "not sent yet") and
          "not known" not in str(chip()).lower(),
          f"no watch, nothing sent: grey 'not sent yet', never 'not "
          f"known': {chip()}")
    res[0] = True
    r.madmapper_watch = MW.MadMapperWatch(
        lambda: res[0], clock=lambda: t[0],
        on_change=r.madmapper_link_changed)
    r.madmapper_watch.check_once()
    check(lamp() == ("ok", "MadMapper running"),
          f"before any show: MadMapper running, green: {lamp()}")
    title = chip().get("title", "")
    check("MadMapper is running; whether the screens show the picture is "
          "not something it can tell" in title and
          "Nothing has been sent to MadMapper yet" in title,
          f"the tooltip says it is a link check only: {title}")
    _no_dashes(title, "the Video lamp's tooltip")
    snap["applied"]["video"] = "lit"
    cond._ver["video"] = 2
    check(lamp() == ("ok", "MadMapper running, lit") and
          "Last sent to MadMapper: lit." in chip()["title"],
          f"after a command: the last sent detail stays: {chip()}")
    snap["applied"]["video"] = "unknown"
    check(lamp() == ("warn", "MadMapper running, last command not "
                             "confirmed"),
          f"a command sent and not confirmed: amber: {lamp()}")
    snap["applied"]["video"] = "black"
    # The heartbeat on the lamp.
    r.madmapper_heartbeat, r.madmapper_heartbeat_cfg = dog, cfg
    playing = {"running": True}
    check(lamp(playing) == ("ok", "MadMapper running, black"),
          f"silent between shows (look BETWEEN): no word on it: "
          f"{lamp(playing)}")
    snap["look"] = "PLAYING"
    check(lamp(playing) == ("warn", "MadMapper running, no heartbeat") and
          "heartbeat has not arrived" in chip(playing)["title"],
          f"a show playing and no heartbeat: amber: {chip(playing)}")
    dog.on_packet(0.1)
    check(lamp(playing) == ("ok", "MadMapper running, heartbeat OK, black"),
          f"heartbeat fresh: said: {lamp(playing)}")
    hb_t[0] += 10
    r.madmapper_heartbeat_cfg = MM.HeartbeatConfig()
    check(lamp(playing) == ("ok", "MadMapper running, black"),
          f"no heartbeat block: never an alarm: {lamp(playing)}")
    snap["look"] = "BETWEEN"
    # MadMapper exits: red, and one alert.
    res[0] = False
    r.madmapper_watch.check_once()
    check(lamp() == ("bad", "MadMapper NOT RUNNING"),
          f"MadMapper gone: NOT RUNNING, whatever was sent: {lamp()}")
    al = [a for a in r.alerts.view() if a["kind"] == "video"]
    check(len(al) == 1 and al[0]["severity"] == "fault" and
          "MadMapper was running and is not any more" in al[0]["text"],
          f"and an alert says so: {al}")
    _no_dashes(al[0]["text"] if al else "", "the MadMapper alert")
    t[0] += 3600
    r.madmapper_watch.check_once()
    check(lamp() == ("bad", "MadMapper NOT RUNNING") and
          len([a for a in r.alerts.view() if a["kind"] == "video"]) == 1,
          "hours later: still NOT RUNNING, one alert")
    r.alerts.clear(kind="video", action="Acknowledge")
    res[0] = True
    r.madmapper_watch.check_once()
    check(not [a for a in r.alerts.view() if a["kind"] == "video"],
          "back: no alert")
    res[0] = False
    r.madmapper_watch.check_once()
    check(len([a for a in r.alerts.view() if a["kind"] == "video"]) == 1,
          "back, then gone again: a second loss is an alert again")
    t[0] += MW.STALE_S + 1
    check(lamp() == ("ok", "black") and
          "was last looked for" in chip()["title"],
          f"a watch that stopped looking: today's detail, never NOT "
          f"RUNNING or running: {chip()}")
    snap["applied"]["video"] = "unknown"
    check(lamp() == ("warn", "last command not confirmed"),
          f"unknown link, command unconfirmed: amber: {lamp()}")
    # MadMapper on another machine: grey, and the tooltip says why.
    r.madmapper_watch = MW.watch("10.0.0.9", windows=True,
                                 clock=lambda: t[0])
    r.madmapper_watch.check_once()
    cond._ver["video"] = 0
    check(lamp() == ("off", "not sent yet") and
          "MadMapper is on another machine" in chip()["title"],
          f"another machine: grey, and why: {chip()}")
    # Not running from the start: the lamp, no alert; the page is told.
    r2 = RM.Remote(types.SimpleNamespace(session=None), sched,
                   folder=tempfile.gettempdir(), clock=lambda: t[0])
    r2.madmapper_watch = MW.MadMapperWatch(
        lambda: False, clock=lambda: t[0],
        on_change=r2.madmapper_link_changed)
    r2.madmapper_watch.check_once()
    check([x["word"] for x in r2.subsystems({}) if x["name"] == "Video"]
          == ["MadMapper NOT RUNNING"] and
          not [a for a in r2.alerts.view() if a["kind"] == "video"],
          "MadMapper not started yet: NOT RUNNING on the lamp, no alert")
    st = r2.status(RM.Ctx(True, "127.0.0.1"))
    check((st.get("madmapper_link") or {}).get("link") == "lost" and
          [x["word"] for x in st["subsystems"] if x["name"] == "Video"] ==
          ["MadMapper NOT RUNNING"],
          f"the status JSON carries it: {st.get('madmapper_link')}")
    check(RM.Remote(types.SimpleNamespace(session=None), sched,
                    folder=tempfile.gettempdir()).status(
        RM.Ctx(True, "127.0.0.1")).get("madmapper_link", 1) is None,
          "no MadMapper watch: madmapper_link is null")
    # web.serve starts it only with MadMapper configured, from its host.
    with open(os.path.join(HERE, "ltcplay", "web.py"),
              encoding="utf-8") as fh:
        web_src = fh.read()
    check("mmwatch_mod.watch(" in web_src and
          "on_change=httpd.remote.madmapper_link_changed" in web_src and
          "httpd.remote.madmapper_heartbeat = httpd.madmapper[1]" in web_src,
          "web.serve starts the MadMapper watch and hands it the heartbeat")
    # The page draws the chip and its tooltip exactly as the engine says.
    with open(os.path.join(HERE, "ltcplay", "web", "remote.html"),
              encoding="utf-8") as fh:
        page = fh.read()
    draw = _js_block(page, '$("subs").innerHTML = ', '\n\n')
    check(draw.startswith('$("subs").innerHTML'),
          "the page has its status strip drawing")
    # The strip draws through the one laser pill (2026-10-26): its pure
    # function comes along.
    draw = _js_block(page, "const CHIP_RANK = {", "// LOGIC END") + "\n" + draw
    node = shutil.which("node")
    if not node:
        check(not IN_CI, "node is missing on this CI runner, so the status "
                         "strip cannot be run; install node in the workflow")
        print("  note: node is not on this machine, so the strip was "
              "checked by reading only (CI runs it)")
        print("  ok")
        return
    js = ("const byId = {subs: {innerHTML: ''}};\n"
          "const $ = id => byId[id];\n"
          "const esc = (t) => String(t == null ? '' : t)"
          ".replace(/&/g,'&amp;').replace(/</g,'&lt;')"
          ".replace(/>/g,'&gt;').replace(/\"/g,'&quot;');\n"
          "const s = " + json.dumps({"subsystems": st["subsystems"]}) +
          ";\n" + draw + "\nconsole.log(byId.subs.innerHTML);\n")
    with tempfile.TemporaryDirectory() as d:
        f = os.path.join(d, "strip.js")
        with open(f, "w", encoding="utf-8") as fh:
            fh.write(js)
        p = subprocess.run([node, f], capture_output=True, text=True,
                           timeout=30)
    html = p.stdout
    check(p.returncode == 0 and
          "Video <span>MadMapper NOT RUNNING</span>" in html and
          'class="chip bad"' in html and
          "whether the screens show the picture is not something it can "
          "tell" in html,
          f"the rack screen shows 'Video MadMapper NOT RUNNING' in red, "
          f"with the tooltip: {p.stderr or html[:400]}")
    print("  ok")


def test_artnet_faults_only_for_the_show_in_use():
    section("Art-Net receivers (Jeff, 2026-10-23): an old unused show file "
            "in the folder (soak_show.json) is a quiet note once a show is "
            "in use (loaded, last Run, or last Run before a restart); with "
            "no show in use (2026-10-24) what is found is one collapsed "
            "note on the rack screen and amber on the Morning card, never "
            "a red FAULT or an alert, except for the only show file there "
            "is; Run keeps the show for a restart; a newly loaded show is "
            "judged at once")
    import json
    import types
    from ltcplay import artnodes as A
    from ltcplay import remote as RM
    S = _sched()
    if S is None:
        return
    R = _RemoteRig(S)
    try:
        rm = R.remote
        rm._artnet_adapters = lambda: set()
        rm._artnet_windows = True
        rm._artnet_probe = lambda a: False

        def show(name, nodes):
            with open(os.path.join(R.folder, name), "w") as fh:
                json.dump({"fps": 30, "cues": [],
                           "clock": {"source": "artnet_master",
                                     "artnet": {"nodes": nodes}}}, fh)
        bad = {"MadMapper": "127.0.0.1", "BEYOND": "10.99.0.1"}
        good = {"MadMapper": "127.0.0.1"}
        ff, seen = A.folder_faults(R.folder, set(), lambda a: False, True,
                                   active={"x.json"})
        show("soak_show.json", bad)
        show("show.json", good)
        ff, seen = A.folder_faults(R.folder, set(), lambda a: False, True,
                                   active={"show.json"})
        check(seen == 2 and ff and all(lv == "note" for lv, _t in ff) and
              "soak_show.json (not the show in use)" in ff[0][1],
              f"an unused file gives notes only: {ff}")
        check([lv for lv, _t in A.folder_faults(
            R.folder, set(), lambda a: False, True)[0]] == ["bad"],
              "with no active list every file counts, as before")

        def card():
            return {c["id"]: c for c in rm.engine_checks()}.get("artnet", {})

        NOTE = [""]

        def alerts():
            st, _h, out = R.ask("GET", "/api/remote/status")
            NOTE[0] = out.get("artnet_note")
            return [a for a in rm.alerts.view() if a["kind"] == "timecode"]
        # No show Run here yet (2026-10-24): nothing is a FAULT or an
        # alert; the rack screen has one note naming what was found, the
        # Morning card says it in amber.
        R.mono[0] += 60
        rm._checks = None
        ck, al = card(), alerts()
        check(ck.get("level") == "warn" and not al and
              ck.get("text", "").startswith(rm.AMBIGUOUS) and
              "soak_show.json: " in ck.get("text", "") and
              "10.99.0.1" in ck.get("text", ""),
              f"nothing Run yet: no fault, no alert, the card amber and "
              f"naming the file: {ck} {al}")
        check(NOTE[0].startswith("Art-Net receivers, a note: No show is "
                                 "loaded, Run or picked yet") and
              "soak_show.json: " in NOTE[0] and "10.99.0.1" in NOTE[0],
              f"the rack screen is given one note: {NOTE[0]!r}")
        check(rm.AMBIGUOUS.startswith("No show is loaded, Run or picked "
                                      "yet, so no show file is judged as "
                                      "a fault"),
              f"the note says why: {rm.AMBIGUOUS!r}")
        # The only show file in the folder is the show that will run: its
        # fault stands, with nothing picked.
        os.rename(os.path.join(R.folder, "show.json"),
                  os.path.join(R.work, "show.json.aside"))
        R.mono[0] += 60
        rm._checks = None
        ck, al = card(), alerts()
        check(ck.get("level") == "bad" and len(al) == 1 and
              "soak_show.json: " in al[0]["text"] and not NOTE[0] and
              not al[0]["text"].startswith("No show"),
              f"the only show file: a fault and an alert, no note: {ck} "
              f"{al} {NOTE[0]!r}")
        rm.alerts.clear(kind="timecode", action="Acknowledge")
        os.rename(os.path.join(R.work, "show.json.aside"),
                  os.path.join(R.folder, "show.json"))
        R.mono[0] += 60
        rm._checks = None
        # show.json loaded (Run): judged at once, the soak file a note.
        R.httpd.control.session = types.SimpleNamespace(
            timeline_path=os.path.join(R.folder, "show.json"), running=True)
        rm._checks = None
        ck, al = card(), alerts()
        check(ck.get("level") == "ok" and "soak_show.json" in
              ck.get("text", "") and not al and not NOTE[0],
              f"show.json in use: the old soak file is a note, and no "
              f"rack screen note: {ck} {al} {NOTE[0]!r}")
        # Stopped: the last Run show stays the one in use.
        R.httpd.control.session = None
        R.httpd.control.last_timeline = "show.json"
        R.mono[0] += 60
        rm._checks = None
        check(card().get("level") == "ok" and not alerts(),
              "after Stop the show last Run is still the one judged")
        # The engine restarts: the show last Run is remembered (once its
        # write, off the request, has landed).
        check(rm.selection_written(5.0), "the last Run's write finished")
        R.httpd.control.last_timeline = None
        rm2 = RM.Remote(R.httpd.control, R.svc, folder=R.work,
                        clock=lambda: R.mono[0], wall=lambda: R.wall[0],
                        log=lambda t: None)
        rm2._artnet_adapters = lambda: set()
        rm2._artnet_windows = True
        rm2._artnet_probe = lambda a: False
        check(rm2._active_show_files() == {"show.json"},
              f"remembered across a restart: {rm2._active_show_files()}")
        # A bad show.json next to a good soak file, show.json the one
        # last Run: a fault, never a note (the reviewer's probe).
        show("show.json", bad)
        show("soak_show.json", good)
        rm2.artnet_alert()
        tc = [a for a in rm2.alerts.view() if a["kind"] == "timecode"]
        check(len(tc) == 1 and "show.json: " in tc[0]["text"] and
              "10.99.0.1" in tc[0]["text"],
              f"the show in use with a bad node: a fault and an alert: {tc}")
        # The soak file loaded instead: judged at once, no wait.
        show("soak_show.json", bad)
        show("show.json", good)
        R.httpd.control.session = types.SimpleNamespace(
            timeline_path=os.path.join(R.folder, "soak_show.json"),
            running=True)
        al = alerts()
        check(len(al) == 1 and "soak_show.json: " in al[0]["text"],
              f"a newly loaded show is judged on the next status, not "
              f"after the 15 s cache: {al}")
        R.httpd.control.session = None
        # Second review of #97, P2-a: soak_show.json last Run, tonight's
        # show.json bad. A show last Run is not the selection: with no
        # selection file (an engine from before it, the reviewer's probe)
        # every file is looked at, and show.json's problem is said, as the
        # note (2026-10-24), never hidden.
        rm.alerts.clear(kind="timecode", action="Acknowledge")
        show("show.json", bad)
        show("soak_show.json", good)
        check(rm.selection_written(5.0) and rm2.selection_written(5.0),
              "no selection write is still on its way")
        os.remove(os.path.join(R.work, rm.SELECTED_SHOW_FILE))
        with open(os.path.join(R.work, rm.LAST_SHOW_FILE), "w") as fh:
            json.dump({"show": "soak_show.json"}, fh)
        R.httpd.control.last_timeline = None
        rm._sel_cache = None
        R.mono[0] += 60
        rm._checks = None
        ck, al = card(), alerts()
        check(ck.get("level") == "warn" and "show.json: " in
              ck.get("text", "") and not al and "show.json: " in NOTE[0] and
              "10.99.0.1" in NOTE[0],
              f"the last Run alone does not make soak_show.json the show: "
              f"show.json's problem is the note: {ck} {al} {NOTE[0]!r}")
        # The picker on the show machine selects show.json: judged at once.
        rm.alerts.clear(kind="timecode", action="Acknowledge")
        st, _h, out = R.ask("POST", "/api/remote/show-select",
                            {"file": "show.json"}, client=("127.0.0.1", 5000))
        check(st == 200 and out.get("selected") == "show.json",
              f"the picker's choice is taken: {st} {out}")
        st, _h, out = R.ask("POST", "/api/remote/show-select",
                            {"file": "show.json"})
        check(st == 403, f"only from the show machine itself: {st}")
        st, _h, out = R.ask("POST", "/api/remote/show-select",
                            {"file": "../x.json"}, client=("127.0.0.1", 5000))
        check(st == 400, f"a file that is not in the folder is refused: {st}")
        st, _h, out = R.ask("GET", "/api/remote/status",
                            client=("127.0.0.1", 5000))
        check(out.get("selected_show") == "show.json",
              f"the page is told the selection: {out.get('selected_show')}")
        ck, al = card(), alerts()
        check(ck.get("level") == "bad" and "show.json: " in
              ck.get("text", "") and len(al) == 1 and
              not ck.get("text", "").startswith("No show is loaded") and
              not al[0]["text"].startswith("No show is loaded") and
              not NOTE[0],
              f"show.json picked: its own fault, no longer every file: "
              f"{ck} {al}")
        # The picker selects the good soak file: show.json is a note.
        R.ask("POST", "/api/remote/show-select", {"file": "soak_show.json"},
              client=("127.0.0.1", 5000))
        rm.alerts.clear(kind="timecode", action="Acknowledge")
        check(card().get("level") == "ok" and not alerts(),
              "the good show picked: no fault")
        # P3-4: the selection file is read at most every SELECTED_READ_S.
        check(rm.selection_written(5.0), "the picker's write finished")
        with open(os.path.join(R.work, rm.SELECTED_SHOW_FILE), "w") as fh:
            json.dump({"show": "show.json"}, fh)
        check(rm._active_show_files() == {"soak_show.json"},
              "within SELECTED_READ_S the cached selection is used")
        R.mono[0] += rm.SELECTED_READ_S + 0.1
        check(rm._active_show_files() == {"show.json"},
              "after it, the file is read again")
        # Run (web.py /api/start) writes the show in use at once, with no
        # status asked for before the engine restarts (2026-10-24).
        check(rm.selection_written(5.0) and rm2.selection_written(5.0),
              "no selection write is still on its way")
        os.remove(os.path.join(R.work, rm.SELECTED_SHOW_FILE))
        rm._sel_cache = None
        started = []

        def fake_start(timeline, **kw):
            started.append(timeline)
            return types.SimpleNamespace(
                timeline_path=os.path.join(R.folder, timeline), banner="",
                notes=[], problems=[])
        real_start = R.httpd.control.start
        R.httpd.control.start = fake_start
        try:
            st, _h, out = R.ask("POST", "/api/start",
                                {"timeline": "show.json"},
                                client=("127.0.0.1", 5000))
        finally:
            R.httpd.control.start = real_start
        check(st == 200 and started == ["show.json"],
              f"Run reached the (fake) start: {st} {out} {started}")
        check(rm.selection_written(5.0), "the selection write finished")
        try:
            with open(os.path.join(R.work, rm.SELECTED_SHOW_FILE)) as fh:
                kept = json.load(fh).get("show")
        except (OSError, ValueError):
            kept = None
        check(kept == "show.json",
              f"Run wrote the show in use at once: {kept!r}")
        rm3 = RM.Remote(R.httpd.control, R.svc, folder=R.work,
                        clock=lambda: R.mono[0], wall=lambda: R.wall[0],
                        log=lambda t: None)
        check(rm3._active_show_files() == {"show.json"},
              f"an engine restarted straight after Run judges it: "
              f"{rm3._active_show_files()}")
        # Review of #102, P2-c: the selection is written atomically (a
        # temp file, then one replace), and a stalled disk never holds up
        # Run's reply: the write is off the request, and the show in use
        # is known at once all the same.
        import threading as _th
        replaced = []
        real_replace = os.replace

        def spy_replace(a, b, *args, **kw):
            replaced.append((a, b))
            return real_replace(a, b, *args, **kw)
        os.replace = spy_replace
        try:
            rm._save_selected_show("soak_show.json")
            check(rm.selection_written(5.0), "the picker's write finished")
        finally:
            os.replace = real_replace
        sel_path = os.path.join(R.work, rm.SELECTED_SHOW_FILE)
        check(replaced and replaced[-1][1] == sel_path and
              replaced[-1][0] != sel_path and
              not os.path.exists(replaced[-1][0]),
              f"the selection is written to a temp file and replaced into "
              f"place: {replaced}")
        with open(sel_path) as fh:
            check(json.load(fh).get("show") == "soak_show.json",
                  "the replaced file is whole")
        gate = _th.Event()
        real_write = rm._write_selection_file

        def stalled(name):
            gate.wait(10)
            return real_write(name)
        rm._write_selection_file = stalled
        R.httpd.control.start = fake_start
        try:
            t0 = time.monotonic()
            st, _h, out = R.ask("POST", "/api/start",
                                {"timeline": "show.json"},
                                client=("127.0.0.1", 5000))
            took = time.monotonic() - t0
            check(st == 200 and took < 2.0,
                  f"a stalled disk does not hold up Run's reply: {st} "
                  f"{took:.2f} s")
            R.mono[0] += rm.SELECTED_READ_S + 1
            check(rm._selected_show() == "show.json",
                  f"the show Run is in use at once, while the disk stalls: "
                  f"{rm._selected_show()!r}")
        finally:
            gate.set()
            R.httpd.control.start = real_start
            check(rm.selection_written(10.0), "the stalled write finished")
            rm._write_selection_file = real_write
        with open(sel_path) as fh:
            check(json.load(fh).get("show") == "show.json",
                  "once the disk answers, the file says the show Run")
        page = open(os.path.join(os.path.dirname(os.path.abspath(
            __file__)), "ltcplay", "web", "remote.html"),
            encoding="utf-8").read()
        check('post("/api/remote/show-select", {file: $("run-file").value})'
              in page and "if(sel && ok.includes(sel) && !RUN_PICKED) "
              '$("run-file").value = sel;' in page,
              "the page's show picker sends its choice and shows the "
              "engine's")
    finally:
        R.close()
    print("  ok")


def _js_block(page, start, end):
    """The page's text from `start` up to (not including) `end`."""
    a = page.find(start)
    b = page.find(end, a + 1)
    return page[a:b] if 0 <= a < b else ""


def _js_fn(page, name):
    """One top-level `function name(...) {...}` of the page, by braces."""
    a = page.find(f"function {name}(")
    if a < 0:
        return ""
    i = page.find("{", a)
    depth = 0
    for j in range(i, len(page)):
        c = page[j]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return page[a:j + 1]
    return ""


def test_rack_screen_jeff_2026_10_23_page():
    section("rack screen (Jeff, 2026-10-23): the arm button shows the "
            "group's state in colour and words and stays hold to arm; ARM "
            "AGAIN in plain words with why; Schedule (was Tonight) opens "
            "each show's notes on a tap, even with a live show polling "
            "every 250 ms; a time zone list with friendly names; a Show and "
            "Programming switch, locked with the reason during a live show; "
            "Startup (was Morning and Shutdown) with Shutdown its own "
            "section; the show file and deck operator in one column")
    import json
    import shutil as _sh
    import subprocess as _sp
    here = os.path.dirname(os.path.abspath(__file__))
    page = open(os.path.join(here, "ltcplay", "web", "remote.html"),
                encoding="utf-8").read()
    # Static wiring.
