    for arg in sys.argv[1:]:
        test_real_show(arg)
    # test_real_show is opt-in: it runs only when a show folder is named on
    # the command line, so it is not expected in a default run.
    OPT_IN = {"test_real_show"}
    defined = {n for n, v in list(globals().items())
               if n.startswith("test_") and callable(v)} - OPT_IN
    never = sorted(defined - RAN)
    if never:
        FAILS.extend(f"{n} is defined but was never called" for n in never)
        print(f"\n{len(never)} test(s) defined but never run:")
        for n in never:
            print(f"  - {n}")

    if _show_before is not None:
        touched = _show_changes(_show_root, _show_before)
        if touched:
            FAILS.append(f"THE REAL SHOW FOLDER WAS CHANGED BY THIS RUN "
                         f"({_show_root}): " + "; ".join(touched[:20]))
            print(f"\n  FAIL  THE REAL SHOW FOLDER WAS CHANGED BY THIS RUN:")
            for t in touched:
                print(f"    {t}")

    # Last check: this run's own temp folder must be empty once the tests'
    # folders are gone. A test that leaves a file or a child process's folder
    # behind is caught here, not discovered later as a full disk.
    _left = _TEMPRUN.finish()
    if _left:
        _what = "; ".join(_TEMPRUN.describe(_left))
        FAILS.append(f"this run left {len(_left)} temp entries behind: "
                     + _what)
        print(f"\n  FAIL  this run left {len(_left)} temp entries behind in "
              f"its own temp folder: {_what}")

    if _TEST_CLOCK[1] is not None:
        TEST_SECONDS[_TEST_CLOCK[1]] = (TEST_SECONDS.get(_TEST_CLOCK[1], 0.0)
                                        + _TEST_CLOCK[0]() - _TEST_CLOCK[2])
        print("\nslowest tests:")
        for _n, _s in sorted(TEST_SECONDS.items(), key=lambda kv: -kv[1])[:15]:
            print(f"  {_s:6.1f}s  {_n}")

    print(f"\n{'-'*50}")
    if SHOW_PROBLEMS:
        print(f"{len(SHOW_PROBLEMS)} thing(s) to fix in the SHOW FILE. The "
              f"program is sound and an update cannot change these:")
        for f in SHOW_PROBLEMS:
            print(f"  - {f}")
        print("  Open Tools and run 'Set the Advatek triggers.command'.")
        print()
    if FAILS:
        print(f"{len(FAILS)} FAILURES in {time.time()-t0:.1f}s")
        for f in FAILS:
            print(f"  - {f}")
        # One annotation per failure, each with its sentence. GitHub keeps
        # ten error annotations a step, so the tenth names the rest.
        for f in FAILS[:9]:
            ci_annotate("selftest failure", str(f)[:1500])
        if len(FAILS) > 9:
            ci_annotate("selftest: more failures",
                        f"{len(FAILS) - 9} more; the job summary and the "
                        f"selftest log artifact list every one")
        ci_summary(f"FAIL ({len(FAILS)} failures)", time.time() - t0, FAILS)
        sys.exit(1)
    ci_summary("ok", time.time() - t0, FAILS)
    print(f"all checks passed in {time.time()-t0:.1f}s")
